window.INCIL_DATA = [{"id":"matta","name":"Matta","chapters":[{"ch":1,"verses":[{"n":"1-2","h":"İsa Mesih'in soyu","t":"İbrahim oğlu, Davut oğlu İsa Mesih'in soyuyla ilgili kayıt şöyledir:\nİbrahim, İshak'ın babasıydı.\nİshak, Yakup'un babası;\nYakup da Yahuda ve onun kardeşlerinin babasıydı."},{"n":"3","t":"Yahuda, Tamar'dan doğan Peres ve Zara'nın babasıydı.\nPeres, Hesron'un babası;\nHesron da Ram'ın babasıydı."},{"n":"4","t":"Ram, Aminadab'ın babası;\nAminadab, Nahşon'un babası;\nNahşon ise Salmon'un babasıydı."},{"n":"5","t":"Salmon, Rahav'dan doğan Boaz'ın babasıydı.\nBoaz, Rut'tan doğan Obed'in babası;\nObed de İşay'ın babası;"},{"n":"6","t":"İşay da, kral Davut'un babasıydı.\nDavut, Uriya'nın karısından doğan Süleyman'ın babasıydı."},{"n":"7","t":"Süleyman, Rehavam'ın babası;\nRehavam, Abiya'nın babası;\nAbiya da Asa'nın babasıydı."},{"n":"8","t":"Asa, Yehoşafat'ın babası;\nYehoşafat, Yoram'ın babası;\nYoram, Uziya'nın babasıydı."},{"n":"9","t":"Uziya, Yotam'ın babası;\nYotam, Ahaz'ın babası;\nAhaz da Hizkiya'nın babasıydı."},{"n":"10","t":"Hizkiya, Manaşe'nin babası;\nManaşe, Amon'un babası;\nAmon ise Yoşiya'nın babasıydı."},{"n":"11","t":"Yoşiya, Babil sürgünü sırasında doğan Yekonya\nve onun kardeşlerinin babasıydı."},{"n":"12","t":"Yekonya, Babil sürgününden sonra doğan Şaltiyel'in babası;\nŞaltiyel ise Zerubabel'in babasıydı."},{"n":"13","t":"Zerubabel, Abihud'un babası;\nAbihud, Elyakim'in babası;\nElyakim de Azor'un babasıydı."},{"n":"14","t":"Azor, Sadok'un babası;\nSadok, Ahim'in babası;\nAhim ise Elihud'un babasıydı."},{"n":"15","t":"Elihud, Elazar'ın babası;\nElazar, Matan'ın babası;\nMatan da Yakup'un babasıydı."},{"n":"16","t":"Yakup, Meryem'in kocası Yusuf'un babasıydı.\nMeryem'den de Mesih denilen İsa doğdu."},{"n":"17","t":"Buna göre, İbrahim'den Davut'a kadar toplam on dört kuşak, Davut'tan Babil sürgününe kadar on dört kuşak ve Babil sürgününden Mesih'e kadar da on dört kuşak geçti."},{"n":"18","h":"İsa Mesih'in doğumu","t":"İsa Mesih'in doğumu da şöyle oldu: annesi Meryem, Yusuf'la nişanlanmıştı. Ama evlenip birleşmelerinden önce Meryem'in Kutsal Ruh'tan gebe kaldığı anlaşıldı."},{"n":"19","t":"Meryem'in nişanlısı Yusuf, doğru bir adam olduğu ve onu herkesin önünde utandırmak istemediği için ondan gizlice ayrılmak niyetindeydi."},{"n":"20","t":"Ama böyle düşünmesi üzerine Rab'bin bir meleği ona rüyada görünerek şöyle dedi: \"Davut oğlu Yusuf, Meryem'i kendine eş olarak almaktan korkma. Çünkü onun rahminde oluşan, Kutsal Ruh'tandır."},{"n":"21","t":"Meryem bir oğul doğuracak. Adını İsa koyacaksın. Çünkü halkını günahlarından kurtaracak olan O'dur.\""},{"n":"22-23","t":"Bütün bunlar, Rab'bin peygamber aracılığıyla bildirdiği şu sözün yerine gelmesi için oldu: \"İşte, kız gebe kalıp bir oğul doğuracak. O'nun adını İmanuel koyacaklar.\" İmanuel, 'Tanrı bizimle' demektir."},{"n":"24","t":"Yusuf uyanınca Rab'bin meleğinin kendisine buyurduğu gibi yaptı ve Meryem'i eş olarak yanına aldı."},{"n":"25","t":"Ne var ki, Meryem oğlunu doğuruncaya dek Yusuf onunla birleşmedi. Doğan çocuğun adını İsa koydu."}]},{"ch":2,"verses":[{"n":"1-2","h":"Yıldızbilimcilerin ziyareti","t":"İsa, Kral Hirodes'in devrinde Yahudiye'nin Beytlehem kasabasında doğduktan sonra bazı yıldızbilimciler doğudan Kudüs'e gelip şöyle dediler: \"Yahudilerin kralı olarak doğan çocuk nerede? Doğuda O'nun yıldızını gördük ve O'na tapınmaya geldik.\""},{"n":"3","t":"Kral Hirodes bunu duyunca bütün Kudüs halkıyla birlikte çok tedirgin oldu."},{"n":"4","t":"Tüm başkâhinleri ve ulusun din bilginlerini toplayarak onlara Mesih'in nerede doğacağını sordu."},{"n":"5","t":"\"Yahudiye'nin Beytlehem kasabasında\" dediler. \"Çünkü peygamber aracılığıyla şöyle yazılmıştır:"},{"n":"6","t":"'Sen, Yahuda diyarında olan ey Beytlehem,\nYahuda önderleri arasında hiç de en önemsizi değilsin!\nÇünkü benim halkım İsrail'i güdecek olan önder\nsenden çıkacaktır.'\""},{"n":"7","t":"Bunun üzerine Hirodes yıldızbilimcileri gizlice çağırıp onlardan yıldızın göründüğü anı tam olarak öğrendi."},{"n":"8","t":"\"Gidin, çocuğu dikkatle arayın, bulduğunuz zaman bana haber verin, ben de gelip O'na tapınayım\" diyerek onları Beytlehem'e gönderdi."},{"n":"9","t":"Yıldızbilimciler, kralı dinledikten sonra yola çıktılar. Doğuda görmüş oldukları yıldız onlara yol gösterdi ve gelip çocuğun bulunduğu yerin üzerinde durdu."},{"n":"10","t":"Yıldızı gördüklerindeolağanüstü bir sevinç duydular."},{"n":"11","t":"Eve girip çocuğu annesi Meryem'le birlikte görünce yere kapanarak O'na tapındılar. Hazinelerini açıp O'na armağan olarak altın, tütsü ve mür sundular."},{"n":"12","t":"Sonra Hirodes'in yanına dönmesinler diye rüyada uyarıldıklarından, ülkelerine başka yoldan döndüler."},{"n":"13","h":"Mısır'a kaçış","t":"Yıldızbilimciler yola çıktıktan sonra Rab'bin bir meleği Yusuf'a rüyada göründü. Ona, \"Kalk!\" dedi. \"Çocuğu ve annesini al ve Mısır'a kaç. Ben sana haber verinceye dek orada kal. Çünkü Hirodes çocuğu öldürmek amacıyla onu arayacak.\""},{"n":"14","t":"Böylece Yusuf kalktı, aynı gece çocuğu ve annesini alıp Mısır'a doğru yola çıktı."},{"n":"15","t":"Hirodes'in ölümüne dek orada kaldı. Bu, Rab'bin peygamber aracılığıyla bildirdiği şu sözün yerine gelmesi için oldu: \"Oğlumu Mısır'dan geri çağırdım.\""},{"n":"16","t":"Hirodes, yıldızbilimciler tarafından aldatıldığını görünce büyük öfkeye kapıldı. Onlardan tam olarak öğrenmiş olduğu zamana göre, Beytlehem ve tüm yöresinde bulunan iki ve daha küçük yaştaki erkek çocukların hepsini öldürttü."},{"n":"17","t":"Böylelikle Yeremya peygamber aracılığıyla bildirilen şu söz yerine gelmiş oldu:"},{"n":"18","t":"\"Ramah'ta bir ses duyuldu,\nağlayış ve acı feryat sesleri!\nÇocukları için ağlayan Rahel,\nteselli edilmek istemiyor.\nÇünkü onlar yok artık!\""},{"n":"19-20","h":"Nasıra'ya dönüş","t":"Hirodes öldükten sonra, Rab'bin bir meleği Mısır'da Yusuf'a rüyada görünerek, \"Kalk!\" dedi. \"Çocuğu ve annesini al, İsrail diyarına dön. Çünkü çocuğu öldürmek isteyenler öldü.\""},{"n":"21","t":"Bunun üzerine Yusuf kalktı, çocuğu ve annesini alıp İsrail diyarına döndü."},{"n":"22","t":"Ama Yahudiye'de Hirodes'in yerine oğlu Arhelas'ın tahta geçtiğini duyunca oraya gitmekten korktu. Rüyada aldığı buyruğa uyarak Celile bölgesine gitti."},{"n":"23","t":"Oraya varınca Nasıra denen kente yerleşti. Bu, peygamberler aracılığıyla bildirilen, \"O'na Nasıralı denecektir\" sözünün yerine gelmesi için oldu."}]},{"ch":3,"verses":[{"n":"1-2","h":"Yahya'nın ortaya çıkışı","t":"O günlerde Vaftizci Yahya ortaya çıktı. Yahudiye çölünde şu çağrıda bulunuyordu: \"Tövbe edin! Göklerin Egemenliği yaklaşmıştır.\""},{"n":"3","t":"Nitekim Yeşaya peygamber aracılığıyla sözü edilen kişi Yahya'dır. Yeşaya şöyle demişti:\n\"Çölde yükselen ses,\n'Rab'bin yolunu hazırlayın,\ngeçeceği patikaları düzleyin' diyor.\""},{"n":"4","t":"Yahya'nın deve tüyünden giysisi, belinde deriden kuşağı vardı. Tek yediği, çekirge ve yaban balıydı."},{"n":"5-6","t":"Kudüs'ün, bütün Yahudiye'nin ve tüm Şeria nehri yöresinin halkı ona geliyor, günahlarını itiraf ediyor, onun tarafından Şeria nehrinde vaftiz ediliyordu."},{"n":"7","t":"Ne var ki, Ferisilerle Sadukilerden birçok kişinin vaftiz olmak için kendisine geldiğini gören Yahya onlara şöyle seslendi: \"Ey engerekler soyu! Gelecek olan gazaptan kaçmanız için sizi kim uyardı?"},{"n":"8","t":"Bundan böyle tövbeye yaraşır meyveler verin."},{"n":"9","t":"Kendi kendinize, 'Biz İbrahim'in soyundanız' diye düşünmeyin. Ben size şunu söyleyeyim: Tanrı, İbrahim'e şu taşlardan çocuk yaratacak güçtedir."},{"n":"10","t":"Balta şimdiden ağaçların köküne dayanmıştır. İyi meyve vermeyen her ağaç kesilip ateşe atılacak."},{"n":"11","t":"Gerçi ben sizi tövbe için suyla vaftiz ediyorum, ama benden sonra gelen benden daha güçlüdür. Ben O'nun çarıklarını çıkarmaya bile layık değilim. O sizi Kutsal Ruh'la ve ateşle vaftiz edecek."},{"n":"12","t":"Yabası elindedir. Harman yerini temizleyecek, buğdayını toplayıp ambara yığacak, samanı sönmeyen ateşte yakacaktır.\""},{"n":"13","h":"İsa vaftiz oluyor","t":"Bu sırada İsa, Yahya tarafından vaftiz edilmek üzere Celile'den Şeria nehrine, Yahya'nın yanına geldi."},{"n":"14","t":"Ne var ki Yahya, \"Benim senin tarafından vaftiz edilmem gerekirken sen mi bana geliyorsun?\" diyerek O'na engel olmak istedi."},{"n":"15","t":"İsa ona şu karşılığı verdi: \"Şimdilik buna razı ol! Çünkü doğru olan her şeyi bu şekilde yerine getirmemiz gerekir.\" O zaman Yahya O'nun dediğine razı oldu."},{"n":"16","t":"İsa vaftiz olur olmaz sudan çıktı. O anda gökler açıldı ve İsa, Tanrı'nın Ruhunun güvercin gibi inip üzerine konduğunu gördü."},{"n":"17","t":"Göklerden gelen bir ses de şöyle dedi: \"Sevgili Oğlum budur, O'ndan hoşnudum.\""}]},{"ch":4,"verses":[{"n":"1","h":"İsa sınanıyor","t":"Bundan sonra İsa, İblis'in denemelerinden geçmek üzere Ruh tarafından çöle götürüldü."},{"n":"2","t":"Kırk gün kırk gece oruç tuttuktansonra acıktı."},{"n":"3","t":"O zaman Ayartıcı O'na gelip, \"Tanrı'nın Oğluysan, söyle de şu taşlar ekmek olsun\" dedi."},{"n":"4","t":"İsa ona şu karşılığı verdi: \"Kutsal Yazılarda, 'İnsan yalnız ekmekle değil, Tanrı'nın ağzından çıkan her sözle yaşar' diye yazılmıştır.\""},{"n":"5-6","t":"Sonra İblis O'nu kutsal kente götürdü. Tapınağın tepesine çıkarıp dedi ki, \"Tanrı'nın Oğluysan, kendini buradan aşağı at. Çünkü şöyle yazılmıştır:\n'Tanrı, senin için meleklerine buyruk verecek.'\n'Ayağın bir taşa çarpmasın diye\nseni elleri üzerinde taşıyacaklar.'\""},{"n":"7","t":"İsa İblis'e şu karşılığı verdi: \"'Tanrın olan Rab'bi sınama' diye de yazılmıştır.\""},{"n":"8","t":"İblis aynı şekilde İsa'yı çok yüksek bir dağa çıkarıp O'na tüm görkemleriyle dünyanın bütün ülkelerini gösterdi."},{"n":"9","t":"\"Yere kapanıp bana taparsan, bütün bunları sana vereceğim\" dedi."},{"n":"10","t":"İsa ona şöyle karşılık verdi: \"Çekil git, Şeytan! 'Tanrın olan Rab'be tap, yalnız O'na kulluk et' diye yazılmıştır.\""},{"n":"11","t":"Bunun üzerine İblis İsa'yı bırakıp gitti. Melekler de gelip İsa'ya hizmet ettiler."},{"n":"12","h":"İsa Müjde'yi duyurmaya başlıyor","t":"İsa, Yahya'nın tutuklandığını duyunca Celile'ye döndü."},{"n":"13","t":"Nasıra'dan ayrılarak Zebulun ve Naftali yöresinde, Celile gölü kıyısında bulunan Kefernahum'a gelip yerleşti."},{"n":"14-15","t":"Bu, Yeşaya peygamber aracılığıyla bildirilen şu sözün yerine gelmesi için oldu:\n\"Zebulun diyarı ve Naftali diyarı,\nŞeria nehrinin ötesinde, deniz tarafı,\nulusların Celilesi!"},{"n":"16","t":"Karanlıkta yaşayan halk,\nbüyük bir ışık gördü.\nÖlümün gölgelediği diyarda\nyaşayanların üzerine bir ışık doğdu.\""},{"n":"17","t":"O günden itibaren İsa şu çağrıda bulunmaya başladı: \"Tövbe edin! Göklerin Egemenliği yaklaştı.\""},{"n":"18","h":"İsa ilk öğrencilerini seçiyor","t":"İsa, Celile gölünün kıyısında gezerken Petrus denen Simun ile kardeşi Andreya'yı gördü. Balıkçı olan bu iki kardeş göle ağ atmaktaydı."},{"n":"19","t":"İsa onlara, \"Ardımdan gelin, sizleri insan tutan balıkçılar yapacağım\" dedi."},{"n":"20","t":"Onlar da hemen ağlarını bırakıp O'nun ardından gittiler."},{"n":"21","t":"Oradan daha ileri giden İsa, başka iki kardeşi, Zebedi'nin oğulları Yakup'la Yuhanna'yı gördü. Babaları Zebedi'yle birlikte kayıkta ağlarını onarıyorlardı. İsa onları çağırdı."},{"n":"22","t":"Onlar da hemen kayığı ve babalarını bırakıp İsa'nın ardından gittiler."},{"n":"23","h":"İsa hastaları iyileştiriyor","t":"İsa, Celile bölgesinin her tarafını dolaştı. Buralardaki havralarda ders veriyor, Göksel Egemenliğin müjdesini duyuruyor, halk arasında rastlanan her hastalığı, her illeti iyileştiriyordu."},{"n":"24","t":"O'nun ünü bütün Suriye'ye yayılmıştı. Çeşit çeşit hastalıklara yakalanmış, ıstırap içinde olan, cine tutsak,saralı, felçli olanların hepsini O'na getirdiler, O da onları iyileştirdi."},{"n":"25","t":"Celile, Dekapolis, Kudüs, Yahudiye ve Şeria nehrinin ötesinden gelen büyük kalabalıklar O'nun ardından gidiyordu."}]},{"ch":5,"verses":[{"n":"1","h":"Gerçek mutluluk","t":"İsa kalabalıkları görünce dağa çıktı. Oturduktan sonra, öğrencileri yanına geldiler."},{"n":"2-3","t":"Onlara seslenip şöyle ders vermeye başladı:\n\"Ne mutlu ruhta yoksul olanlara!\nGöklerin Egemenliği onlarındır."},{"n":"4","t":"Ne mutlu yaslı olanlara!\nOnlar teselli edilecekler."},{"n":"5","t":"Ne mutlu yumuşak huylu olanlara!\nOnlar yeryüzünü miras alacaklar."},{"n":"6","t":"Ne mutlu doğruluğa acıkıp susayanlara!\nOnlar doyurulacaklar."},{"n":"7","t":"Ne mutlu merhametli olanlara!\nOnlar merhamet bulacaklar."},{"n":"8","t":"Ne mutlu yüreği temiz olanlara!\nOnlar Tanrı'yı görecekler."},{"n":"9","t":"Ne mutlu barışı sağlayanlara!\nOnlara Tanrı oğulları denecek."},{"n":"10","t":"Ne mutlu doğruluk uğruna zulüm görenlere!\nGöklerin Egemenliği onlarındır."},{"n":"11","t":"\"Bana olan bağlılığınızdan ötürü insanlar size sövüp zulmettikleri, yalan yere size karşı her türlü kötü sözü söyledikleri zaman ne mutlu size!"},{"n":"12","t":"Sevinin, sevinçle coşun! Çünkü göklerdeki ödülünüz büyüktür. Sizden önce yaşamış olan peygamberlere de böyle zulmettiler."},{"n":"13","h":"Tuz ve ışık","t":"\"Yeryüzünün tuzu sizsiniz. Ama tuz tadını yitirirse, ona tekrar nasıl tuz tadı verilebilir? Artık dışarı atılıp insanların ayakları altında çiğnenmekten başka bir şeye yaramaz."},{"n":"14","t":"\"Dünyanın ışığı sizsiniz. Tepenin üzerine kurulan kent gizlenemez."},{"n":"15","t":"İnsanlar da kandil yakıp tahıl ölçeği altına koymazlar. Tersine, kandilliğe koyarlar; oradan da evdekilerin hepsine ışık verir."},{"n":"16","t":"Sizin ışığınız insanların önünde öyle parlasın ki, iyi işlerinizi görerek göklerde olan Babanızı yüceltsinler!"},{"n":"17","h":"Kutsal Yasa","t":"\"Kutsal Yasa'yı ya da peygamberlerin sözlerini geçersizkılmak için geldiğimi sanmayın. Ben geçersiz kılmaya değil, tamamlamaya geldim."},{"n":"18","t":"Size doğrusunu söyleyeyim, gök ve yer ortadan kalkmadan, her şey gerçekleşmeden, Kutsal Yasa'dan ufacık bir harf ya da bir nokta bile eksilmeyecek."},{"n":"19","t":"Bu nedenle, bu buyrukların en küçüklerinden birini kim çiğner ve başkalarına öyle yapmayı öğretirse, Göklerin Egemenliğinde en küçük sayılacak. Ama bu buyrukları kim yerine getirir ve başkalarına öğretirse, Göklerin Egemenliğinde büyük sayılacak."},{"n":"20","t":"Size şunu söyleyeyim: doğruluğunuz din bilginleriyle Ferisilerinkini kat kat aşmadıkça, Göklerin Egemenliğine asla giremezsiniz!"},{"n":"21","h":"Öfke ve cinayet","t":"\"Atalarımıza, 'Adam öldürme. Öldüren, yargılanmayı hak edecek' denildiğini duydunuz."},{"n":"22","t":"Ama ben size diyorum ki, kardeşine karşı öfkelenen her kişi yargılanmayı hak edecek. Kim kardeşine aşağılayıcı bir söz söylerse, Yüksek Kurul'un yargısını hak edecek. Kim kardeşine ahmak derse, cehennem ateşini hak edecek."},{"n":"23-24","t":"Bu yüzden, adağını sunağa getirdiğinde, orada kardeşinin sana karşı bir şikâyeti olduğunu hatırlarsan, adağını orada, sunağın önünde bırak, git, önce kardeşinle barış; sonra gel, adağını sun."},{"n":"25","t":"Senden davacı olanla, daha yoldayken çabucak anlaş. Yoksa o seni yargıca, yargıç da gardiyana teslim edebilir; sonunda da hapse atılabilirsin."},{"n":"26","t":"Sana doğrusunu söyleyeyim, son kuruşu ödemedikçe oradan asla çıkamazsın."},{"n":"27","h":"Zina ve boşanma","t":"\"'Zina etme' denildiğini duydunuz."},{"n":"28","t":"Ama ben size diyorum ki, bir kadına şehvetle bakan her adam, zaten yüreğinde o kadınla zina etmiştir."},{"n":"29","t":"Eğer sağ gözün seni günaha sokarsa, onu çıkar, at. Çünkü vücudunun bir üyesinin yok olması, tüm vücudunun cehenneme atılmasından iyidir."},{"n":"30","t":"Eğer sağ elin seni günaha sokarsa, onu kes, at. Çünkü vücudunun bir üyesinin yok olması, tüm vücudunun cehenneme gitmesinden iyidir."},{"n":"31","t":"\"'Kim karısını boşarsa ona boş kâğıdını versin' denilmiştir."},{"n":"32","t":"Ama ben size diyorum ki, karısını cinsel ahlaksızlıktan başka bir nedenle boşayan her adam, onu zinaya itmiş olur. Boşanmış bir kadınla evlenen de zina etmiş olur."},{"n":"33","h":"Ant içmek","t":"\"Yine atalarımıza, 'Yalan yere ant içme, ama Rab'be içtiğin antları tut' denildiğini duydunuz."},{"n":"34-35","t":"Oysa ben size diyorum ki, hiç ant içmeyin, ne gök üzerine - çünkü orası Tanrı'nın tahtıdır; ne yer üzerine - çünkü orası O'nun ayaklarının basamağıdır; ne de Kudüs üzerine - çünkü orası Büyük Kral'ın kentidir."},{"n":"36","t":"Başınızın üzerine de ant içmeyin. Çünkü saçınızın tek telini ak ya da kara edemezsiniz."},{"n":"37","t":"'Evet'iniz evet, 'hayır'ınız hayır olsun. Bundan fazlası Şeytan'dandır."},{"n":"38","h":"Göze göz, dişe diş","t":"\"'Göze göz, dişe diş' denildiğini duydunuz."},{"n":"39","t":"Ama ben size diyorum ki, kötüye karşı direnmeyin. Sağ yanağınıza bir tokat atana öbür yanağınızı da çevirin."},{"n":"40","t":"Size karşı davacı olup mintanınızı almak isteyene abanızı da verin."},{"n":"41","t":"Sizi bin adım yol yürümeye zorlayanla iki bin adım yürüyün."},{"n":"42","t":"Sizden bir şey dileyene verin, sizden ödünç isteyeni geri çevirmeyin."},{"n":"43","h":"Düşmanlarınızı sevin","t":"\"'Komşunu sev, düşmanından nefret et' denildiğini duydunuz."},{"n":"44","t":"Ama ben size diyorum ki, düşmanlarınızı sevin, size zulmedenler için dua edin."},{"n":"45","t":"Öyle ki, göklerde olan Babanızın oğulları olasınız. Çünkü O, güneşini hem kötülerin hem de iyilerin üzerine doğdurur. Yağmurunu da hem doğruların hem de eğrilerin üzerine yağdırır."},{"n":"46","t":"Eğer yalnız sizi sevenleri severseniz, ne ödülünüz olur? Vergi görevlileri de öyle yapmıyor mu?"},{"n":"47","t":"Yalnız kardeşlerinize selam verirseniz, fazladan ne yapmış olursunuz? Putperestler de öyle yapmıyor mu?"},{"n":"48","t":"Bu nedenle, göksel Babanız yetkin olduğu gibi, siz de yetkin olun."}]},{"ch":6,"verses":[{"n":"1","h":"Yoksullara yardım","t":"\"Dikkat edin! Yapmanız gereken doğru işleri gösteriş için insanların gözü önünde yapmayın. Öyle yaparsanız, göklerdeki Babanızdan ödül alamazsınız."},{"n":"2","t":"\"Bu nedenle, birisine sadaka vereceğiniz zaman bunu ilan etmek için önünüzde borazan çaldırmayın. İkiyüzlü kişiler, insanların övgüsünü kazanmak için havralarda ve sokaklarda böyle yaparlar. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır."},{"n":"3","t":"Siz sadaka verdiğiniz zaman, sol eliniz sağ elinizin ne yaptığını bilmesin."},{"n":"4","t":"Öyle ki, verdiğiniz sadaka gizli kalsın. Gizlilik içinde yapılanı gören Babanız sizi ödüllendirecektir."},{"n":"5","h":"Dua","t":"\"Dua ettiğiniz zaman ikiyüzlüler gibi olmayın. Onlar, herkes kendilerini görsün diye havralarda ve caddelerin köşe başlarında dikilip dua etmekten zevk alırlar. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır."},{"n":"6","t":"Siz ise, dua edeceğiniz zaman odanıza girip kapıyı örtün ve gizlide olan Babanıza dua edin. Gizlilik içinde yapılanı gören Babanız sizi ödüllendirecektir."},{"n":"7","t":"Dua ettiğinizde, putperestler gibi boş sözler tekrarlayıp durmayın. Onlar, söz kalabalığıyla seslerini duyurabileceklerini sanırlar."},{"n":"8","t":"Siz onlara benzemeyin! Çünkü Babanız, nelere gereksinmeniz olduğunu daha siz O'ndan dilemeden önce bilir."},{"n":"9","t":"\"Bunun için siz şöyle dua edin:\n'Göklerdeki Babamız,\nadın kutsal kılınsın."},{"n":"10","t":"Egemenliğin gelsin.\nGökte olduğu gibi, yeryüzünde de\nsenin istediğin olsun."},{"n":"11","t":"Bugün bize gündelik ekmeğimizi ver."},{"n":"12","t":"Bize karşı suç işleyenleri bağışladığımız gibi,\nsen de bizim suçlarımızı bağışla."},{"n":"13","t":"Ayartılmamıza izin verme.\nKötü olandan bizi kurtar.\nÇünkü egemenlik, güç ve yücelik\nsonsuzlara dek senindir. Amin.'"},{"n":"14","t":"\"Başkalarının suçlarını bağışlarsanız, göksel Babanız da sizin suçlarınızı bağışlar."},{"n":"15","t":"Ama siz başkalarının suçlarını bağışlamazsanız, Babanız da sizin suçlarınızı bağışlamaz."},{"n":"16","h":"Oruç","t":"\"Oruç tuttuğunuz zaman, ikiyüzlüler gibi surat asmayın. Onlar oruç tuttuklarını insanlara belli etmek için kendilerine perişan bir görünüm verirler. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır."},{"n":"17","t":"Siz oruç tuttuğunuz zaman, başınıza yağ sürüp yüzünüzü yıkayın."},{"n":"18","t":"Öyle ki, insanlara değil, gizlide olan Babanıza oruçlu görünesiniz. Gizlilik içinde yapılanı gören Babanız sizi ödüllendirecektir."},{"n":"19","h":"Göksel hazineler","t":"\"Yeryüzünde kendinize hazineler biriktirmeyin. Burada güve ve pas onları yiyip bitirir, hırsızlar da girip çalarlar."},{"n":"20","t":"Bunun yerine kendinize gökte hazineler biriktirin. Orada ne güve ne pas onları yiyip bitirir, ne de hırsızlar girip çalar."},{"n":"21","t":"Hazineniz neredeyse, yüreğiniz de orada olacak."},{"n":"22","t":"\"Bedenin ışığı gözdür. Gözünüz sağlamsa, tüm bedeniniz aydınlık olur."},{"n":"23","t":"Gözünüz bozuksa, tüm bedeniniz karanlık olur. Buna göre, içinizdeki 'ışık' karanlıksa, ne korkunçtur o karanlık!"},{"n":"24","t":"\"Hiç kimse iki efendiye kulluk edemez. Ya birinden nefret edip öbürünü sever, ya da birine bağlanıp öbürünü hor görür. Siz hem Tanrı'ya, hem de paraya kulluk edemezsiniz."},{"n":"25","h":"Kaygılanmayın","t":"\"Bu nedenle size şunu söylüyorum: 'Ne yiyip ne içeceğiz?' diye canınız için, ya da 'Ne giyeceğiz?' diye bedeniniz için kaygılanmayın. Can yiyecekten, beden de giyecekten daha önemli değil mi?"},{"n":"26","t":"Gökte uçan kuşlara bakın! Ne eker, ne biçer, ne de ambarlarda yiyecek biriktirirler. Göksel Babanız yine de onları doyurur. Siz onlardan çok daha değerli değil misiniz?"},{"n":"27","t":"Hangi biriniz kaygılanmakla ömrünü bir anlık uzatabilir?"},{"n":"28","t":"Giyecek konusunda neden kaygılanıyorsunuz? Kır zambaklarının nasıl büyüdüğüne bakın! Ne çalışırlar, ne de iplik eğirirler."},{"n":"29","t":"Ama size şunu söyleyeyim, tüm görkemine rağmen Süleyman bilebunlardan biri gibi giyinmiş değildi."},{"n":"30","t":"Bugün var olup yarın ocağa atılacak olan kır otunu böyle giydiren Tanrı'nın sizi de giydireceği çok daha kesin değil mi, ey imanı kıt olanlar?"},{"n":"31","t":"\"Öyleyse, 'Ne yiyeceğiz?' 'Ne içeceğiz?' ya da 'Ne giyeceğiz?' diyerek kaygılanmayın."},{"n":"32","t":"Uluslar hep bu şeylerin peşinden giderler. Oysa göksel Babanız tüm bunları gereksindiğinizi bilir."},{"n":"33","t":"Siz önce O'nun egemenliğinin ve O'ndaki doğruluğun ardından gidin, o zaman size tüm bunlar da verilecektir."},{"n":"34","t":"O halde yarın için kaygılanmayın. Yarının kaygısı yarının olsun. Her günün derdi kendine yeter."}]},{"ch":7,"verses":[{"n":"1","h":"Başkasını yargılamayın","t":"\"Başkasını yargılamayın ki, siz de yargılanmayasınız."},{"n":"2","t":"Başkasını nasıl yargılarsanız, siz de aynı yoldan yargılanacaksınız. Hangi ölçekle ölçerseniz, size de aynı ölçek uygulanacak."},{"n":"3","t":"Sen neden kardeşinin gözündeki çöpü görürsün de kendi gözündeki merteği farketmezsin?"},{"n":"4","t":"Senin gözünde mertek varken nasıl olur da kardeşine, 'İzin ver de gözündeki çöpü çıkarayım' dersin?"},{"n":"5","t":"Seni ikiyüzlü! Önce kendi gözündeki merteği çıkar, o zaman kardeşinin gözündeki çöpü çıkarmak için daha iyi görürsün."},{"n":"6","t":"\"Kutsal olanı köpeklere vermeyin. İncilerinizi domuzların önüne atmayın. Yoksa bunları ayaklarıyla çiğnedikten sonra dönüp sizi parçalayabilirler."},{"n":"7","h":"Tanrı'dan dileyin","t":"\"Dileyin, size verilecek; arayın, bulacaksınız; kapıyı çalın, size açılacaktır."},{"n":"8","t":"Çünkü her dileyen alır, arayan bulur, kapıyı çalana kapı açılır."},{"n":"9","t":"Hanginiz kendisinden ekmek isteyen oğluna taş verir?"},{"n":"10","t":"Ya da balık isterse ona yılan verir?"},{"n":"11","t":"Sizler kötü yürekli olduğunuz halde çocuklarınıza güzel armağanlar vermeyi biliyorsanız, göklerde olan Babanızın, kendisinden dileyenlere güzel şeyler vereceği çok daha kesin değil mi?"},{"n":"12","t":"\"İnsanların size nasıl davranmasını istiyorsanız, siz de onlara öyle davranın. Kutsal Yasa'nın ve peygamberlerin söylediği budur."},{"n":"13","h":"Dar kapı, geniş kapı","t":"\"Dar kapıdan girin. Çünkü kişiyi yıkıma götüren kapı geniş ve yol enlidir. Bu kapıdan girenler çoktur."},{"n":"14","t":"Yaşama götüren kapı ise dar, yol da çetindir. Bu yolu bulanlar azdır."},{"n":"15","h":"Ağaç ve meyvesi","t":"\"Sahte peygamberlerden sakının! Kuzu postuna bürünerek gelirler size, ama özde yırtıcı kurtlardır."},{"n":"16","t":"Onları meyvelerinden tanıyacaksınız. Dikenli bitkilerden üzüm, devedikenlerinden incir toplanabilir mi?"},{"n":"17","t":"Bunun gibi, her iyi ağaç iyi meyve verir, kötü ağaç ise kötü meyve verir."},{"n":"18","t":"İyi ağaç kötü meyve veremez. Kötü ağaç da iyi meyve veremez."},{"n":"19","t":"İyi meyve vermeyen her ağaç kesilip ateşe atılır."},{"n":"20","t":"Böylece sahte peygamberleri meyvelerinden tanıyacaksınız."},{"n":"21","t":"\"Beni, 'Rab! Rab!' diye çağıran herkes Göklerin Egemenliğine girecek değildir. Ancak göklerde olan Babamın isteğini yerine getiren girecektir."},{"n":"22","t":"O gün birçokları bana diyecek ki, 'Rab! Rab! Biz senin adınla peygamberlik etmedik mi? Senin adınla cinler kovmadık mı? Senin adınla birçok mucize yapmadık mı?'"},{"n":"23","t":"O zaman ben de onlara açıkça şöyle diyeceğim: 'Ben sizi hiç tanımadım. Çekilin önümden, ey kötülük yapanlar!'"},{"n":"24","h":"Sağlam temel, çürük temel","t":"\"İşte bu sözlerimi duyup uygulayan herkes, evini kaya üzerinde kuran akıllı adama benzer."},{"n":"25","t":"Yağmur yağmış, seller yükselmiş, yeller esmiş ve eve saldırmış; ama ev yıkılmamış. Çünkü kaya üzerine kurulmuştu."},{"n":"26","t":"Bu sözlerimi duyup da uygulamayan herkes, evini kum üzerinde kuran budala adama benzer."},{"n":"27","t":"Yağmur yağmış, seller yükselmiş, yeller esmiş ve eve yüklenmiş. Ve ev çökmüş; çöküşü de korkunç olmuş.\""},{"n":"28","t":"İsa konuşmasını bitirince, halk O'nun öğretişine şaşıp kaldı."},{"n":"29","t":"Çünkü onlara kendi din bilginleri gibi değil, yetkili biri gibi ders veriyordu."}]},{"ch":8,"verses":[{"n":"1","h":"İsa bir cüzamlıyı iyileştiriyor","t":"İsa dağdan inince büyük bir kalabalık O'nun ardından gitti."},{"n":"2","t":"Bu sırada cüzamlı bir adam yaklaşıp O'nun önünde yere kapanarak, \"Rab\" dedi, \"eğer istersen beni temiz kılabilirsin.\""},{"n":"3","t":"İsa elini uzatıp adama dokundu, \"İsterim, temiz ol!\" dedi. Adam hemen o anda cüzamdan temizlendi."},{"n":"4","t":"Sonra İsa adama, \"Sakın kimseye bir şey söyleme!\" dedi. \"Git, kâhine görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musa'nın buyurduğu adağı sun.\""},{"n":"5-6","h":"Yüzbaşının imanı","t":"İsa Kefernahum'a varınca bir yüzbaşı O'na gelip, \"Ya Rab\" diye yalvardı, \"felçli uşağım korkunç acılar içinde evde yatıyor.\""},{"n":"7","t":"İsa, \"Gelip onu iyileştireceğim\" dedi."},{"n":"8","t":"Ama yüzbaşı, \"Rab, ben layık değilim ki, çatımın altına giresin!\" karşılığını verdi. \"Sen yeter ki bir söz söyle, uşağımiyileşir."},{"n":"9","t":"Ben de buyruk altında bir adamım, benim de buyruğumda askerlerim var. Birine, 'Git' derim, gider; bir diğerine, 'Gel' derim, gelir; köleme, 'Şunu yap' derim, yapar.\""},{"n":"10","t":"İsa, duyduğu bu sözlere hayran kaldı. Ardından gelenlere, \"Size doğrusunu söyleyeyim\" dedi, \"ben böyle imanı İsrail'de kimsede görmedim."},{"n":"11","t":"Size şunu söyleyeyim, doğudan ve batıdan birçok insan gelecek, Göklerin Egemenliğinde İbrahim, İshak ve Yakup'la birlikte sofraya oturacaklar."},{"n":"12","t":"Ama bu egemenliğin asıl mirasçıları dışarıya, karanlığa atılacak. Orada ağlayış ve diş gıcırtısı olacaktır.\""},{"n":"13","t":"Sonra İsa yüzbaşıya, \"Git, inandığın gibi olsun\" dedi.\nVe uşak o anda iyileşti."},{"n":"14","h":"İsa birçoklarını iyileştiriyor","t":"İsa Petrus'un evine geldiğinde, onun kaynanasının ateşler içinde yattığını gördü."},{"n":"15","t":"İsa kadının eline dokununca ateşi düşüverdi. Kadın kalkıp İsa'ya hizmet etmeye başladı."},{"n":"16","t":"Akşam olunca cine tutsak birçok kişiyi kendisine getirdiler. İsa onlardaki kötü ruhları bir sözle kovdu, hastaların hepsini iyileştirdi."},{"n":"17","t":"Bu, Yeşaya peygamber aracılığıyla bildirilen şu sözün yerine gelmesi için oldu:\n\"Zayıflıklarımızı O kaldırdı,\nhastalıklarımızı O yüklendi.\""},{"n":"18","h":"İsa'yı izlemenin bedeli","t":"İsa, çevresindeki kalabalığı görünce gölün karşı yakasına geçilmesini buyurdu."},{"n":"19","t":"O sırada din bilginlerinden biri gelip O'na şöyle dedi: \"Öğretmenim, nereye gidersen, senin ardından geleceğim.\""},{"n":"20","t":"İsa ona, \"Tilkilerin ini, gökte uçan kuşların yuvası var, ama İnsanoğlu'nun başını yaslayacak bir yeri yok\" dedi."},{"n":"21","t":"Bir diğer öğrencisi İsa'ya, \"Rab, izin ver de önce gidip babamı gömeyim\" dedi."},{"n":"22","t":"İsa ona, \"Sen ardımdan gel\" dedi. \"Ölüleri bırak, kendi ölülerini kendileri gömsünler.\""},{"n":"23","h":"İsa fırtınayı dindiriyor","t":"İsa kayığa binince, ardından öğrencileri de bindi."},{"n":"24","t":"Gölde ansızın büyük bir fırtına koptu. Öyle ki, dalgalar kayığın üzerinden aşıyordu. İsa ise uykuya dalmıştı."},{"n":"25","t":"Öğrenciler gidip O'nu uyandırarak, \"Rab, kurtar bizi, batıyoruz!\" dediler."},{"n":"26","t":"İsa, \"Ey imanı kıt olanlar, neden korkuyorsunuz?\" dedi. Sonra kalkıp rüzgârı ve gölü azarladı. Ortalık sütliman oldu."},{"n":"27","t":"Hepsi hayret içinde kaldı. \"Bu nasıl bir adam ki, rüzgâr da göl de O'nun sözünü dinliyor?\" dediler."},{"n":"28","h":"Cinli iki adamın iyileştirilmesi","t":"İsa gölün karşı yakasında Gadaralıların memleketine vardığında, cine tutsak iki kişi mezarlık mağaralardan çıkıp O'nu karşıladı. Bunlar öyle tehlikeliydi ki, o yoldan kimse geçemiyordu."},{"n":"29","t":"İsa'ya, \"Ey Tanrı'nın Oğlu, bizden ne istiyorsun?\" diye bağırdılar. \"Buraya, zaman dolmadan bize işkence etmeye mi geldin?\""},{"n":"30","t":"Onlardan uzakta otlayan büyük bir domuz sürüsü vardı."},{"n":"31","t":"Cinler İsa'ya, \"Bizi kovacaksan, şu domuz sürüsüne gönder\" diye yalvardılar."},{"n":"32","t":"İsa onlara, \"Gidin!\" dedi. Cinler de adamlardan çıkıp domuzların içine girdiler. O anda bütün sürü dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu."},{"n":"33","t":"Domuzları güdenler ise kaçıp kente gittiler. Cinli adamlarla ilgili haberleri dahil, olup bitenlerin hepsini anlattılar."},{"n":"34","t":"Bunun üzerine bütün kent halkı İsa'yı karşılamaya çıktı. O'nu görünce bölgelerinden ayrılması için yalvardılar."}]},{"ch":9,"verses":[{"n":"1","h":"Bir felçlinin iyileştirilmesi","t":"İsa bir kayığa binip karşı kıyıya geçti ve kendi kentine gitti."},{"n":"2","t":"Kendisine, şilteye yatırılmış felçli bir adam getirdiler. Onların imanını gören İsa felçliye, \"Oğlum, cesur ol, günahların bağışlandı\" dedi."},{"n":"3","t":"Bunun üzerine bazı din bilginleri içlerinden, \"Bu adam Tanrı'ya küfrediyor!\" dediler."},{"n":"4","t":"Onların ne düşündüklerini bilen İsa dedi ki, \"Yüreğinizde neden kötü düşüncelere yer veriyorsunuz?"},{"n":"5","t":"Hangisi daha kolay? 'Günahların bağışlandı' demek mi, yoksa 'Kalk, yürü' demek mi?"},{"n":"6","t":"Ne var ki, İnsanoğlu'nun yeryüzünde günahları bağışlama yetkisine sahip olduğunu bilesiniz diye…\" Sonra felçliye, \"Kalk, şilteni topla ve evine git!\" dedi."},{"n":"7","t":"Adam da kalkıp evine gitti."},{"n":"8","t":"Halk bunu görünce korkuya kapıldı. İnsana böyle bir yetki veren Tanrı'yı yücelttiler."},{"n":"9","h":"Matta'nın öğrencilere katılması","t":"İsa oradan geçerken, vergi toplama kulübesinde oturan birini gördü. Adı Matta olan bu adama, \"Ardımdan gel\" dedi. Adam da kalkıp İsa'nın ardından gitti."},{"n":"10","t":"Sonra İsa, Matta'nın evinde sofrada otururken, birçok vergi görevlisi ve günahkâr birçok kişi gelip O'nunla ve öğrencileriyle birlikte oturdu."},{"n":"11","t":"Bunu gören Ferisiler, İsa'nın öğrencilerine, \"Sizin öğretmeniniz neden vergi görevlileri ve günahkârlarla birlikte yemek yiyor?\" diye sordular."},{"n":"12","t":"İsa söylenenleri işitince şöyle dedi: \"Sağlamların değil, hastaların hekime ihtiyacı var."},{"n":"13","t":"Gidin de, 'Ben kurban değil, merhamet isterim' sözünün anlamını öğrenin. Çünkü ben doğrukişileri değil, günahkârları çağırmaya geldim.\""},{"n":"14","h":"Oruçla ilgili soru","t":"Bu arada Yahya'nın öğrencileri gelip İsa'ya, \"Biz ve Ferisiler oruç tutuyoruz da, senin öğrencilerin niçin tutmuyor?\" diye sordular."},{"n":"15","t":"İsa şöyle karşılık verdi: \"Güvey hâlâ aralarındayken, davetliler yas tutar mı hiç? Ama güveyin aralarından alınacağı günler gelecek, onlar işte o zaman oruç tutacaklar."},{"n":"16","t":"Hiç kimse eski bir giysiyi çekmemiş bir kumaş parçasıyla yamamaz. Çünkü konulan yama, giysiden kopar ve yırtık daha kötü duruma gelir."},{"n":"17","t":"Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa tulumlar patlar; hem şarap dökülür, hem de tulumlar mahvolur. Yeni şarap yeni tulumlara doldurulur, böylece her ikisi de korunmuş olur.\""},{"n":"18","h":"Dirilen kız, iyileşen kadın","t":"İsa onlara bu sözleri söylerken bir havra yöneticisi gelip O'nun önünde yere kapanarak, \"Kızım az önce öldü. Ama sen gelip elini onun üzerine koyarsan, dirilecek\" dedi."},{"n":"19","t":"İsa kalkıp öğrencileriyle birlikte adamın ardından gitti."},{"n":"20","t":"Tam o sırada, on iki yıldır kanaması olan bir kadın İsa'nın arkasından yetişip giysisinin eteğine dokundu."},{"n":"21","t":"İçinden, \"Giysisine bir dokunsam kurtulacağım\" diyordu."},{"n":"22","t":"İsa arkasına dönüp onu görünce, \"Cesur ol, kızım! İmanın seni kurtardı\" dedi. Ve kadın o anda iyileşti."},{"n":"23-24","t":"İsa, yöneticinin evine varıp kaval çalanlarla gürültülü kalabalığı görünce, \"Çekilin!\" dedi. \"Kız ölmedi, sadece uyuyor.\" Onlar ise kendisiyle alay ettiler."},{"n":"25","t":"Kalabalık dışarı çıkarılınca İsa içeri girip kızın elinden tuttu, kız da ayağa kalktı."},{"n":"26","t":"Bu olayın haberi o yörenin tümüne yayıldı."},{"n":"27","h":"İki körle bir dilsizin iyileştirilmesi","t":"İsa oradan ayrılırken iki kör adam, \"Ey Davut Oğlu, halimize acı!\" diye feryat ederek O'nun ardından gittiler."},{"n":"28","t":"İsa eve girince iki kör adam da yanına geldi. Onlara, \"İstediğinizi yapabileceğime inanıyor musunuz?\" diye sordu.\nAdamlar, \"İnanıyoruz, ya Rab!\" dediler."},{"n":"29","t":"Bunun üzerine İsa körlerin gözlerine dokunarak, \"İmanınıza göre olsun\" dedi."},{"n":"30","t":"Ve adamların gözleri açıldı.\nİsa, \"Sakın kimse bunu bilmesin\" diyerek onları kesin bir şekilde uyardı."},{"n":"31","t":"Onlar ise çıkıp İsa'yla ilgili haberi o yörenin tümüne yaydılar."},{"n":"32","t":"Adamlar çıkarken İsa'ya, cine tutsak dilsiz biri getirildi."},{"n":"33","t":"Cin kovulunca adamın dili çözüldü. Halk hayret içinde, \"İsrail'de böylesi hiç görülmemiştir\" diyordu."},{"n":"34","t":"Ferisiler ise, \"Cinleri, cinlerin reisinin gücüyle kovuyor\" diyorlardı."},{"n":"35","h":"Ürün bol, işçi az","t":"İsa tüm kent ve köyleri dolaştı. Buralardaki havralarda ders veriyor, Göksel Egemenliğin müjdesini duyuruyor, her hastalığı, her illeti iyileştiriyordu."},{"n":"36","t":"Kalabalıkları görünce onlara acıdı. Çünkü çobansız koyunlar gibi şaşkın ve perişandılar."},{"n":"37","t":"O zaman İsa öğrencilerine şöyle dedi: \"Ürün bol, ama işçi az."},{"n":"38","t":"Bu nedenle ürünün sahibi olan Rab'be yalvarın da, ürününü kaldıracak işçiler göndersin.\""}]},{"ch":10,"verses":[{"n":"1","h":"İsa on iki elçisini göreve gönderiyor","t":"İsa on iki öğrencisini yanına çağırdı; kötü ruhları kovmak ve her hastalığı, her illeti iyileştirmek üzere onlara kötü ruhlar üzerine yetki verdi."},{"n":"2-4","t":"Bu on iki elçinin adları şöyle: birincisi Petrus adıyla bilinen Simun, onun kardeşi Andreya, Zebedi'nin oğulları Yakup ve Yuhanna, Filipus ve Bartalmay, Tomas ve vergi görevlisi Matta, Alfay oğlu Yakup ve Taday, Yurtsever Simun ve İsa'yı sonradan ele veren Yahuda İskariyot."},{"n":"5","t":"İsa Onikileri şu buyrukla halkın arasına gönderdi: \"Diğer uluslara ait yerlere gitmeyin. Samiriyelilere ait kentlerin de hiçbirine uğramayın."},{"n":"6","t":"Bunun yerine, İsrail halkının kaybolmuş koyunlarına gidin."},{"n":"7","t":"Gittiğiniz her yerde Göklerin Egemenliğinin yaklaştığını duyurun."},{"n":"8","t":"Hastaları iyileştirin, ölüleri diriltin, cüzamlıları temiz kılın, cinleri kovun. Karşılıksız aldınız, karşılıksız verin."},{"n":"9","t":"Kuşağınıza altın, gümüş, ya da bakır para koymayın."},{"n":"10","t":"Yolculuk için ne torba, ne yedek mintan, ne çarık, ne de değnek alın. Çünkü işçi kendi yiyeceğini hak eder."},{"n":"11","t":"Hangi kent ya da köye girerseniz, orada saygıdeğer birini arayın ve ayrılıncaya dek onunla kalın."},{"n":"12","t":"Onun evine girerken, evdekilere esenlik dileyin."},{"n":"13","t":"Eğer o evdekiler buna layıksa, dilediğiniz esenlik onların üzerinde kalsın; layık değillerse, dilediğiniz esenlik size geri dönsün."},{"n":"14","t":"Sizi kabul etmeyen, sözlerinizi dinlemeyen bir evden ya da bir kentten ayrılırken, ayaklarınızın tozunu silkin."},{"n":"15","t":"Size doğrusunu söyleyeyim, yargı günü Sodom ve Gomora diyarının hali o kentin halinden daha dayanılır olacaktır."},{"n":"16","h":"Gelecekteki sıkıntılar","t":"\"İşte, kurtların arasına koyunlar gibi gönderiyorum sizi. Yılan gibi akıllı, güvercin gibi saf olun."},{"n":"17","t":"İnsanlardan sakının. Sizi mahkemelere verecekler, havralarında kamçılayacaklar."},{"n":"18","t":"Hatta benden ötürü valilerin ve kralların önüne çıkarılacaksınız. Böylece onlara ve uluslara tanıklık edeceksiniz."},{"n":"19","t":"Sizleri mahkemeye verdikleri zaman, neyi nasıl söyleyeceğinizi düşünerek kaygılanmayın. Ne söyleyeceğiniz o anda size bildirilecek."},{"n":"20","t":"Çünkü konuşacak olan siz olmayacaksınız, Babanızın Ruhu sizin aracılığınızla konuşacaktır."},{"n":"21","t":"\"Kardeş kardeşini, baba çocuğunu ölüme teslim edecek. Çocuklar anne babalarına baş kaldırıp onları öldürtecekler."},{"n":"22","t":"Benim adımdan ötürü herkes sizden nefret edecek. Ama sonuna kadar dayanan kurtulacaktır."},{"n":"23","t":"Bir kentte size zulmettikleri zaman ötekine kaçın. Size doğrusunu söyleyeyim, İnsanoğlu gelinceye dek İsrail'in tüm kentlerini dolaşmış olmayacaksınız."},{"n":"24","t":"\"Öğrenci öğretmeninden, köle de efendisinden üstün değildir."},{"n":"25","t":"Öğrencinin öğretmeni gibi, kölenin de efendisi gibi olması yeterlidir. Eğer insanlar evin efendisine Beelzebub derlerse, ev halkına daha neler demezler!"},{"n":"26","h":"Kimden korkmalı","t":"\"Bunun için onlardan korkmayın. Örtülü olup da açığa çıkarılmayacak, gizli olup da bilinmeyecek hiçbir şey yoktur."},{"n":"27","t":"Size karanlıkta söylediklerimi, siz gün ışığında söyleyin. Kulağınıza fısıldananı, damlardan duyurun."},{"n":"28","t":"Bedeni öldüren, ama canı öldürmeye gücü yetmeyenlerden korkmayın. Hem canı hem de bedeni cehennemde mahvedecek güçte olan Tanrı'dan korkun."},{"n":"29","t":"İki serçe bir meteliğe satılmıyor mu? Ama Babanızın oluru olmadan bunlardan bir teki bile yere düşmez."},{"n":"30","t":"Size gelince, başınızdaki saçlar bile tek tek sayılıdır."},{"n":"31","t":"Öyleyse korkmayın, siz birçok serçeden daha değerlisiniz."},{"n":"32","t":"\"İnsanların önünde beni açıkça kabul eden herkesi, ben de göklerde olan Babamın önünde açıkça kabul edeceğim."},{"n":"33","t":"İnsanların önünde beni inkâr edeni, ben de göklerde olan Babamın önünde inkâr edeceğim."},{"n":"34","h":"İsa'ya layık olmak","t":"\"Yeryüzüne barış getirmeye geldiğimi sanmayın! Ben barış değil, kılıç getirmeye geldim."},{"n":"35","t":"Çünkü ben oğulla babasının, kızla annesinin, gelinle kaynanasının arasına ayrılık sokmaya geldim."},{"n":"36","t":"'İnsanın düşmanları, kendi ev halkı olacaktır.'"},{"n":"37","t":"Annesini ya da babasını beni sevdiğinden çok seven, bana layık değildir. Oğlunu ya da kızını beni sevdiğinden çok seven, bana layık değildir."},{"n":"38","t":"Çarmıhını yüklenip ardımdan gelmeyen, bana layık değildir."},{"n":"39","t":"Canını kurtaran, onu yitirecek. Benim uğruma canını yitiren ise onu kurtaracaktır."},{"n":"40","t":"\"Sizi kabul eden, beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur."},{"n":"41","t":"Bir peygamberi, peygamber olduğu için kabul eden, peygambere yaraşan bir ödül alacak. Doğru bir adamı, doğru biri olduğu için kabul eden, doğru adama yaraşan bir ödül alacak."},{"n":"42","t":"Bu sıradan kişilerden herhangi birine, öğrencim olduğu için bir bardak soğuk su bile içiren, size doğrusunu söyleyeyim, ödülsüz kalmayacaktır.\""}]},{"ch":11,"verses":[{"n":"1","h":"İsa ve Vaftizci Yahya","t":"İsa, on iki öğrencisine bütün bu buyrukları verdikten sonraonların kentlerinde ders vermek ve Tanrı sözünü duyurmak üzere oradan ayrıldı."},{"n":"2-3","t":"Tutukevinde bulunan Yahya, Mesih'in yaptığı işleri duyunca, O'na gönderdiği öğrencileri aracılığıyla şunu sordu: \"Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?\""},{"n":"4","t":"İsa onlara şöyle karşılık verdi: \"Gidin, işitip gördüklerinizi Yahya'ya bildirin."},{"n":"5","t":"Körlerin gözleri açılıyor, kötürümler yürüyor, cüzamlılar temiz kılınıyor, sağırlar işitiyor, ölüler diriliyor ve müjde yoksullara duyuruluyor."},{"n":"6","t":"Benden ötürü sendeleyip düşmeyene ne mutlu!\""},{"n":"7","t":"Yahya'nın öğrencileri ayrılırken İsa halka Yahya'dan söz etmeye başladı. \"Çöle ne görmeye gittiniz?\" dedi. \"Rüzgârda sallanan bir kamış mı?"},{"n":"8","t":"Söyleyin, ne görmeye gittiniz? Zarif giysilere bürünmüş bir adam mı? Oysa zarif giysiler giyenler, kralların saraylarında bulunur."},{"n":"9","t":"Öyleyse ne görmeye gittiniz? Bir peygamber mi? Evet! Ve size şunu söyleyeyim, gördüğünüz kişi peygamberden de üstündür."},{"n":"10","t":"'Bak, habercimi senin önünden gönderiyorum;\no önden gidip senin yolunu hazırlayacak'\ndiye yazılmış olan sözler onunla ilgilidir."},{"n":"11","t":"Size doğrusunu söyleyeyim, kadından doğanlar arasında, Vaftizci Yahya'dan daha üstün olanı ortaya çıkmamıştır. Bununla birlikte, Göklerin Egemenliğinde en küçük olan, ondan üstündür."},{"n":"12","t":"Vaftizci Yahya'nın ortaya çıktığı günden bu yana Göklerin Egemenliği zorlanıyor, zorlu kişiler onu ele geçirmeye çalışıyor."},{"n":"13","t":"Yahya'ya dek tüm peygamberlerle Kutsal Yasa, olacakları önceden bildirdiler."},{"n":"14","t":"Eğer bunu kabul etmek isterseniz, gelecek olan İlyas odur."},{"n":"15","t":"Kulağı olan, işitsin!"},{"n":"16-17","t":"\"Ben bu kuşağın insanlarını neye benzeteyim? Çarşı meydanlarında oturup arkadaşlarına,\n'Size kaval çaldık, oynamadınız;\nağıt yaktık, dövünmediniz'\ndiye seslenen çocuklara benziyorlar."},{"n":"18","t":"Yahya geldiği zaman oruç tutup içkiden kaçındı, ona 'cinli' diyorlar."},{"n":"19","t":"İnsanoğlu geldiği zaman hem yedi, hem içti. Bu kez de diyorlar ki, 'Şu obur ve ayyaş adama bakın! Vergi görevlileri ve günahkârlarla dost oldu!' Ne var ki bilgelik, ortaya koyduğu işlerle doğrulanır.\""},{"n":"20-21","h":"Tövbe etmeyen kentler","t":"Sonra İsa, mucizelerinin çoğunu yapmış olduğu kentleri, tövbe etmedikleri için şöyle azarlamaya başladı: \"Vay haline, ey Horazin! Vay haline, ey Beytsayda! Sizlerde yapılan mucizeler Sur ve Sayda'da yapılmış olsaydı, onlar çoktan çulla örtünüp kül içinde oturarak tövbe etmiş olurlardı."},{"n":"22","t":"Size şunu söyleyeyim, yargı günü Sur ve Sayda'nın hali sizinkinden daha dayanılır olacak!"},{"n":"23","t":"Ya sen, ey Kefernahum, göğe mi çıkarılacaksın? Hayır, sen ta ölüler diyarına ineceksin! Çünkü sende yapılan mucizeler Sodom'da yapılmış olsaydı, o kent bugüne dek ayakta kalırdı."},{"n":"24","t":"Sana şunu söyleyeyim, yargı günü Sodom diyarının hali, seninkinden daha dayanılır olacak!\""},{"n":"25","h":"Yorgunlara müjde","t":"İsa bundan sonra şöyle dedi: \"Baba, göğün ve yerin Rabbi! Bu gerçekleri bilge ve akıllı kişilerden gizleyip küçük çocuklara açtığın için sana şükrederim."},{"n":"26","t":"Evet Baba, bunun böyle olması senin isteğindi."},{"n":"27","t":"\"Babam her şeyi bana emanet etti. Oğul'u, Baba'dan başka kimse tanımaz. Oğul'dan ve Oğul'un Baba'yı tanıtmayı dilediği kişilerden başkası da Baba'yı tanımaz."},{"n":"28","t":"\"Ey bütün yorgunlar ve yükü ağır olanlar! Bana gelin, ben size huzur veririm."},{"n":"29","t":"Ben yumuşak huylu ve alçakgönüllüyüm. Boyunduruğuma girin ve benden öğrenin, böylece canlarınız huzur bulur."},{"n":"30","t":"Boyunduruğum kolay taşınır, vereceğim yük de hafiftir.\""}]},{"ch":12,"verses":[{"n":"1","h":"Sept günü sorunu","t":"O sıralarda, bir Sept günü İsa ekinler arasından geçiyordu. Acıkmış olan öğrencileri başakları koparıp yemeye başladılar."},{"n":"2","t":"Bunu gören Ferisiler İsa'ya, \"Bak, senin öğrencilerin Sept günü yapılması yasak olanı yapıyorlar\" dediler."},{"n":"3","t":"İsa onlara, \"Davut'un, yanındakilerle birlikte acıkınca ne yaptığını okumadınız mı?\" diye sordu."},{"n":"4","t":"\"Tanrı'nın evine girdi, kendisinin ve yanındakilerin yemesi yasak olan, ancak kâhinlerin yiyebileceği adak ekmeklerini yedi."},{"n":"5","t":"Ya da kâhinlerin her hafta tapınakta Sept günüyle ilgili buyruğu çiğnedikleri halde suçlu duruma düşmediklerini Kutsal Yasa'da okumadınız mı?"},{"n":"6","t":"Size şunu söyleyeyim, burada tapınaktan daha üstün bir şey var."},{"n":"7","t":"Eğer siz, 'Ben kurban değil, merhamet isterim' sözünün anlamını bilseydiniz, suçsuz kişileri yargılamazdınız."},{"n":"8","t":"Çünkü İnsanoğlu Sept gününün de Rabbidir.\""},{"n":"9","t":"İsa oradan ayrılıp onların havrasına gitti."},{"n":"10","t":"Orada eli sakat bir adam vardı. İsa'yı suçlamak amacıyla kendisine, \"Sept günü bir hastayı iyileştirmek Kutsal Yasa'ya uygun mudur?\" diye sordular."},{"n":"11","t":"İsa onlara şu karşılığı verdi: \"Hanginizin bir koyunu olur da Sept günü çukura düşerse onu tutup çıkarmaz?"},{"n":"12","t":"İnsan, koyundan ne kadar daha değerlidir! O halde Sept günü iyilik yapmak Yasa'ya uygundur.\""},{"n":"13","t":"Sonra adama, \"Elini uzat\" dedi. Adam elini uzattı. Sakat el, öbürü gibi eski sağlam durumuna geliverdi."},{"n":"14","t":"Dışarı çıkan Ferisiler ise İsa'yı yok etmek için anlaştılar."},{"n":"15","h":"Tanrı'nın seçtiği kul","t":"İsa bunu bildiği için oradan ayrıldı. Birçok kişi O'nun ardından gitti, O da hepsini iyileştirdi."},{"n":"16","t":"Kendisini başkalarınatanıtmamaları için onları uyardı."},{"n":"17-18","t":"Bu, Yeşaya peygamber aracılığıyla bildirilen şu sözün yerine gelmesi için oldu:\n\"İşte, benim seçtiğim kulum,\ncanımın hoşnut olduğu sevgili kulum.\nRuhumu O'nun üzerine koyacağım,\nO da adaleti uluslara ilan edecek."},{"n":"19","t":"Çekişip bağırmayacak,\nyollarda kimse O'nun sesini duymayacak."},{"n":"20","t":"Ezilmiş kamışı kırmayacak,\ntüten fitili söndürmeyecek,\nve sonunda adaleti zafere ulaştıracak."},{"n":"21","t":"Uluslar da O'nun adına ümit bağlayacak.\""},{"n":"22","h":"İsa ve Beelzebub","t":"Daha sonra İsa'ya, cine tutsak, kör ve dilsiz biri getirildi. İsa adamı iyileştirdi. Öyle ki, adamın dili çözüldü, gözleri görmeye başladı."},{"n":"23","t":"Bütün kalabalık şaşırıp kaldı. \"Bu, Davut'un Oğlu olabilir mi?\" diye soruyorlardı."},{"n":"24","t":"Ferisiler bunu duyunca, \"Bu adam cinleri, ancak cinlerin reisi Beelzebub'un gücüyle kovuyor\" dediler."},{"n":"25","t":"Onların ne düşündüğünü bilen İsa şöyle dedi: \"Kendi içinde bölünmüş olan her ülke yıkıma uğrar. Kendi içinde bölünmüş hiçbir kent ya da ev ayakta kalamaz."},{"n":"26","t":"Eğer Şeytan Şeytan'ı kovarsa, kendi içinde bölünmüş demektir. Bu durumda onun egemenliği nasıl ayakta kalabilir?"},{"n":"27","t":"Eğer ben cinleri Beelzebub'un gücüyle kovuyorsam, sizin adamlarınız cinleri kimin gücüyle kovuyorlar? Sizi bu durumda kendi adamlarınız yargılayacak."},{"n":"28","t":"Ama ben cinleri Tanrı'nın Ruhuyla kovuyorsam, Tanrı'nın Egemenliği üzerinize gelmiş demektir."},{"n":"29","t":"\"Bir kimse güçlü adamın evine girip onun malını nasıl çalabilir? Ancak önceden o güçlü adamı bağlarsa, onun evini soyabilir."},{"n":"30","t":"\"Benden yana olmayan bana karşıdır. Benimle birlikte toplamayan dağıtıyor demektir."},{"n":"31","t":"Bunun için size diyorum ki, insanların işlediği her günah, ettiği her küfür bağışlanacak; ama Ruh'a karşı yapılan küfür bağışlanmayacak."},{"n":"32","t":"İnsanoğlu'na karşı bir söz söyleyen, bağışlanacak; ama Kutsal Ruh'a karşı bir söz söyleyen, ne bu çağda, ne de gelecek çağda bağışlanacaktır."},{"n":"33","t":"\"Ya ağacı iyi, meyvesini de iyi sayın; ya da ağacı kötü, meyvesini de kötü sayın. Çünkü her ağaç meyvesinden tanınır."},{"n":"34","t":"Sizi engerekler soyu! Kötü olan sizler nasıl iyi sözler söyleyebilirsiniz? Çünkü ağız yürekten taşanı söyler."},{"n":"35","t":"İyi insan, içindeki iyilik hazinesinden iyilik, kötü insan ise içindeki kötülük hazinesinden kötülük çıkarır."},{"n":"36","t":"Size şunu söyleyeyim, insanlar, söyleyecekleri her boş söz için yargı gününde hesap verecekler."},{"n":"37","t":"Kendi sözlerinizle aklanacak, yine kendi sözlerinizle suçlu çıkarılacaksınız.\""},{"n":"38","h":"Yunus'un belirtisi","t":"Bu arada bazı din bilginleri ve Ferisiler söz alarak şöyle dediler: \"Öğretmenimiz, senden doğaüstü bir belirti görmek istiyoruz.\""},{"n":"39","t":"İsa onlara şu karşılığı verdi: \"Kötü ve vefasız kuşak bir belirti istiyor! Ama ona Yunus peygamberin belirtisinden başka bir belirti gösterilmeyecek."},{"n":"40","t":"Yunus, nasıl üç gün üç gece o koca balığın karnında kaldıysa, İnsanoğlu da üç gün üç gece yerin bağrında kalacak."},{"n":"41","t":"Ninova halkı, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü Ninovalılar, Yunus'un çağrısı üzerine tövbe ettiler. Bakın, Yunus'tan daha üstün olan buradadır."},{"n":"42","t":"Güney Kraliçesi, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü kraliçe, Süleyman'ın bilgece sözlerini dinlemek için dünyanın ta öbür ucundan gelmişti. Bakın, Süleyman'dan daha üstün olan buradadır."},{"n":"43","t":"\"Kötü ruh kişinin içinden çıkınca kurak yerlerde dolanıp huzur arar, ama bulamaz."},{"n":"44","t":"O zaman, 'Çıktığım eve, kendi evime döneyim' der. Eve gelince orayı bomboş, süpürülmüş ve düzeltilmiş bulur."},{"n":"45","t":"Bunun üzerine gider, yanına kendisinden kötü yedi ruh daha alır ve eve girip yerleşirler. Böylece o kişinin son durumu ilkinden beter olur. Bu kötü kuşağın başına gelecek olan da budur.\""},{"n":"46","h":"İsa'nın annesi ve kardeşleri","t":"İsa hâlâ halka seslenmekteyken, annesiyle kardeşleri geldi. O'nunla konuşmak isteyerek dışarıda durdular."},{"n":"47","t":"Birisi İsa'ya, \"Bak\" dedi, \"annenle kardeşlerin dışarıda duruyor, seninle konuşmak istiyorlar.\""},{"n":"48","t":"İsa, kendisiyle konuşana şu karşılığı verdi: \"Kimdir annem, kimdir kardeşlerim?\""},{"n":"49","t":"Eliyle öğrencilerini göstererek, \"İşte annem, işte kardeşlerim!\" dedi."},{"n":"50","t":"\"Göklerdeki Babamın isteğini kim yerine getirirse, kardeşim, kızkardeşim ve annem odur.\""}]},{"ch":13,"verses":[{"n":"1","h":"Tohum benzetmesi","t":"Aynı gün İsa evden çıktı, gidip gölün kıyısında oturdu."},{"n":"2","t":"Çevresinde öyle büyük bir kalabalık toplandı ki, kendisi bir kayığa binip oturdu. Bütün kalabalık kıyıda duruyordu."},{"n":"3","t":"İsa onlara benzetmelerle birçok şey anlattı. \"Bakın\" dedi, \"ekincinin biri tohum ekmeye çıkmış."},{"n":"4","t":"Ektiği tohumlardan kimi yol kenarına düşmüş. Kuşlar gelip bunları yemiş."},{"n":"5","t":"Kimi, toprağı az olan kayalık yerlere düşmüş. Toprak derin olmadığından hemen filizlenmişler."},{"n":"6","t":"Ne var ki, güneş doğunca kavrulmuşlar, kök salamadıkları için kuruyup gitmişler."},{"n":"7","t":"Kimi, dikenler arasına düşmüş. Dikenler büyümüş, filizleri boğmuş."},{"n":"8","t":"Kimi ise iyi toprağa düşmüş. Bazısı yüz, bazısı altmış, bazısı da otuz kat ürün vermiş."},{"n":"9","t":"Kulağı olan işitsin!\""},{"n":"10","t":"Öğrencileri gelip İsa'ya, \"Halka neden benzetmelerle sesleniyorsun?\" diye sordular."},{"n":"11","t":"İsa şu cevabı verdi: \"Göklerin Egemenliğinin sırlarını anlama yeteneği size verildi, ama onlara verilmedi."},{"n":"12","t":"Kimde varsa, ona daha çok verilecek ve o bolluk içinde olacak. Ama kimde yoksa, kendisinde olan da elinden alınacak."},{"n":"13","t":"Onlara benzetmelerle seslenmemin nedeni budur. Çünkü,\n'Gördükleri halde görmezler.\nDuydukları halde duymaz ve anlamazlar.'"},{"n":"14","t":"\"Yeşaya'nın şu peygamberlik sözü onların bu durumunda gerçekleşmiş oluyor:\n'Duyacak duyacak, ama hiç anlamayacaksınız,\nbakacak bakacak, ama hiç görmeyeceksiniz!"},{"n":"15","t":"Çünkü bu halkın yüreği duygusuzlaştı,\nkulakları ağır işitir oldu.\nGözlerini de kapadılar.\nÖyle ki, gözleri görmesin,\nkulakları işitmesin, yürekleri anlamasın,\nve bana dönmesinler.\nDönselerdi, onları iyileştirirdim.'"},{"n":"16","t":"\"Ama ne mutlu size ki, gözleriniz görüyor, kulaklarınız işitiyor!"},{"n":"17","t":"Size doğrusunu söyleyeyim, nice peygamberler, nice doğru kişiler sizin gördüklerinizi görmek istediler, ama göremediler. Sizin işittiklerinizi işitmek istediler, ama işitemediler."},{"n":"18","t":"\"Şimdi ekinciyle ilgili benzetmeyi siz dinleyin."},{"n":"19","t":"Her kim Göksel Egemenlikle ilgili sözü işitir de anlamazsa, Şeytan gelir, onun yüreğine ekileni söker götürür. Yol kenarına ekilen tohum işte budur."},{"n":"20-21","t":"Kayalık yerlere ekilen ise işittiği sözü hemen sevinçle kabul eden, ama kök salamadığı için ancak bir süre dayanan kişidir. Böyle biri Tanrı sözünden ötürü sıkıntı ya da zulme uğrayınca hemen sendeleyip düşer."},{"n":"22","t":"Dikenler arasında ekilen de şudur: sözü işitir, ama dünyasal kaygılar ve zenginliğin aldatıcılığı sözü boğar ve ürün vermesini engeller."},{"n":"23","t":"İyi toprağa ekilen tohum ise, sözü işitip anlayan birine benzer. Böylesi elbette ürün verir, kimi yüz, kimi altmış, kimi de otuz kat.\""},{"n":"24","h":"Deliceler benzetmesi","t":"İsa onlara başka bir benzetme anlattı: \"Göklerin Egemenliği, tarlasına iyi tohum eken adama benzer\" dedi."},{"n":"25","t":"\"Ne var ki, herkes uyurken, adamın düşmanı gelmiş ve buğdayın arasına delice ekip gitmiş."},{"n":"26","t":"Ekin gelişip başak salınca, deliceler de görünmüş."},{"n":"27","t":"\"Mal sahibinin köleleri gelip ona şöyle demişler: 'Efendimiz, sen tarlana iyi tohum ekmedin mi? Öyleyse delice nereden çıktı?'"},{"n":"28","t":"\"O da onlara, 'Bunu bir düşman yapmıştır' demiş.\n\"'Gidip deliceleri toplamamızı ister misin?' diye sormuş köleler."},{"n":"29","t":"\"'Hayır' demiş. 'Deliceleri toplarken belki buğdayı da sökersiniz."},{"n":"30","t":"Ekinin biçileceği zamana kadar bırakın, ikisi yan yana büyüsün. Ekin biçme zamanı gelince orakçılara diyeceğim ki,Önce deliceleri toplayın, yakılmak üzere demet yapın. Buğdayı ise toplayıp ambarıma koyun.'\""},{"n":"31","h":"Hardal tanesi ve maya benzetmeleri","t":"İsa onlara bir benzetme daha anlattı: \"Göklerin Egemenliği bir adamın alıp tarlasına ektiği hardal tanesine benzer\" dedi."},{"n":"32","t":"\"Hardal tüm tohumların en küçüğü olduğu halde, gelişince bahçe bitkilerinin boyunu aşar, ağaç olur. Öyle ki, gökte uçan kuşlar gelip dallarında barınır.\""},{"n":"33","t":"İsa onlara başka bir benzetme anlattı: \"Göklerin Egemenliği, bir kadının alıp tüm hamuru kabartmak için üç ölçek una karıştırdığı mayaya benzer.\""},{"n":"34","t":"İsa bütün bunları halka benzetmelerle anlattı. Benzetme kullanmadan onlara hiçbir şey anlatmazdı."},{"n":"35","t":"Bu, peygamber aracılığıyla bildirilen şu sözün yerine gelmesi için oldu:\n\"Ağzımı benzetmeler anlatarak açacağım,\ndünyanın kuruluşundan beri\ngizli kalmış sırları dile getireceğim.\""},{"n":"36","h":"Deliceler benzetmesi açıklanıyor","t":"Bundan sonra İsa halkı bırakıp eve gitti. Öğrencileri yanına gelip, \"Tarladaki delicelerle ilgili benzetmeyi bize açıkla\" dediler."},{"n":"37","t":"İsa, \"İyi tohumu eken, İnsanoğlu'dur\" diye karşılık verdi."},{"n":"38","t":"\"Tarla ise dünyadır. İyi tohum, Göksel Egemenliğin oğulları, deliceler de kötü olanın oğullarıdır."},{"n":"39","t":"Deliceleri eken düşman, İblis'tir. Ekin biçme zamanı, çağın sonu; orakçılar ise meleklerdir."},{"n":"40","t":"\"Deliceler nasıl toplanıp ateşte yakılıyorsa, çağın sonunda da böyle olacak."},{"n":"41-42","t":"İnsanoğlu meleklerini gönderecek, onlar da insanları günaha düşüren her şeyi, kötülük yapan herkesi O'nun egemenliğinden toplayıp kızgın fırına atacaklar. Orada ağlayış ve diş gıcırtısı olacaktır."},{"n":"43","t":"Doğru kişiler o zaman Babalarının egemenliğinde güneş gibi parlayacaklar. Kulağı olan işitsin!"},{"n":"44","h":"Define ve inci benzetmeleri","t":"\"Göklerin Egemenliği, tarlada saklı bir defineye benzer. Bunu bulan adam yine saklamış. Sevinç içinde gitmiş, varını yoğunu satıp o tarlayı satın almış."},{"n":"45","t":"\"Yine Göklerin Egemenliği, güzel inciler arayan bir tüccara benzer."},{"n":"46","t":"Tüccar, çok değerli bir inci bulunca gitmiş, varını yoğunu satıp o inciyi satın almış."},{"n":"47","h":"Ağ benzetmesi","t":"\"Yine Göklerin Egemenliği, denize atılan ve her çeşit balığı toplayan bir ağa benzer."},{"n":"48","t":"Ağ dolunca onu kıyıya çekerler. Yere oturup yararlı balıkları seçer ve kaplara koyarlar, yararsız olanları atarlar."},{"n":"49-50","t":"Çağın sonunda da böyle olacak. Meleklergelip kötü kişileri doğruların arasından ayıracaklar ve onları kızgın fırına atacaklar. Orada ağlayış ve diş gıcırtısı olacaktır."},{"n":"51","t":"\"Bütün bunları anladınız mı?\" diye sordu İsa.\nO'na, \"Evet\" karşılığını verdiler."},{"n":"52","t":"O da onlara, \"İşte böylece Göklerin Egemenliği için eğitilmiş her din bilgini, hazinesinden hem yeni hem eski değerler çıkaran bir mal sahibine benzer\" dedi."},{"n":"53","h":"İsa reddediliyor","t":"İsa bütün bu benzetmeleri anlattıktan sonra oradan ayrıldı."},{"n":"54","t":"Kendi memleketine gitti ve oradaki havrada halka ders vermeye başladı. Halk şaşıp kalmıştı. \"Adamın bu bilgeliği ve mucizeler yaratan gücü nereden geliyor?\" diyorlardı."},{"n":"55","t":"\"Marangozun oğlu değil mi bu? Annesinin adı Meryem değil mi? Yakup, Yusuf, Simun ve Yahuda O'nun kardeşleri değil mi?"},{"n":"56","t":"Kızkardeşlerinin hepsi aramızda yaşamıyor mu? O halde O'nun bütün bu yaptıkları nereden geliyor?\""},{"n":"57","t":"Ve gücenip O'nu reddettiler.\nAma İsa onlara şöyle dedi: \"Bir peygamber, kendi memleketinden ve evinden başka yerde hor görülmez.\""},{"n":"58","t":"İmansızlıklarından ötürü İsa orada pek fazla mucize yapmadı."}]},{"ch":14,"verses":[{"n":"1-2","h":"Yahya peygamberin öldürülmesi","t":"O günlerde İsa'yla ilgili haberleri duyan bölge kralı Hirodes, adamlarına, \"Bu, Vaftizci Yahya'dır\" dedi. \"Ölümden dirilmiştir. Olağanüstü güçlerin O'nda etkin olmasının nedeni de budur.\""},{"n":"3","t":"Hirodes, kardeşi Filipus'un karısı Hirodiya yüzünden Yahya'yı tutuklatmış, bağlatıp zindana attırmıştı."},{"n":"4","t":"Çünkü Yahya Hirodes'e, \"O kadınla evlenmen Kutsal Yasa'ya aykırıdır\" demişti."},{"n":"5","t":"Hirodes Yahya'yı öldürtmek istemiş, ama halktan korkmuştu. Çünkü halk Yahya'yı peygamber sayıyordu."},{"n":"6-7","t":"Hirodes'in doğum günü şenliği sırasında Hirodiya'nın kızı ortaya çıkıp dans etti. Bu, Hirodes'in öyle hoşuna gitti ki, ant içerek kıza her ne dilerse vereceğini söyledi."},{"n":"8","t":"Kız, annesinin kışkırtmasıyla, \"Bana şimdi, bir tepsi üzerinde Vaftizci Yahya'nın başını ver\" dedi."},{"n":"9","t":"Kral buna çok üzüldüyse de, konuklarının önünde içtiği anttan ötürü bu dileğin yerine getirilmesini buyurdu."},{"n":"10","t":"Adam gönderip zindanda Yahya'nın başını kestirdi."},{"n":"11","t":"Bir tepsi üzerinde getirilen baş genç kıza verildi, kız da bunu annesine götürdü."},{"n":"12","t":"Yahya'nın öğrencileri gelip cesedi aldılar ve gömdüler. Sonra gidip İsa'ya haber verdiler."},{"n":"13","h":"İsa beş bin kişiyi doyuruyor","t":"İsa bunu duyunca, tek başına tenha bir yere çekilmek üzerebir kayıkla oradan ayrıldı. Bunu öğrenen halk, kentlerden çıkıp O'nu yaya olarak izledi."},{"n":"14","t":"İsa kayıktan inince büyük bir kalabalıkla karşılaştı. Onlara acıdı ve hasta olanlarını iyileştirdi."},{"n":"15","t":"Akşama doğru öğrencileri O'nun yanına gelip dediler ki, \"Burası ıssız bir yer, vakit de artık geç oldu. Halkı salıver de köylere gidip kendilerine yiyecek alsınlar.\""},{"n":"16","t":"İsa, \"Gitmelerine gerek yok, onlara siz yiyecek verin\" dedi."},{"n":"17","t":"Öğrenciler, \"Burada beş ekmekle iki balıktan başka bir şeyimiz yok ki\" dediler."},{"n":"18","t":"İsa, \"Onları buraya, bana getirin\" dedi."},{"n":"19","t":"Halka çimenlerin üzerine oturmalarını buyurduktan sonra, beş ekmekle iki balığı aldı, gözlerini göğe dikerek şükran duasını yaptı; sonra ekmekleri bölüp öğrencilerine verdi, onlar da halka dağıttılar."},{"n":"20","t":"Herkes yiyip doyduktan sonra on iki sepet dolusu yemek artığı topladılar."},{"n":"21","t":"Yemek yiyenlerin sayısı, kadın ve çocuklar hariç, yaklaşık beş bin erkekti."},{"n":"22","h":"İsa su üstünde yürüyor","t":"Bundan hemen sonra İsa öğrencilerine, kayığa binip kendisinden önce karşı yakaya geçmelerini buyurdu. Bu arada kendisi halkı salıverecekti."},{"n":"23","t":"Halkı salıverdikten sonra dua etmek için tek başına dağa çıktı. Akşam olurken orada yalnızdı."},{"n":"24","t":"O sırada kayık kıyıdan bir hayli uzakta dalgalarla boğuşuyordu. Çünkü rüzgâr karşı yönden esiyordu."},{"n":"25","t":"Sabaha karşı İsa, gölün üstünde yürüyerek onlara yaklaştı."},{"n":"26","t":"Öğrenciler, O'nun gölün üstünde yürüdüğünü görünce dehşete kapıldılar. \"Bu bir hayalet!\" diyerek korkuyla bağrıştılar."},{"n":"27","t":"Ama İsa hemen onlara seslenerek, \"Cesur olun! Ben'im, korkmayın!\" dedi."},{"n":"28","t":"Petrus buna karşılık, \"Ya Rab\" dedi, \"eğer sen isen, buyruk ver de su üstünde yürüyerek sana geleyim.\""},{"n":"29","t":"İsa, \"Gel!\" dedi.\nPetrus da kayıktan indi, su üstünde yürüyerek İsa'ya yaklaştı."},{"n":"30","t":"Ama rüzgârın ne kadar güçlü estiğini görünce korktu, batmaya başladı. \"Rab, beni kurtar!\" diye bağırdı."},{"n":"31","t":"İsa hemen elini uzatıp onu tuttu. Ona, \"Ey imanı kıt adam, neden kuşkuya düştün?\" dedi."},{"n":"32","t":"Onlar kayığa bindikten sonra rüzgâr dindi."},{"n":"33","t":"Kayıktakiler, \"Sen gerçekten Tanrı'nın Oğlusun\" diyerek O'na tapındılar."},{"n":"34","t":"Karşı yakaya vardıklarında Ginesar'da karaya çıktılar."},{"n":"35","t":"Oranın halkı İsa'yı tanıyınca bütün yöreye haber salıp hastaların hepsini O'na getirdiler."},{"n":"36","t":"Sadece giysisinin eteğine dokunmalarına izin vermesi için yalvardılar. Dokunanların hepsi de iyileşti."}]},{"ch":15,"verses":[{"n":"1-2","h":"İnsanı kirleten nedir?","t":"Bu sırada Kudüs'ten bazı Ferisiler ve din bilginleri İsa'ya gelip şunu sordular: \"Senin öğrencilerin neden atalarımızın geleneğine karşı geliyorlar? Yemekten önce ellerini yıkamıyorlar.\""},{"n":"3","t":"İsa onlara şu karşılığı verdi: \"Ya siz, neden geleneğiniz uğruna Tanrı buyruğuna karşı geliyorsunuz?"},{"n":"4","t":"Tanrı şöyle buyurdu: 'Annene babana saygı göster' ve, 'Annesine ya da babasına söven mutlaka ölümle cezalandırılsın.'"},{"n":"5-6","t":"Ama siz, 'Her kim anne ya da babasına, benden alacağın tüm maddi yardım Tanrı'ya adanmıştır derse, artık babasına saygı göstermek zorunda değildir' diyorsunuz. Böylelikle, geleneğiniz uğruna Tanrı'nın sözünü geçersiz kılmış oluyorsunuz."},{"n":"7-8","t":"Ey ikiyüzlüler! Yeşaya'nın sizinle ilgili şu peygamberlik sözü ne doğrudur:\n'Bu halk dudaklarıyla beni sayar,\nama yürekleri benden uzaktır."},{"n":"9","t":"Bana boşuna taparlar.\nÇünkü öğrettikleri, sadece insan kurallarıdır.'\""},{"n":"10","t":"İsa, halkı yanına çağırıp onlara, \"Dinleyin ve şunu belleyin\" dedi."},{"n":"11","t":"\"İnsanı kirleten, ağzına giren değildir. Ağzından çıkandır insanı kirleten.\""},{"n":"12","t":"Bu sırada öğrencileri O'na gelip, \"Biliyor musun, Ferisiler bu sözü duyunca gücendiler\" dediler."},{"n":"13","t":"İsa şu karşılığı verdi: \"Göksel Babamın dikmediği her fidan kökünden sökülecek."},{"n":"14","t":"Bırakın onları; onlar körlerin kör kılavuzlarıdır. Eğer kör köre kılavuzluk ederse, her ikisi de çukura düşer.\""},{"n":"15","t":"Petrus, \"Bu benzetmeyi bize açıkla\" dedi."},{"n":"16","t":"\"Siz de mi hâlâ anlamıyorsunuz?\" diye sordu İsa."},{"n":"17","t":"\"Ağza giren her şeyin mideye indiğini, oradan da ayakyoluna atıldığını bilmiyor musunuz?"},{"n":"18","t":"Ne var ki ağızdan çıkan, yürekten kaynaklanır. İnsanı kirleten de budur."},{"n":"19","t":"Çünkü kötü düşünceler, cinayet, zina, cinsel ahlaksızlık, hırsızlık, yalan tanıklık ve iftira hep yürekten kaynaklanır."},{"n":"20","t":"İnsanı kirleten bunlardır. Yıkanmamış ellerle yemek yemek insanı kirletmez.\""},{"n":"21","h":"Kenanlı kadının imanı","t":"İsa oradan ayrılıp Sur ve Sayda bölgesine geçti."},{"n":"22","t":"O yöreden Kenanlı bir kadın İsa'ya gelip, \"Ya Rab, ey Davut Oğlu, halime acı! Kızım cine tutsak, çok kötü durumda\" diye feryat etti."},{"n":"23","t":"İsa kadına hiçbir karşılık vermedi. Öğrencileri yaklaşıp, \"Sal şunu, gitsin!\" diye rica ettiler. \"Arkamızdan bağırıp duruyor.\""},{"n":"24","t":"İsa, \"Ben yalnız İsrail halkının kaybolmuş koyunlarına gönderildim\" diye cevap verdi."},{"n":"25","t":"Kadın ise yaklaşıp, \"Ya Rab, bana yardım et!\" diyerek O'nun önünde yere kapandı."},{"n":"26","t":"İsa ona, \"Çocukların ekmeğini alıp köpeklere atmak doğru değildir\" dedi."},{"n":"27","t":"Kadın, \"Haklısın, Rab\" dedi. \"Ama köpekler de efendilerinin sofrasından düşen kırıntıları yer.\""},{"n":"28","t":"O zaman İsa ona şu karşılığı verdi: \"Ey kadın, imanın büyük! Dilediğin gibi olsun.\" Ve kadının kızı o saatte iyileşti."},{"n":"29","h":"İsa dört bin kişiyi doyuruyor","t":"İsa oradan ayrıldı, Celile gölünün kıyısından geçerek dağa çıkıp oturdu."},{"n":"30","t":"Yanına büyük bir kalabalık geldi. Beraberlerinde kötürüm, kör, çolak, dilsiz ve daha birçok hasta vardı. Hastaları O'nun ayaklarının dibine bıraktılar. O da onları iyileştirdi."},{"n":"31","t":"Halk, dilsizlerin konuştuğunu, çolakların sağlam oluverdiğini, körlerin gördüğünü, kötürümlerin yürüdüğünü görünce şaştı ve İsrail'in Tanrısını yüceltti."},{"n":"32","t":"İsa öğrencilerini yanına çağırıp, \"Halka acıyorum\" dedi. \"Üç gündür yanımdalar ve yiyecek hiçbir şeyleri yok. Onları aç aç evlerine göndermek istemiyorum, yolda bayılabilirler.\""},{"n":"33","t":"Öğrenciler kendisine, \"Böyle ıssız bir yerde bu kadar kalabalığı doyuracak ekmeği nereden bulalım?\" dediler."},{"n":"34","t":"İsa, \"Kaç ekmeğiniz var?\" diye sordu.\n\"Yedi ekmekle birkaç küçük balığımız var\" dediler."},{"n":"35","t":"Bunun üzerine İsa, halka yere oturmalarını buyurdu."},{"n":"36","t":"Yedi ekmekle balıkları aldı, şükredip bunları böldü, öğrencilerine verdi. Onlar da halka dağıttılar."},{"n":"37","t":"Herkes yiyip doyduktan sonra yedi küfe dolusu yemek artığı topladılar."},{"n":"38","t":"Yemek yiyenlerin sayısı, kadın ve çocuklar hariç, dört bin erkekti."},{"n":"39","t":"İsa, halkı salıverdikten sonra kayığa binip Magadan bölgesine geçti."}]},{"ch":16,"verses":[{"n":"1","h":"Doğaüstü bir belirti isteniyor","t":"Ferisilerle Sadukiler İsa'nın yanına geldiler. O'nu sınamak amacıyla kendilerine gökten bir belirti göstermesini istediler."},{"n":"2","t":"İsa onlara şu karşılığı verdi: \"Akşam olunca siz, 'Gökyüzünün rengi kızıl olduğuna göre hava iyi olacak' dersiniz."},{"n":"3","t":"Sabahleyin, 'Bugün gök kızıl ve bulutlu. Hava bozacak' dersiniz. Gökyüzünün görünümünü yorumlayabiliyorsunuz da, belirli zamanlarla ilgili belirtileri yorumlayamıyor musunuz?"},{"n":"4","t":"Kötü ve vefasız kuşak bir belirti istiyor! Ama ona Yunus'un belirtisinden başka bir belirti gösterilmeyecek.\" Sonra İsa onları bırakıp gitti."},{"n":"5","h":"Ferisilerle Sadukilerin mayası","t":"Öğrenciler gölün karşı yakasına geçerken ekmek almayı unutmuşlardı."},{"n":"6","t":"İsa onlara, \"Dikkatli olun, Ferisilerin ve Sadukilerin mayasından kaçının!\" dedi."},{"n":"7","t":"Onlar ise kendi aralarında konuşarak, \"Ekmek almadığımız için böyle diyor\" dediler."},{"n":"8","t":"Bunun farkında olan İsa şöyle dedi: \"Ey imanı kıt olanlar! Ekmeğiniz yok diye aranızda ne konuşup duruyorsunuz?"},{"n":"9-10","t":"Hâlâ anlamıyor musunuz? Beş ekmekle beş bin kişinin doyduğunu, kaçsepet dolusu yemek artığı topladığınızı hatırlamıyor musunuz? Yedi ekmekle dört bin kişinin doyduğunu, kaç küfe dolusu yemek artığı topladığınızı hatırlamıyor musunuz?"},{"n":"11","t":"Ben size, 'Ferisilerin ve Sadukilerin mayasından kaçının' derken, ekmekten söz etmediğimi nasıl oluyor da anlamıyorsunuz?\""},{"n":"12","t":"Kendilerine ekmek mayasından değil de, Ferisilerle Sadukilerin öğretisinden kaçınmalarını söylediğini o zaman anladılar."},{"n":"13","h":"Petrus'un Mesih'i tanıması","t":"İsa, Filipus Sezariyesi bölgesine geldiğinde öğrencilerine şunu sordu: \"Halk, İnsanoğlu'nun kim olduğunu söylüyor?\""},{"n":"14","t":"Öğrencileri şu karşılığı verdiler: \"Kimi Vaftizci Yahya, kimi İlyas, kimi de Yeremya ya da peygamberlerden biri olduğunu söylüyor.\""},{"n":"15","t":"İsa onlara, \"Ya siz\" dedi, \"ben kimim dersiniz?\""},{"n":"16","t":"Simun Petrus, \"Sen, yaşayan Tanrı'nın Oğlu Mesih'sin\" cevabını verdi."},{"n":"17","t":"İsa ona, \"Ne mutlu sana, Yunus oğlu Simun!\" dedi. \"Bu sırrı sana açan insan değil, göklerdeki Babamdır."},{"n":"18","t":"Ben de sana şunu söyleyeyim, sen Petrus'sun ve ben topluluğumu bu kayanın [] üzerine kuracağım. Ölüler diyarının kapıları ona karşı direnemeyecek."},{"n":"19","t":"Göklerin Egemenliğinin anahtarlarını sana vereceğim. Yeryüzünde bağlayacağın her şey göklerde de bağlanmış olacak; yeryüzünde çözeceğin her şey göklerde de çözülmüş olacak.\""},{"n":"20","t":"Bu sözlerden sonra İsa, kendisinin Mesih olduğunu kimseye söylememeleri için öğrencilerini uyardı."},{"n":"21","h":"İsa ölüp dirileceğini önceden bildiriyor","t":"Bundan sonra İsa, kendisinin Kudüs'e gitmesi, ihtiyarlar, başkâhinler ve din bilginlerinin elinden çok acı çekmesi, öldürülmesi ve üçüncü gün dirilmesi gerektiğini öğrencilerine anlatmaya başladı."},{"n":"22","t":"Bunun üzerine Petrus O'nu bir kenara çekip azarlamaya başladı. \"Tanrı korusun, ya Rab! Senin başına asla böyle bir şey gelmeyecek!\" dedi."},{"n":"23","t":"Ama İsa dönüp Petrus'a şöyle dedi: \"Çekil önümden, Şeytan! Sen yolumda engelsin. Senin düşüncelerin Tanrı'nın değil, insanın düşünceleridir.\""},{"n":"24","t":"Sonra İsa, öğrencilerine şunları söyledi: \"Ardımdan gelmek isteyen, kendini inkâr etsin, çarmıhını yüklenip beni izlesin."},{"n":"25","t":"Canını kurtarmak isteyen, onu yitirecek; canını benim uğruma yitiren ise onu kurtaracaktır."},{"n":"26","t":"İnsan bütün dünyayı kazanıp da canından olursa, bunun kendisine ne yararı olur? İnsan, kendi canına karşılık ne verebilir?"},{"n":"27","t":"İnsanoğlu, Babasının görkemi içinde melekleriyle gelecek ve herkese, yaptıklarının karşılığını verecektir."},{"n":"28","t":"Size doğrusunu söyleyeyim, burada bulunanlar arasında, İnsanoğlu'nun kendi egemenliği içinde geldiğini görmeden ölümü tatmayacak olanlar var.\""}]},{"ch":17,"verses":[{"n":"1","h":"İsa'nın görünümü değişiyor","t":"Altı gün sonra İsa, yanına yalnız Petrus, Yakup ve Yakup'un kardeşi Yuhanna'yı alarak yüksek bir dağa çıktı."},{"n":"2","t":"Orada, gözlerinin önünde İsa'nın görünümü değişti. Yüzü güneş gibi parladı, giysileri ışık gibi bembeyaz oldu."},{"n":"3","t":"O anda Musa'yla İlyas öğrencilere göründü. İsa ile konuşuyorlardı."},{"n":"4","t":"Petrus İsa'ya, \"Ya Rab\" dedi, \"burada bulunmamız ne iyi oldu! İstersen burada üç çardak kurayım: biri sana, biri Musa'ya, biri de İlyas'a.\""},{"n":"5","t":"Petrus hâlâ konuşurken, parlak bir bulut birden onları gölgeledi. Buluttan gelen bir ses, \"Sevgili Oğlum budur, O'ndan hoşnudum. O'nu dinleyin!\" dedi."},{"n":"6","t":"Öğrenciler bunu işitince, dehşet içinde yüzüstü yere kapandılar."},{"n":"7","t":"İsa gelip onlara dokundu, \"Kalkın, korkmayın!\" dedi."},{"n":"8","t":"Başlarını kaldırıp bakınca İsa'dan başka kimseyi göremediler."},{"n":"9","t":"Dağdan inerlerken İsa onlara, \"İnsanoğlu ölümden dirilmeden önce, gördüklerinizi kimseye söylemeyin\" diye buyurdu."},{"n":"10","t":"Öğrencileri O'na şunu sordular: \"Peki, din bilginleri neden önce İlyas'ın gelmesi gerektiğini söylüyorlar?\""},{"n":"11","t":"İsa, \"İlyas gerçekten gelecek ve her şeyi yeniden düzene koyacak\" diye cevap verdi."},{"n":"12","t":"\"Size şunu söyleyeyim, İlyas zaten gelmiştir, ama onu tanımadılar, ona yapmadıklarını bırakmadılar. Aynı şekilde İnsanoğlu da onların elinden acı çekecektir.\""},{"n":"13","t":"O zaman öğrenciler İsa'nın kendilerine Vaftizci Yahya'dan söz ettiğini anladılar."},{"n":"14","h":"Cinli çocuk iyileştiriliyor","t":"Kalabalığın yanına vardıklarında bir adam İsa'ya yaklaşıp O'nun önünde diz çöktü."},{"n":"15","t":"\"Ya Rab\" dedi, \"oğlumun haline acı! Çocuk saralı ve çok acı çekiyor. Sık sık ateşe ya da suya düşüyor."},{"n":"16","t":"Onu senin öğrencilerine getirdim, ama iyileştiremediler.\""},{"n":"17","t":"İsa, \"Ey imansız ve sapmış kuşak!\" dedi. \"Sizinle daha ne kadar kalacağım? Size daha ne kadar katlanacağım? Çocuğu buraya, bana getirin.\""},{"n":"18","t":"İsa cini azarlayınca, cin çocuktan çıktı, çocuk da o anda iyileşti."},{"n":"19","t":"Sonra öğrenciler tek başlarına İsa'ya gelip, \"Biz cini neden kovamadık?\" diye sordular."},{"n":"20-21","t":"İsa, \"İmanınız kıt olduğu için\" karşılığını verdi. \"Size doğrusunu söyleyeyim, bir hardal tanesi kadar imanınız olsa şu dağa, 'Buradan şuraya göç' derseniz, göçer. Sizin için imkânsız bir şey kalmaz.\""},{"n":"22-23","h":"İsa ölüp dirileceğini tekrar bildiriyor","t":"Celile'de bir araya geldiklerinde İsa onlara, \"İnsanoğlu, insanların eline teslim edilecek ve öldürülecek, ama üçüncü gündirilecek\" dedi.\nÖğrenciler buna çok kederlendiler."},{"n":"24","h":"Tapınak vergisi","t":"Kefernahum'a geldiklerinde, iki dirhemlik tapınak vergisini toplayanlar Petrus'a gelip, \"Öğretmeniniz tapınak vergisini ödemiyor mu?\" diye sordular."},{"n":"25","t":"Petrus, \"Ödüyor\" dedi.\nPetrus eve gelince, daha kendisi bir şey söylemeden İsa ona, \"Simun, ne dersin?\" dedi. \"Dünya kralları gümrük ya da vergiyi kimlerden alırlar? Kendi oğullarından mı, yabancılardan mı?\""},{"n":"26","t":"Petrus'un, \"Yabancılardan\" demesi üzerine İsa, \"O halde oğullar muaftır\" dedi."},{"n":"27","t":"\"Ama vergi toplayanları gücendirmeyelim. Göle gidip oltanı at. Tuttuğun ilk balığı çıkar, onun ağzını aç, dört dirhemlik bir akçe bulacaksın. Parayı al, ikimizin vergisi olarak onlara ver.\""}]},{"ch":18,"verses":[{"n":"1","h":"En büyük kim?","t":"Bu sırada İsa'nın öğrencileri O'na yaklaşıp, \"Göklerin Egemenliğinde en büyük kim?\" diye sordular."},{"n":"2-3","t":"İsa, yanına küçük bir çocuk çağırdı, onu orta yere dikip şöyle dedi: \"Size doğrusunu söyleyeyim, yolunuzdan dönüp küçük çocuklar gibi olmazsanız, Göklerin Egemenliğine asla giremezsiniz."},{"n":"4","t":"Kim bu çocuk gibi alçakgönüllü olursa, Göklerin Egemenliğinde en büyük odur."},{"n":"5","t":"Böyle bir çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur."},{"n":"6","t":"\"Ama kim bana iman eden bu küçüklerden birini günaha düşürürse, boynuna kocaman bir değirmen taşı asılıp denizin dibine atılması kendisi için daha iyi olur."},{"n":"7","t":"İnsanı günaha düşüren tuzaklardan ötürü vay dünyanın haline! Böyle tuzakların olması kaçınılmazdır. Ama bu tuzaklara aracılık eden kişinin vay haline!"},{"n":"8","t":"\"Eğer elin ya da ayağın seni günaha sokarsa, onu kesip at. Çolak ya da tek ayaklı olarak yaşama kavuşman, iki el iki ayak sahibi olarak sönmez ateşe atılmandan iyidir."},{"n":"9","t":"Eğer gözün seni günaha sokarsa, onu çıkarıp at. Tek gözle yaşama kavuşman, iki göz sahibi olarak cehennem ateşine atılmandan iyidir."},{"n":"10-11","t":"\"Bu küçüklerden bir tekini bile hor görmekten sakının! Size şunu söyleyeyim, onların göklerdeki melekleri, göklerde olan Babamın yüzünü her zaman görürler."},{"n":"12","h":"Kaybolmuş koyun benzetmesi","t":"\"Siz ne dersiniz? Bir adamın yüz koyunu olsa ve bunlardan biri yolunu şaşırsa, doksan dokuzunu dağlarda bırakıp yolunu şaşıranı aramaya gitmez mi?"},{"n":"13","t":"Eğer onu bulacak olursa, size doğrusunu söyleyeyim, yolunu şaşırmamış olan doksan dokuzu içinsevindiğinden daha çok onun için sevinir."},{"n":"14","t":"Bunun gibi, göklerdeki Babanız da bu küçüklerden hiçbirinin kaybolmasını istemez."},{"n":"15","h":"Bir kardeş günah işlerse","t":"\"Eğer kardeşin sana karşı günah işlerse, ona git, suçunu kendisine göster. Her şey yalnız ikinizin arasında kalsın. Kardeşin seni dinlerse, onu kazanmış olursun."},{"n":"16","t":"Ama dinlemezse, yanına bir ya da iki kişi daha al ki, söylenen her şey iki ya da üç tanığın sözüyle doğrulansın."},{"n":"17","t":"Eğer kardeşin onları dinlemek istemezse, durumu inanlılar topluluğuna bildir. İnanlılar topluluğunu da dinlemek istemezse, onu bir putperest ya da vergi görevlisi yerine koy."},{"n":"18","t":"\"Size doğrusunu söyleyeyim, yeryüzünde bağlayacağınız her şey gökte de bağlanmış olacak. Yeryüzünde çözeceğiniz her şey gökte de çözülmüş olacak."},{"n":"19","t":"Yine size şunu söyleyeyim, yeryüzünde aranızdan iki kişi, dileyecekleri herhangi bir şey için uyuşurlarsa, göklerdeki Babam dileklerini yerine getirir."},{"n":"20","t":"Nerede iki ya da üç kişi benim adımla toplanırsa, ben de orada onların arasındayım.\""},{"n":"21","h":"Acımasız köle benzetmesi","t":"Bunun üzerine Petrus İsa'ya gelip, \"Ya Rab\" dedi, \"kardeşim bana karşı kaç kez günah işlerse onu bağışlamalıyım? Yedi kez mi?\""},{"n":"22","t":"İsa ona, \"Yedi kez değil\" dedi. \"Yetmiş kere yedi kez derim sana."},{"n":"23","t":"Şöyle ki, Göklerin Egemenliği, köleleriyle hesaplaşmak isteyen bir krala benzer."},{"n":"24","t":"Kral hesap görmeye başladığında, kendisine on bin talant borcu olan bir köle getirilmiş."},{"n":"25","t":"Kölenin ödeme gücü olmadığından efendisi onun, karısının, çocuklarının ve bütün malının satılıp borcun ödenmesini buyurmuş."},{"n":"26","t":"Köle yere kapanıp efendisine, 'Bana karşı sabırlı ol! Sana bütün borcumu öderim' demiş."},{"n":"27","t":"Efendisi köleye acımış, borcunu bağışlayıp onu salıvermiş."},{"n":"28","t":"\"Ama köle çıkıp gitmiş, kendisine yüz dinar borcu olan bir başka köleye rastlamış. Onu yakalayıp, 'Borcunu öde' diyerek boğazına sarılmış."},{"n":"29","t":"Bu köle yüzüstü yere kapanmış, 'Bana karşı sabırlı ol! Sana borcumu öderim' diye yalvarmış."},{"n":"30","t":"Ama ilk köle bunu reddetmiş. Gitmiş, borcunu ödeyinceye dek kalmak üzere adamı zindana attırmış."},{"n":"31","t":"Öteki köleler, olanları görünce çok üzülmüşler. Efendilerine gidip bütün olup bitenleri anlatmışlar."},{"n":"32","t":"\"Bunun üzerine efendisi köleyi yanına çağırmış. 'Ey kötü köle!' demiş. 'Bana yalvardığın için bütün borcunu bağışladım."},{"n":"33","t":"Benim sana acıdığım gibi, senin de köle arkadaşına acıman gerekmez miydi?'"},{"n":"34","t":"Bu öfkeyle efendisi, tüm borcunu ödeyinceye dek onu işkencecilere teslim etmiş."},{"n":"35","t":"\"Eğer her biriniz kardeşini yürekten bağışlamazsa, göksel Babam da size öyle davranacaktır.\""}]},{"ch":19,"verses":[{"n":"1","h":"Boşanmayla ilgili soru","t":"İsa, bu konuşmasını bitirdikten sonra Celile'den ayrılıp Yahudiye sınırlarına, Şeria nehrinin ötesine geçti."},{"n":"2","t":"Büyük halk toplulukları da O'nun ardından gitti. Hasta olanlarını orada iyileştirdi."},{"n":"3","t":"İsa'nın yanına gelen bazı Ferisiler, O'nu sınamak amacıyla şunu sordular: \"Bir adamın, herhangi bir nedenle karısını boşaması Kutsal Yasa'ya uygun mudur?\""},{"n":"4-5","t":"İsa şu karşılığı verdi: \"Kutsal Yazıları okumadınız mı? Yaradan, ta başlangıçtan insanları 'erkek ve dişi olarak yarattı' ve şöyle dedi: 'Bu nedenle adam annesini babasını bırakacak, karısına bağlanacak ve ikisi tek bir beden olacaklar.'"},{"n":"6","t":"Şöyle ki, onlar artık iki değil, tek bedendir. O halde Tanrı'nın birleştirdiğini, insan ayırmasın.\""},{"n":"7","t":"Ferisiler İsa'ya, \"Öyleyse\" dediler, \"Musa neden erkeğin, karısını, bir boş kâğıdı verip boşayabileceğini söyledi?\""},{"n":"8","t":"İsa onlara, \"Musa, karılarınızı boşamanıza, yüreklerinizin katılığından ötürü izin verdi\" dedi. \"Başlangıçta bu böyle değildi."},{"n":"9","t":"Ben size şunu söyleyeyim, karısını cinsel ahlaksızlıktan başka bir nedenle boşayıp başkasıyla evlenen, zina etmiş olur. Boşanmış kadınla evlenen de zina etmiş olur.\""},{"n":"10","t":"Öğrenciler İsa'ya, \"Eğer bir erkekle karısı arasındaki ilişki buysa, hiç evlenmemek daha iyi!\" dediler."},{"n":"11","t":"İsa onlara, \"Herkes bu sözü kabul edemez\" dedi. \"Ancak böyle bir Tanrı vergisine sahip olanlar kabul edebilir."},{"n":"12","t":"Çünkü doğuştan, ana rahminden çıktıklarında hadım olanlar bulunduğu gibi, insanlar tarafından hadım edilmiş olanlar ve kendilerini Göklerin Egemenliği uğruna hadım saymış olanlar da vardır. Bunu kabul edebilen, kabul etsin!\""},{"n":"13-14","h":"İsa küçük çocukları kutsuyor","t":"O sırada bazıları küçük çocukları İsa'nın yanına getirdiler; ellerini onların üzerine koyup dua etmesini istediler. Öğrenciler onları azarlayınca İsa, \"Bırakın çocukları\" dedi. \"Bana gelmelerine engel olmayın! Çünkü Göklerin Egemenliği böylelerinindir.\""},{"n":"15","t":"Ellerini onların üzerine koyduktan sonra oradan ayrıldı."},{"n":"16","h":"Zenginlik ve sonsuz yaşam","t":"Adamın biri İsa'ya gelip, \"Öğretmenim, sonsuz yaşama kavuşmak için nasıl bir iyilik yapmalıyım?\" diye sordu."},{"n":"17","t":"İsa ona, \"İyilik konusunda neden bana soru soruyorsun?\" dedi. \"İyi olan tek biri var. Yaşama kavuşmak istersen, O'nun buyruklarını yerine getir.\""},{"n":"18-19","t":"\"Hangi buyrukları?\" diye sordu adam.\nİsa şu karşılığı verdi: \"'Adam öldürme, zina etme, hırsızlık yapma, yalan yere tanıklık etme, annene babana saygı göster' ve 'komşunu kendin gibi sev.'\""},{"n":"20","t":"Genç adam, \"Bunların hepsini yerine getirdim\" dedi, \"daha ne eksiğim var?\""},{"n":"21","t":"İsa ona, \"Eğer eksiksiz olmak istersen, git, varını yoğunu sat, parasını yoksullara ver; böylece göklerde hazinen olur. Sonra gel, beni izle\" dedi."},{"n":"22","t":"Genç adam bu sözleri işitince üzüntü içinde oradan uzaklaştı. Çünkü çok malı vardı."},{"n":"23","t":"İsa öğrencilerine, \"Size doğrusunu söyleyeyim\" dedi, \"zengin bir kişinin Göklerin Egemenliğine girmesi güç olacak."},{"n":"24","t":"Yine şunu söyleyeyim ki, devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliğine girmesinden daha kolaydır.\""},{"n":"25","t":"Bunu işiten öğrenciler büsbütün şaşırdılar, \"Öyleyse kim kurtulabilir?\" diye sordular."},{"n":"26","t":"İsa onlara bakarak, \"İnsanlar için bu imkânsız, ama Tanrı için her şey mümkün\" dedi."},{"n":"27","t":"Bunun üzerine Petrus O'na, \"Bak\" dedi, \"biz her şeyi bırakıp senin ardından geldik. Neyimiz olacak?\""},{"n":"28","t":"İsa onlara, \"Size doğrusunu söyleyeyim\" dedi, \"her şey yenilendiğinde, İnsanoğlu görkemli tahtına oturduğunda, siz, evet ardımdan gelmiş olan sizler, on iki tahta oturup İsrail'in on iki oymağını yargılayacaksınız."},{"n":"29","t":"Benim adım uğruna evlerini, kardeşlerini, anne ya da babasını, çocuklarını ya da topraklarını bırakmış olan herkes, bunların yüz katını elde edecek ve sonsuz yaşamı miras alacak."},{"n":"30","t":"Ne var ki, birincilerin birçoğu sonuncu, sonuncuların birçoğu da birinci olacak."}]},{"ch":20,"verses":[{"n":"1","t":"\"Göklerin Egemenliği, bağında çalışacak işçi tutmak için sabah erkenden dışarı çıkan toprak sahibine benzer."},{"n":"2","t":"Adam, işçilerle günlüğü bir dinara anlaşıp onları bağına göndermiş."},{"n":"3","t":"\"Saat dokuza doğru tekrar dışarı çıkmış, çarşı meydanında boş duran başka adamlar görmüş."},{"n":"4-5","t":"Onlara, 'Siz de bağa gidip çalışın. Hakkınız ne ise, veririm' demiş, onlar da bağa gitmişler.\n\"Öğleyin ve saat üçe doğru yine çıkıp aynı şeyi yapmış."},{"n":"6","t":"Saat beşe doğru çıkınca, orada duran daha başkalarını görmüş. Onlara, 'Neden bütün gün burada boş duruyorsunuz?' diye sormuş."},{"n":"7","t":"\"'Kimse bize iş vermedi ki' demişler.\n\"Onlara, 'Siz de bağa gidin, çalışın' demiş."},{"n":"8","t":"\"Akşam olunca, bağın sahibi kâhyasına, 'İşçileri çağır' demiş. 'Sonunculardan başlayarak, birincilerine kadar, hepsine ücretlerini ver.'"},{"n":"9","t":"\"Saat beşe doğru işe başlamış olanlar gelip kâhyadan birer dinar almışlar."},{"n":"10","t":"Birinciler gelince daha çok alacaklarını sanmışlar, ama onlara da birer dinar verilmiş."},{"n":"11","t":"Paralarını alınca bağın sahibine karşı söylenmeye başlamışlar."},{"n":"12","t":"'Bu sonuncular yalnız bir saat çalıştılar' demişler. 'Ama sen onları, günün yükünü ve sıcağını çeken bizlerle bir tuttun!'"},{"n":"13","t":"\"Bağın sahibi onlardan birine şöyle karşılık vermiş: 'Arkadaş, sana haksızlık ettiğim yok! Seninle bir dinara anlaşmadık mı?"},{"n":"14","t":"Hakkını al, git! Sana verdiğimi bu sonuncuya davermek istiyorum."},{"n":"15","t":"Kendi paramla istediğimi yapmaya hakkım yok mu? Yoksa elim açık diye kıskanıyor musun?'"},{"n":"16","t":"\"İşte böylece sonuncular birinci, birinciler de sonuncu olacak.\""},{"n":"17-18","h":"İsa ölüp dirileceğini üçüncü kez bildiriyor","t":"İsa Kudüs'e giderken, yolda on iki öğrencisini bir yana çekip onlara özel olarak şunu söyledi: \"Şimdi Kudüs'e gidiyoruz. İnsanoğlu, başkâhinlerin ve din bilginlerinin eline teslim edilecek, onlar da O'nu ölüm cezasına çarptıracaklar."},{"n":"19","t":"O'nunla alay etmeleri, kamçılayıp çarmıha germeleri için O'nu diğer uluslara teslim edecekler. Ne var ki O, üçüncü gün dirilecek.\""},{"n":"20","h":"Bir annenin isteği","t":"O sırada Zebedi oğullarının annesi oğullarıyla birlikte İsa'ya yaklaştı. Önünde yere kapanarak kendisinden bir dileği olduğunu söyledi."},{"n":"21","t":"İsa kadına, \"Ne istiyorsun?\" diye sordu.\nKadın O'na, \"Buyruk ver de senin egemenliğinde bu iki oğlumdan biri senin sağında, biri de solunda otursun\" dedi."},{"n":"22","t":"\"Siz ne dilediğinizi bilmiyorsunuz\" diye karşılık verdi İsa. \"Benim içeceğim kâseden siz içebilir misiniz?\"\n\"Evet, içebiliriz\" dediler."},{"n":"23","t":"İsa onlara, \"Elbette benim kâsemden içeceksiniz\" dedi, \"ama sağımda ya da solumda oturmanıza izin vermek benim elimde değil. Babam bu yerleri belirli kişiler için hazırlamıştır.\""},{"n":"24","t":"Bunu işiten diğer on öğrenci iki kardeşe kızdılar."},{"n":"25","t":"Ama İsa onları yanına çağırıp şöyle dedi: \"Bilirsiniz ki, ulusların önderleri onları egemenlik hırsıyla yönetirler, ileri gelenleri de onlara ağırlıklarını hissettirirler."},{"n":"26","t":"Sizin aranızda böyle olmayacak. Aranızda büyük olmak isteyen, diğerlerinin hizmetkârı olsun."},{"n":"27","t":"Aranızda birinci olmak isteyen, diğerlerinin kulu olsun."},{"n":"28","t":"Nitekim İnsanoğlu, hizmet edilmeye değil, hizmet etmeye ve canını birçokları uğruna fidye olarak vermeye geldi.\""},{"n":"29","h":"İki körün gözleri açılıyor","t":"Eriha'dan ayrılırlarken büyük bir kalabalık İsa'nın ardından gitti."},{"n":"30","t":"Yol kenarında oturan iki kör adam, İsa'nın oradan geçmekte olduğunu duyunca, \"Ya Rab, ey Davut Oğlu, halimize acı!\" diye bağırdılar."},{"n":"31","t":"Kalabalık onları azarlayarak susturmak istediyse de onlar, \"Ya Rab, ey Davut Oğlu, halimize acı!\" diyerek daha çok bağırdılar."},{"n":"32","t":"İsa durup onları çağırdı. \"Sizin için ne yapmamı istiyorsunuz?\" diye sordu."},{"n":"33","t":"Onlar da, \"Ya Rab, gözlerimiz açılsın\" dediler."},{"n":"34","t":"İsa onlara acıdı, gözlerine dokundu. O anda yeniden görmeye başladılar ve O'nun ardından gittiler."}]},{"ch":21,"verses":[{"n":"1-2","h":"İsa'nın Kudüs'e girişi","t":"Kudüs'e yaklaşıp Zeytin dağının yamacında bulunan Beytfacı köyüne geldiklerinde İsa, öğrencilerinden ikisini şu sözlerle köye gönderdi: \"Karşınızdaki köye gidin. Hemen orada bağlı bir dişi eşek ve yanında bir sıpa bulacaksınız. Onları çözüp bana getirin."},{"n":"3","t":"Size bir şey diyen olursa, 'Rab'bin bunlara ihtiyacı var, hemen geri gönderecek' dersiniz.\""},{"n":"4-5","t":"Bu olay, peygamber aracılığıyla bildirilen şu sözün yerine gelmesi için oldu:\n\"Siyon kızına deyin ki,\n'Bak, alçakgönüllü Kralın, bir eşeğe,\nevet bir sıpaya,\nbir eşek yavrusuna binmiş\nsana geliyor.'\""},{"n":"6","t":"Öğrenciler gittiler, İsa'nın kendilerine buyurduğu gibi yaptılar."},{"n":"7","t":"Eşekle sıpayı getirip üzerlerine giysilerini yaydılar, İsa da sıpanın üzerine bindi."},{"n":"8","t":"Halkın büyük bir bölümü giysilerini yolun üzerine serdi. Bazıları da ağaçlardan dallar kesiyor, yola seriyorlardı."},{"n":"9","t":"Önden giden ve arkadan gelen kalabalıklar şöyle bağırıyorlardı:\n\"Davut Oğluna hozana!\nRab'bin adıyla gelene övgüler olsun,\nen yücelerde hozana!\""},{"n":"10","t":"İsa Kudüs'e girdiği zaman bütün kent, \"Bu kimdir?\" diyerek çalkandı."},{"n":"11","t":"Kalabalıklar, \"Bu, Celile'nin Nasıra kentinden İsa peygamber\" diyordu."},{"n":"12","h":"İsa satıcıları tapınaktan kovuyor","t":"İsa, tapınağın avlusuna girerek oradaki bütün satıcı ve alıcıları dışarı kovdu. Para bozanların masalarını, güvercin satanların sehpalarını devirdi."},{"n":"13","t":"Onlara şöyle dedi: \"'Benim evime dua evi denecek' diye yazılmıştır. Ama siz burayı haydut inine çevirdiniz!\""},{"n":"14","t":"İsa tapınaktayken kendisine gelen kör ve kötürümleri iyileştirdi."},{"n":"15","t":"Ne var ki, başkâhinlerle din bilginleri, O'nun yarattığı harikaları ve tapınakta, \"Davut Oğluna hozana!\" diye bağıran çocukları görünce öfkelendiler."},{"n":"16","t":"İsa'ya, \"Bunların ne söylediğini duyuyor musun?\" diye sordular.\n\"Duyuyorum\" dedi İsa. \"Siz şu sözü hiç okumadınız mı? 'Küçük çocukların ve emzikte olanların dudaklarından kendine övgüler döktürdün.'\""},{"n":"17","t":"İsa onları bırakıp kentten çıktı. Beytanya'ya dönüp geceyi orada geçirdi."},{"n":"18","h":"Kuruyan incir ağacı","t":"İsa sabah erkenden kente dönerken acıkmıştı."},{"n":"19","t":"Yol kenarında gördüğü bir incir ağacına yaklaştı. Ağaçta yapraktan başka bir şey bulamayınca ağaca, \"Artık sonsuza dek meyven olmasın!\" dedi. İncir ağacı hemen o anda kurudu."},{"n":"20","t":"Öğrenciler bunu görünce şaşkına döndüler. \"İncir ağacı birdenbire nasıl kurudu?\" diye sordular."},{"n":"21","t":"İsa onlara şu karşılığı verdi: \"Size doğrusunu söyleyeyim, eğer imanınız olur da kuşku duymazsanız, yalnız incir ağacına olanı yapmakla kalmazsınız; şu dağa, 'Kalk, denize atıl' derseniz, dediğiniz olacaktır."},{"n":"22","t":"İman ederek dua ettiğinizde, dilediğiniz her şeyi alacaksınız.\""},{"n":"23","h":"İsa'nın yetkisi","t":"İsa tapınağa girmiş ders veriyordu. Bu sırada başkâhinler ve halkın ihtiyarları O'nun yanına gelerek, \"Bunları hangi yetkiyle yapıyorsun, bu yetkiyi sana kim verdi?\" diye sordular."},{"n":"24","t":"İsa onlara şu karşılığı verdi: \"Ben de size bir soru soracağım. Bana cevap verirseniz, ben de size bunları hangi yetkiyle yaptığımı söylerim."},{"n":"25","t":"Yahya'nın vaftiz etme yetkisi nereden geldi, Tanrı'dan mı, insanlardan mı?\"\nBunu aralarında şöyle tartışmaya başladılar: \"'Tanrı'dan' dersek, bize, 'Öyleyse ona niçin inanmadınız?' diyecek."},{"n":"26","t":"Yok eğer 'insanlardan' dersek… Halkın tepkisinden korkuyoruz. Çünkü herkes Yahya'yı peygamber sayıyor.\""},{"n":"27","t":"İsa'ya, \"Bilmiyoruz\" diye cevap verdiler.\nİsa, \"Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim\" dedi."},{"n":"28","h":"İki oğul benzetmesi","t":"\"Ama şuna ne dersiniz? Bir adamın iki oğlu varmış. Adam birincisine gidip, 'Oğlum, git bugün bağda çalış' demiş."},{"n":"29","t":"\"O da, 'Gitmem!' demiş. Ama sonra pişman olup gitmiş."},{"n":"30","t":"\"Adam ikinci oğluna gidip aynı şeyi söylemiş. O da, 'Giderim, efendim' demiş, ama gitmemiş."},{"n":"31","t":"\"İkisinden hangisi babasının isteğini yerine getirmiş olur?\"\n\"Birincisi\" diye karşılık verdiler.\nİsa da onlara, \"Size doğrusunu söyleyeyim, vergi görevlileriyle fahişeler, Tanrı'nın Egemenliğine sizden önce giriyorlar\" dedi."},{"n":"32","t":"\"Yahya size doğruluk yolunu göstermeye geldi, ona inanmadınız. Oysa vergi görevlileriyle fahişeler ona inandılar. Siz bunu gördükten sonra bile pişman olup ona inanmadınız."},{"n":"33","h":"Bağ kiracıları benzetmesi","t":"\"Bir benzetme daha dinleyin: toprak sahibi bir adam, bağ dikmiş, çevresini çitle çevirmiş, üzüm sıkmak için bir çukur kazmış, bir de bekçi kulesi yapmış. Sonra bağı bağcılara kiralayıp yolculuğa çıkmış."},{"n":"34","t":"Bağbozumu yaklaşınca, üründen kendisine düşeni almaları için kölelerini bağcılara yollamış."},{"n":"35","t":"Bağcılar adamın kölelerini yakalamış, birini dövmüş, birini öldürmüş, diğerini de taşlamışlar."},{"n":"36","t":"Bağ sahibi bu kez ilkinden daha çok sayıda köle yollamış. Bağcılar bunlara da aynı şeyi yapmışlar."},{"n":"37","t":"Sonunda bağ sahibi, 'Oğlumu sayarlar' diyerek bağcılara onu yollamış."},{"n":"38","t":"\"Ama bağcılar adamın oğlunu görünce birbirlerine, 'Mirasçı bu; gelin, onu öldürüp mirasına konalım' demişler."},{"n":"39","t":"Böylece onu yakalayıp bağdan dışarı atmış ve öldürmüşler."},{"n":"40","t":"Bu durumda bağın sahibi geldiği zaman bağcılara ne yapacak?\""},{"n":"41","t":"İsa'ya şu karşılığı verdiler: \"Bu korkunç adamları korkunç bir şekilde yok edecek; bağı da, ürününü kendisine zamanında verecek olan başka bağcılara kiralayacak.\""},{"n":"42","t":"İsa onlara şunu sordu: \"Kutsal Yazılarda şu sözleri hiç okumadınız mı?\n\n'Yapıcıların reddettiği taş,\nişte köşenin baş taşı oldu.\nRab'bin işidir bu,\ngözümüzde harika bir iş!'"},{"n":"43","t":"\"Bu nedenle size şunu söyleyeyim, Tanrı'nın Egemenliği sizden alınacak ve bunun ürünlerini yetiştirecek bir ulusa verilecek."},{"n":"44","t":"\"Bu taşın üzerine düşen, paramparça olacak; taş da kimin üzerine düşerse, onu ezip toz edecek.\""},{"n":"45","t":"Başkâhinler ve Ferisiler, İsa'nın anlattığı benzetmeleri duyunca bunları kendileri için söylediğini anladılar."},{"n":"46","t":"O'nu tutuklamak istedilerse de, halkın tepkisinden korktular. Çünkü halk, O'nu peygamber sayıyordu."}]},{"ch":22,"verses":[{"n":"1-2","h":"Düğün şöleni benzetmesi","t":"İsa söz alıp onlara yine benzetmelerle şöyle seslendi: \"Göklerin Egemenliği, oğlu için düğün şöleni hazırlayan bir krala benzer."},{"n":"3","t":"Kral, şölene davet ettiklerini çağırmak üzere kölelerini göndermiş, ama davetliler gelmek istememiş."},{"n":"4","t":"\"Kral yine başka kölelerini gönderirken onlara demiş ki, 'Davetlilere şunu söyleyin: Bakın, ben ziyafetimi hazırladım. Sığırlarım, besili hayvanlarım kesildi. Her şey hazır, gelin şölene!'"},{"n":"5","t":"\"Ama davetliler aldırmamışlar. Biri tarlasına, biri ticaretine gitmiş."},{"n":"6","t":"Öbürleri de kralın kölelerini yakalayıp hırpalamış ve öldürmüşler."},{"n":"7","t":"Kral öfkelenmiş. Ordularını gönderip o katilleri yok etmiş, kentlerini ateşe vermiş."},{"n":"8","t":"\"Sonra kölelerine şöyle demiş: 'Düğün şöleni hazır, ama çağırdıklarım buna layık değilmiş."},{"n":"9","t":"Gidin yol kavşaklarına, kimibulursanız düğüne çağırın.'"},{"n":"10","t":"Böylece köleler yollara dökülmüş, iyi kötü kimi bulmuşlarsa, hepsini toplamışlar. Düğün yeri konuklarla dolmuş."},{"n":"11","t":"\"Kral konukları görmeye geldiğinde, orada düğün elbisesi giymemiş bir adam görmüş."},{"n":"12","t":"Ona, 'Arkadaş, üzerinde düğün elbisesi olmadan buraya nasıl girdin?' diye sorunca, adamın dili tutulmuş."},{"n":"13","t":"\"O zaman kral, uşaklarına, 'Şunun ellerini ayaklarını bağlayın, onu dışarıya, karanlığa atın!' demiş. 'Orada ağlayış ve diş gıcırtısı olacaktır.'"},{"n":"14","t":"\"Çünkü çağrılanlar çok, ama seçilenler azdır.\""},{"n":"15","h":"Sezar'ın hakkı Sezar'a","t":"Bunun üzerine Ferisiler çıkıp gittiler. İsa'yı, kendi söyleyeceği sözlerle tuzağa düşürmek amacıyla bir düzen kurdular."},{"n":"16","t":"Hirodes yanlılarıyla birlikte gönderdikleri kendi öğrencileri İsa'ya gelip, \"Öğretmenimiz\" dediler, \"senin dürüst biri olduğunu, Tanrı yolunu dürüstçe öğrettiğini, kimseyi kayırmadığını biliyoruz. Çünkü insanlar arasında ayrım yapmazsın."},{"n":"17","t":"Peki ne dersin, söyle bize, Sezar'a vergi vermek Kutsal Yasa'ya uygun mu, değil mi?\""},{"n":"18","t":"İsa onların kötü niyetlerini bildiğinden, \"Ey ikiyüzlüler!\" dedi. \"Beni neden sınıyorsunuz?"},{"n":"19","t":"Vergi ödemekte kullandığınız parayı gösterin bana!\" O'na bir dinar getirdiler."},{"n":"20","t":"İsa onlara, \"Bu resim, bu yazı kimin?\" diye sordu."},{"n":"21","t":"\"Sezar'ın\" dediler.\nO zaman İsa onlara, \"Öyleyse Sezar'ın hakkını Sezar'a, Tanrı'nın hakkını da Tanrı'ya verin\" dedi."},{"n":"22","t":"Bu sözleri duyunca şaştılar, İsa'yı bırakıp gittiler."},{"n":"23-24","h":"Dirilişle ilgili soru","t":"Ölümden sonra diriliş olmadığını söyleyen Sadukiler, aynı gün İsa'ya gelip şunu sordular: \"Öğretmenimiz, Musa şöyle buyurmuştur: 'Eğer bir adam çocuk sahibi olmadan ölürse, kardeşi onun karısını alsın, soyunu sürdürsün.'"},{"n":"25","t":"Aramızda yedi kardeş vardı. İlki evlendi ve öldü. Çocuğu olmadığından karısını kardeşine bıraktı."},{"n":"26","t":"İkincisi, üçüncüsü, yedincisine kadar hepsine aynı şey oldu."},{"n":"27","t":"Hepsinden sonra kadın da öldü."},{"n":"28","t":"Buna göre diriliş günü kadın bu yedi kardeşten hangisinin karısı olacak? Çünkü hepsi de onunla evlendi.\""},{"n":"29","t":"İsa onlara, \"Siz Kutsal Yazıları ve Tanrı'nın gücünü bilmediğiniz için yanılıyorsunuz\" diye karşılık verdi."},{"n":"30","t":"\"Dirilişten sonra insanlar ne evlenir, ne de evlendirilir, gökteki melekler gibidirler."},{"n":"31","t":"Ölülerin dirilmesi konusuna gelince, Tanrı'nın size bildirdiği şu sözü okumadınız mı?"},{"n":"32","t":"'Ben İbrahim'in Tanrısı, İshak'ın Tanrısı ve Yakup'un Tanrısıyım' diyor. Tanrı ölülerin değil, yaşayanların Tanrısıdır.\""},{"n":"33","t":"Bunları işiten halk, O'nun öğretişine şaşıp kaldı."},{"n":"34","h":"En büyük buyruk","t":"Ferisiler, İsa'nın Sadukileri susturduğunu duyunca bir araya toplandılar."},{"n":"35-36","t":"Onlardan biri, bir Kutsal Yasa uzmanı, İsa'yı sınamak amacıyla O'na şunu sordu: \"Öğretmenim, Kutsal Yasa'da en önemli buyruk hangisi?\""},{"n":"37","t":"İsa ona şu karşılığı verdi: \"'Tanrın olan Rab'bi bütün yüreğinle, bütün canınla ve bütün aklınla sev.'"},{"n":"38","t":"İşte ilk ve en önemli buyruk budur."},{"n":"39","t":"İlkine benzeyen ikinci buyruk da şudur: 'Komşunu kendin gibi sev.'"},{"n":"40","t":"Kutsal Yasa'nın tümü ve peygamberlerin sözleri bu iki buyruğa dayanır.\""},{"n":"41-42","h":"Mesih kimin oğlu?","t":"Ferisiler toplu haldeyken İsa onlara şunu sordu: \"Mesih'le ilgili olarak ne düşünüyorsunuz? O, kimin oğludur?\"\nOnlar da, \"Davut'un Oğlu\" dediler."},{"n":"43","t":"İsa şöyle dedi: \"O halde nasıl oluyor da Davut, Ruh'tan esinlenerek O'ndan 'Rab' diye söz ediyor? Şöyle diyor Davut:"},{"n":"44","t":"'Rab Rabbime dedi ki,\nBen düşmanlarını\nsenin ayaklarının altına serinceye dek\nsağımda otur.'"},{"n":"45","t":"Davut O'ndan Rab diye söz ettiğine göre, O nasıl Davut'un Oğlu olur?\""},{"n":"46","t":"İsa'ya hiç kimse karşılık veremedi. O günden sonra artık kimse de O'na bir şey sormaya cesaret edemedi."}]},{"ch":23,"verses":[{"n":"1-2","h":"Vay halinize!","t":"Bundan sonra İsa halka ve öğrencilerine şöyle seslendi: \"Din bilginleri ve Ferisiler Musa'nın kürsüsünde otururlar."},{"n":"3","t":"Bu nedenle size söylediklerinin tümünü yapın ve yerine getirin, ama onların yaptıklarını yapmayın. Çünkü söyledikleri şeyleri kendileri yapmazlar."},{"n":"4","t":"Ağır ve taşınması güç yükleri bağlayıp başkalarının omuzlarına koyarlar da, kendileri bu yükleri taşımak için parmaklarını bile kıpırdatmak istemezler."},{"n":"5","t":"\"Yaptıklarının tümünü gösteriş için yaparlar. Örneğin, muskalarını büyük, giysilerinin püsküllerini [] uzun yaparlar."},{"n":"6","t":"Şölenlerde başköşeye, havralarda en seçkin yerlere kurulmaya bayılırlar."},{"n":"7","t":"Meydanlarda selamlanmaktan ve insanların kendilerini 'Rabbî' diye çağırmalarından zevk duyarlar."},{"n":"8","t":"\"Kimse sizi 'Rabbî' diye çağırmasın. Çünkü sizin bir tek öğretmeniniz var ve hepiniz kardeşsiniz."},{"n":"9","t":"Yeryüzünde kimseye 'Baba' demeyin. Çünkü bir tek Babanız var, O da göksel Baba'dır."},{"n":"10","t":"Kimse sizi 'önder' diye çağırmasın. Çünkü bir tek önderiniz var, O da Mesih'tir."},{"n":"11","t":"Aranızda en üstün olan, diğerlerinin hizmetkârı olsun."},{"n":"12","t":"Kendini yücelten alçaltılacak, kendinialçaltan yüceltilecektir."},{"n":"13-14","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Göklerin Egemenliğinin kapısını insanların yüzüne kapıyorsunuz; ne kendiniz içeri giriyorsunuz, ne de girmek isteyenleri bırakıyorsunuz!"},{"n":"15","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Tek bir kişiyi dininize döndürmek için denizleri ve kıtaları dolaşırsınız. Dininize döneni de kendinizden iki kat daha cehennemlik yaparsınız."},{"n":"16","t":"\"Vay halinize kör kılavuzlar! Diyorsunuz ki, 'Tapınak üzerine ant içenin andı sayılmaz, ama tapınaktaki altın üzerine ant içen, andını yerine getirmek zorundadır.'"},{"n":"17","t":"Budalalar, körler! Hangisi daha önemli, altın mı, altını kutsal kılan tapınak mı?"},{"n":"18","t":"Yine diyorsunuz ki, 'Sunak üzerine ant içenin andı sayılmaz, ama sunaktaki adağın üzerine ant içen, andını yerine getirmek zorundadır.'"},{"n":"19","t":"Ey körler! Hangisi daha önemli, adak mı, adağı kutsal kılan sunak mı?"},{"n":"20","t":"Öyleyse sunak üzerine ant içen, hem sunağın hem de sunaktaki her şeyin üzerine ant içmiş olur."},{"n":"21","t":"Tapınak üzerine ant içen de hem tapınak, hem de tapınakta yaşayan Tanrı üzerine ant içmiş olur."},{"n":"22","t":"Gök üzerine ant içen, Tanrı'nın tahtı ve tahtta oturanın üzerine ant içmiş olur."},{"n":"23","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Siz nanenin, anasonun ve kimyonun ondalığını verirsiniz de, Kutsal Yasa'nın daha önemli yönleri olan adalet, merhamet ve sadakati ihmal edersiniz. Ondalık vermeyi ihmal etmeden esas bunları yerine getirmeniz gerekirdi."},{"n":"24","t":"Ey kör kılavuzlar! Küçük sineği süzer ayırır, ama deveyi yutarsınız!"},{"n":"25","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Bardağın ve çanağın dışını temizlersiniz, ama bunların içi açgözlülük ve taşkınlıkla doludur."},{"n":"26","t":"Ey kör Ferisi! Sen önce bardağın ve çanağın içini temizle ki, dıştan da temiz olsunlar."},{"n":"27","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Siz dıştan güzel görünen, ama içi ölü kemikleri ve her türlü pislikle dolu badanalı mezarlara benzersiniz."},{"n":"28","t":"Dıştan insanlara doğru kişilermiş gibi görünürsünüz, ama içte ikiyüzlülük ve kötülükle dolusunuz."},{"n":"29","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Peygamberlerin mezarlarını yaparsınız, doğru kişilerin türbelerini donatırsınız."},{"n":"30","t":"'Atalarımızın yaşadığı günlerde yaşasaydık, onlarla birlikte peygamberlerin kanına girmezdik' diyorsunuz."},{"n":"31","t":"Böylece, peygamberleri öldürenlerin torunları olduğunuza siz kendiniz tanıklık ediyorsunuz."},{"n":"32","t":"Haydi, atalarınızın başlattığı işi bitirin!"},{"n":"33","t":"\"Sizi yılanlar, sizi engerekler soyu! Cehennem cezasından nasıl kaçacaksınız?"},{"n":"34","t":"İşte bunun için size peygamberler, bilge kişiler ve din bilginleri gönderiyorum. Bunlardan kimini öldürecek, çarmıha gereceksiniz. Kimini havralarınızda kamçılayacak, kentten kente kovalayacaksınız."},{"n":"35","t":"Böylelikle, doğru kişi olan Habil'in kanından, tapınakla sunak arasında öldürdüğünüz Berekya'nın oğlu Zekeriya'nın kanına kadar, yeryüzünde akıtılan her doğru kişinin kanından sorumlu tutulacaksınız."},{"n":"36","t":"Size doğrusunu söyleyeyim, bunların hepsinden bu kuşak sorumlu tutulacaktır."},{"n":"37","t":"\"Ey Kudüs! Peygamberleri öldüren, kendisine gönderilenleritaşlayan Kudüs! Bir tavuk, civcivlerini kanatları altına nasıl toplarsa, ben de kaç kez senin çocuklarını öylece toplamak istedim, ama siz istemediniz."},{"n":"38","t":"Bakın, eviniz ıssız bırakılacak!"},{"n":"39","t":"Size şunu söyleyeyim: 'Rab'bin adıyla gelene övgüler olsun!' diyeceğiniz zamana dek beni bir daha görmeyeceksiniz.\""}]},{"ch":24,"verses":[{"n":"1","h":"Sonun belirtileri","t":"İsa tapınaktan çıkıp giderken, öğrencileri, tapınağın binalarını O'na göstermek için yanına geldiler."},{"n":"2","t":"İsa onlara, \"Bütün bunları görüyor musunuz?\" dedi. \"Size doğrusunu söyleyeyim, burada taş üstünde taş kalmayacak, hepsi yıkılacak!\""},{"n":"3","t":"İsa, Zeytin dağında otururken öğrencileri yalnız olarak yanına geldiler. \"Söyle bize\" dediler, \"bu dediklerin ne zaman olacak, senin gelişini ve çağın bitimini gösteren belirti ne olacak?\""},{"n":"4","t":"İsa onlara şu karşılığı verdi: \"Sakın kimse sizi saptırmasın!"},{"n":"5","t":"Birçokları, 'Mesih benim' diyerek benim adımla gelecek, birçok kişiyi saptıracaklar."},{"n":"6","t":"Savaş gürültüleri, savaş haberleri duyacaksınız. Korkmayın sakın! Bunların olması gerek, ama bu daha son demek değildir."},{"n":"7","t":"Ulus ulusa, devlet devlete savaş açacak; yer yer kıtlıklar, depremler olacak."},{"n":"8","t":"Bütün bunlar, doğum sancılarının başlangıcıdır."},{"n":"9","t":"\"O zaman sizi sıkıntıya sokacaklar ve öldürecekler. Benim adımdan ötürü tüm uluslar sizden nefret edecek."},{"n":"10","t":"O zaman birçok kişi imandan sapacak, birbirlerini ele verecek ve birbirlerinden nefret edecekler."},{"n":"11","t":"Birçok sahte peygamber türeyecek ve bunlar birçok kişiyi saptıracak."},{"n":"12","t":"Kötülüklerin çoğalmasından ötürü birçoklarının sevgisi soğuyacak."},{"n":"13","t":"Ama sonuna kadar dayanan kurtulacaktır."},{"n":"14","t":"Göksel Egemenliğin bu müjdesi tüm uluslara bir tanıklık olmak üzere bütün dünyada duyurulacak, ve son o zaman gelecektir."},{"n":"15-16","t":"\"Danyal peygamberin sözünü ettiği yıkıcı iğrenç şeyin kutsal yerde dikildiğini gördüğünüz zaman (okuyan anlasın), Yahudiye'de olanlar dağlara kaçsın."},{"n":"17","t":"Damda olan, evindeki eşyalarını almak için aşağı inmesin."},{"n":"18","t":"Tarlada olan, abasını almak için geri dönmesin."},{"n":"19","t":"O günlerde gebe olan, çocuk emziren kadınların vay haline!"},{"n":"20","t":"Dua edin ki, kaçışınız kışa ya da Sept gününe rastlamasın."},{"n":"21","t":"Çünkü o günlerde öyle korkunç bir sıkıntı olacak ki, dünyanın başlangıcından bu yana böylesi olmamış, ondan sonra da olmayacaktır."},{"n":"22","t":"O günler kısaltılmamış olsaydı, hiç kimse kurtulamazdı. Ama seçilmiş olanlar uğruna o günler kısaltılacak."},{"n":"23","t":"Eğer o zaman biri size, 'İşte Mesih burada', ya da 'İşte şurada' derse, inanmayın."},{"n":"24","t":"Çünkü sahte mesihler, sahte peygamberler türeyecek; bunlar büyük mucizeler ve harikalar yaratacaklar. Öyle ki, ellerinden gelse, seçilmiş olanları bile saptıracaklar."},{"n":"25","t":"İşte size önceden söylemiş bulunuyorum."},{"n":"26","t":"\"Bunun için size, 'İşte Mesih çölde' derlerse gitmeyin. 'Bakın, iç odalarda' derlerse inanmayın."},{"n":"27","t":"Çünkü İnsanoğlu'nun gelişi, doğuda çakıp batıya kadar her taraftan görülen şimşek gibi olacaktır."},{"n":"28","t":"\"Leş neredeyse, akbabalar oraya üşüşecek."},{"n":"29","t":"\"O günlerin sıkıntısından hemen sonra,\n'Güneş kararacak,\nay ışığını vermez olacak,\nyıldızlar gökten düşecek\nve göksel güçler sarsılacak.'"},{"n":"30","t":"\"O zaman İnsanoğlu'nun belirtisi gökte görünecek. Yeryüzündeki bütün halklar ağlayıp dövünecek, İnsanoğlu'nun gökteki bulutlar üzerinde büyük güç ve görkemle geldiğini görecekler."},{"n":"31","t":"Kendisi, güçlü bir borazan sesiyle meleklerini gönderecek ve onlar, O'nun seçtiklerini, göklerin bir ucundan öbür ucuna kadar dört yelden alıp bir araya toplayacaklar."},{"n":"32","t":"\"İncir ağacından ders alın! Dalları filizlenip yapraklarını sürünce, yaz mevsiminin yakın olduğunu anlarsınız."},{"n":"33","t":"Aynı şekilde, bütün bunların gerçekleştiğini gördüğünüzde bilin ki, İnsanoğlu yakındır, kapıdadır."},{"n":"34","t":"Size doğrusunu söyleyeyim, bütün bunlar olmadan bu kuşak ortadan kalkmayacak."},{"n":"35","t":"Gök ve yer ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır."},{"n":"36","h":"Bilinmeyen gün ve saat","t":"\"O günü ve saati, ne gökteki melekler, ne de Oğul bilir; Baba'dan başka kimse bilmez."},{"n":"37","t":"Nuh'un günlerinde nasıl olduysa, İnsanoğlu'nun gelişinde de öyle olacak."},{"n":"38","t":"Nuh'un gemiye bindiği güne dek, tufandan önceki günlerde insanlar yiyip içiyor, evlenip evlendiriliyorlardı."},{"n":"39","t":"Tufan gelinceye, hepsini süpürüp götürünceye dek başlarına geleceklerden habersizdiler. İnsanoğlu'nun gelişi de öyle olacak."},{"n":"40","t":"O gün tarlada bulunan iki kişiden biri alınacak, biri bırakılacak."},{"n":"41","t":"Değirmende buğday öğüten iki kadından biri alınacak, biri bırakılacak."},{"n":"42","t":"\"Bunun için uyanık kalın. Çünkü Rabbinizin geleceği günü bilemezsiniz."},{"n":"43","t":"Ama şunu bilin ki, ev sahibi, hırsızın gece hangi saatte geleceğini bilse, uyanık durur, evinin soyulmasına fırsat vermez."},{"n":"44","t":"Bunun için siz de hazır olun! Çünkü İnsanoğlu, ummadığınız bir saatte gelecektir."},{"n":"45","t":"\"Efendinin, hizmetkârlarına vaktinde yiyecek vermek için üzerlerinde yetkili kıldığı güvenilir ve akıllı köle kimdir?"},{"n":"46","t":"Efendisi eve döndüğünde işinin başında bulacağı o köleye ne mutlu!"},{"n":"47","t":"Size doğrusunu söyleyeyim, efendisi onu tüm malının üzerinde yetkili kılacak."},{"n":"48-51","t":"Ama o köle kötü olur da kendi kendine, \"Efendim gecikiyor\" der ve yoldaşlarını dövmeye başlarsa, sarhoşlarla birlikte yiyip içerse, efendisi, onun beklemediği bir günde, ummadığı bir saatte gelecek, onu şiddetle cezalandıracak ve ikiyüzlülerle bir tutacak. Orada ağlayış ve diş gıcırtısı olacaktır."}]},{"ch":25,"verses":[{"n":"1","h":"On kız benzetmesi","t":"\"O zaman Göklerin Egemenliği, kandillerini alıp güveyi karşılamaya çıkmış olan on kıza benzeyecek."},{"n":"2","t":"Bunların beşi akılsız, beşi de akıllıymış."},{"n":"3","t":"Akılsızlar kandillerini almışlarsa da, yanlarına yağ almamışlar."},{"n":"4","t":"Akıllılar ise, kandilleriyle birlikte kaplar içinde yağ da almışlar."},{"n":"5","t":"Güvey gecikince hepsini uyku tutmuş ve dalıp uyumuşlar."},{"n":"6","t":"\"Gece yarısı bir ses yankılanmış: 'İşte güvey geliyor, onu karşılamaya çıkın!'"},{"n":"7","t":"Bunun üzerine kızların hepsi kalkıp kandillerini tazelemişler."},{"n":"8","t":"\"Akılsızlar akıllılara, 'Kandillerimiz sönüyor, bize yağınızdan verin!' demişler."},{"n":"9","t":"\"Akıllılar, 'Olmaz! Hem bize hem size yetmeyebilir. En iyisi satıcılara gidin, kendinize yağ alın' demişler."},{"n":"10","t":"\"Ne var ki, onlar yağ satın almaya giderlerken güvey gelmiş. Hazırlıklı olan kızlar, onunla birlikte düğün şölenine girmişler ve kapı kapanmış."},{"n":"11","t":"\"Daha sonra gelen öbür kızlar, 'Efendimiz, efendimiz, aç kapıyı bize!' demişler."},{"n":"12","t":"\"Güvey ise, 'Size doğrusunu söyleyeyim, sizi tanımıyorum' demiş."},{"n":"13","t":"\"Bu nedenle uyanık durun. Çünkü o günü ve o saati bilemezsiniz."},{"n":"14","h":"Emanet para benzetmesi","t":"\"Göksel Egemenlik, yolculuğa çıkmak üzere olan bir adamın kölelerini çağırıp malını onlara emanet etmesine benzer."},{"n":"15","t":"\"Adam, her birinin yeteneğine göre, birine beş, birine iki, birine de bir talant vererek yola çıkmış."},{"n":"16","t":"Beş talant alan, hemen gidip bu parayı işletmiş ve beş talant daha kazanmış."},{"n":"17","t":"İki talant alan da iki talant daha kazanmış."},{"n":"18","t":"Bir talant alan ise gidip toprağı kazmış ve efendisinin parasını saklamış."},{"n":"19","t":"\"Uzun zaman sonra bu kölelerin efendisi dönmüş, onlarla hesaplaşmaya oturmuş."},{"n":"20","t":"Beş talant almış olan gelip beş talant daha getirmiş, 'Efendimiz' demiş, 'bana beş talant emanet etmiştin; bak, beş talant daha kazandım.'"},{"n":"21","t":"\"Efendisi ona, 'Aferin, iyi ve güvenilir köle!' demiş. 'Sen küçük işlerde güvenilir olduğunu gösterdin, ben de seni büyük işlerin başına geçireceğim. Gel, efendinin şenliğine katıl!'"},{"n":"22","t":"\"İki talant almış olan da gelmiş, 'Efendimiz' demiş, 'bana iki talant emanet etmiştin; bak, iki talant daha kazandım.'"},{"n":"23","t":"\"Efendisi ona, 'Aferin, iyi ve güvenilir köle!' demiş. 'Sen küçük işlerde güvenilir olduğunu gösterdin, ben de seni büyük işlerin başına geçireceğim. Gel, efendinin şenliğine katıl!'"},{"n":"24","t":"\"Sonra bir talant almış olan gelmiş, 'Efendimiz' demiş, 'senin sert bir adam olduğunu biliyordum. Ekmediğin yerden biçer, harman savurmadığın yerden devşirirsin."},{"n":"25","t":"Bu nedenle korktum, gidip senin verdiğin talantı toprağa gömdüm. İşte, al paranı!'"},{"n":"26-27","t":"\"Efendisi ona şu karşılığı vermiş: 'Kötü ve tembel köle! Ekmediğim yerden biçtiğimi, harman savurmadığım yerden devşirdiğimi biliyordun ha? Öyleyse paramı faizcilere vermeliydin. Ben de geldiğimde onu faiziyle geri alırdım…"},{"n":"28","t":"Haydi, elindeki talantı alın, on talantı olana verin!"},{"n":"29","t":"Çünkükimde varsa, ona daha çok verilecek ve o bolluk içinde olacak. Ama kimde yoksa, kendisinde olan da elinden alınacak."},{"n":"30","t":"Şu yararsız köleyi dışarıya, karanlığa atın. Orada ağlayış ve diş gıcırtısı olacaktır.'"},{"n":"31","h":"Koyunlar ve keçiler","t":"\"İnsanoğlu kendi görkemi içinde bütün melekleriyle birlikte gelince, görkemli tahtına oturacak."},{"n":"32","t":"Ulusların hepsi O'nun önünde toplanacak, O da koyunları keçilerden ayıran bir çoban gibi, onları birbirinden ayıracak."},{"n":"33","t":"Koyunları sağına, keçileri soluna alacak."},{"n":"34","t":"\"O zaman Kral, sağındaki kişilere, 'Sizler, Babamın kutsadıkları, gelin!' diyecek. 'Dünya kurulduğundan beri sizin için hazırlanmış olan egemenliği miras alın!"},{"n":"35","t":"Çünkü acıkmıştım, bana yiyecek verdiniz; susamıştım, bana içecek verdiniz; yabancıydım, beni içeri aldınız."},{"n":"36","t":"Çıplaktım, beni giydirdiniz; hastaydım, benimle ilgilendiniz; zindandaydım, yanıma geldiniz.'"},{"n":"37","t":"\"O vakit doğru kişiler O'na şu karşılığı verecekler: 'Ya Rab, biz seni ne zaman aç görüp doyurduk, ya da susamış görüp içecek verdik?"},{"n":"38","t":"Seni ne zaman yabancı gördük de içeri aldık, ya da çıplak görüp giydirdik?"},{"n":"39","t":"Seni ne zaman hasta ya da zindanda görüp yanına geldik?'"},{"n":"40","t":"\"Kral da onlara şöyle cevap verecek: 'Size doğrusunu söyleyeyim, bu en basit kardeşlerimden biri için yaptığınızı, benim için yapmış oldunuz.'"},{"n":"41","t":"\"Sonra solundakilere şöyle diyecek: 'Ey lanetliler, çekilin önümden! İblis ile onun melekleri için hazırlanmış sönmez ateşe yollanın!"},{"n":"42-43","t":"Çünkü acıkmıştım, bana yiyecek vermediniz; susamıştım, bana içecek vermediniz; yabancıydım, beni içeri almadınız; çıplaktım, beni giydirmediniz; hastaydım, zindandaydım, benimle ilgilenmediniz."},{"n":"44","t":"\"O vakit onlar da şöyle karşılık verecekler: 'Ya Rab, seni ne zaman aç, susamış, yabancı, çıplak, hasta ya da zindanda gördük de sana hizmet etmedik?'"},{"n":"45","t":"\"Kral da onlara şu cevabı verecek: 'Size doğrusunu söyleyeyim, mademki bu en basit kardeşlerimden biri için bunu yapmadınız, benim için de yapmamış oldunuz.'"},{"n":"46","t":"\"Bunlar sonsuz azaba uğrayacak, doğrular ise sonsuz yaşama kavuşacaklar.\""}]},{"ch":26,"verses":[{"n":"1-2","h":"İsa'yı öldürme tasarısı","t":"İsa bütün bunları anlattıktan sonra öğrencilerine şöyle dedi: \"Biliyorsunuz, iki gün sonra Fısıh bayramıdır, ve İnsanoğlu çarmıha gerilmek üzere ele verilecek.\""},{"n":"3","t":"Bu sırada başkâhinler ve halkın ihtiyarları, Kayafa adındaki başkâhinin sarayında toplandılar."},{"n":"4","t":"İsa'yı hileyle tutuklayıp öldürmek için düzen kurdular."},{"n":"5","t":"Ama, 'Bayramda olmasın ki, halk arasında kargaşalık çıkmasın' diyorlardı."},{"n":"6-7","h":"İsa Beytanya'da","t":"İsa Beytanya'da cüzamlı Simun'un evindeyken, yanına bir kadın geldi. Kadın, kaymaktaşından bir kap içinde çok değerli, hoş kokulu bir yağ getirmişti. İsa sofrada otururken, kadın yağı O'nun başından aşağı döktü."},{"n":"8","t":"Öğrenciler bunu görünce kızdılar. \"Nedir bu savurganlık?\" dediler."},{"n":"9","t":"\"Bu yağ pahalıya satılabilir, parası yoksullara verilebilirdi.\""},{"n":"10","t":"Söylenenleri fark eden İsa, öğrencilerine, \"Kadını neden üzüyorsunuz?\" dedi. \"Benim için güzel bir şey yaptı."},{"n":"11","t":"Yoksullar her zaman aranızdadır, ama ben her zaman aranızda olmayacağım."},{"n":"12","t":"Kadın bu hoş kokulu yağı, beni gömülmeye hazırlamak için bedenimin üzerine boşalttı."},{"n":"13","t":"Size doğrusunu söyleyeyim, bu müjde dünyanın her neresinde duyurulursa, bu kadının yaptığı da onun anılması için anlatılacak.\""},{"n":"14-15","h":"Yahuda'nın ihaneti","t":"O sırada Onikilerden biri - adı Yahuda İskariyot olanı - başkâhinlere giderek, \"O'nu ele verirsem bana ne verirsiniz?\" dedi. Otuz gümüş tartıp ona verdiler."},{"n":"16","t":"Yahuda o andan itibaren İsa'yı ele vermek için fırsat kollamaya başladı."},{"n":"17","h":"Fısıh yemeği","t":"Mayasız Ekmek bayramının ilk günü öğrenciler İsa'nın yanına gelerek, \"Fısıh yemeğini yemen için nerede hazırlık yapmamızı istersin?\" diye sordular."},{"n":"18","t":"İsa onlara, \"Kente varıp o adamın evine gidin\" dedi. \"Ona şöyle deyin: 'Öğretmen diyor ki, zamanım yaklaştı. Fısıh bayramını, öğrencilerimle birlikte senin evinde kutlayacağım.'\""},{"n":"19","t":"Öğrenciler, İsa'nın buyruğunu yerine getirerek Fısıh yemeği için hazırlık yaptılar."},{"n":"20","t":"Akşam olunca İsa on iki öğrencisiyle yemeğe oturdu."},{"n":"21","t":"Yemek yerlerken, \"Size doğrusunu söyleyeyim, sizden biri beni ele verecek\" dedi."},{"n":"22","t":"Bu söz onları kedere boğdu. Teker teker, \"Rab, beni demek istemedin ya?\" diye sormaya başladılar."},{"n":"23","t":"O da, \"Beni ele verecek olan\" dedi, \"elindeki ekmeği benimle birlikte sahana batırandır."},{"n":"24","t":"İnsanoğlu, kendisi için yazılmış olduğu gibi gidiyor, ama İnsanoğlu'nu ele verenin vay haline! O adam hiç doğmamış olsaydı, kendisi için daha iyi olurdu.\""},{"n":"25","t":"O'nu ele verecek olan Yahuda, \"Rabbî, yoksa beni mi demek istedin?\" diye sordu.\nİsa ona, \"Söylediğin gibidir\" karşılığını verdi."},{"n":"26","t":"Yemek sırasında İsa eline ekmek aldı, şükran duasını yapıp ekmeği böldü ve öğrencilerine verdi. \"Alın, yiyin\" dedi, \"bu benim bedenimdir.\""},{"n":"27","t":"Sonra bir kâse alıp şükretti ve bunu öğrencilerine vererek, \"Hepiniz bundan için\" dedi."},{"n":"28","t":"\"Çünkü bu benim kanımdır, günahların bağışlanması için birçokları uğrunaakıtılan antlaşma kanıdır."},{"n":"29","t":"Size şunu söyleyeyim, Babamın egemenliğinde sizinle birlikte tazesini içeceğim o güne dek, asmanın bu ürününden bir daha içmeyeceğim.\""},{"n":"30","t":"Bir ilahi söyledikten sonra dışarı çıkıp Zeytin dağına doğru gittiler."},{"n":"31","h":"Petrus'un inkârı önceden bildiriliyor","t":"Bu arada İsa öğrencilerine, \"Bu gece hepiniz benden ötürü sendeleyip düşeceksiniz\" dedi. \"Çünkü şöyle yazılmıştır:\n'Çobanı vuracağım,\nsürüdeki koyunlar da darmadağın olacak.'"},{"n":"32","t":"Ama ben dirildikten sonra sizden önce Celile'ye gideceğim.\""},{"n":"33","t":"Petrus O'na, \"Herkes senden ötürü sendeleyip düşse de, ben asla düşmem\" dedi."},{"n":"34","t":"\"Sana doğrusunu söyleyeyim\" dedi İsa, \"bu gece horoz ötmeden sen beni üç kez inkâr edeceksin.\""},{"n":"35","t":"Petrus, \"Seninle birlikte ölmem bile gerekse, seni asla inkâr etmem\" dedi. Öğrencilerin hepsi de aynı şeyi söyledi."},{"n":"36","h":"Getsemani bahçesinde","t":"Sonra İsa öğrencileriyle birlikte Getsemani denen bir yere geldi. Öğrencilerine, \"Ben şuraya gidip dua edeceğim, siz burada oturun\" dedi."},{"n":"37","t":"Petrus ile Zebedi'nin iki oğlunu yanına aldı. Kederlenmeye ve ağır bir sıkıntı duymaya başlamıştı."},{"n":"38","t":"Onlara, \"Yüreğim ölüm derecesinde kederli\" dedi. \"Burada kalın, benimle birlikte uyanık durun.\""},{"n":"39","t":"Biraz ilerledi, yüzüstü yere kapanıp dua etmeye başladı. \"Baba\" dedi, \"mümkünse bu kâse benden uzaklaştırılsın. Yine de benim değil, senin istediğin olsun.\""},{"n":"40","t":"Öğrencilerin yanına döndüğünde onları uyumuş buldu. Petrus'a, \"Demek ki benimle birlikte bir saat uyanık kalamadınız!\" dedi."},{"n":"41","t":"\"Uyanık durup dua edin ki, ayartılmayasınız. Ruh isteklidir, ama beden güçsüzdür.\""},{"n":"42","t":"İsa ikinci kez uzaklaşıp dua etti. \"Baba\" dedi, \"eğer ben içmeden bu kâsenin uzaklaştırılması mümkün değilse, senin istediğin olsun.\""},{"n":"43","t":"Geri geldiğinde öğrencilerini yine uyumuş buldu. Onların göz kapaklarına bir ağırlık çökmüştü."},{"n":"44","t":"Onları bırakıp tekrar uzaklaştı, yine aynı sözlerle üçüncü kez dua etti."},{"n":"45","t":"Sonra öğrencilerin yanına dönerek, \"Hâlâ uyuyor, dinleniyor musunuz?\" dedi. \"İşte saat yaklaştı, İnsanoğlu günahkârların eline veriliyor."},{"n":"46","t":"Kalkın, gidelim. İşte beni ele veren geldi!\""},{"n":"47","h":"İsa tutuklanıyor","t":"İsa daha konuşurken, Onikilerden biri olan Yahuda geldi. Yanında, başkâhinlerle halkın ihtiyarları tarafından gönderilmişkılıçlı sopalı büyük bir kalabalık vardı."},{"n":"48","t":"İsa'yı ele veren Yahuda, \"Kimi öpersem, İsa O'dur, O'nu tutuklayın\" diye onlarla sözleşmişti."},{"n":"49","t":"Dosdoğru İsa'ya gidip, \"Selam, Rabbî!\" diyerek O'nu öptü."},{"n":"50","t":"İsa ona, \"Arkadaş, bunun için mi geldin?\" dedi. Bunun üzerine adamlar yaklaştı, İsa'yı yakalayıp tutukladılar."},{"n":"51","t":"İsa'yla birlikte olanlardan biri, ani bir hareketle kılıcını çekti, başkâhinin kölesine vurup kulağını uçurdu."},{"n":"52","t":"O zaman İsa ona, \"Kılıcını yerine koy!\" dedi. \"Kılıç çekenlerin hepsi kılıçla ölecek."},{"n":"53","t":"Yoksa Babamdan yardım isteyemez miyim sanıyorsun? İstesem, hemen şu an bana on iki tümenden fazla melek gönderir."},{"n":"54","t":"Ama böyle olması gerektiğini bildiren Kutsal Yazılar o zaman nasıl yerine gelir?\""},{"n":"55","t":"Bundan sonra İsa kalabalığa dönüp şöyle seslendi: \"Bir haydudun peşindeymiş gibi beni kılıç ve sopalarla mı yakalamaya geldiniz? Her gün tapınakta oturup ders veriyordum, beni tutuklamadınız."},{"n":"56","t":"Ama bütün bunlar, peygamberlerin yazdıkları yerine gelsin diye oldu.\" O zaman öğrencilerin hepsi O'nu bırakıp kaçtı."},{"n":"57","h":"İsa Yüksek Kurul'un önünde","t":"İsa'yı tutuklayanlar, O'nu başkâhin Kayafa'ya götürdüler. Din bilginleriyle ihtiyarlar da orada toplanmışlardı."},{"n":"58","t":"Petrus, İsa'yı uzaktan, ta başkâhinin avlusuna kadar izledi. Sonucu görmek için içeri girip nöbetçilerin yanına oturdu."},{"n":"59","t":"Başkâhinlerle Yüksek Kurul'un tamamı, İsa'yı ölüm cezasına çarptırmak için kendisine karşı yalancı tanıklar arıyorlardı."},{"n":"60-61","t":"Ortaya birçok yalancı tanık çıktığı halde, aradıklarını bulamadılar. Sonunda ortaya çıkan iki kişi şöyle dediler: \"Bu adam, 'Ben Tanrı'nın tapınağını yıkıp üç günde yeniden kurabilirim' dedi.\""},{"n":"62","t":"Başkâhin ayağa kalkıp İsa'ya, \"Hiç cevap vermeyecek misin?\" dedi. \"Nedir bunların sana karşı ettiği bu tanıklıklar?\""},{"n":"63","t":"İsa susmaya devam etti. Başkâhin ise O'na, \"Yaşayan Tanrı adına sana yemin ettiriyorum, söyle bize, Tanrı'nın Oğlu Mesih sen misin?\" dedi."},{"n":"64","t":"İsa, \"Söylediğin gibidir\" karşılığını verdi. \"Üstelik size şunu söyleyeyim, bundan sonra İnsanoğlu'nun, kudretli Olan'ın sağında oturduğunu ve göğün bulutları üzerinde geldiğini göreceksiniz.\""},{"n":"65","t":"Bunun üzerine başkâhin giysilerini yırtarak, \"Tanrı'ya küfretti!\" dedi. \"Artık tanıklara ne ihtiyacımız var? İşte küfürü işittiniz."},{"n":"66","t":"Buna ne diyorsunuz?\"\n\"Ölümü hak etti!\" diye cevap verdiler."},{"n":"67-68","t":"Bunun üzerine İsa'nın yüzüne tükürüp O'nu yumrukladılar. Bazıları da O'nu tokatlayıp, \"Ey Mesih, peygamberliğini göster bakalım, sana vuran kim?\" dediler."},{"n":"69","h":"Petrus İsa'yı inkâr ediyor","t":"Petrus ise dışarıda, avluda oturuyordu. Bir hizmetçi kızyanına gelip, \"Sen de Celileli İsa'yla birlikteydin\" dedi."},{"n":"70","t":"Ama Petrus bunu herkesin önünde inkâr ederek şöyle dedi: \"Senin neden söz ettiğini anlamıyorum.\""},{"n":"71","t":"Sonra avlu kapısının önüne çıktı. Onu gören başka bir hizmetçi kız orada bulunanlara, \"Bu adam Nasıralı İsa'yla birlikteydi\" dedi."},{"n":"72","t":"Petrus yemin ederek, \"Ben o adamı tanımıyorum\" diye yine inkâr etti."},{"n":"73","t":"Orada duranlar az sonra Petrus'a yaklaşıp, \"Gerçekten sen de onlardansın. Lehçen seni ele veriyor\" dediler."},{"n":"74","t":"Petrus kendine lanet okuyup yemin ederek, \"O adamı tanımıyorum!\" dedi.\nTam o anda horoz öttü."},{"n":"75","t":"Petrus, İsa'nın, \"Horoz ötmeden sen beni üç kez inkâr edeceksin\" dediğini hatırladı ve dışarı çıkıp acı acı ağladı."}]},{"ch":27,"verses":[{"n":"1","h":"Yahuda kendini asıyor","t":"Sabah olunca tüm başkâhinlerle halkın ihtiyarları, İsa'yı ölüm cezasına çarptırmak konusunda anlaştılar."},{"n":"2","t":"O'nu bağladılar ve götürüp vali Pilatus'a teslim ettiler."},{"n":"3","t":"İsa'yı ele veren Yahuda, O'nun mahkûm edildiğini görünce yaptığına pişman oldu. Otuz gümüşü başkâhinlere ve ihtiyarlara geri götürdü."},{"n":"4","t":"\"Ben suçsuz birini ele vermekle günah işledim\" dedi.\nOnlar ise, \"Bundan bize ne? Onu sen düşün\" dediler."},{"n":"5","t":"Yahuda paraları tapınağın içine fırlatarak oradan ayrıldı, gidip kendini astı."},{"n":"6","t":"Paraları toplayan başkâhinler, \"Kan bedeli olan bu paraları tapınağın hazinesine koymak doğru olmaz\" dediler."},{"n":"7","t":"Kendi aralarında anlaşarak bu parayla yabancılar için mezarlık yapmak üzere Çömlekçi Tarlasını satın aldılar."},{"n":"8","t":"Bunun için bu tarlaya bugüne dek 'Kan Tarlası' denilmiştir."},{"n":"9-10","t":"Böylece Yeremya peygamber aracılığıyla bildirilen şu söz yerine gelmiş oldu:\n\"İsrail oğullarından kimilerinin\nO'na biçtikleri değerin karşılığı olan\notuz gümüşü aldılar\nve Rab'bin bana buyurduğu gibi,\nçömlekçinin tarlasını satın almak için harcadılar.\""},{"n":"11","h":"İsa vali Pilatus'un önünde","t":"İsa valinin önüne çıkarıldı. Vali O'na, \"Sen Yahudilerin Kralı mısın?\" diye sordu.\nİsa, \"Söylediğin gibidir\" dedi."},{"n":"12","t":"Başkâhinlerle ihtiyarlar O'nu suçlayınca hiç karşılık vermedi."},{"n":"13","t":"Pilatus O'na, \"Senin aleyhinde yaptıkları bunca tanıklığı duymuyor musun?\" dedi."},{"n":"14","t":"İsa bir tek konuda bile onacevap vermedi. Vali buna çok şaştı."},{"n":"15","t":"Her Fısıh bayramında vali, halkın istediği bir tutukluyu salıvermeyi adet edinmişti."},{"n":"16","t":"O günlerde Barabas adında ünlü bir tutuklu vardı."},{"n":"17","t":"Halk bir araya toplandığında, Pilatus onlara, \"Sizin için kimi salıvereyim istersiniz, Barabas'ı mı, Mesih denilen İsa'yı mı?\" diye sordu."},{"n":"18","t":"İsa'yı kıskançlıktan ötürü kendisine teslim ettiklerini biliyordu."},{"n":"19","t":"Pilatus yargı kürsüsünde otururken karısı ona, \"O doğru adama dokunma. Dün gece rüyamda O'nun yüzünden çok sıkıntı çektim\" diye haber gönderdi."},{"n":"20","t":"Başkâhinler ve ihtiyarlar ise, Barabas'ın salıverilmesini ve İsa'nın öldürülmesini istesinler diye halkı kışkırttılar."},{"n":"21","t":"Vali onlara şunu sordu: \"Sizin için ikisinden hangisini salıvereyim istersiniz?\"\n\"Barabas'ı\" dediler."},{"n":"22","t":"Pilatus, \"Öyleyse Mesih denen İsa'yı ne yapayım?\" dedi.\nHep bir ağızdan, \"Çarmıha gerilsin!\" dediler."},{"n":"23","t":"Pilatus, \"O ne kötülük yaptı ki?\" diye sordu.\nOnlar ise daha yüksek sesle, \"Çarmıha gerilsin!\" diye bağrışıp durdular."},{"n":"24","t":"Pilatus, elinden bir şey gelmediğini, tersine, bir kargaşalığın başladığını görünce su aldı, kalabalığın önünde ellerini yıkayıp şöyle dedi: \"Bu adamın kanından ben sorumlu değilim. Bu işe siz bakın!\""},{"n":"25","t":"Bütün halk şu karşılığı verdi: \"O'nun kanının sorumluluğu bizim ve çocuklarımızın üzerinde olsun!\""},{"n":"26","t":"Bunun üzerine Pilatus onlar için Barabas'ı salıverdi. İsa'yı ise kamçılattıktan sonra çarmıha gerilmek üzere askerlere teslim etti."},{"n":"27","h":"Askerlerin İsa'yı aşağılaması","t":"Sonra valinin askerleri İsa'yı vali konağına götürüp tüm taburu başına topladılar."},{"n":"28","t":"O'nu soyup üzerine kırmızı bir kaftan geçirdiler."},{"n":"29","t":"Dikenlerden bir taç örüp başına koydular, sağ eline de bir kamış tutturdular. Önünde diz çöküp, \"Selam, ey Yahudilerin Kralı!\" diyerek O'nunla alay ettiler."},{"n":"30","t":"Üzerine tükürdüler, kamışı alıp başına vurdular."},{"n":"31","t":"O'nunla böyle alay ettikten sonra kaftanı üzerinden çıkarıp O'na yine kendi giysilerini giydirdiler ve çarmıha germek üzere O'nu alıp götürdüler."},{"n":"32","h":"İsa çarmıha geriliyor","t":"Dışarı çıktıklarında Simun adında Kireneli bir adama rastladılar. İsa'nın çarmıhını ona zorla taşıttılar."},{"n":"33-34","t":"Golgota, yani Kafatası denilen yere vardıklarında içmesi için İsa'ya ödle karışık şarap verdiler. İsa bunu tadınca içmek istemedi."},{"n":"35","t":"Askerler O'nu çarmıha gerdikten sonra kura çekerek giysilerini aralarında paylaştılar."},{"n":"36","t":"Sonra oturup yanında nöbet tuttular."},{"n":"37","t":"Başının üzerine,\n\"BU, YAHUDİLERİN KRALI İSA'DIR\"\ndiye yazan bir suç yaftası astılar."},{"n":"38","t":"İsa'yla birlikte, biri sağında öbürü solunda olmak üzere iki haydut da çarmıha gerildi."},{"n":"39-40","t":"Oradan geçenler başlarını sallayıp İsa'ya sövüyor, \"Hani sen tapınağı yıkıp üç günde yeniden kuracaktın? Haydi, kurtar kendini! Tanrı'nın Oğluysan, çarmıhtan in!\" diyorlardı."},{"n":"41-42","t":"Başkâhinler, din bilginleri ve ihtiyarlar da aynı şekilde O'nunla alay ederek, \"Başkalarını kurtardı, kendini kurtaramıyor\" diyorlardı. \"İsrail'in Kralı imiş! Şimdi çarmıhtan aşağı insin de O'na iman edelim."},{"n":"43","t":"Tanrı'ya güveniyordu; Tanrı O'nu seviyorsa, kurtarsın bakalım! Çünkü, 'Ben Tanrı'nın Oğluyum' demişti.\""},{"n":"44","t":"İsa'yla birlikte çarmıha gerilmiş olan haydutlar da O'na aynı şekilde hakaret ettiler."},{"n":"45","h":"İsa'nın ölümü","t":"Bütün ülkenin üzerine öğleyin saat on ikiden saat üçe kadar süren bir karanlık çöktü."},{"n":"46","t":"Saat üçe doğru İsa yüksek sesle, \"Elî, Elî, lema şevaktani?\" yani, \"Tanrım, Tanrım, beni niçin terk ettin?\" diye bağırdı."},{"n":"47","t":"Orada duranlardan bazıları bunu işitince, \"Bu adam İlyas'ı çağırıyor\" dediler."},{"n":"48","t":"İçlerinden biri hemen koşup bir sünger getirdi, ekşi şaraba batırıp bir kamışın ucuna takarak İsa'ya içirdi."},{"n":"49","t":"Diğerleri ise, \"Dur bakalım, İlyas gelip O'nu kurtaracak mı?\" dediler."},{"n":"50","t":"İsa, yüksek sesle bir kez daha bağırdı ve ruhunu teslim etti."},{"n":"51","t":"O anda tapınaktaki perde yukarıdan aşağıya dek yırtılarak ikiye bölündü. Yer sarsıldı, kayalar yarıldı."},{"n":"52","t":"Mezarlar açıldı, ölmüş olan birçok kutsal kişinin cesetleri dirildi."},{"n":"53","t":"Bunlar mezarlarından çıkıp İsa'nın dirilişinden sonra kutsal kente girdiler ve birçok kimseye göründüler."},{"n":"54","t":"İsa'yı bekleyen yüzbaşı ve beraberindeki askerler, depremi ve öbür olayları görünce dehşete kapıldılar ve, \"Bu gerçekten Tanrı'nın Oğluydu!\" dediler."},{"n":"55","t":"Orada, olup bitenleri uzaktan izleyen birçok kadın vardı. Bunlar, Celile'den İsa'nın peşinden gelip O'na hizmet etmişlerdi."},{"n":"56","t":"Aralarında Mecdelli Meryem, Yakup ile Yusuf'un annesi Meryem ve Zebedi oğullarının annesi de vardı."},{"n":"57","h":"İsa'nın gömülmesi","t":"Akşama doğru Yusuf adında zengin bir Aramatyalı geldi. O da İsa'nın bir öğrencisiydi."},{"n":"58","t":"Pilatus'a gidip İsa'nın cesedini istedi. Pilatus da cesedin ona verilmesini buyurdu."},{"n":"59-60","t":"Yusuf cesedi aldı, temiz keten beze sardı, kayaya oydurmuş olduğu kendi yeni mezarına yatırdı. Mezarın girişine büyük bir taş yuvarlayıp oradan ayrıldı."},{"n":"61","t":"Mecdelli Meryem ile öteki Meryem ise orada, mezarın karşısında oturuyorlardı."},{"n":"62-63","t":"Ertesi gün, yani Hazırlık gününden sonraki gün, başkâhinlerle Ferisiler Pilatus'un önünde toplanarak, \"Efendimiz\"dediler, \"O aldatıcının, daha yaşarken, 'Ben öldükten üç gün sonra dirileceğim' dediğini hatırlıyoruz."},{"n":"64","t":"Onun için buyruk ver de üçüncü güne dek mezarı güvenlik altına alsınlar. Yoksa öğrencileri gelir, cesedini çalar ve halka, 'Ölümden dirildi' derler. Bu sonuncu aldatmaca ilkinden beter olur.\""},{"n":"65","t":"Pilatus onlara, \"Bir manga asker alın, gidip mezarı dilediğiniz gibi güvenlik altına alın\" dedi."},{"n":"66","t":"Onlar da askerlerle birlikte gittiler, taşı mühürleyip mezarı güvenlik altına aldılar."}]},{"ch":28,"verses":[{"n":"1","h":"İsa'nın dirilişi","t":"Sept gününü izleyen haftanın ilk günü, tan yeri ağarırken, Mecdelli Meryem ile öbür Meryem mezarı görmeye gittiler."},{"n":"2","t":"Ansızın büyük bir deprem oldu. Rab'bin bir meleği gökten indi ve mezara gidip taşı bir yana yuvarlayarak üzerine oturdu."},{"n":"3","t":"Görünüşü şimşek gibi, giysileri ise kar gibi bembeyazdı."},{"n":"4","t":"Nöbetçiler korkudan titremeye başladılar, sonra ölü gibi yere yıkıldılar."},{"n":"5","t":"Melek kadınlara şöyle seslendi: \"Korkmayın! Çarmıha gerilmiş olan İsa'yı aradığınızı biliyorum."},{"n":"6","t":"O burada yok; söylemiş olduğu gibi dirildi. Gelin, O'nun yattığı yeri görün."},{"n":"7","t":"Hemen O'nun öğrencilerine gidip şöyle deyin: 'İsa ölümden dirildi. Sizden önce Celile'ye gidiyor, kendisini orada göreceksiniz.' İşte ben size söylemiş bulunuyorum.\""},{"n":"8","t":"Kadınlar, hem korku hem büyük sevinç içinde, çabucak mezardan uzaklaşıp koşa koşa İsa'nın öğrencilerine haber vermeye gittiler."},{"n":"9","t":"Ansızın İsa onların karşısına çıktı, \"Selam size!\" dedi. Onlar da yaklaşıp İsa'nın ayaklarına sarıldılar, O'na tapınmaya başladılar."},{"n":"10","t":"O zaman İsa onlara, \"Korkmayın!\" dedi. \"Gidip kardeşlerime haber verin, Celile'ye gitsinler, beni orada görecekler.\""},{"n":"11","h":"Nöbetçilerin getirdiği haber","t":"Kadınlar daha yoldayken nöbetçi askerlerden bazıları kente giderek olup bitenlerin hepsini başkâhinlere bildirdiler."},{"n":"12-13","t":"Başkâhinler ihtiyarlarla birlikte toplanıp birbirlerine danıştıktan sonra askerlere çok miktarda para vererek dediler ki, \"Siz şöyle diyeceksiniz: 'Öğrencileri geceleyin geldi, biz uyurken O'nun cesedini çalıp götürdüler.'"},{"n":"14","t":"Eğer bu haber valinin kulağına gidecek olursa biz onu yatıştırır, size bir zarar gelmesini önleriz.\""},{"n":"15","t":"Böylece askerler parayı aldılar ve kendilerine söylendiği gibi yaptılar. Bu söylenti bugüne dek Yahudiler arasında tekrarlanagelmiştir."},{"n":"16","h":"Son buyruk","t":"On bir öğrenci Celile'ye, İsa'nın kendilerine bildirdiği dağagittiler."},{"n":"17","t":"İsa'yı gördükleri zaman O'na tapındılar. Ama bazıları kuşku içindeydi."},{"n":"18","t":"İsa yanlarına gelip kendilerine şunları söyledi: \"Gökte ve yeryüzünde bütün yetki bana verildi."},{"n":"19","t":"Bu nedenle gidin, bütün ulusları öğrencilerim olarak yetiştirin. Onları Baba, Oğul ve Kutsal Ruh'un adıyla vaftiz edin."},{"n":"20","t":"Size buyurduğum her şeye uymayı onlara öğretin. İşte ben, dünyanın sonuna dek her an sizinle birlikteyim.\""}]}]},{"id":"markos","name":"Markos","chapters":[{"ch":1,"verses":[{"n":"1","h":"Vaftizci Yahya'nın gelişi","t":"Tanrı'nın Oğlu İsa Mesih'le ilgili müjdenin başlangıcı."},{"n":"2","t":"Yeşaya peygamberin kitabında şöyle yazılmıştır:\n\"Bak, habercimi senin önünden gönderiyorum;\no senin yolunu hazırlayacak.\""},{"n":"3","t":"\"Çölde yükselen ses,\n'Rab'bin yolunu hazırlayın,\ngeçeceği patikaları düzleyin' diyor.\""},{"n":"4","t":"Böylece Vaftizci Yahya çölde ortaya çıktı. İnsanları, günahlarının bağışlanması için tövbe edip vaftiz olmaya çağırıyordu."},{"n":"5","t":"Bütün Yahudiye halkı ve Kudüslülerin hepsi ona geliyor, günahlarını itiraf ediyor, onun tarafından Şeria nehrinde vaftiz ediliyordu."},{"n":"6","t":"Yahya'nın deve tüyünden giysisi, belinde deriden kuşağı vardı. Çekirge ve yaban balı yerdi."},{"n":"7","t":"Şu haberi yayıyordu: \"Benden sonra benden daha güçlü Olan geliyor. Eğilip O'nun çarıklarının bağını çözmeye bile layık değilim."},{"n":"8","t":"Ben sizi suyla vaftiz ettim, ama O sizi Kutsal Ruh'la vaftiz edecektir.\""},{"n":"9","h":"İsa görevine başlıyor","t":"O günlerde Celile'nin Nasıra kentinden çıkıp gelen İsa, Yahya tarafından Şeria nehrinde vaftiz edildi."},{"n":"10","t":"Tam sudan çıkarken, göklerin yarıldığını ve Ruh'un güvercin gibi kendi üzerine indiğini gördü."},{"n":"11","t":"Göklerden, \"Sen benim sevgili Oğlumsun, senden hoşnudum\" diyen bir ses geldi."},{"n":"12","t":"O an Ruh, İsa'yı çöle gönderdi."},{"n":"13","t":"İsa çölde kaldığı kırk gün boyunca Şeytan tarafından sınandı. Yabani hayvanlar arasındaydı ve melekler O'na hizmet ediyordu."},{"n":"14","t":"Yahya'nın tutuklanmasından sonra İsa, Tanrı'nın müjdesini duyura duyura Celile'ye gitti."},{"n":"15","t":"\"Zaman doldu\" diyordu, \"Tanrı'nın Egemenliği yaklaştı. Tövbe edin, Müjde'ye inanın!\""},{"n":"16","t":"İsa, Celile gölünün kıyısından geçerken, göle ağ atmakta olan Simun ile kardeşi Andreya'yı gördü. Bu adamlar balıkçıydı."},{"n":"17","t":"İsa onlara, \"Ardımdan gelin, sizleri insan tutan balıkçılar yapacağım\" dedi."},{"n":"18","t":"Onlar da hemen ağlarını bırakıp O'nun ardından gittiler."},{"n":"19","t":"Oradan biraz ileri gidince Zebedi'nin oğulları Yakup'la Yuhanna'yı gördü. Kayıkta ağlarını onarıyorlardı."},{"n":"20","t":"İsa hemen onları çağırdı. Onlar da babaları Zebedi'yi işçilerle birlikte kayıkta bırakarak İsa'nın ardından gittiler."},{"n":"21","h":"İsa kötü ruhları kovuyor, hastaları iyileştiriyor","t":"Kefernahum'a girdiler. Sept günü olunca İsa hemen havraya girip ders vermeye başladı."},{"n":"22","t":"Halk O'nun öğretişine şaşıp kaldı. Çünkü onlara din bilginleri gibi değil, yetkili biri gibi ders veriyordu."},{"n":"23-24","t":"Tam o sırada havralarında bulunan ve kötü ruha tutsak olan bir adam, \"Ey Nasıralı İsa, bizden ne istiyorsun?\" diye bağırdı. \"Bizi mahvetmeye mi geldin? Senin kim olduğunu biliyorum, Tanrı'nın Kutsalısın sen!\""},{"n":"25","t":"İsa, \"Sus, çık o adamdan!\" diyerek kötü ruhu azarladı."},{"n":"26","t":"Kötü ruh adamı sarstı ve büyük bir çığlık atarak içinden çıktı."},{"n":"27","t":"Herkes şaşıp kaldı. Birbirlerine, \"Bu nasıl şey?\" diye sormaya başladılar. \"Yepyeni bir öğreti! Kötü ruhlara bile yetkiyle buyruk veriyor, onlar da sözünü dinliyorlar.\""},{"n":"28","t":"Böylece İsa'yla ilgili haberler, tüm Celile bölgesinin her yerine hızla yayıldı."},{"n":"29","t":"İsa havradan çıkar çıkmaz, Yakup ve Yuhanna ile birlikte Simun ve Andreya'nın evine gitti."},{"n":"30","t":"Simun'un kaynanası ateşler içinde yatıyordu. Durumu hemen İsa'ya bildirdiler."},{"n":"31","t":"O da hastaya yaklaştı, elinden tutup kaldırdı. Kadının ateşi düştü ve kendisi onlara hizmet etmeye başladı."},{"n":"32","t":"Akşam olup güneş batınca, bütün hastaları ve cine tutsak olanları İsa'ya getirdiler."},{"n":"33","t":"Bütün kent halkı kapıya toplanmıştı."},{"n":"34","t":"İsa, çeşitli hastalıklara yakalanmış birçok kişiyi iyileştirdi, birçok cini kovdu. Cinlerin konuşmasına izin vermiyordu. Çünkü onlar kendisinin kim olduğunu biliyorlardı."},{"n":"35","t":"Sabah çok erkenden, ortalık henüz ağarmadan İsa kalktı, evden çıkıp ıssız bir yere gitti, orada dua etmeye başladı."},{"n":"36","t":"Simun ile yanındakiler İsa'yı aramaya çıktılar."},{"n":"37","t":"O'nu bulunca, \"Herkes seni arıyor!\" dediler."},{"n":"38","t":"İsa onlara, \"Başka yerlere, yakındaki kasabalara gidelim\" dedi. \"Oralarda da Tanrı sözünü duyurayım. Bunun için çıkıp geldim.\""},{"n":"39","t":"Böylece havralarında Tanrı sözünü duyurarak ve cinleri kovarak tüm Celile bölgesini dolaştı."},{"n":"40","h":"İsa bir cüzamlıyı iyileştiriyor","t":"İsa'ya cüzamlı biri geldi, diz çöküp O'na şöyle yalvardı: \"Eğer istersen beni temiz kılabilirsin.\""},{"n":"41","t":"Yüreği sızlayan İsa, elini uzatıp adama dokundu, \"İsterim, temiz ol!\" dedi."},{"n":"42","t":"Adam hemen o anda cüzamdan kurtulup tertemiz oldu."},{"n":"43","t":"İsa onu sıkıca uyararak derhal yanından uzaklaştırdı."},{"n":"44","t":"\"Sakın kimseye bir şey söyleme!\" dedi. \"Git, kâhine görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musa'nın buyurduğu adakları sun.\""},{"n":"45","t":"Ne var ki, adam çıkıp gitti, olayla ilgili haberi her tarafa yayıp duyurmaya başladı. Öyle ki, İsa artık hiçbir kente açıkça giremez oldu. Ancak dışarıda, ıssız yerlerde kalıyordu. Ve halk her yerden O'na akın ediyordu."}]},{"ch":2,"verses":[{"n":"1","h":"Bir felçlinin iyileştirilmesi","t":"Birkaç gün sonra İsa tekrar Kefernahum'a geldiğinde, evde olduğu işitildi."},{"n":"2","t":"O kadar çok insan toplandı ki, artık kapının önünde bile duracak yer kalmamıştı. İsa onlara Tanrı sözünü anlatıyordu."},{"n":"3","t":"Bu arada O'na dört kişinin taşıdığı felçli bir adamı getirdiler."},{"n":"4","t":"Kalabalıktan O'na yaklaşamadıkları için, bulunduğu yerin üzerindeki damı delip açarak felçliyi üstünde yattığı döşekle birlikte aşağı indirdiler."},{"n":"5","t":"Onların imanını gören İsa felçliye, \"Oğlum, günahların bağışlandı\" dedi."},{"n":"6-7","t":"Orada oturmakta olan bazı din bilginleri ise için için şöyle düşündüler: \"Bu adam neden böyle konuşuyor? Tanrı'ya küfrediyor! Tek Tanrı'dan başka kim günahları bağışlayabilir?\""},{"n":"8","t":"Akıllarından geçeni hemen ruhunda sezen İsa onlara, \"Aklınızdan neden böyle şeyler geçiriyorsunuz?\" dedi."},{"n":"9","t":"\"Hangisi daha kolay, felçliye, 'Günahların bağışlandı' demek mi, yoksa, 'Kalk, döşeğini topla ve yürü' demek mi?"},{"n":"10-11","t":"Ne var ki, İnsanoğlu'nun yeryüzünde günahları bağışlama yetkisine sahip olduğunu bilesiniz diye…\" Sonra felçliye, \"Sana söylüyorum, kalk, döşeğini topla ve evine git!\" dedi."},{"n":"12","t":"Adam kalktı, derhal döşeğini topladı ve hepsinin gözü önünde çıkıp gitti. Herkes şaşakalmıştı. Tanrı'yı övüyorlar, \"Böylesini hiç görmemiştik\" diyorlardı."},{"n":"13","h":"Levi'nin öğrencilere katılması","t":"İsa yine çıkıp göl kıyısına gitti. Bütün halk O'nun yanına geldi, O da onlara ders vermeye başladı."},{"n":"14","t":"Yoldan geçerken, vergi toplama kulübesinde oturan Alfay oğlu Levi'yi gördü. Ona, \"Ardımdan gel\" dedi. Levi de kalkıp İsa'nın ardından gitti."},{"n":"15","t":"Daha sonra İsa, Levi'nin evinde yemek yerken, birçok vergi görevlisi ve günahkâr birçok kişi O'nunla ve öğrencileriyle birlikte sofraya oturmuştu. O'nu izleyen böyle birçok kişi vardı."},{"n":"16","t":"Ferisilerden bazı din bilginleri, O'nu günahkârlar ve vergi görevlileriyle birlikte yemekte görünce öğrencilerine, \"Niçin vergi görevlileri ve günahkârlarla birlikte yemek yiyor?\" diye sordular."},{"n":"17","t":"Bunu işiten İsa onlara, \"Sağlamların değil, hastaların hekime ihtiyacı var\" dedi. \"Ben doğru kişileri değil, günahkârları çağırmaya geldim.\""},{"n":"18","h":"Oruçla ilgili soru","t":"Yahya'nın öğrencileriyle Ferisiler oruç tutarken, bazı kişiler İsa'ya gelip, \"Yahya'nın ve Ferisilerin öğrencileri oruç tutuyor da, senin öğrencilerin niçin tutmuyor?\" diye sordular."},{"n":"19","t":"İsa şöyle karşılık verdi: \"Güvey aralarında olduğu sürece davetliler oruç tutar mı hiç? Güvey aralarında oldukça oruç tutamazlar!"},{"n":"20","t":"Ama güveyin aralarından alınacağı günler gelecek, onlar işte o zaman, o gün oruç tutacaklar."},{"n":"21","t":"Hiç kimse eski bir giysiyi çekmemiş bir kumaş parçasıyla yamamaz. Yoksa yeni yama eski giysiden kopar ve yırtık daha kötü duruma gelir."},{"n":"22","t":"Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa şarap tulumları patlatır, şarap da tulumlar da mahvolur. Yeni şarap yeni tulumlara doldurulur.\""},{"n":"23","h":"Sept günü sorunu","t":"Bir Sept günü İsa ekinler arasından geçiyordu. Öğrencileri yolda giderken başakları koparmaya başladılar."},{"n":"24","t":"Ferisiler İsa'ya, \"Bak, Sept günü yapılması yasak olanı neden yapıyorlar?\" dediler."},{"n":"25","t":"İsa onlara, \"Davut'un, kendisi ve yanındakiler aç ve muhtaç kalınca ne yaptığını hiç okumadınız mı?\" diye sordu."},{"n":"26","t":"\"Başkâhin Aviyatar'ın zamanında Davut, Tanrı'nın evine girdi, kâhinlerden başkasının yemesi yasak olan adak ekmeklerini yedi ve yanındakilere de verdi.\""},{"n":"27","t":"Sonra onlara, \"İnsan Sept günü için değil, Sept günü insan için yaratıldı\" dedi."},{"n":"28","t":"\"Bu nedenle İnsanoğlu Sept gününün de Rabbidir.\""}]},{"ch":3,"verses":[{"n":"1","h":"Eli sakat bir adam iyileştiriliyor","t":"İsa yine havraya girdi. Orada eli sakat bir adam vardı."},{"n":"2","t":"Bazıları İsa'yı suçlamak amacıyla, Sept günü hastayı iyileştirecek mi diye O'nu gözlüyorlardı."},{"n":"3","t":"İsa, eli sakat olan adama, \"Ayağa kalk, ortaya çık!\" dedi."},{"n":"4","t":"Sonra havradakilere, \"Kutsal Yasa'ya göre Sept günü iyilik yapmak mı doğru, kötülük yapmak mı? Can kurtarmak mı doğru, öldürmek mi?\" diye sordu. Onlardan ses çıkmadı."},{"n":"5","t":"İsa, çevresindekilere öfkeyle baktı. Yüreklerinin katılığı O'nu kederlendirmişti. Adama, \"Elini uzat!\" dedi. Adam elini uzattı, eli eskisi gibi sağlam oluverdi."},{"n":"6","t":"Dışarı çıkan Ferisiler, İsa'yı yok etmek için Hirodes yanlılarıyla hemen görüşmeye başladılar."},{"n":"7-8","h":"İsa, Celile gölünün kıyısında","t":"İsa, öğrencileriyle birlikte göl kıyısına çekildi. Celile'den büyük bir kalabalık O'nun ardından geldi. Ayrıca, O'nun bütün yaptıklarını duyan büyük bir kalabalık Yahudiye'den, Kudüs'ten, İdumeya'dan, Şeria nehrinin ötesinden, Sur ve Sayda bölgelerinden kendisine akın etti."},{"n":"9","t":"İsa, kalabalığın arasında sıkışıp kalmamak için öğrencilerine, küçük bir kayığı hazır bulundurmalarını söyledi."},{"n":"10","t":"Birçoklarını iyileştirmiş olduğundan, çeşitli hastalıklara yakalanmış olanların hepsi O'na dokunmak için üzerine üşüşüyorlardı."},{"n":"11","t":"Kötü ruhlar da O'nu görünce ayaklarına kapanıyor, \"Sen Tanrı'nın Oğlusun!\" diye bağırıyorlardı."},{"n":"12","t":"Ama İsa, kim olduğunu açıklamasınlar diye onları sıkı sıkıya uyardı."},{"n":"13","h":"İsa on iki elçisini seçiyor","t":"İsa, dağa çıkarak istediği kişileri yanına çağırdı. Onlar da yanına gittiler."},{"n":"14-19","t":"İsa bunlardan on iki kişiyi yanında bulundurmak, Tanrı sözünü duyurmaya göndermek ve cinleri kovmaya yetkili kılmak üzere seçti. Seçtiği bu on iki kişi şunlardır: Petrus adını verdiği Simun, Beni-Regeş, yani 'GökgürültüsüOğulları' adını verdiği Zebedi'nin oğulları Yakup ve Yuhanna, Andreya, Filipus, Bartalmay, Matta, Tomas, Alfay oğlu Yakup, Taday, Yurtsever Simun ve İsa'yı ele veren Yahuda İskariyot."},{"n":"20","h":"İsa ve Beelzebub","t":"İsa bundan sonra eve gitti. Yine öyle büyük bir kalabalık toplandı ki, İsa'yla öğrencileri yemek bile yiyemediler."},{"n":"21","t":"Yakınları bunu duyunca, \"Aklını kaçırmış\" diyerek O'nu almaya geldiler."},{"n":"22","t":"Kudüs'ten gelen din bilginleri ise, \"Beelzebub O'nun içine girmiş\" ve \"Cinleri, cinlerin reisinin gücüyle kovuyor\" diyorlardı."},{"n":"23","t":"Bunun üzerine İsa din bilginlerini yanına çağırıp onlara benzetmelerle seslendi. \"Şeytan, Şeytan'ı nasıl kovabilir?\" dedi."},{"n":"24","t":"\"Bir ülke kendi içinde bölünmüşse, o ülke ayakta kalamaz."},{"n":"25","t":"Bir ev kendi içinde bölünmüşse, o ev ayakta kalamaz."},{"n":"26","t":"Şeytan da kendine karşı gelip kendi içinde bölünmüşse, artık ayakta kalamaz; sonu gelmiş demektir."},{"n":"27","t":"Hiç kimse güçlü adamın evine girip onun malını çalamaz. Ancak önceden o güçlü adamı bağlarsa, onun evini soyabilir."},{"n":"28-29","t":"Size doğrusunu söyleyeyim, insanların işlediği her günah, ettiği her küfür bağışlanacak, ama Kutsal Ruh'a küfreden asla bağışlanmayacak. Bunu yapan, asla silinmeyecek bir günah işlemiş olur.\""},{"n":"30","t":"İsa bu sözleri, \"O'nda kötü ruh var\" dedikleri için söyledi."},{"n":"31","h":"İsa'nın annesiyle kardeşleri","t":"Daha sonra İsa'nın annesiyle kardeşleri geldi. Dışarıda durdular, haber gönderip O'nu çağırdılar."},{"n":"32","t":"İsa'nın çevresinde oturan kalabalıktan bazıları, \"Bak\" dediler, \"annenle kardeşlerin dışarıda, seni istiyorlar.\""},{"n":"33","t":"İsa buna karşılık onlara, \"Kimdir annem ve kardeşlerim?\" dedi."},{"n":"34","t":"Sonra etrafına, çevresinde oturanlara bakıp şöyle dedi: \"İşte annem, işte kardeşlerim!"},{"n":"35","t":"Tanrı'nın isteğini kim yerine getirirse, kardeşim, kızkardeşim ve annem odur.\""}]},{"ch":4,"verses":[{"n":"1","h":"Tohum benzetmesi","t":"İsa göl kıyısında halka yine ders vermeye başladı. Çevresinde öyle büyük bir kalabalık toplandı ki, kendisi göldeki bir kayığa binip oturdu. Bütün kalabalık göl kıyısında, karada duruyordu."},{"n":"2-3","t":"İsa onlara benzetmelerle birçok şey öğretiyordu. Öğretirken, \"Şunu dinleyin\" dedi. \"Ekincinin biri tohum ekmeye çıkmış."},{"n":"4","t":"Ektiği tohumlardan kimi yol kenarına düşmüş. Kuşlar gelip bunları yemiş."},{"n":"5","t":"Kimi, toprağı az olan kayalık yere düşmüş. Toprak derin olmadığından hemen filizlenmişler."},{"n":"6","t":"Ne var ki, güneş doğunca kavrulmuşlar ve kök salamadıkları için kuruyup gitmişler."},{"n":"7","t":"Kimi, dikenler arasına düşmüş. Dikenler büyümüş, filizleri boğmuş ve filizler ürün verememiş."},{"n":"8","t":"Kimi ise iyi toprağa düşmüş, büyüyüpçoğalmış, ürün vermiş. Bazısı otuz, bazısı altmış, bazısı da yüz kat ürün vermiş.\""},{"n":"9","t":"Sonra İsa şunu ekledi: \"İşitecek kulağı olan işitsin!\""},{"n":"10","h":"Benzetmelerin amacı","t":"Onikilerle diğer izleyicileri İsa'yla yalnız kalınca, kendisinden benzetmelerin anlamını sordular."},{"n":"11","t":"O da onlara şöyle dedi: \"Tanrı'nın Egemenliğinin sırrı sizlere açıklandı, ama dışarıda olanlara her şey benzetmelerle anlatılır."},{"n":"12","t":"Öyle ki,\n'Bakıp bakıp görmesinler,\nduyup duyup anlamasınlar da,\ndönüp bağışlanmasınlar.'\""},{"n":"13","h":"Tohum benzetmesi açıklanıyor","t":"İsa sonra onlara, \"Siz bu benzetmeyi anlamıyor musunuz?\" dedi. \"Öyleyse bütün diğer benzetmeleri nasıl anlayacaksınız?"},{"n":"14","t":"Ekincinin ektiği, Tanrı sözüdür."},{"n":"15","t":"Bazı insanlar sözün ekildiği yerde yol kenarına düşen tohumlara benzer. Bunlar sözü işitir işitmez, Şeytan gelir, yüreklerine ekilen sözü alır götürür."},{"n":"16-17","t":"Kayalık yerlere ekilenler ise, işittikleri sözü hemen sevinçle kabul eden, ama kök salamadıkları için ancak bir süre dayanan kişilerdir. Böyleleri Tanrı sözünden ötürü sıkıntı ya da zulme uğrayınca hemen sendeleyip düşerler."},{"n":"18-19","t":"Yine bazıları dikenler arasında ekilen tohumlara benzerler. Bunlar sözü işitirler, ama dünyasal kaygılar, zenginliğin aldatıcılığı ve daha başka hevesler araya girip sözü boğar ve ürün vermesini engeller."},{"n":"20","t":"İyi toprağa ekilenler ise, sözü işiten, onu benimseyen, kimi otuz, kimi altmış, kimi de yüz kat ürün veren kişilerdir.\""},{"n":"21","h":"Kandil kandilliğe konur","t":"Onlara, \"Kandili, tahıl ölçeğinin ya da yatağın altına koymak için mi getirirler?\" dedi. \"Kandilliğe koymak için değil mi?"},{"n":"22","t":"Gizli olan ne varsa, açığa çıkarılmak üzere gizlenmiştir; saklı olan ne varsa, aydınlığa çıkmak üzere saklanmıştır."},{"n":"23","t":"İşitecek kulağı olan işitsin!\""},{"n":"24","t":"İsa şöyle devam etti: \"İşittiklerinize dikkat edin! Hangi ölçekle ölçerseniz, size de aynı ölçek uygulanacak. Hatta size daha fazlası verilecek."},{"n":"25","t":"Çünkü kimde varsa, ona daha çok verilecek. Ama kimde yoksa, kendisinde olan da elinden alınacak.\""},{"n":"26","h":"Filizlenen tohum benzetmesi","t":"Sonra İsa şöyle dedi: \"Tanrı'nın Egemenliği, toprağa tohum saçan adama benzer."},{"n":"27","t":"Gece olur, uyur; gündüz olur, kalkar. Kendisi nasıl olduğunu bilmez ama, tohum filizlenir, gelişir."},{"n":"28","t":"Toprak kendiliğinden ürün verir. Önce filizi, sonra başağı, sonunda da başağı dolduran taneleri verir."},{"n":"29","t":"Ürün olgunlaşınca, adam hemenorağı vurur. Çünkü ürünü biçme zamanı gelmiştir.\""},{"n":"30","h":"Hardal tanesi benzetmesi","t":"İsa sonra şöyle dedi: \"Tanrı'nın Egemenliğini neye benzetelim, nasıl bir benzetmeyle anlatalım?"},{"n":"31-32","t":"Tanrı'nın Egemenliği, hardal tanesine benzer. Hardal, yeryüzünde toprağa ekilen tüm tohumların en küçüğü olmakla birlikte, ekildikten sonra gelişir, tüm bahçe bitkilerinin boyunu aşar. Öylesine dal budak salar ki, gökte uçan kuşlar gölgesinde barınabilir.\""},{"n":"33","t":"İsa, Tanrı sözünü, buna benzer birçok benzetmeyle halkın anlayabildiği ölçüde anlatırdı."},{"n":"34","t":"Benzetme kullanmadan onlara hiçbir şey anlatmazdı. Ama kendi öğrencileriyle yalnız kaldığında, onlara her şeyi açıklardı."},{"n":"35","h":"İsa fırtınayı yatıştırıyor","t":"O gün akşam olunca öğrencilerine, \"Karşı yakaya geçelim\" dedi."},{"n":"36","t":"Öğrenciler kalabalığı geride bırakarak İsa'yı, içinde bulunduğu kayıkla götürdüler. Yanında başka kayıklar da vardı."},{"n":"37","t":"Bu sırada büyük bir fırtına koptu. Dalgalar kayığa öyle saldırıyordu ki, kayık neredeyse suyla dolmuştu."},{"n":"38","t":"İsa, kayığın kıç tarafında bir yastığa yaslanmış uyuyordu. Öğrenciler O'nu uyandırıp, \"Öğretmenimiz, batıyoruz! Hiç aldırmıyor musun?\" dediler."},{"n":"39","t":"İsa kalkıp rüzgârı azarladı, göle, \"Sus, sakin ol!\" dedi. Rüzgâr dindi, ortalık sütliman oldu."},{"n":"40","t":"İsa öğrencilerine, \"Neden bu kadar korkaksınız? Hâlâ imanınız yok mu?\" dedi."},{"n":"41","t":"Onlar ise büyük korku içinde birbirlerine, \"Bu adam kim ki, rüzgâr da göl de O'nun sözünü dinliyor?\" dediler."}]},{"ch":5,"verses":[{"n":"1","h":"Cinli bir adamın iyileştirilmesi","t":"Gölün karşı yakasına, Gerasalıların memleketine vardılar."},{"n":"2","t":"İsa kayıktan iner inmez, kötü ruha tutsak olan bir adam mezarlık mağaralardan çıkıp O'nu karşıladı."},{"n":"3","t":"Mezarların içinde yaşayan bu adamı artık kimse zincirle bile bağlı tutamıyordu."},{"n":"4","t":"Birçok kez zincirler ve ayak köstekleriyle bağlandığı halde, zincirleri koparmış, köstekleri parçalamıştı. Hiç kimse onunla başa çıkamıyordu."},{"n":"5","t":"Gece gündüz mezarlarda, dağlarda bağırıp duruyor, kendi kendini taşlarla yaralıyordu."},{"n":"6","t":"Uzaktan İsa'yı görünce koşup geldi, O'nun önünde yere kapandı."},{"n":"7","t":"Yüksek sesle haykırarak, \"Ey İsa, yüce Tanrı'nın Oğlu, benden ne istiyorsun? Tanrı hakkı için sana yalvarırım, bana işkence etme!\" dedi."},{"n":"8","t":"Çünkü İsa, \"Ey kötü ruh, adamın içinden çık!\" demişti."},{"n":"9","t":"Sonra İsa adama, \"Adın ne?\" diye sordu.\n\"Adım Tümen. Çünkü sayımız çok\" dedi."},{"n":"10","t":"Ruhları o bölgeden çıkarmaması için İsa'ya yalvarıp yakardı."},{"n":"11","t":"Orada, dağın yamacında otlayan büyük bir domuz sürüsü vardı."},{"n":"12","t":"Kötü ruhlar İsa'ya, \"Bizi şu domuzlara gönder, onlara girelim\" diye yalvardılar."},{"n":"13","t":"İsa'nın izin vermesi üzerine kötü ruhlar adamdan çıkıp domuzların içine girdiler. Yaklaşık iki bin domuzdan oluşan sürü, dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu."},{"n":"14","t":"Domuzları güdenler kaçıp kentte ve köylerde olayın haberini yaydılar. Halk olup biteni görmeye çıktı."},{"n":"15","t":"İsa'nın yanına geldiklerinde, önceleri bir tümen cine tutsak olan adamı giyinmiş, aklı başına gelmiş, oturmuş görünce korktular."},{"n":"16","t":"Olayı görenler, cinli adama olanları ve domuzların başına gelenleri halka anlattılar."},{"n":"17","t":"Bunun üzerine halk, bölgelerinden ayrılması için İsa'ya yalvarmaya başladı."},{"n":"18","t":"İsa kayığa binerken, önceleri cine tutsak olan adam O'na, \"Seninle geleyim\" diye yalvardı."},{"n":"19","t":"Ama İsa adama izin vermedi. Ona, \"Evine, yakınlarının yanına dön\" dedi. \"Rab'bin senin için neler yaptığını, sana nasıl merhamet ettiğini onlara anlat.\""},{"n":"20","t":"Adam da gitti, İsa'nın kendisi için neler yaptığını Dekapolis'te duyurmaya başladı. Anlattıklarına herkes şaşıp kalıyordu."},{"n":"21","h":"Dirilen kız, iyileşen kadın","t":"İsa kayıkla karşı yakaya dönünce, çevresinde büyük bir kalabalık toplandı. Kendisi gölün kıyısında duruyordu."},{"n":"22-23","t":"Bu sırada havra yöneticilerinden Yair adında biri geldi. İsa'yı görünce ayaklarına kapandı, \"Küçük kızım can çekişiyor. Gelip ellerini onun üzerine koy da kurtulsun, yaşasın!\" diye yalvardı."},{"n":"24","t":"İsa adamla birlikte gitti. İsa'nın ardından giden büyük bir kalabalık da O'nu dört bir yandan sıkıştırıyordu."},{"n":"25","t":"Orada, on iki yıldır kanaması olan bir kadın vardı."},{"n":"26","t":"Bir sürü hekimin elinden çok çekmiş, tüm varını yoğunu harcamış, ama iyileşeceğine daha da kötüleşmişti."},{"n":"27","t":"Kadın, İsa hakkında anlatılanları duymuştu. Bu nedenle, kalabalıkta O'nun arkasından gelip giysisine dokundu."},{"n":"28","t":"İçinden, \"Giysilerine bile dokunsam kurtulacağım\" diyordu."},{"n":"29","t":"Hemen o anda kanaması kesiliverdi. Kadın, bedeninin derinliğinde ıstıraptan kurtulduğunu hissetti."},{"n":"30","t":"İsa ise, kendisinden bir gücün akıp gittiğini hemen anladı. Kalabalığın ortasında dönüp, \"Giysilerime kim dokundu?\" diye sordu."},{"n":"31","t":"Öğrencileri O'na, \"Seni sıkıştıran kalabalığı görüyorsun! Nasıl oluyor da, 'Bana kim dokundu' diye soruyorsun?\" dediler."},{"n":"32","t":"İsa bunu yapmış olanı görmek için çevresine bakındı."},{"n":"33","t":"Kadın da kendisindeki değişikliği biliyordu. Korkuyla titreyerek geldi, İsa'nın ayaklarına kapandı ve O'na tüm gerçeği anlattı."},{"n":"34","t":"İsa ona, \"Kızım\" dedi, \"imanın seni kurtardı. Esenlikle git. Istırabın son bulsun.\""},{"n":"35","t":"İsa daha konuşurken, havra yöneticisinin evinden adamlar geldi. Yöneticiye, \"Kızın öldü\" dediler. \"Öğretmeni neden hâlâ rahatsız ediyorsun?\""},{"n":"36","t":"İsa bu sözlere aldırmadan havra yöneticisine, \"Korkma, sadece iman et!\" dedi."},{"n":"37","t":"İsa, Petrus, Yakup ve Yakup'un kardeşi Yuhanna'dan başka hiç kimsenin kendisiyle birlikte gitmesine izin vermedi."},{"n":"38","t":"Havra yöneticisinin evine vardıklarında İsa, acı acı ağlayıp feryat edengürültülü bir kalabalıkla karşılaştı."},{"n":"39","t":"İçeri girerek onlara, \"Niye gürültü edip ağlıyorsunuz?\" dedi. \"Çocuk ölmedi, sadece uyuyor.\""},{"n":"40","t":"Onlar ise kendisiyle alay ettiler. Ama İsa hepsini dışarı çıkardıktan sonra çocuğun annesini babasını ve kendisiyle birlikte olanları alıp çocuğun bulunduğu odaya girdi."},{"n":"41","t":"Çocuğun elinden tutarak ona, \"Talita kumi!\" dedi. Bu söz, 'Kızım, sana söylüyorum, kalk' demektir."},{"n":"42","t":"On iki yaşında olan kız hemen ayağa kalktı, yürümeye başladı.\nOradakileri derin bir şaşkınlık aldı."},{"n":"43","t":"İsa, \"Bunu kimse bilmesin\" diyerek onları sıkı sıkıya uyardı ve kıza yiyecek bir şey verilmesini buyurdu."}]},{"ch":6,"verses":[{"n":"1","h":"İsa reddediliyor","t":"İsa oradan ayrılarak kendi memleketine gitti. Öğrencileri de ardından gittiler."},{"n":"2","t":"Sept günü olunca İsa havrada ders vermeye başladı. Söylediklerini işiten birçok kişi şaşıp kaldı. \"Bu adam bunları nereden öğrendi?\" diye soruyorlardı. \"Kendisine verilen bu bilgelik nedir? Nasıl böyle mucizeler yapabiliyor?"},{"n":"3","t":"Meryem'in oğlu, Yakup, Yose, Yahuda ve Simun'un kardeşi olan marangoz değil mi bu? Kızkardeşleri burada, aramızda yaşamıyor mu?\" Ve gücenip O'nu reddettiler."},{"n":"4","t":"İsa da onlara, \"Bir peygamber, kendi memleketinden, akraba çevresinden ve kendi evinden başka yerde hor görülmez\" dedi."},{"n":"5","t":"Orada birkaç hastayı, üzerlerine ellerini koyarak iyileştirmekten başka hiçbir mucize yapamadı."},{"n":"6","t":"Halkın imansızlığına şaşıyordu.\nİsa, çevredeki köyleri dolaşıp ders veriyordu."},{"n":"7","h":"İsa on iki elçisini görevlendiriyor","t":"On iki öğrencisini yanına çağırdı ve onları ikişer ikişer halk arasına göndermeye başladı. Onlara, kötü ruhları kovma yetkisini verdi."},{"n":"8","t":"Yolculuk için yanlarına değnekten başka bir şey almamalarını söyledi. Ne ekmek, ne torba, ne de kuşaklarında para götüreceklerdi."},{"n":"9","t":"Onlara çarık giymelerini söyledi. Ama, \"İki mintan giymeyin\" dedi."},{"n":"10","t":"\"Bir yere gittiğiniz zaman, oradan ayrılıncaya dek hep aynı evde kalın\" diye devam etti."},{"n":"11","t":"\"İnsanların sizi kabul etmedikleri, sizi dinlemedikleri bir yerden ayrılırken, onlara uyarı olsun diye ayağınızın altındaki tozu silkin!\""},{"n":"12","t":"Böylece öğrenciler yola çıkıp insanları tövbeye çağırmaya başladılar."},{"n":"13","t":"Birçok cin kovdular; birçok hastayı, üzerlerine yağ sürerek iyileştirdiler."},{"n":"14","h":"Yahya peygamberin öldürülmesi","t":"Kral Hirodes de olup bitenleri duydu. Çünkü İsa'nın ünü her tarafa yayılmıştı. Bazıları, \"Bu adam, ölümden dirilmiş olanVaftizci Yahya'dır. Olağanüstü güçlerin O'nda etkin olmasının nedeni de budur\" diyordu."},{"n":"15","t":"Başkaları, \"O İlyas'tır\" diyor, yine başkaları, \"Eski peygamberlerden biri gibi bir peygamberdir\" diyordu."},{"n":"16","t":"Hirodes bunları duyunca, \"Başını kestirdiğim Yahya dirilmiştir!\" dedi."},{"n":"17-18","t":"Hirodes'in kendisi, kardeşi Filipus'un karısı Hirodiya'nın yüzünden adam gönderip Yahya'yı tutuklatmış, zindana attırıp zincire vurdurmuştu. Çünkü Hirodes bu kadınla evlenince Yahya ona, \"Kardeşinin karısıyla evlenmen Kutsal Yasa'ya aykırıdır\" demişti."},{"n":"19","t":"Hirodiya bu yüzden Yahya'ya kin bağlamıştı; onu öldürtmek istiyor, ama başaramıyordu."},{"n":"20","t":"Çünkü Yahya'nın doğru ve kutsal bir adam olduğunu bilen Hirodes ondan korkuyor ve onu koruyordu. Yahya'yı dinlediği zaman büyük bir şaşkınlık içinde kalıyor, yine de onu dinlemekten zevk alıyordu."},{"n":"21","t":"Ne var ki, Hirodes'in kendi doğum gününde saray büyükleri, komutanlar ve Celile'nin ileri gelenleri için verdiği şölende beklenen fırsat doğdu."},{"n":"22","t":"Hirodiya'nın kızı içeri girip dans etti. Bu, Hirodes'le konuklarının hoşuna gitti.\nKral genç kıza, \"Dile benden, ne dilersen veririm\" dedi."},{"n":"23","t":"Ant içerek, \"Benden ne dilersen, krallığımın yarısı da olsa, veririm\" dedi."},{"n":"24","t":"Kız dışarı çıkıp annesine, \"Ne isteyeyim?\" diye sordu.\n\"Vaftizci Yahya'nın başını iste\" dedi annesi."},{"n":"25","t":"Kız derhal koşup kralın yanına girdi, \"Vaftizci Yahya'nın başını bir tepsi üzerinde hemen bana vermeni istiyorum\" diyerek dileğini açıkladı."},{"n":"26","t":"Kral buna çok üzüldüyse de, konuklarının önünde içtiği anttan ötürü kızı reddetmek istemedi."},{"n":"27","t":"Derhal bir cellat gönderip Yahya'nın başını getirmesini buyurdu. Cellat zindana giderek Yahya'nın başını kesti."},{"n":"28","t":"Kesik başı bir tepsi üzerinde getirip genç kıza verdi, kız da annesine götürdü."},{"n":"29","t":"Yahya'nın öğrencileri bunu duyunca gelip cesedi aldılar ve mezara koydular."},{"n":"30","h":"İsa beş bin kişiyi doyuruyor","t":"Elçiler, İsa'nın yanına dönerek yaptıkları ve öğrettikleri her şeyi O'na anlattılar."},{"n":"31","t":"İsa onlara, \"Gelin, tek başımıza tenha bir yere gidelim de biraz dinlenin\" dedi. Gelen giden öyle çoktu ki, yemek yemeye bile vakit bulamıyorlardı."},{"n":"32","t":"Kayığa binip tek başlarına tenha bir yere doğru yol aldılar."},{"n":"33","t":"Gittiklerini gören birçok kişi onları tanıdı. Halk civardaki bütün kentlerden yaya olarak yola dökülüp onlardan önce oraya vardı."},{"n":"34","t":"İsa kayıktan inince büyük bir kalabalıkla karşılaştı. Çobansız koyunlara benzeyen bu insanlara acıdı ve onlara birçok konuda ders vermeye başladı."},{"n":"35-36","t":"Vakit iyice ilerleyince, öğrencileri O'nun yanına gelip dediler ki, \"Burası ıssız bir yer, vakit de çok geç. Halkı salıver de çevredeki çiftlik ve köylere gidip kendilerine yiyecek alsınlar.\""},{"n":"37","t":"İsa ise, \"Onlara siz yiyecek verin\" diye karşılık verdi.\nÖğrenciler İsa'ya, \"Gidip iki yüz dinarlık ekmek alıp onlara yedirelim mi yani?\" diye sordular."},{"n":"38","t":"İsa onlara, \"Kaç ekmeğiniz var, gidin bakın\" dedi.\nÖğrenip geldiler, \"Beş ekmekle iki balığımız var\" dediler."},{"n":"39","t":"İsa onlara, herkesi küme küme yeşil çimenlerin üzerine oturtmalarını buyurdu."},{"n":"40","t":"Halk yüzer ellişer kişilik bölükler halinde oturdu."},{"n":"41","t":"İsa, beş ekmekle iki balığı aldı, gözlerini göğe dikerek şükran duasını yaptı; sonra ekmekleri böldü ve halka dağıtmaları için öğrencilerine verdi. İki balığı da hepsinin arasında paylaştırdı."},{"n":"42-43","t":"Herkes yiyip doyduktan sonra on iki sepet dolusu ekmek ve balık artığı topladılar."},{"n":"44","t":"Yemek yiyen erkeklerin sayısı beş bin kadardı."},{"n":"45","h":"İsa su üstünde yürüyor","t":"Bundan hemen sonra İsa, öğrencilerine, kayığa binip kendisinden önce karşı yakada bulunan Beytsayda'ya geçmelerini buyurdu. Bu arada kendisi halkı evlerine gönderecekti."},{"n":"46","t":"Onları uğurladıktan sonra, dua etmek için dağa çıktı."},{"n":"47-48","t":"Akşam olduğunda, kayık gölün ortasına varmıştı. Yalnız başına karada kalmış olan İsa, öğrencilerinin kürek çekmekte çok zorlandıklarını gördü. Çünkü rüzgâr onlara karşı esiyordu. Sabaha karşı İsa, gölün üstünde yürüyerek onlara yaklaştı. Yanlarından geçip gidecekti."},{"n":"49","t":"Onlar ise, gölün üstünde yürüdüğünü görünce O'nu hayalet sanarak bağrıştılar."},{"n":"50","t":"Hepsi O'nu görmüş ve dehşete kapılmıştı. Ama kendisi hemen onlara seslenerek, \"Cesur olun! Ben'im, korkmayın!\" dedi."},{"n":"51","t":"İsa kayığa binip onlara katılınca rüzgâr dindi. Onlar ise tam bir şaşkınlık içindeydiler."},{"n":"52","t":"Ekmekle ilgili mucizeyi bile anlamamışlardı; zihinleri körleşmişti."},{"n":"53","h":"İsa, Ginesar'da hastaları iyileştiriyor","t":"İsa'yla öğrencileri karşı yakaya vardıklarında Ginesar'da karaya çıkıp kayığı bağladılar."},{"n":"54","t":"Onlar kayıktan inince, halk İsa'yı hemen tanıdı."},{"n":"55","t":"Bazıları koşa koşa tüm yöreyi dolaştı. İsa'nın bulunduğu yeri öğrenenler, hastaları döşekler üzerinde oraya götürmeye başladılar."},{"n":"56","t":"Köy olsun, kent ya da çiftlik olsun, İsa'nın gittiği her yerde, hastaları meydanlara yatırıyor, sadece giysisinin eteğine dokunmalarına izin vermesi için yalvarıyorlardı. Dokunanların hepsi de iyileşti."}]},{"ch":7,"verses":[{"n":"1","h":"İnsanı kirleten nedir?","t":"Kudüs'ten gelen Ferisiler ve bazı din bilginleri, İsa'nın çevresinde toplandılar."},{"n":"2","t":"O'nun öğrencilerinden bazılarının murdar, yani yıkanmamış ellerle yemek yediklerini gördüler."},{"n":"3","t":"Ferisiler, hatta bütün Yahudiler, atalarının geleneği uyarınca ellerini iyice yıkamadan yemek yemezler."},{"n":"4","t":"Keza, çarşıdan dönünce, yıkanmadan yemek yemezler. Ayrıca kâse, testi ve bakır kapların yıkanmasıyla ilgili başka birçok geleneğe de uyarlar."},{"n":"5","t":"Ferisiler ve din bilginleri İsa'ya, \"Senin öğrencilerin neden atalarımızın geleneğine uymuyorlar, niçin murdar ellerle yemek yiyorlar?\" diye sordular."},{"n":"6","t":"İsa onlara şöyle cevap verdi: \"Yeşaya'nın siz ikiyüzlülerle ilgili peygamberlik sözü ne doğrudur! Yazmış olduğu gibi,\n'Bu halk, dudaklarıyla beni sayar,\nama yürekleri benden uzaktır."},{"n":"7","t":"Bana boşuna taparlar.\nÇünkü öğrettikleri, sadece insan kurallarıdır.'"},{"n":"8","t":"Siz Tanrı buyruğunu bir yana bırakmış, insan geleneğine uyuyorsunuz.\""},{"n":"9","t":"İsa onlara ayrıca şunu söyledi: \"Kendi geleneğinizi sürdürmek için Tanrı buyruğunu bir kenara itmeyi ne de güzel beceriyorsunuz!"},{"n":"10","t":"Musa, 'Annene babana saygı göster' ve, 'Annesine ya da babasına söven mutlaka ölümle cezalandırılsın' diye buyurmuştu."},{"n":"11-12","t":"Ama siz, 'Eğer bir adam annesine ya da babasına, benden alacağın tüm maddi yardım kurbandır, yani Tanrı'ya adanmıştır derse, artık annesi ya da babası için bir şey yapmasına izin yok' diyorsunuz."},{"n":"13","t":"Böylece kuşaktan kuşağa aktardığınız geleneklerle Tanrı'nın sözünü geçersiz kılıyorsunuz. Buna benzer daha birçok şey yapıyorsunuz.\""},{"n":"14","t":"İsa, halkı yine yanına çağırıp onlara, \"Hepiniz beni dinleyin ve şunu belleyin\" dedi."},{"n":"15-16","t":"\"İnsanın dışında olup içine giren hiçbir şey onu kirletemez. İnsanı kirleten, insanın içinden çıkandır.\""},{"n":"17","t":"İsa kalabalığı bırakıp eve girince, öğrencileri O'na bu benzetmenin anlamını sordular."},{"n":"18","t":"O da onlara, \"Demek siz de anlamıyorsunuz, öyle mi?\" dedi. \"Dışarıdan insanın içine giren hiçbir şeyin onu kirletemeyeceğini bilmiyor musunuz?"},{"n":"19","t":"Dıştan giren, insanın yüreğine değil, midesine gider, oradan da ayakyoluna atılır.\" İsa bu sözlerle, tüm yiyeceklerin temiz olduğunu bildirmiş oluyordu."},{"n":"20","t":"İsa şöyle devam etti: \"İnsanı kirleten, insanın içinden çıkandır."},{"n":"21-22","t":"Çünkü kötü düşünceler, cinsel ahlaksızlık, hırsızlık, cinayet, zina, açgözlülük, kötülük, hile, sefahat, kıskançlık, iftira, kibir ve akılsızlık içten, insanın yüreğinden kaynaklanır."},{"n":"23","t":"Bu kötülüklerin hepsi içten kaynaklanır ve insanı kirletir.\""},{"n":"24","h":"Fenikeli kadının imanı","t":"İsa oradan ayrılarak Sur ve Sayda bölgesine gitti. Burada bir eve girdi. Kimsenin bunu bilmesini istemiyordu, ama gizlenemedi."},{"n":"25","t":"Küçük kızı kötü ruha tutsak olan bir kadın, İsa'yla ilgili haberi duyar duymaz geldi, ayaklarına kapandı."},{"n":"26","t":"Yahudi olmayan bu kadın Suriye-Fenike ırkındandı. Kızından cini kovması için İsa'ya rica etti."},{"n":"27","t":"İsa ona, \"Bırak, önce çocuklar doysunlar\" dedi. \"Çocukların ekmeğini alıp köpeklere atmak doğru değildir.\""},{"n":"28","t":"Kadın buna karşılık, \"Haklısın, Rab\" dedi. \"Ama köpekler de sofranın altında çocukların ekmek kırıntılarını yer.\""},{"n":"29","t":"İsa ona, \"Söylediğin bu sözün hatırı için git, cin kızından çıkmış bulunuyor\" dedi."},{"n":"30","t":"Kadın evine gittiğinde çocuğunu cinden kurtulmuş, yatakta yatarbuldu."},{"n":"31","h":"Sağır bir adam iyileştiriliyor","t":"Sur bölgesinden ayrılan İsa, Sayda yoluyla Dekapolis bölgesinin ortasından geçerek tekrar Celile gölüne geldi."},{"n":"32","t":"Ona sağır ve dili tutuk bir adam getirdiler, elini üzerine koyması için yalvardılar."},{"n":"33","t":"İsa adamı kalabalıktan ayırıp bir yana çekti. Parmaklarını adamın kulaklarına soktu, tükürüp onun diline dokundu."},{"n":"34","t":"Sonra göğe bakarak içini çekti ve adama, \"Effata\", yani \"Açıl!\" dedi."},{"n":"35","t":"Adamın kulakları hemen açıldı, dili çözüldü ve düzgün bir şekilde konuşmaya başladı."},{"n":"36","t":"İsa orada bulunanları, bunu kimseye söylememeleri için uyardı. Ama onları ne kadar uyardıysa, onlar haberi o kadar çok yaydılar."},{"n":"37","t":"Halk büyük bir hayret içinde kalmıştı. \"Yaptığı her şey mükemmel. Sağırların kulaklarını açıyor, dilsizleri konuşturuyor!\" diyorlardı."}]},{"ch":8,"verses":[{"n":"1-2","h":"İsa dört bin kişiyi doyuruyor","t":"O günlerde yine büyük bir kalabalık toplanmıştı. Yiyecek bir şeyleri olmadığı için İsa öğrencilerini yanına çağırıp, \"Halka acıyorum\" dedi. \"Üç gündür yanımdalar ve yiyecek hiçbir şeyleri yok."},{"n":"3","t":"Onları aç aç evlerine gönderirsem, yolda bayılırlar. Hem bazıları uzak yoldan geliyor.\""},{"n":"4","t":"Öğrencileri buna karşılık, \"Böyle ıssız bir yerde bu kadar kişiyi doyuracak ekmeği insan nereden bulabilir?\" dediler."},{"n":"5","t":"İsa, \"Kaç ekmeğiniz var?\" diye sordu.\n\"Yedi tane\" dediler."},{"n":"6","t":"Bunun üzerine İsa, halka yere oturmalarını buyurdu. Sonra yedi ekmeği aldı, şükredip bunları böldü, dağıtmaları için öğrencilerine verdi. Onlar da halka dağıttılar."},{"n":"7","t":"Birkaç küçük balıkları da vardı. İsa şükran duasını yapıp bunları da dağıtmalarını söyledi."},{"n":"8","t":"Herkes yiyip doyduktan sonra yedi küfe dolusu yemek artığı topladılar."},{"n":"9-10","t":"Orada yaklaşık dört bin kişi vardı. İsa onları salıverdikten sonra öğrencileriyle birlikte hemen kayığa binip Dalmanuta taraflarına geçti."},{"n":"11","h":"Ferisilerin ve Hirodes'in mayası","t":"Ferisiler gelip İsa'yla tartışmaya başladılar. O'nu sınamak amacıyla gökten bir belirti göstermesini istediler."},{"n":"12","t":"İsa içten bir ah çekerek, \"Bu kuşak neden bir belirti istiyor?\" dedi. \"Size doğrusunu söyleyeyim, bu kuşağa hiçbir belirti gösterilmeyecek.\""},{"n":"13","t":"Sonra onları orada bırakıp yine kayığa bindi ve karşı yakaya yöneldi."},{"n":"14","t":"Öğrenciler ekmek almayı unutmuşlardı. Kayıkta, yanlarında bir tek ekmek vardı."},{"n":"15","t":"İsa onlara şu uyarıda bulundu: \"Dikkatli olun, Ferisilerin mayasından ve Hirodes'in mayasından sakının!\""},{"n":"16","t":"Onlar ise kendi aralarında, \"Ekmeğimiz olmadığı için böyle diyor\" şeklinde konuştular."},{"n":"17","t":"Bunun farkında olan İsa, \"Ekmeğiniz yok diye ne konuşup duruyorsunuz?\" dedi. \"Hâlâ akıl erdiremiyor, anlamıyor musunuz? Zihniniz körleşti mi?"},{"n":"18-19","t":"Gözleriniz olduğu halde görmüyor musunuz? Kulaklarınız olduğu halde işitmiyor musunuz? Hatırlamıyor musunuz, beş ekmeği beş bin kişiye bölüştürdüğümde kaç sepet dolusu yemek artığı topladınız?\"\n\"On iki\" dediler."},{"n":"20","t":"\"Yedi ekmeği dört bin kişiye bölüştürdüğümde kaç küfe dolusu yemek artığı topladınız?\"\n\"Yedi\" dediler."},{"n":"21","t":"İsa onlara, \"Hâlâ anlamıyor musunuz?\" dedi."},{"n":"22","h":"Beytsayda'da kör bir adam iyileştiriliyor","t":"İsa ile öğrencileri Beytsayda'ya geldiler. Orada bazı kişiler İsa'ya kör bir adam getirip ona dokunması için yalvardılar."},{"n":"23","t":"İsa körün elinden tutarak onu köyün dışına çıkardı. Gözlerine tükürüp ellerini üzerine koydu ve, \"Bir şey görüyor musun?\" diye sordu."},{"n":"24","t":"Adam başını kaldırıp, \"İnsanlar görüyorum\" dedi, \"ağaçlara benziyorlar, ama yürüyorlar.\""},{"n":"25","t":"Sonra İsa ellerini yeniden adamın gözleri üzerine koydu. Adam gözlerini açtı, baktı; iyileşmiş ve her şeyi açık seçik görmeye başlamıştı."},{"n":"26","t":"İsa, \"Köye bile girme!\" diyerek onu evine gönderdi."},{"n":"27","h":"Petrus'un Mesih'i tanıması","t":"İsa, öğrencileriyle birlikte Filipus Sezariyesi'ne bağlı köylere gitti. Yolda öğrencilerine, \"Halk, benim kim olduğumu söylüyor?\" diye sordu."},{"n":"28","t":"Öğrencileri O'na şu karşılığı verdiler: \"Vaftizci Yahya diyorlar. Ama kimi İlyas, kimi de peygamberlerden biri olduğunu söylüyor.\""},{"n":"29","t":"O da onlara, \"Ya siz, ben kimim dersiniz?\" diye sordu.\nPetrus, \"Sen Mesih'sin\" cevabını verdi."},{"n":"30","t":"Bunun üzerine İsa bu konuda kimseye bir şey söylememeleri için onları uyardı."},{"n":"31","h":"İsa ölüp dirileceğini önceden bildiriyor","t":"İsa, İnsanoğlu'nun çok acı çekmesi, ihtiyarlar, başkâhinler ve din bilginlerince reddedilmesi, öldürülmesi ve üç gün sonra dirilmesi gerektiğini onlara anlatmaya başladı."},{"n":"32","t":"Bunları açıkça söylüyordu. Bunun üzerine Petrus O'nu bir kenara çekip azarlamaya başladı."},{"n":"33","t":"Ama İsa dönüp diğer öğrencilerine baktı. Petrus'u azarlayarak, \"Çekil önümden, Şeytan!\" dedi. \"Senin düşüncelerin Tanrı'nın değil, insanın düşünceleridir.\""},{"n":"34","t":"Öğrencileriyle birlikte halkı da yanına çağırıp şöyle konuştu: \"Ardımdan gelmek isteyen, kendini inkâr etsin, çarmıhını yüklenip beni izlesin."},{"n":"35","t":"Canını kurtarmak isteyen onu yitirecek; canını benimve Müjde'nin uğruna yitiren ise onu kurtaracaktır."},{"n":"36","t":"İnsan bütün dünyayı kazanıp da canından olursa, bunun kendisine ne yararı olur?"},{"n":"37","t":"İnsan, kendi canına karşılık ne verebilir?"},{"n":"38","t":"Bu vefasız ve günahkâr kuşağın ortasında, kim benden ve benim sözlerimden utanırsa, İnsanoğlu da, Babasının görkemi içinde kutsal meleklerle birlikte geldiğinde o kişiden utanacaktır.\""}]},{"ch":9,"verses":[{"n":"1","t":"İsa, \"Size doğrusunu söyleyeyim\" diye devam etti, \"burada bulunanlar arasında, Tanrı Egemenliğinin güçlü biçimde gerçekleştiğini görmeden ölümü tatmayacak olanlar var.\""},{"n":"2","h":"İsa'nın görünümü değişiyor","t":"Altı gün sonra İsa, yanına yalnız Petrus, Yakup ve Yuhanna'yı alarak yüksek bir dağa çıktı. Orada, gözlerinin önünde İsa'nın görünümü değişti."},{"n":"3","t":"Giysileri göz kamaştırıcı bir beyazlığa büründü; yeryüzünde hiçbir çamaşırcının erişemeyeceği bir beyazlıktı bu."},{"n":"4","t":"O anda Musa'yla İlyas öğrencilere göründü. İsa'yla konuşuyorlardı."},{"n":"5","t":"Petrus İsa'ya, \"Rabbî, burada bulunmamız ne iyi oldu! Üç çardak kuralım: biri sana, biri Musa'ya, biri de İlyas'a\" dedi."},{"n":"6","t":"Ne söyleyeceğini bilmiyordu. Çünkü çok korkmuşlardı."},{"n":"7","t":"Bu sırada bir bulut gelip onları gölgeledi. Buluttan gelen bir ses, \"Sevgili Oğlum budur, O'nu dinleyin!\" dedi."},{"n":"8","t":"Öğrenciler birden çevrelerine baktılar, ama bu kez yanlarında İsa'dan başka kimseyi göremediler."},{"n":"9","t":"Dağdan inerlerken İsa onları, İnsanoğlu ölümden dirilmeden orada gördüklerini hiç kimseye söylememeleri için uyardı."},{"n":"10","t":"Bu uyarıya uymakla birlikte kendi aralarında, \"Ölümden dirilmek ne demek?\" diye tartışıp durdular."},{"n":"11","t":"İsa'ya, \"Din bilginleri neden önce İlyas'ın gelmesi gerektiğini söylüyorlar?\" diye sordular."},{"n":"12","t":"O da onlara şöyle dedi: \"Gerçekten de önce İlyas gelir ve her şeyi yeniden düzene koyar. Ama nasıl oluyor da İnsanoğlu'nun çok acı çekeceği ve hiçe sayılacağı yazılmıştır?"},{"n":"13","t":"Size şunu söyleyeyim, İlyas geldi bile, ve onun hakkında yazılmış olduğu gibi, ona yapmadıklarını bırakmadılar.\""},{"n":"14","h":"Cine tutsak bir çocuğun iyileştirilmesi","t":"Öteki öğrencilerin yanına döndüklerinde, onların çevresinde büyük bir kalabalığın toplandığını, birtakım din bilginlerinin onlarla tartıştığını gördüler."},{"n":"15","t":"Kalabalık İsa'yı görünce büyük bir şaşkınlığa kapıldı ve koşup O'nu selamladı."},{"n":"16","t":"İsa öğrencilerine, \"Onlarla ne tartışıyorsunuz?\" diye sordu."},{"n":"17","t":"Halktan biri O'na, \"Öğretmenim\" diye karşılık verdi, \"dilsiz bir ruha tutsak olan oğlumu sana getirdim."},{"n":"18","t":"Ruh onu nerede yakalarsa yere çarpıyor. Çocuk ağzından köpükler saçıyor, dişlerini gıcırdatıyor ve kaskatı kesiliyor. Ruhu kovmaları için öğrencilerine başvurdum, ama başaramadılar.\""},{"n":"19","t":"İsa onlara, \"Ey imansız kuşak!\" dedi. \"Sizinle daha ne kadar kalacağım? Size daha ne kadar katlanacağım? Getirin çocuğu bana!\""},{"n":"20","t":"Çocuğu kendisine getirdiler. Ruh, İsa'yı görür görmez çocuğu şiddetle sarstı; çocuk yere düştü, ağzından köpükler saçarak yuvarlanmaya başladı."},{"n":"21","t":"İsa çocuğun babasına, \"Bu hal çocuğun başına geleli ne kadar oldu?\" diye sordu.\n\"Küçüklüğünden beri böyle\" dedi babası."},{"n":"22","t":"\"Üstelik ruh onu öldürmek için birçok kez ateşe ya da suya attı. Elinden bir şey gelirse, bize yardım et, halimize acı!\""},{"n":"23","t":"İsa ona, \"Elimden gelirse mi? İman eden biri için her şey mümkün!\" dedi."},{"n":"24","t":"Çocuğun babası hemen, \"İman ediyorum, imansızlığımı yenmeme yardım et!\" diye feryat etti."},{"n":"25","t":"İsa, halkın koşuşup geldiğini görünce kötü ruhu azarlayarak, \"Sana buyuruyorum, dilsiz ve sağır ruh, çocuğun içinden çık ve ona bir daha girme!\" dedi."},{"n":"26","t":"Bunun üzerine ruh bir çığlık attı ve çocuğu şiddetle sarsarak çıktı. Çocuk ölü gibi hareketsiz kaldı, öyle ki oradakilerin birçoğu, \"Öldü!\" diyordu."},{"n":"27","t":"Ama İsa elinden tutup kaldırınca, çocuk ayağa kalktı."},{"n":"28","t":"İsa eve girdikten sonra öğrencileri özel olarak O'na, \"Biz kötü ruhu neden kovamadık?\" diye sordular."},{"n":"29","t":"İsa onlara, \"Bu tür ruhlar ancak duayla kovulabilir\" cevabını verdi."},{"n":"30","h":"İsa ölüp dirileceğini tekrar bildiriyor","t":"Oradan ayrılmış, Celile bölgesinden geçiyorlardı. İsa hiç kimsenin bunu bilmesini istemiyordu."},{"n":"31","t":"Öğrencilerine ders verirken şöyle diyordu: \"İnsanoğlu, insanların eline teslim edilecek ve öldürülecek, ama öldürüldükten üç gün sonra dirilecek.\""},{"n":"32","t":"Onlar bu sözleri anlamıyor, İsa'ya soru sormaktan da korkuyorlardı."},{"n":"33","h":"En büyük kim?","t":"Kefernahum'a vardılar. Eve girdikten sonra İsa onlara, \"Yolda aranızda neyi tartışıyordunuz?\" diye sordu."},{"n":"34","t":"Hiç birinden ses çıkmadı. Çünkü yolda aralarında kimin en büyük olduğunu tartışmışlardı."},{"n":"35","t":"İsa oturup Onikileri yanına çağırdı. Onlara şöyle dedi: \"Birinci olmak isteyen en sonuncu olsun, herkesin hizmetkârı olsun.\""},{"n":"36-37","t":"Küçük bir çocuğu alıp orta yere dikti, sonra onu kucağına alarak onlara şöyle dedi: \"Böyle bir çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur. Beni kabul eden de beni değil, beni göndereni kabul etmiş olur.\""},{"n":"38","h":"Bize karşı olmayan bizden yanadır","t":"Yuhanna O'na, \"Öğretmenim\" dedi, \"senin adınla cin kovan birinigördük, ama bizi izleyenlerden olmadığı için ona engel olmaya çalıştık.\""},{"n":"39","t":"\"Ona engel olmayın!\" dedi İsa. \"Çünkü benim adımla mucize yapıp da hemen ardından beni kötüleyecek kimse yoktur."},{"n":"40","t":"Bize karşı olmayan, bizden yanadır."},{"n":"41","t":"Size doğrusunu söyleyeyim, Mesih'e ait olduğunuz için sizlere bir bardak su içiren ödülsüz kalmayacaktır."},{"n":"42","h":"Birini günaha sokmanın cezası","t":"\"Kim bana iman eden bu küçüklerden birini günaha düşürürse, boynuna kocaman bir değirmen taşı geçirilip denize atılması kendisi için daha iyi olur."},{"n":"43-44","t":"Eğer elin seni günaha sokarsa, onu kes. Çolak olarak yaşama kavuşman, iki el sahibi olarak sönmez ateşe, cehenneme gitmenden iyidir."},{"n":"45-46","t":"Eğer ayağın seni günaha sokarsa, onu kes. Tek ayaklı olarak yaşama kavuşman, iki ayak sahibi olarak cehenneme atılmandan iyidir."},{"n":"47","t":"Eğer gözün seni günaha sokarsa, onu çıkarıp at. Tanrı'nın Egemenliğine tek gözle girmen, iki göz sahibi olarak cehenneme atılmandan iyidir."},{"n":"48","t":"'Oradakileri kemiren kurt ölmez,\nyakan ateş de sönmez.'"},{"n":"49","t":"Çünkü herkes ateşle tuzlanacaktır."},{"n":"50","t":"Tuz yararlıdır. Ama tuz tuzluluğunu yitirirse, ona tekrar nasıl tat verebilirsiniz? İçinizde tuz olsun ve birbirinizle barış içinde yaşayın!\""}]},{"ch":10,"verses":[{"n":"1","h":"Boşanmayla ilgili soru","t":"İsa oradan ayrılıp Yahudiye sınırlarına, Şeria nehrinin ötesine geçti. Çevresinde yine kalabalıklar toplanmıştı; her zamanki gibi onlara ders veriyordu."},{"n":"2","t":"Yanına gelen bazı Ferisiler O'nu sınamak amacıyla, \"Bir erkeğin, karısını boşaması Kutsal Yasa'ya uygun mudur?\" diye sordular."},{"n":"3","t":"İsa karşılık olarak, \"Musa size ne buyurdu?\" dedi."},{"n":"4","t":"Onlar, \"Musa, erkeğin bir boş kâğıdı yazarak karısını boşamasına izin vermiştir\" dediler."},{"n":"5","t":"İsa onlara, \"Musa bu buyruğu size yüreklerinizin katılığından ötürü yazdı\" dedi."},{"n":"6","t":"\"Tanrı, yaratılışın ta başlangıcından insanları 'erkek ve dişi olarak yarattı.'"},{"n":"7-8","t":"'Bu nedenle adam annesini babasını bırakacak, karısına bağlanacak ve ikisi tek bir beden olacaklar.' Şöyle ki, onlar artık iki değil, tek bedendir."},{"n":"9","t":"O halde Tanrı'nın birleştirdiğini insan ayırmasın.\""},{"n":"10","t":"Öğrencileri evde O'na yine bu konuyla ilgili bazı sorular sordular."},{"n":"11","t":"İsa onlara, \"Karısını boşayıp başkasıyla evlenen, karısına karşı zina etmiş olur\" dedi."},{"n":"12","t":"\"Kocasını boşayıp başkasıyla evlenen kadın da zina etmiş olur.\""},{"n":"13","h":"İsa küçük çocukları kutsuyor","t":"Bu arada bazıları küçük çocukları İsa'nın yanına getiriyor, onlara dokunmasını istiyorlardı. Ne var ki, öğrenciler onları azarladılar."},{"n":"14","t":"İsa bunu görünce kızdı. Öğrencilerine, \"Bırakın, çocuklar bana gelsin\" dedi. \"Onlara engel olmayın! Çünkü Tanrı'nın Egemenliği böylelerinindir."},{"n":"15","t":"Size doğrusunu söyleyeyim, Tanrı'nın Egemenliğini bir çocuk gibi kabul etmeyen, bu egemenliğe asla giremez.\""},{"n":"16","t":"Çocukları kucağına aldı, ellerini üzerlerine koyup onları kutsadı."},{"n":"17","h":"Zenginlik ve sonsuz yaşam","t":"İsa yola çıkarken, biri koşarak yanına geldi. Önünde diz çöküp O'na, \"İyi öğretmenim, sonsuz yaşama kavuşmak için ne yapmalıyım?\" diye sordu."},{"n":"18","t":"İsa ona, \"Bana neden iyi diyorsun?\" dedi. \"İyi olan tek biri var, O da Tanrı'dır."},{"n":"19","t":"O'nun buyruklarını biliyorsun: 'Adam öldürme, zina etme, hırsızlık yapma, yalan yere tanıklık etme, kimsenin hakkını yeme, annene babana saygı göster.'\""},{"n":"20","t":"Adam, \"Öğretmenim, bunların hepsini gençliğimden beri yerine getiriyorum\" dedi."},{"n":"21","t":"Ona sevgiyle bakan İsa, \"Bir tek eksiğin var\" dedi. \"Git neyin varsa sat, parasını yoksullara ver; böylece gökte hazinen olur. Sonra gel, beni izle.\""},{"n":"22","t":"Bu sözler üzerine adamın yüzü asıldı, üzüntü içinde oradan uzaklaştı. Çünkü çok malı vardı."},{"n":"23","t":"İsa çevresine göz gezdirdikten sonra öğrencilerine, \"Varlıklı kişilerin Tanrı Egemenliğine girmesi ne güç olacak!\" dedi."},{"n":"24","t":"Öğrenciler O'nun sözlerine şaştılar. Ama İsa onlara yine, \"Çocuklar\" dedi, \"Tanrı'nın Egemenliğine girmek ne güçtür!"},{"n":"25","t":"Devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliğine girmesinden daha kolaydır.\""},{"n":"26","t":"Öğrenciler büsbütün şaşırmışlardı. Birbirlerine, \"Öyleyse kim kurtulabilir?\" diyorlardı."},{"n":"27","t":"İsa onlara bakarak, \"İnsanlar için bu imkânsız, ama Tanrı için değil. Tanrı için her şey mümkün\" dedi."},{"n":"28","t":"Petrus O'na, \"Bak, biz her şeyi bırakıp senin ardından geldik\" demeye başladı."},{"n":"29-30","t":"\"Size doğrusunu söyleyeyim\" dedi İsa, \"benim ve Müjde'nin uğruna evini, kardeşlerini, anne ya da babasını, çocuklarını ya da topraklarını bırakıp da şimdi, bu çağda çekeceği zulümlerle birlikte yüz kat daha fazla eve, kardeşe, anneye, çocuğa, toprağa ve gelecek çağda sonsuz yaşama kavuşmayacak hiç kimse yoktur."},{"n":"31","t":"Ne var ki, birincilerin birçoğu sonuncu, sonuncuların birçoğu da birinci olacak.\""},{"n":"32-33","h":"İsa ölüp dirileceğini üçüncü kez bildiriyor","t":"Yola çıkmış Kudüs'e gidiyorlardı. İsa önlerinde yürüyordu. Öğrencileri şaşkınlık içindeydi, ardından gelenler ise korkuyorlardı. İsa Onikileri yine bir yana çekip kendi başına gelecekleri anlatmaya başladı: \"Şimdi Kudüs'e gidiyoruz\" dedi. \"İnsanoğlu, başkâhinlerin ve din bilginlerinin eline teslimedilecek. Onlar da O'nu ölüm cezasına çarptıracak ve diğer uluslara teslim edecekler."},{"n":"34","t":"O'nunla alay edecek, üzerine tükürecek ve O'nu kamçılayıp öldürecekler. Ne var ki O, üç gün sonra dirilecek.\""},{"n":"35","h":"Yakup'la Yuhanna'nın dileği","t":"Zebedi'nin oğulları Yakup ile Yuhanna İsa'ya yaklaşıp, \"Öğretmenimiz, bir dileğimiz var, bunu bizim için yapmanı istiyoruz\" dediler."},{"n":"36","t":"İsa onlara, \"Sizin için ne yapmamı istiyorsunuz?\" diye sordu."},{"n":"37","t":"\"Sen yüceliğine kavuşunca birimize sağında, ötekimize de solunda oturma ayrıcalığını ver\" dediler."},{"n":"38","t":"\"Siz ne dilediğinizi bilmiyorsunuz\" dedi İsa. \"Benim içeceğim kâseden siz içebilir misiniz? Benim vaftiz olacağım gibi siz de vaftiz olabilir misiniz?\""},{"n":"39-40","t":"\"Evet, olabiliriz\" dediler.\nİsa onlara, \"Benim içeceğim kâseden siz de içeceksiniz, benim vaftiz olacağım gibi siz de vaftiz olacaksınız\" dedi. \"Ama sağımda ya da solumda oturmanıza izin vermek benim elimde değil. Bu yerler belirli kişiler için hazırlanmıştır.\""},{"n":"41","t":"Bunu işiten diğer on öğrenci Yakup'la Yuhanna'ya kızmaya başladılar."},{"n":"42","t":"İsa onları yanına çağırıp şöyle dedi: \"Bilirsiniz ki, ulusların önderleri sayılanlar, onları egemenlik hırsıyla yönetirler, ileri gelenleri de onlara ağırlıklarını hissettirirler."},{"n":"43","t":"Sizin aranızda böyle olmayacak. Aranızda büyük olmak isteyen, diğerlerinin hizmetkârı olsun."},{"n":"44","t":"Aranızda birinci olmak isteyen, hepinizin kulu olsun."},{"n":"45","t":"Çünkü İnsanoğlu bile hizmet edilmeye değil, hizmet etmeye ve canını birçokları uğruna fidye olarak vermeye geldi.\""},{"n":"46","h":"Kör Bartimay'ın gözleri açılıyor","t":"Sonra Eriha'ya geldiler. İsa, öğrencileri ve büyük bir kalabalıkla birlikte Eriha'dan ayrılırken, Timay oğlu Bartimay adında kör bir dilenci yol kenarında oturuyordu."},{"n":"47","t":"Nasıralı İsa'nın orada olduğunu duyunca, \"Ey Davut Oğlu İsa, halime acı!\" diye bağırmaya başladı."},{"n":"48","t":"Birçok kimse onu azarlayarak susturmak istediyse de o, \"Ey Davut Oğlu, halime acı!\" diyerek daha çok bağırdı."},{"n":"49","t":"İsa durdu, \"Çağırın onu\" dedi.\nKör adama seslenerek, \"Ne mutlu sana! Kalk, seni çağırıyor!\" dediler."},{"n":"50","t":"Adam abasını üstünden atarak ayağa fırladı ve İsa'nın yanına geldi."},{"n":"51","t":"İsa ona, \"Senin için ne yapmamı istiyorsun?\" diye sordu.\nKör adam, \"Rabbuni, gözlerim görsün\" dedi."},{"n":"52","t":"İsa, \"Gidebilirsin, imanın seni kurtardı\" dedi. Adam o anda yeniden görmeye başladı ve yol boyunca İsa'nın ardından gitti."}]},{"ch":11,"verses":[{"n":"1-2","h":"İsa'nın Kudüs'e girişi","t":"Kudüs'e yaklaşıp Zeytin dağının yamacında bulunan Beytfacı ile Beytanya'ya geldiklerinde İsa öğrencilerinden ikisini şu sözlerle köye gönderdi: \"Karşınızdaki köye gidin. Köye girer girmez, üzerine daha hiç kimsenin binmediği, bağlı duran bir sıpa bulacaksınız. Onu çözüp bana getirin."},{"n":"3","t":"Biri size, 'Bunu niye yapıyorsunuz?' derse, 'Rab'bin ona ihtiyacı var, hemen geri gönderecek' dersiniz.\""},{"n":"4","t":"Gittiler ve yol üzerinde, bir evin sokak kapısının yanında bağlı buldukları sıpayı çözdüler."},{"n":"5","t":"Orada duranlardan bazıları, \"Sıpayı ne diye çözüyorsunuz?\" dediler."},{"n":"6","t":"Öğrenciler İsa'nın kendilerine söylediklerini tekrarlayınca, adamlar onları rahat bıraktı."},{"n":"7","t":"Sıpayı İsa'ya getirip üzerine kendi giysilerini yaydılar. İsa da sıpaya bindi."},{"n":"8","t":"Birçokları giysilerini, bazıları da çevredeki ağaçlardan kestikleri dalları yola serdiler."},{"n":"9","t":"Önden gidenler ve arkadan gelenler şöyle bağırıyorlardı:\n\"Hozana!\nRab'bin adıyla gelene övgüler olsun!"},{"n":"10","t":"Atamız Davut'un yaklaşan egemenliği kutlu olsun!\nEn yücelerde hozana!\""},{"n":"11","t":"İsa Kudüs'e varınca tapınağa gitti, her tarafı gözden geçirdi. Sonra vakit ilerlemiş olduğundan Onikilerle birlikte Beytanya'ya döndü."},{"n":"12","h":"İncir ağacı lanetleniyor","t":"Ertesi gün Beytanya'dan çıktıklarında İsa acıkmıştı."},{"n":"13","t":"Uzakta, yapraklanmış bir incir ağacı görünce belki üzerinde incir bulurum diye yaklaştı. Ağacın yanına vardığında yapraktan başka bir şey bulamadı. Çünkü incir mevsimi değildi."},{"n":"14","t":"İsa ağaca, \"Artık senden hiç kimse bir daha meyve yemesin!\" dedi. Öğrencileri de bunu duydular."},{"n":"15","h":"İsa satıcıları tapınaktan kovuyor","t":"Oradan Kudüs'e geldiler. İsa tapınağın avlusuna girerek oradaki satıcı ve alıcıları dışarı kovmaya başladı. Para bozanların masalarını, güvercin satanların sehpalarını devirdi."},{"n":"16","t":"Yük taşıyan hiç kimsenin tapınağın avlusundan geçmesine izin vermedi."},{"n":"17","t":"Halka ders verirken şunları söyledi: \"'Benim evime, tüm ulusların dua evi denecek' diye yazılmamış mıdır? Ama siz burayı haydut inine çevirdiniz.\""},{"n":"18","t":"Başkâhinler ve din bilginleri bunu duyunca İsa'yı yok etmek için bir yol aramaya başladılar. O'ndan korkuyorlardı. Çünkü bütün halk O'nun öğretisine hayrandı."},{"n":"19","t":"Akşam olunca İsa'yla öğrencileri kentten ayrıldı."},{"n":"20","h":"İncir ağacından alınacak ders","t":"Sabah erkenden incir ağacının yanından geçerlerken, ağacın kökten kurumuş olduğunu gördüler."},{"n":"21","t":"Olayı hatırlayan Petrus, \"Rabbî, bak! Lanetlediğin incir ağacı kurumuş!\" dedi."},{"n":"22","t":"İsa onlara şöyle karşılık verdi: \"Tanrı'ya iman edin."},{"n":"23","t":"Size doğrusunu söyleyeyim, kim şu dağa, 'Kalk, denize atıl!' der ve yüreğinde kuşku duymadan dediğinin olacağına inanırsa, dileği yerine gelecektir."},{"n":"24","t":"Bunun için size diyorum ki, duayla dilediğiniz her şeyi daha şimdiden almış olduğunuza inanın, dileğiniz yerine gelecektir."},{"n":"25-26","t":"Kalkıp dua ettiğiniz zaman, birine karşı bir şikâyetiniz varsa onu bağışlayın ki, göklerde olan Babanız da sizin suçlarınızı bağışlasın.\""},{"n":"27-28","h":"İsa'nın yetkisi","t":"Yine Kudüs'e geldiler. İsa tapınakta gezinirken başkâhinler, din bilginleri ve ihtiyarlar O'nun yanına gelip, \"Bunları hangi yetkiyle yapıyorsun, bunları yapma yetkisini sana kim verdi?\" diye sordular."},{"n":"29","t":"İsa da onlara, \"Size bir soru soracağım\" dedi. \"Bana cevap verin, ben de size bunları hangi yetkiyle yaptığımı söylerim."},{"n":"30","t":"Yahya'nın vaftiz etme yetkisi Tanrı'dan mıydı, insanlardan mıydı? Cevap verin bana.\""},{"n":"31","t":"Bunu aralarında şöyle tartışmaya başladılar: \"'Tanrı'dan' dersek, 'Öyleyse ona niçin inanmadınız?' diyecek."},{"n":"32","t":"Yok eğer 'insanlardan' dersek…\"\nHalkın tepkisinden korkuyorlardı. Çünkü herkes Yahya'yı gerçekten peygamber sayıyordu."},{"n":"33","t":"İsa'ya, \"Bilmiyoruz\" diye cevap verdiler.\nİsa da onlara, \"Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim\" dedi."}]},{"ch":12,"verses":[{"n":"1","h":"Bağ kiracıları benzetmesi","t":"İsa onlara benzetmelerle seslenmeye başladı. \"Adamın biri bir bağ dikmiş, çevresini çitle çevirmiş, üzüm sıkmak için bir çukur kazmış, bir de bekçi kulesi yapmış. Sonra bağı bağcılara kiralayıp yolculuğa çıkmış."},{"n":"2","t":"Mevsimi gelince bağın ürününden kendisine düşen payı almak üzere bağcılara bir köle yollamış."},{"n":"3","t":"Bağcılar köleyi yakalayıp dövmüş ve eli boş göndermişler."},{"n":"4","t":"Bağ sahibi bu kez onlara bir başka köle yollamış. Onu da başından yaralamış ve aşağılamışlar."},{"n":"5","t":"Birini daha yollamış, ama onu öldürmüşler. Daha birçok köle yollamış. Bunların kimini dövmüş, kimini öldürmüşler."},{"n":"6","t":"\"Bağ sahibinin yanında tek biri kalmış, o da sevgili oğluymuş. 'Oğlumu sayarlar' diyerek bağcılara en son onu yollamış."},{"n":"7","t":"\"Ama bağcılar birbirlerine, 'Mirasçı bu' demişler, 'gelin onu öldürelim, miras bizim olur.'"},{"n":"8","t":"Böylece onu yakalayıp öldürmüşler ve bağdan dışarı atmışlar."},{"n":"9","t":"\"Bu durumda bağın sahibi ne yapacak? Gelip bağcıları yok edecek, bağı da başkalarına verecek."},{"n":"10-11","t":"Şu Kutsal Yazı'yı okumadınız mı?\n'Yapıcıların reddettiği taş,\nişte köşenin baş taşı oldu.\nRab'bin işidir bu,\ngözümüzde harika bir iş!'\""},{"n":"12","t":"İsa'nın bu benzetmede kendilerinden söz ettiğini anlayan Yahudi önderler O'nu tutuklamak istediler; ama halkın tepkisinden korktukları için O'nu bırakıp gittiler."},{"n":"13","h":"Sezar'ın hakkı Sezar'a","t":"Daha sonra İsa'yı söyleyeceği sözlerle tuzağa düşürmek amacıyla Ferisilerden ve Hirodes yanlılarından bazılarını O'na gönderdiler."},{"n":"14","t":"Bunlar gelip İsa'ya, \"Öğretmenimiz\" dediler, \"senin dürüst biri olduğunu, kimseyi kayırmadan, insanlar arasında ayrım yapmadan Tanrı yolunu dürüstçe öğrettiğini biliyoruz. Sezar'a vergi vermek Kutsal Yasa'ya uygun mu, değil mi? Verelim mi, vermeyelim mi?\""},{"n":"15","t":"Onların ikiyüzlülüğünü bilen İsa şöyle dedi: \"Beni neden sınıyorsunuz? Bana bir dinar getirin bakayım.\""},{"n":"16","t":"Parayı getirdiler. İsa onlara, \"Bu resim, bu yazı kimin?\" diye sordu.\n\"Sezar'ın\" dediler."},{"n":"17","t":"İsa da onlara, \"Sezar'ın hakkını Sezar'a, Tanrı'nın hakkını da Tanrı'ya verin\" dedi.\nİsa'nın sözlerine şaşakaldılar."},{"n":"18-19","h":"Dirilişle ilgili soru","t":"Ölümden sonra diriliş olmadığını söyleyen Sadukiler İsa'ya gelip şunu sordular: \"Öğretmenimiz, Musa yazılarında bize şöyle buyurmuştur: 'Eğer bir adamın kardeşi ölüp bir dul bırakır ama çocuk bırakmazsa, sağ kalan kardeş, ölenin karısını alıp soyunu sürdürsün.'"},{"n":"20","t":"Yedi kardeş vardı. Birincisi evlendi ve çocuk bırakmadan öldü."},{"n":"21","t":"İkincisi aynı kadını aldı, o da çocuk sahibi olmadan öldü. Üçüncüsüne de öyle oldu."},{"n":"22","t":"Yedisi de çocuksuz öldü. Hepsinden sonra kadın da öldü."},{"n":"23","t":"Diriliş günü, ölümden dirildiklerinde kadın bunlardan hangisinin karısı olacak? Çünkü yedisi de onunla evlendi.\""},{"n":"24","t":"İsa onlara şöyle karşılık verdi: \"Ne Kutsal Yazıları ne de Tanrı'nın gücünü biliyorsunuz. Yanılmanızın nedeni de bu değil mi?"},{"n":"25","t":"İnsanlar ölümden dirilince ne evlenir ne evlendirilir, göklerdeki melekler gibidirler."},{"n":"26","t":"Ölülerin dirilmesi konusuna gelince, Musa'nın kitabında, alevlenen çalıyla ilgili bölümde Tanrı'nın Musa'ya söylediklerini okumadınız mı? 'Ben İbrahim'in Tanrısı, İshak'ın Tanrısı ve Yakup'un Tanrısıyım' diyor."},{"n":"27","t":"Tanrı ölülerin değil, yaşayanların Tanrısıdır. Siz büyük bir yanılgı içindesiniz.\""},{"n":"28","h":"En büyük buyruk","t":"Onların tartışmalarını dinleyen ve İsa'nın onlara güzel bir cevap verdiğini gören bir din bilgini yaklaşıp O'na, \"Tüm buyrukların en önemlisi hangisidir?\" diye sordu."},{"n":"29","t":"İsa şöyle karşılık verdi: \"En önemlisi şudur: 'Dinle, ey İsrail! Tanrımız olan Rab tek Rab'dir."},{"n":"30","t":"Tanrın olan Rab'bi bütün yüreğinle, bütün canınla, bütün aklınla ve bütün gücünle sev.'"},{"n":"31","t":"İkincisi de şudur: 'Komşunu kendin gibi sev.' Bunlardan daha büyük buyruk yoktur.\""},{"n":"32","t":"Din bilgini İsa'ya, \"İyi söyledin, öğretmenim\" dedi. \"'Tanrı tektir ve O'ndan başkası yoktur' demekle doğruyu söyledin."},{"n":"33","t":"İnsanın Tanrı'yı bütün yüreğiyle, bütün anlayışıyla ve bütün gücüyle sevmesi, komşusunu da kendi gibi sevmesi, tüm yakılmalık adaklardan ve sunulan kurbanlardan daha önemlidir.\""},{"n":"34","t":"İsa, onun akıllıca cevap verdiğini görerek, \"Sen Tanrı'nın Egemenliğinden uzak değilsin\" dedi.\nBundan sonra kimse O'na soru sormaya cesaret edemedi."},{"n":"35","h":"Mesih kimin oğlu?","t":"İsa tapınakta ders verirken şunu sordu: \"Nasıl oluyor da din bilginleri, 'Mesih, Davut'un Oğludur' diyorlar?"},{"n":"36","t":"Davut'un kendisi, Kutsal Ruh'tan esinlenerek şöyle demişti:\n'Rab Rabbime dedi ki,\nBen düşmanlarını\nsenin ayaklarının altına serinceye dek\nsağımda otur.'"},{"n":"37","t":"Davut'un kendisi O'ndan Rab diye söz ettiğine göre, O nasıl Davut'un Oğlu olur?\"\nOradaki büyük kalabalık O'nu sevinçle dinliyordu."},{"n":"38-39","h":"İsa ikiyüzlü din bilginlerini kınıyor","t":"İsa ders verirken şöyle dedi: \"Uzun kaftanlar içinde dolaşmaktan, meydanlarda selamlanmaktan, havralarda en seçkin yerlere ve şölenlerde başköşelere kurulmaktan hoşlanan din bilginlerinden sakının."},{"n":"40","t":"Dul kadınların malını mülkünü sömüren, gösteriş için uzun uzun dua eden bu kişilerin cezası daha da ağır olacaktır.\""},{"n":"41","h":"Dul kadının bağışı","t":"İsa tapınaktaki bağış kutusunun karşısında oturmuş, kutuya para atan halkı seyrediyordu. Birçok zengin kişi kutuya büyük paralar attı."},{"n":"42","t":"Yoksul bir dul kadın da geldi, birkaç kuruş değerinde iki bakır para attı."},{"n":"43","t":"Öğrencilerini yanına çağıran İsa onlara şöyle dedi: \"Size doğrusunu söyleyeyim, bu yoksul dul kadın kutuya herkesten daha çok para attı."},{"n":"44","t":"Çünkü diğerlerinin hepsi, zenginliklerinden artanı attılar. Bu kadın ise yoksulluğuna rağmen, varını yoğunu, geçinmek için elinde bulunanın tümünü verdi.\""}]},{"ch":13,"verses":[{"n":"1","h":"Sonun belirtileri","t":"İsa tapınaktan çıkarken öğrencilerinden biri O'na, \"Öğretmenim\" dedi, \"bak, ne görkemli taşlar! Ne görkemli yapılar!\""},{"n":"2","t":"İsa ona, \"Bu büyük yapıları görüyor musun? Burada taş üstünde taş kalmayacak, hepsi yıkılacak!\" dedi."},{"n":"3-4","t":"İsa, Zeytin dağında, tapınağın karşısında otururken Petrus, Yakup, Yuhanna ve Andreya özel olarak kendisine şunu sordular: \"Söyle bize, bu dediklerin ne zaman olacak, bütün bunların gerçekleşmek üzere olduğunu gösteren belirti ne olacak?\""},{"n":"5","t":"İsa onlara anlatmaya başladı: \"Sakın kimse sizi saptırmasın\" dedi."},{"n":"6","t":"\"Birçokları, 'Ben O'yum' diyerek benim adımla gelecek ve birçok kişiyi saptıracaklar."},{"n":"7","t":"Savaş gürültüleri, savaş haberleri duyunca korkmayın. Bunların olması gerek, ama bu daha son demek değildir."},{"n":"8","t":"Ulus ulusa, devlet devlete savaş açacak; yer yer depremler, kıtlıklar olacak. Bunlar, doğum sancılarının başlangıcıdır."},{"n":"9","t":"\"Ama siz kendinize dikkat edin! İnsanlar sizi mahkemelere verecekler, havralarda dövecekler. Benden ötürü valilerin ve kralların önüne çıkarılacak, böylece onlara tanıklık edeceksiniz."},{"n":"10","t":"Ne var ki, önce Müjde'nin tüm uluslara duyurulması gerekir."},{"n":"11","t":"Sizi tutuklayıp mahkemeye verdiklerinde, 'Ne söyleyeceğiz?' diye önceden kaygılanmayın. O anda size ne esinlenirse onu söyleyin. Çünkü konuşacak olan siz değil, Kutsal Ruh olacak."},{"n":"12","t":"Kardeş kardeşini, baba çocuğunu ölüme teslim edecek. Çocuklar anne babalarına baş kaldırıp onları öldürtecekler."},{"n":"13","t":"Benim adımdan ötürü herkes sizden nefret edecek. Ama sonuna kadar dayanan kurtulacaktır."},{"n":"14","t":"\"Yıkıcı iğrenç şeyin, bulunmaması gereken yerde dikildiğini gördüğünüz zaman (okuyan anlasın), Yahudiye'de olanlar dağlara kaçsın."},{"n":"15","t":"Damda olan, evinden bir şey almak için aşağı inmesin, içeri girmesin."},{"n":"16","t":"Tarlada olan, abasını almak için geri dönmesin."},{"n":"17","t":"O günlerde gebe olan, çocuk emziren kadınların vay haline!"},{"n":"18","t":"Dua edin ki, kaçışınız kışa rastlamasın."},{"n":"19","t":"Çünkü o günlerde öyle bir sıkıntı olacak ki, Tanrı'nın var ettiği yaratılışın başlangıcından bu yana böylesi olmamış, ondan sonra da olmayacaktır."},{"n":"20","t":"Rab o günleri kısaltmamış olsaydı, hiç kimse kurtulamazdı. Ama Rab, seçilmiş olanlar, kendi seçtiği kişiler uğruna o günleri kısaltmıştır."},{"n":"21","t":"Eğer o zaman biri size, 'İşte Mesih burada', ya da, 'İşte şurada' derse, inanmayın."},{"n":"22","t":"Çünkü sahte mesihler, sahte peygamberler türeyecek; bunlar, mucizeler ve harikalar yaratacaklar. Öyle ki, ellerinden gelse seçilmiş olanları saptıracaklar."},{"n":"23","t":"Ama siz dikkatli olun. İşte size her şeyi önceden söylemiş bulunuyorum."},{"n":"24-25","h":"Mesih'in tekrar gelişi","t":"\"Ama o günlerde, o sıkıntıdan sonra,\n'Güneş kararacak,\nay ışığını vermez olacak,\nyıldızlar gökten düşecek\nve göksel güçler sarsılacak.'"},{"n":"26","t":"\"O zaman İnsanoğlu'nun bulutlar içinde büyük güç ve görkemle geldiğini görecekler."},{"n":"27","t":"İnsanoğlu o zaman meleklerini gönderecek, kendi seçtiklerini, yeryüzünün bir ucundan göğün öbür ucuna kadar, dört yelden alıp bir araya toplayacak."},{"n":"28","t":"\"İncir ağacından ders alın. Dalları filizlenip yapraklarını sürünce, yaz mevsiminin yakın olduğunu anlarsınız."},{"n":"29","t":"Aynı şekilde, bu olayların gerçekleştiğini gördüğünüzde bilin ki İnsanoğlu yakındır, kapıdadır."},{"n":"30","t":"Size doğrusunu söyleyeyim, bütün bunlar olmadan bu kuşak ortadan kalkmayacak."},{"n":"31","t":"Gök ve yer ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır."},{"n":"32","h":"Bilinmeyen gün ve saat","t":"\"O günü ve o saati, ne gökteki melekler, ne de Oğul bilir; Baba'dan başka kimse bilmez."},{"n":"33","t":"Dikkat edin, uyanık durun, dua edin. Çünkü o anın ne zaman geleceğini bilemezsiniz."},{"n":"34","t":"Bu, yolculuğa çıkan bir adamın durumuna benzer. Evinden ayrılırken kölelerine yetki ve birer görev verir, kapıdaki nöbetçiye de uyanık kalmasını buyurur."},{"n":"35","t":"Siz de uyanık kalın. Çünkü evin efendisi ne zaman gelecek, akşam mı, gece yarısı mı, horoz öttüğünde mi, sabaha doğru mu, bilemezsiniz."},{"n":"36","t":"Ansızın gelip sizi uykuda bulmasın!"},{"n":"37","t":"Size söylediklerimi herkese söylüyorum; uyanık kalın!\""}]},{"ch":14,"verses":[{"n":"1","h":"İsa'nın ölümü yaklaşıyor","t":"Fısıh ve Mayasız Ekmek bayramına iki gün kalmıştı. Başkâhinlerle din bilginleri İsa'yı hileyle tutuklayıp öldürmenin bir yolunu arıyorlardı."},{"n":"2","t":"\"Bayramda olmasın, yoksa halk arasında kargaşalık çıkar\" diyorlardı."},{"n":"3","t":"İsa Beytanya'da cüzamlı Simun'un evinde sofrada otururken yanına bir kadın geldi. Kadın, kaymaktaşından bir kap içinde çok değerli, saf hintsümbülü yağı getirmişti. Kabı kırarak yağı O'nun başından aşağı döktü."},{"n":"4-5","t":"Bazıları buna kızdılar; birbirlerine, \"Bu yağ niçin böyle boş yere harcandı? Üç yüz dinardan fazlaya satılabilir, parası yoksullara verilebilirdi\" diyerek kadını azarlamaya başladılar."},{"n":"6","t":"\"Kadını rahat bırakın\" dedi İsa. \"Neden üzüyorsunuz onu? Benim için güzel bir şey yaptı."},{"n":"7","t":"Yoksullar her zaman aranızdadır, dilediğiniz anda onlara yardım edebilirsiniz; ama ben her zaman aranızda olmayacağım."},{"n":"8","t":"Kadın elinden geleni yaptı, beni gömülmeye hazırlamak üzere daha şimdiden bedenimi yağladı."},{"n":"9","t":"Size doğrusunu söyleyeyim, Müjde dünyanın her neresinde duyurulursa, bu kadının yaptığı da onun anılması için anlatılacak.\""},{"n":"10","t":"Bu arada Onikilerden biri olan Yahuda İskariyot, İsa'yı ele vermek amacıyla başkâhinlerin yanına gitti."},{"n":"11","t":"Onlar bunu işitince sevindiler, Yahuda'ya para vermeyi vaat ettiler. O da İsa'yı ele vermek için fırsat kollamaya başladı."},{"n":"12","h":"Fısıh yemeği","t":"Fısıh kurbanının kesildiği Mayasız Ekmek bayramının ilk günü öğrencileri İsa'ya, \"Fısıh yemeğini yemen için nereye gidip hazırlık yapmamızı istersin?\" diye sordular."},{"n":"13","t":"O da öğrencilerinden ikisini şu sözlerle önden gönderdi: \"Kente gidin, orada su testisi taşıyan bir adam çıkacak karşınıza. Onu izleyin."},{"n":"14","t":"Adamın gideceği evin sahibine şöyle deyin: 'Öğretmen, öğrencilerimle birlikte Fısıh yemeğini yiyeceğim konuk odası nerede? diye soruyor.'"},{"n":"15","t":"Ev sahibi size, üst katta döşenmiş, hazır büyük bir oda gösterecek. Orada bizim için hazırlık yapın.\""},{"n":"16","t":"Öğrenciler yola çıkıp kente gittiler. Her şeyi, İsa'nın kendilerine söylemiş olduğu gibi buldular ve Fısıh yemeği için hazırlık yaptılar."},{"n":"17","t":"Akşam olunca İsa Onikilerle birlikte geldi."},{"n":"18","t":"Sofraya oturmuş yemek yerlerken İsa, \"Size doğrusunu söyleyeyim\" dedi, \"sizden biri, benimle yemek yiyen biri beni ele verecek.\""},{"n":"19","t":"Onlar da kederlenerek birer birer kendisine, \"Beni demek istemedin ya?\" diye sormaya başladılar."},{"n":"20","t":"İsa onlara, \"Onikilerden biridir, ekmeğini benimle birlikte sahana batırandır\" dedi."},{"n":"21","t":"\"Evet, İnsanoğlu kendisi için yazılmış olduğu gibi gidiyor, ama İnsanoğlu'nu ele verenin vay haline! O adam hiç doğmamış olsaydı, kendisi için daha iyi olurdu.\""},{"n":"22","t":"İsa yemek sırasında eline ekmek aldı, şükran duasını yapıp ekmeği böldü ve, \"Alın, bu benim bedenimdir\" diyerek öğrencilerine verdi."},{"n":"23","t":"Sonra bir kâse alıp şükretti ve bunu öğrencilerine verdi. Hepsi bundan içti."},{"n":"24","t":"\"Bu benim kanım\" dedi İsa, \"birçokları uğruna akıtılan antlaşma kanıdır."},{"n":"25","t":"Size doğrusunu söyleyeyim, Tanrı'nın Egemenliğinde tazesini içeceğim o güne dek, asmanın ürününden bir daha içmeyeceğim.\""},{"n":"26","t":"Bir ilahi söyledikten sonra dışarı çıkıp Zeytin dağına doğru gittiler."},{"n":"27","h":"Petrus'un inkârı önceden bildiriliyor","t":"Bu arada İsa öğrencilerine, \"Hepiniz sendeleyip düşeceksiniz\" dedi. \"Çünkü şöyle yazılmıştır:\n'Çobanı vuracağım,\nkoyunlar da darmadağın olacak.'"},{"n":"28","t":"Ama ben dirildikten sonra sizden önce Celile'ye gideceğim.\""},{"n":"29","t":"Petrus O'na, \"Herkes sendeleyip düşse bile, ben düşmem\" dedi."},{"n":"30","t":"\"Sana doğrusunu söyleyeyim\" dedi İsa, \"bugün, bu gece, horoz iki kez ötmeden sen beni üç kez inkâr edeceksin.\""},{"n":"31","t":"Ama Petrus üsteleyerek, \"Seninle birlikte ölmem bile gerekse, seni asla inkâr etmem\" dedi. Öğrencilerin hepsi de aynı şeyi söyledi."},{"n":"32","h":"Getsemani bahçesinde","t":"Sonra Getsemani denilen bir yere geldiler. İsa öğrencilerine,\"Ben dua ederken siz burada oturun\" dedi."},{"n":"33","t":"Petrus'u, Yakup'u ve Yuhanna'yı yanına aldı. Hüzünlenmeye ve ağır bir sıkıntı duymaya başlamıştı."},{"n":"34","t":"Onlara, \"Yüreğim ölüm derecesinde kederli\" dedi. \"Burada kalın, uyanık durun.\""},{"n":"35","t":"Biraz ilerledi, yüzüstü yere kapanıp dua etmeye başladı. \"Mümkünse o saati yaşamayayım\" dedi."},{"n":"36","t":"\"Abba, Baba, senin için her şey mümkün, bu kâseyi benden uzaklaştır. Ama benim değil, senin istediğin olsun.\""},{"n":"37","t":"Öğrencilerinin yanına döndüğünde onları uyumuş buldu. Petrus'a, \"Simun\" dedi, \"uyuyor musun? Bir saat uyanık kalamadın mı?"},{"n":"38","t":"Uyanık durup dua edin ki, ayartılmayasınız. Ruh isteklidir, ama beden güçsüzdür.\""},{"n":"39","t":"Yine uzaklaştı, aynı sözleri tekrarlayarak dua etti."},{"n":"40","t":"Geri geldiğinde öğrencilerini yine uyumuş buldu. Onların göz kapaklarına bir ağırlık çökmüştü. İsa'ya ne diyeceklerini bilemiyorlardı."},{"n":"41","t":"İsa üçüncü kez yanlarına döndü, \"Hâlâ uyuyor, dinleniyor musunuz?\" dedi. \"Yeter! Saat geldi. İşte İnsanoğlu günahkârların eline veriliyor."},{"n":"42","t":"Kalkın, gidelim. İşte beni ele veren geldi!\""},{"n":"43","h":"İsa tutuklanıyor","t":"Tam o anda, İsa daha konuşurken, Onikilerden biri olan Yahuda çıkageldi. Yanında başkâhinler, din bilginleri ve ihtiyarlar tarafından gönderilmiş kılıçlı sopalı bir kalabalık vardı."},{"n":"44","t":"İsa'yı ele veren Yahuda, \"Kimi öpersem, İsa O'dur. O'nu tutuklayın, güvenlik altına alıp götürün\" diye onlarla sözleşmişti."},{"n":"45","t":"Gelir gelmez İsa'ya yaklaştı, \"Rabbî\" diyerek O'nu öptü."},{"n":"46","t":"Onlar da İsa'yı yakalayıp tutukladılar."},{"n":"47","t":"İsa'nın yanında bulunanlardan biri kılıcını çekti, başkâhinin kölesine vurup kulağını uçurdu."},{"n":"48","t":"İsa onlara, \"Bir haydudun peşindeymiş gibi beni kılıç ve sopalarla mı yakalamaya geldiniz?\" dedi."},{"n":"49","t":"\"Her gün tapınakta, yanıbaşınızda ders veriyordum, beni tutuklamadınız. Ama bu, Kutsal Yazılar yerine gelsin diye oldu.\""},{"n":"50","t":"O zaman öğrencilerinin hepsi O'nu bırakıp kaçtı."},{"n":"51","t":"İsa'nın ardından sadece keten beze sarınmış bir genç gidiyordu. Bu genç de yakalandı."},{"n":"52","t":"Ama keten bezin içinden sıyrılıp çıplak olarak kaçtı."},{"n":"53","h":"İsa Yüksek Kurul'un önünde","t":"İsa'yı görevli başkâhine götürdüler. Bütün başkâhinler, ihtiyarlar ve din bilginleri de orada toplandı."},{"n":"54","t":"Petrus, İsa'yı başkâhinin avlusunun içine kadar uzaktan izledi. Avluda nöbetçilerle birlikte ateşin başında oturup ısınmaya başladı."},{"n":"55","t":"Başkâhinler ve Yüksek Kurul'un tamamı, İsa'yı ölüm cezasına çarptırmak için kendisine karşı tanık arıyor, ama bulamıyorlardı."},{"n":"56","t":"Birçok kişi O'na karşı yalan yere tanıklık ettiyse de, tanıklıkları birbirini tutmadı."},{"n":"57-58","t":"Bazıları kalkıp O'na karşı yalan yere şöyle tanıklık ettiler: \"Biz O'nun, 'Elle yapılmış bu tapınağı yıkacağım ve üç günde, elle yapılmamış başka bir tapınak kuracağım' dediğini işittik.\""},{"n":"59","t":"Ama bu noktada bile tanıklıkları birbirini tutmadı."},{"n":"60","t":"Sonra başkâhin topluluğun ortasında ayağa kalkarak İsa'ya, \"Hiç cevap vermeyecek misin? Nedir bunların sana karşı ettiği bu tanıklıklar?\" diye sordu."},{"n":"61","t":"Ne var ki, İsa susmaya devam etti, hiç cevap vermedi.\nBaşkâhin O'na yeniden, \"Yüce Olan'ın Oğlu Mesih sen misin?\" diye sordu."},{"n":"62","t":"İsa, \"Ben'im\" dedi. \"Ve sizler, İnsanoğlu'nun kudretli Olan'ın sağında oturduğunu ve göğün bulutlarıyla geldiğini göreceksiniz.\""},{"n":"63-64","t":"Başkâhin giysilerini yırtarak, \"Artık tanıklara ne ihtiyacımız var?\" dedi. \"Küfürü işittiniz. Buna ne diyorsunuz?\"\nHepsi de İsa'nın ölüm cezasını hak ettiğine karar verdiler."},{"n":"65","t":"Bazıları O'nun üzerine tükürmeye, gözlerini bağlayarak O'nu yumruklamaya başladılar. \"Haydi, peygamberliğini göster!\" diyorlardı. Nöbetçiler de O'nu aralarına alıp tokatladılar."},{"n":"66-67","h":"Petrus İsa'yı inkâr ediyor","t":"Petrus aşağıda, avludayken, başkâhinin hizmetçi kızlarından biri geldi. Isınmakta olan Petrus'u görünce onu dikkatle süzüp, \"Sen de Nasıralı İsa'yla birlikteydin\" dedi."},{"n":"68","t":"Petrus ise bunu inkâr ederek, \"Senin neden söz ettiğini bilmiyorum, anlamıyorum\" dedi ve dışarıya, dış kapının önüne çıktı. Bu arada horoz öttü."},{"n":"69","t":"Hizmetçi kız Petrus'u görünce etrafta duranlara yine, \"Bu adam onlardan biri\" demeye başladı."},{"n":"70","t":"Petrus tekrar inkâr etti. Çevrede duranlar az sonra Petrus'a yine, \"Gerçekten onlardansın; sen de Celilelisin\" dediler."},{"n":"71","t":"Petrus kendine lanet okuyup yemin ederek, \"Sözünü ettiğiniz o adamı tanımıyorum\" dedi."},{"n":"72","t":"Tam o anda horoz ikinci kez öttü. Petrus, İsa'nın kendisine, \"Horoz iki kez ötmeden sen beni üç kez inkâr edeceksin\" dediğini hatırladı ve hüngür hüngür ağlamaya başladı."}]},{"ch":15,"verses":[{"n":"1","h":"İsa, vali Pilatus'un önünde","t":"Sabah olunca başkâhinler, ihtiyarlar, din bilginleri ve Yüksek Kurul'un tüm diğer üyeleri bir danışma toplantısı yaptıktan sonra İsa'yı bağladılar, götürüp Pilatus'a teslim ettiler."},{"n":"2","t":"Pilatus O'na, \"Sen Yahudilerin Kralı mısın?\" diye sordu.\nİsa ona, \"Söylediğin gibidir\" cevabını verdi."},{"n":"3","t":"Başkâhinler O'na karşı birçok suçlamada bulundular."},{"n":"4","t":"Pilatus O'na yeniden, \"Hiç cevap vermeyecek misin?\" diye sordu. \"Bak, seni ne kadar çok şeyle suçluyorlar.\""},{"n":"5","t":"Ama İsa artık cevap vermiyordu. Pilatus buna şaştı."},{"n":"6","h":"İsa ölüm cezasına çarptırılıyor","t":"Pilatus, her Fısıh bayramında halkın istediği bir tutukluyusalıverirdi."},{"n":"7","t":"O sırada hapishanede, ayaklanma sırasında adam öldürmüş olan isyancılarla birlikte tutuklu bulunan Barabas adında biri vardı."},{"n":"8","t":"Halk, Pilatus'a gelip her zamanki gibi kendileri için birini salıvermesini istedi."},{"n":"9","t":"Pilatus onlara, \"Sizin için Yahudilerin Kralını salıvermemi ister misiniz?\" dedi."},{"n":"10","t":"Başkâhinlerin İsa'yı kıskançlıktan ötürü kendisine teslim ettiklerini biliyordu."},{"n":"11","t":"Ne var ki başkâhinler, İsa'nın değil, Barabas'ın salıverilmesini istemeleri için halkı kışkırttılar."},{"n":"12","t":"Pilatus onlara tekrar seslenerek, \"Öyleyse Yahudilerin Kralı dediğiniz adamı ne yapayım?\" diye sordu."},{"n":"13","t":"\"O'nu çarmıha ger!\" diye bağırdılar yine."},{"n":"14","t":"Pilatus onlara, \"O ne kötülük yaptı ki?\" dedi.\nOnlar ise daha yüksek sesle, \"O'nu çarmıha ger!\" diye bağrıştılar."},{"n":"15","t":"Halkı memnun etmek isteyen Pilatus, onlar için Barabas'ı salıverdi. İsa'yı ise kamçılattıktan sonra çarmıha gerilmek üzere askerlere teslim etti."},{"n":"16","h":"Askerlerin İsa'yı aşağılaması","t":"Askerler İsa'yı, Pretoryum denilen vali konağına götürüp tüm taburu topladılar."},{"n":"17","t":"O'na mor renkte bir giysi giydirdiler, dikenlerden bir taç örüp başına geçirdiler."},{"n":"18","t":"\"Selam, ey Yahudilerin Kralı!\" diyerek O'nu selamlamaya başladılar."},{"n":"19","t":"Başına bir kamışla vuruyor, üzerine tükürüyor, diz çöküp önünde yere kapanıyorlardı."},{"n":"20","t":"O'nunla böyle alay ettikten sonra mor giysiyi üzerinden çıkarıp O'na yine kendi giysilerini giydirdiler ve çarmıha germek üzere O'nu dışarı götürdüler."},{"n":"21","h":"İsa çarmıha geriliyor","t":"Kırdan gelmekte olan Simun adında Kireneli bir adam oradan geçiyordu. İskender ve Rufus'un babası olan bu adama İsa'nın çarmıhını zorla taşıttılar."},{"n":"22","t":"İsa'yı Golgota, yani Kafatası denilen yere götürdüler."},{"n":"23","t":"O'na mürle karışık şarap vermek istediler, ama içmedi."},{"n":"24","t":"Sonra O'nu çarmıha gerdiler ve kim ne alacak diye kura çekerek giysilerini aralarında paylaştılar."},{"n":"25","t":"İsa'yı çarmıha gerdiklerinde saat dokuzdu."},{"n":"26","t":"Üzerindeki suç yaftasında, 'YAHUDİLERİN KRALI' diye yazılıydı."},{"n":"27-28","t":"İsa'yla birlikte, biri sağında öbürü solunda olmak üzere iki haydudu da çarmıha gerdiler."},{"n":"29-30","t":"Oradan geçenler başlarını sallayıp İsa'ya sövüyor, \"Hani sen tapınağı yıkıp üç günde yeniden kuracaktın? Çarmıhtan in de kurtar kendini!\" diyorlardı."},{"n":"31","t":"Aynı şekilde başkâhinler ve din bilginleri de O'nunla alay ederek aralarında, \"Başkalarını kurtardı, kendini kurtaramıyor\" diye konuşuyorlardı."},{"n":"32","t":"\"İsrail'in Kralı Mesih şimdi çarmıhtan insin de görelim ve iman edelim.\" İsa'yla birlikte çarmıha gerilmiş olanlar da O'na hakaret ettiler."},{"n":"33","h":"İsa'nın ölümü","t":"Bütün ülkenin üzerine öğleyin saat on ikiden saat üçe kadar süren bir karanlık çöktü."},{"n":"34","t":"Saat üçte İsa yüksek sesle, \"Elohi, Elohi, lema şevaktani\" yani, \"Tanrım, Tanrım, beni niçin terk ettin?\" diye bağırdı."},{"n":"35","t":"Orada duranlardan bazıları bunu işitince, \"Bakın, İlyas'ı çağırıyor\" dediler."},{"n":"36","t":"Aralarından biri koşup bir süngeri ekşi şaraba batırdı, bir kamışın ucuna takarak İsa'ya içirdi. \"Dur bakalım, İlyas gelip O'nu indirecek mi?\" dedi."},{"n":"37","t":"Ama İsa yüksek sesle bağırarak son nefesini verdi."},{"n":"38","t":"O anda tapınaktaki perde yukarıdan aşağıya dek yırtılarak ikiye bölündü."},{"n":"39","t":"İsa'nın karşısında duran yüzbaşı, O'nun bu şekilde son nefesini verdiğini görünce, \"Bu adam gerçekten Tanrı'nın Oğluydu\" dedi."},{"n":"40","t":"Olup bitenleri uzaktan izleyen bazı kadınlar da vardı. Aralarında Mecdelli Meryem, küçük Yakup ile Yose'nin annesi Meryem ve Şalome bulunuyordu."},{"n":"41","t":"İsa daha Celile'deyken bu kadınlar O'nun peşinden gitmiş ve O'na hizmet etmişlerdi. O'nunla birlikte Kudüs'e gelmiş olan daha birçok kadın da olup bitenleri izliyordu."},{"n":"42-43","h":"İsa'nın gömülmesi","t":"O gün Hazırlık günü, yani Sept gününden önceki gündü. Artık akşam oluyordu. Bu nedenle, Yüksek Kurul'un saygın bir üyesi olup Tanrı'nın Egemenliğini ümitle bekleyen Aramatyalı Yusuf geldi, cesaretini toplayarak Pilatus'un huzuruna çıktı ve İsa'nın cesedini istedi."},{"n":"44","t":"Pilatus, İsa'nın bu kadar çabuk ölmüş olmasına şaştı. Yüzbaşıyı çağırıp, \"Öleli çok oldu mu?\" diye sordu."},{"n":"45","t":"Yüzbaşıdan durumu öğrenince Yusuf'a, cesedi alması için izin verdi."},{"n":"46","t":"Yusuf da keten bez satın aldı, cesedi çarmıhtan indirip beze sardı ve kayadan oyulmuş bir mezara yatırarak mezarın girişine bir taş yuvarladı."},{"n":"47","t":"Mecdelli Meryem ile Yose'nin annesi Meryem, İsa'nın nereye konulduğunu gördüler."}]},{"ch":16,"verses":[{"n":"1","h":"İsa'nın dirilişi","t":"Sept günü geçince, Mecdelli Meryem, Yakup'un annesi Meryem ve Şalome gidip İsa'nın cesedine sürmek üzere baharat satın aldılar."},{"n":"2","t":"Haftanın ilk günü sabah çok erkenden, güneşin doğuşuyla birlikte mezara gittiler."},{"n":"3","t":"Aralarında, \"Mezarın girişindeki taşı bizim için kim yana yuvarlayacak?\" diye konuşuyorlardı."},{"n":"4","t":"Başlarını kaldırıp bakınca, o kocaman taşın yana yuvarlanmış olduğunu gördüler."},{"n":"5","t":"Mezara girip sağ tarafta, beyaz kaftan giyinmiş genç bir adamın oturduğunu görünce çok şaşırdılar."},{"n":"6","t":"Adam onlara, \"Şaşırmayın!\" dedi. \"Siz çarmıha gerilmiş olan Nasıralı İsa'yı arıyorsunuz. O dirildi, burada yok. İşte O'nu yatırdıkları yer."},{"n":"7","t":"Şimdi O'nun öğrencilerine ve Petrus'a gidip şöyle deyin: 'İsa sizden önce Celile'ye gidiyor. Size bildirdiği gibi, kendisini orada göreceksiniz.'\""},{"n":"8","t":"Kadınlar mezardan çıkıp kaçtılar. Onları bir titreme, bir şaşkınlık almıştı. Korkularından kimseye bir şey söylemediler."},{"n":"9","h":"İsa öğrencilerine görünüyor","t":"İsa, haftanın ilk günü sabah erkenden dirildiği zaman önce Mecdelli Meryem'e göründü. Bu kadından yedi cin kovmuştu."},{"n":"10","t":"Meryem gitti, İsa'yla bulunmuş olan, şimdiyse yas tutup gözyaşı döken öğrencilerine haberi verdi."},{"n":"11","t":"Ne var ki onlar, İsa'nın diri olduğunu ve Meryem'e göründüğünü duyunca inanmadılar."},{"n":"12","t":"Bundan sonra İsa kırlara doğru yürümekte olan öğrencilerinden ikisine değişik bir biçimde göründü."},{"n":"13","t":"Bunlar geri dönüp diğerlerine haber verdiler, ama diğerleri bunlara da inanmadılar."},{"n":"14","t":"İsa daha sonra, sofrada otururlarken Onbirlere göründü. Kendisini dirilmiş olarak görenlere inanmadıkları için imansızlıklarından ve yüreklerinin duygusuzluğundan ötürü onları azarladı."},{"n":"15","h":"İsa öğrencilerini bütün dünyaya gönderiyor","t":"İsa onlara şöyle buyurdu: \"Dünyanın her yanına gidin, Müjde'yi bütün yaratılışa duyurun."},{"n":"16","t":"İman edip vaftiz olan kurtulacak, iman etmeyen ise hüküm giyecek."},{"n":"17-18","t":"İman edenlerle birlikte görülecek belirtiler şunlardır: benim adımla cinleri kovacaklar, yeni diller konuşacaklar, yılanları elleriyle tutacaklar. Öldürücü bir zehir içseler bile, bundan zarar görmeyecekler. Ellerini hastaların üzerine koyacaklar ve hastalar iyileşecek.\""},{"n":"19","t":"Rab İsa onlara bu sözleri söyledikten sonra göğe alındı ve Tanrı'nın sağında oturdu."},{"n":"20","t":"Öğrencileri de gidip Tanrı sözünü her yere yaydılar. Rab onlarla birlikte çalışıyor, görülen belirtilerle sözünü doğruluyordu."}]}]},{"id":"luka","name":"Luka","chapters":[{"ch":1,"verses":[{"n":"1-3","t":"Sayın Teofilos,\nBirçok kişi aramızda olup bitenlerin tarihçesini yazmaya girişmiştir. Nitekim başlangıçtan beri bu olayların görgü tanığı ve Tanrı sözünün hizmetkârı olanlar bunları bize iletmişlerdir. Ben de tüm bu olayları ta başından özenle araştırmış biri olarak bunları sana sırasıyla yazmayı uygun gördüm."},{"n":"4","t":"Öyle ki, sana verilen bilgilerin doğruluğunu bilesin."},{"n":"5","h":"Yahya'nın doğumu önceden bildiriliyor","t":"Yahudiye kralı Hirodes zamanında, Abiya bölüğünden Zekeriya adında bir kâhin vardı. Harun'un soyundan olan karısının adı ise Elizabet'ti."},{"n":"6","t":"Her ikisi de Tanrı'nın gözünde doğru kişilerdi, Rab'bin tüm buyruk ve kurallarına eksiksizce uyarlardı."},{"n":"7","t":"Elizabet kısır olduğu için çocukları olmuyordu. Her ikisinin de yaşı ilerlemişti."},{"n":"8","t":"Zekeriya, hizmet sırasının kendi bölüğünde olduğu bir gün, Tanrı'nın önünde kâhinlik görevini yerine getiriyordu."},{"n":"9","t":"Kâhinlik geleneği uyarınca Rab'bin tapınağına girip buhur yakma görevi kurayla ona verilmişti."},{"n":"10","t":"Buhur yakma saatinde bütün halk topluluğu dışarıda dua ediyordu."},{"n":"11","t":"Bu sırada, Rab'bin bir meleği buhur sunağının sağında dikilip Zekeriya'ya göründü."},{"n":"12","t":"Zekeriya onu görünce şaşırdı, korkuya kapıldı."},{"n":"13","t":"Melek ona, \"Korkma, Zekeriya\" dedi, \"duan kabul edildi. Karın Elizabet sana bir oğul doğuracak, onun adını Yahya koyacaksın."},{"n":"14","t":"Sevinip coşacaksın. Birçokları da onun doğumuna sevinecek."},{"n":"15","t":"O, Rab'bin gözünde büyük olacak. Hiç şarap ve içki içmeyecek; daha annesinin rahmindeyken Kutsal Ruh'la dolacak."},{"n":"16","t":"İsrail oğullarından birçoğunu, Tanrıları olan Rab'be döndürecek."},{"n":"17","t":"Babaların yüreklerini çocuklarına döndürmek, söz dinlemeyenleri doğru kişilerin anlayışına yöneltmek ve Rab için hazırlanmış bir halk yetiştirmek üzere, İlyas'ın ruhu ve gücüyle Rab'bin önünden gidecektir.\""},{"n":"18","t":"Zekeriya meleğe, \"Bundan nasıl emin olabilirim?\" dedi. \"Çünkü ben yaşlandım, karımın da yaşı ilerledi.\""},{"n":"19","t":"Melek ona şöyle karşılık verdi: \"Ben Tanrı'nın huzurunda duran Cebrail'im. Seninle konuşmak ve bu müjdeyi sana bildirmek için gönderildim."},{"n":"20","t":"İşte, belirlenen zamanda yerine gelecek olan sözlerime inanmadığın için dilin tutulacak, bunların gerçekleşeceği güne dek konuşamayacaksın.\""},{"n":"21","t":"Zekeriya'yı bekleyen halk, onun tapınakta bu kadar uzun süre kalmasına şaştı."},{"n":"22","t":"Zekeriya ise dışarı çıktığında onlarla konuşamadı. O zaman tapınakta bir görüm gördüğünü anladılar. Kendisi onlara işaretler yapıyor, ama konuşamıyordu."},{"n":"23","t":"Görev süresi bitince Zekeriya evine döndü."},{"n":"24","t":"Bir süre sonra karısı Elizabet gebe kaldı ve beş ay evine kapandı."},{"n":"25","t":"\"Bunu benim için yapan Rab'dir\" dedi. \"Bu günlerde benimle ilgilenerek insanlar arasındautancımı giderdi.\""},{"n":"26-27","h":"İsa'nın doğumu önceden bildiriliyor","t":"Elizabet'in hamileliğinin altıncı ayında Tanrı, melek Cebrail'i Celile'de bulunan Nasıra adlı kente, Davut'un soyundan Yusuf adındaki adama nişanlı olan bir kıza gönderdi. Kızın adı Meryem'di."},{"n":"28","t":"Onun yanına giren melek, \"Ey Tanrı'nın lütfuna erişen kız, selam! Rab seninledir\" dedi."},{"n":"29","t":"Söylenenlere çok şaşıran Meryem, bu selamın ne anlama gelebileceğini düşünmeye başladı."},{"n":"30","t":"Ama melek ona, \"Korkma Meryem\" dedi, \"sen Tanrı'nın lütfuna eriştin."},{"n":"31","t":"Bak, gebe kalıp bir oğul doğuracaksın, adını İsa koyacaksın."},{"n":"32","t":"O büyük olacak, kendisine 'en yüce Olan'ın Oğlu' denecek. Rab Tanrı O'na, atası Davut'un tahtını verecek."},{"n":"33","t":"O da sonsuza dek Yakup'un soyu üzerinde egemenlik sürecek, ve egemenliğinin sonu gelmeyecektir.\""},{"n":"34","t":"Meryem meleğe, \"Bu nasıl olur? Ben erkeğe varmadım ki\" dedi."},{"n":"35","t":"Melek ona şöyle cevap verdi: \"Kutsal Ruh senin üzerine gelecek, en yüce Olan'ın gücü senin üstüne gölge salacak. Bunun için doğacak olana kutsal, Tanrı Oğlu denecek."},{"n":"36","t":"Bak, senin akrabalarından Elizabet de yaşlılığında bir oğula gebe kalmıştır. Kısır bilinen bu kadın şimdi altıncı ayındadır."},{"n":"37","t":"Tanrı'nın yapamayacağı hiçbir şey yoktur.\""},{"n":"38","t":"\"Ben Rab'bin kuluyum\" dedi Meryem, \"bana dediğin gibi olsun.\" Bundan sonra melek onun yanından ayrıldı."},{"n":"39","h":"Meryem, Elizabet'i ziyaret ediyor","t":"O günlerde Meryem kalkıp aceleyle dağlık bölgeye, Yahuda oymağının bir kentine gitti."},{"n":"40","t":"Zekeriya'nın evine girerek Elizabet'i selamladı."},{"n":"41-42","t":"Elizabet Meryem'in selamını duyunca rahmindeki çocuk hopladı. Kutsal Ruh'la dolan Elizabet, yüksek sesle şöyle dedi: \"Kadınlar arasında kutsanmış bulunuyorsun, rahminin ürünü de kutsanmıştır!"},{"n":"43","t":"Nasıl oldu da Rabbimin annesi yanıma geldi?"},{"n":"44","t":"Bak, selamının sesi kulaklarıma eriştiği an, çocuk rahmimde sevinçle hopladı."},{"n":"45","t":"İman eden kadına ne mutlu! Çünkü Rab'bin ona söylediği sözler gerçekleşecektir.\""},{"n":"46-47","t":"Meryem de şöyle dedi:\n\"Canım Rab'bi yüceltir;\nruhum, Kurtarıcım Tanrı sayesinde sevinçle coşar."},{"n":"48","t":"Çünkü O, sıradan biri olan kuluyla ilgilendi.\nİşte, bundan böyle tüm kuşaklar beni mutlu sayacak."},{"n":"49","t":"Çünkü güçlü Olan, benim için büyük işler yaptı.\nO'nun adı kutsaldır."},{"n":"50","t":"Kuşaktan kuşağa kendisinden korkanlara merhamet eder."},{"n":"51","t":"Eliyle güçlü işler yaptı;\nkibirlileri yüreklerindeki kuruntularla darmadağın etti."},{"n":"52","t":"Hükümdarları tahtlarından indirdi,\nsıradan insanları yükseltti."},{"n":"53","t":"Aç olanları iyiliklerle doyurdu,\nzenginleri ise elleri boş çevirdi."},{"n":"54-55","t":"Atalarımıza söz verdiği gibi,\nİbrahim'e ve onun soyuna sonsuza dek\nmerhamet etmeyi unutmayarak\nkulu İsrail'in yardımına yetişti.\""},{"n":"56","t":"Meryem, üç ay kadar Elizabet'in yanında kaldı, sonra kendi evine döndü."},{"n":"57","h":"Yahya peygamberin doğumu","t":"Elizabet'in doğum yapacağı vakit geldi ve bir oğul doğurdu."},{"n":"58","t":"Komşularıyla akrabaları, Rab'bin ona ne büyük merhamet gösterdiğini duyunca, onun sevincine katıldılar."},{"n":"59","t":"Sekizinci gün çocuğun sünneti için geldiler. Ona babası Zekeriya'nın adını vereceklerdi."},{"n":"60","t":"Ama annesi, \"Hayır, adı Yahya olacak\" dedi."},{"n":"61","t":"Ona, \"Akrabaların arasında bu adı taşıyan hiç kimse yok ki\" dediler."},{"n":"62","t":"Bunun üzerine babasına işaretler yaparak çocuğun adını ne koymak istediğini sordular."},{"n":"63","t":"Onlardan bir yazı levhası isteyen Zekeriya, \"Adı Yahya'dır\" diye yazdı. Herkes şaşakaldı."},{"n":"64","t":"O anda Zekeriya'nın ağzı açıldı, dili çözüldü. Tanrı'yı överek konuşmaya başladı."},{"n":"65","t":"Çevrede oturanların hepsi korkuya kapıldı. Bütün bu olaylar, Yahudiye'nin dağlık bölgesinin her yanında konuşulur oldu."},{"n":"66","t":"Duyan herkes derin derin düşünüyor, \"Bu çocuk acaba ne olacak?\" diyordu. Çünkü Rab onunla birlikteydi."},{"n":"67","h":"Zekeriya'nın şükran ilahisi","t":"Çocuğun babası Zekeriya, Kutsal Ruh'la dolarak şu peygamberlikte bulundu:"},{"n":"68","t":"\"İsrail'in Tanrısı olan Rab'be övgüler olsun!\nÇünkü halkının yardımına gelip onları fidyeyle kurtardı."},{"n":"69-71","t":"Eski çağlardan beri\nkutsal peygamberlerinin ağzından bildirdiği gibi,\nkulu Davut'un soyundan\nbizim için güçlü bir kurtarıcı çıkardı;\ndüşmanlarımızdan,\nbizden nefret edenlerin hepsinin elinden\nkurtuluşumuzu sağladı."},{"n":"72","t":"Böylece atalarımıza merhamet ederek\nkutsal antlaşmasını anmış oldu."},{"n":"73-75","t":"Nitekim bizi düşmanlarımızın elinden kurtaracağına\nve ömrümüz boyunca\nkendi önünde kutsallık ve doğruluk içinde,\nkorkusuzca kendisine tapınmamızı sağlayacağına dair\natamız İbrahim'e ant içerek söz vermişti."},{"n":"76-77","t":"Sen de, ey çocuk,\nen yüce Olan'ın peygamberi diye anılacaksın.\nRab'bin yollarını hazırlamak üzere önünden gidecek\nve O'nun halkına,\ngünahlarının bağışlanmasıyla kurtulacaklarını bildireceksin."},{"n":"78","t":"Çünkü Tanrımızın yüreği merhamet doludur."},{"n":"79","t":"O'nun merhameti sayesinde,\nyücelerden doğan Güneş,\nkaranlıkta ve ölümün gölgesinde yaşayanlara ışık saçmak\nve ayaklarımızı esenlik yoluna yöneltmek üzere\nyardımımıza gelecektir.\""},{"n":"80","t":"Çocuk büyüyor, ruhsal yönden güçleniyordu. İsrail halkına görüneceği güne dek ıssız yerlerde yaşadı."}]},{"ch":2,"verses":[{"n":"1","t":"O günlerde Sezar Avgustus tüm Roma dünyasında bir nüfus sayımının yapılması için ferman çıkardı."},{"n":"2","t":"Bu ilk sayım, Kirinyus'un Suriye valiliği zamanında yapıldı."},{"n":"3","t":"Herkes yazılmak için kendi kentine gitti."},{"n":"4","t":"Böylece Yusuf da, Davut'un soyundan ve torunlarından olduğu için Celile'nin Nasıra kentinden kalkıp Yahudiye bölgesine, Davut'un kenti olan Beytlehem'e gitti."},{"n":"5","t":"Orada, hamile olan nişanlısı Meryem'le birlikte yazılacaktı."},{"n":"6-7","t":"Onlar oradayken, Meryem'in doğum yapma vakti geldi ve ilk oğlunu doğurdu. Onu kundağa sarıp bir yemliğe yatırdı. Çünkü handa kendilerine yer yoktu."},{"n":"8","h":"Çobanlar ve melekler","t":"Aynı yörede, sürülerinin yanında nöbet tutarak geceyi kırlarda geçiren çobanlar vardı."},{"n":"9","t":"Rab'bin bir meleği onlara göründü ve Rab'bin görkemi çevrelerini aydınlattı. Büyük bir korkuya kapıldılar."},{"n":"10-11","t":"Melek ise onlara, \"Korkmayın!\" dedi. \"Size, tüm halk için büyük sevinç kaynağı olacak bir müjde getiriyorum: bugün size, Davut'un kentinde bir Kurtarıcı doğdu. Bu, Rab olan Mesih'tir."},{"n":"12","t":"Ve işte size bir işaret: kundağa sarılmış ve yemlikte yatan bir bebek bulacaksınız.\""},{"n":"13-14","t":"Birdenbire meleğin yanında, göksel ordulardan oluşan büyük bir topluluk belirdi. Tanrı'yı överek,\n\"En yücelerde Tanrı'ya yücelik olsun,\nyeryüzünde O'nun hoşnut kaldığı insanlara\nesenlik olsun!\" dediler."},{"n":"15","t":"Melekler yanlarından ayrılıp göğe çekildikten sonra çobanlar birbirlerine, \"Haydi, Beytlehem'e gidelim, Rab'bin bize bildirdiği bu olayı görelim\" dediler."},{"n":"16","t":"Aceleyle gidip Meryem'le Yusuf'u ve yemlikte yatan bebeği buldular."},{"n":"17","t":"Onları görünce, çocukla ilgili olarak kendilerine anlatılanları onlara bildirdiler."},{"n":"18","t":"Bunu duyanların hepsi, çobanların kendilerine söylediklerine şaşıp kaldılar."},{"n":"19","t":"Meryem isebütün bu sözleri derin derin düşünerek yüreğinde sakladı."},{"n":"20","t":"Çobanlar, işitip gördüklerinin tümü için Tanrı'yı yüceltip överek geri döndüler. Her şeyi, kendilerine anlatıldığı gibi bulmuşlardı."},{"n":"21","h":"İsa'nın tapınakta Tanrı'ya adanması","t":"Sekizinci gün, çocuğu sünnet etme zamanı gelince, kendisine İsa adı verildi. Bu, O'nun ana rahmine düşmesinden önce meleğin O'na vermiş olduğu isimdi."},{"n":"22","t":"Musa'nın Yasasına göre arınma günlerinin bitiminde Yusuf'la Meryem çocuğu Rab'be adamak için Kudüs'e götürdüler."},{"n":"23","t":"Nitekim Rab'bin Yasasında, \"İlk doğan her erkek çocuk Rab'be adanmış sayılacak\" diye yazılmıştır."},{"n":"24","t":"Ayrıca Rab'bin Yasasında buyrulduğu gibi, kurban olarak \"bir çift kumru ya da iki güvercin yavrusu\" sunacaklardı."},{"n":"25","t":"O sırada Kudüs'te Şimon adında bir adam vardı. Doğru ve dindar biri olan bu adam, İsrail'in teselli edileceği zamanı özlemle bekliyordu. Kutsal Ruh onun üzerindeydi."},{"n":"26","t":"Rab'bin Mesihini görmeden kendisinin ölmeyeceği ona Kutsal Ruh tarafından bildirilmişti."},{"n":"27-28","t":"Böylece Şimon, Ruh'un yönlendirmesiyle tapınağa geldi. Küçük İsa'nın annesi babası, Kutsal Yasa'nın ilgili kuralını yerine getirmek üzere O'nu içeri getirdiklerinde, Şimon O'nu kucağına aldı ve Tanrı'yı överek şöyle dedi:"},{"n":"29","t":"\"Ey Rabbim, vermiş olduğun sözü tuttun;\nkulun olan ben artık huzur içinde ölebilirim."},{"n":"30-32","t":"Çünkü senin sağladığın\nve tüm halkların gözü önünde hazırladığın kurtuluşu,\nulusları aydınlatıp\nhalkın İsrail'e yücelik kazandıracak ışığı\ngözlerimle gördüm.\""},{"n":"33","t":"İsa'nın annesiyle babası, O'nun hakkında söylenenlere şaştılar."},{"n":"34","t":"Şimon onları kutsayıp çocuğun annesi Meryem'e şöyle dedi: \"Bu çocuk, İsrail'de birçok kişinin düşmesine ya da yükselmesine yol açmak ve aleyhinde konuşulacak bir belirti olmak üzere belirlenmiştir."},{"n":"35","t":"Senin kalbine de âdeta bir kılıç saplanacak. Bütün bunlar, birçoklarının yüreğindeki düşüncelerin açığa çıkması için olacak.\""},{"n":"36-37","t":"Aşer oymağından Fanuel'in kızı Anna adında çok yaşlı bir kadın peygamber vardı. Genç kız olarak evlenip kocasıyla yedi yıl yaşadıktan sonra dul kalmıştı. Şimdi seksen dört yaşındaydı. Tapınaktan ayrılmıyor, oruç tutup dua ederek gece gündüz Tanrı'ya tapınıyordu."},{"n":"38","t":"Tam o sırada ortaya çıkan Anna, Tanrı'ya şükretti ve Kudüs'ün kurtuluşunu bekleyen herkese bu çocuktan söz etmeye başladı."},{"n":"39","t":"Yusuf'la Meryem, Rab'bin Yasasında öngörülen her şeyi yerine getirdikten sonra Celile'ye, kendi kentleri olan Nasıra'ya döndüler."},{"n":"40","t":"Çocuk büyüyor, güçleniyor ve bilgelikte yetkinleşiyordu. Tanrı'nın lütfu O'nun üzerindeydi."},{"n":"41","h":"İsa tapınakta","t":"İsa'nın annesi babası her yıl Fısıh bayramında Kudüs'e giderlerdi."},{"n":"42","t":"İsa on iki yaşına gelince, bayram geleneğine uyarak yine gittiler."},{"n":"43-44","t":"Bayramdan sonra eve dönerlerken küçük İsa Kudüs'te kaldı. Bunu farketmeyen annesi babası, çocuğun yol arkadaşlarıyla birlikte olduğunu sanarak bir günlük yol gittiler. Sonra O'nu akrabalar ve dostlar arasında aramaya başladılar."},{"n":"45","t":"Bulamayınca O'nu araya araya Kudüs'e döndüler."},{"n":"46","t":"Üç gün sonra O'nu tapınakta buldular. Din öğretmenleri arasında oturmuş, hem onları dinliyor, hem sorular soruyordu."},{"n":"47","t":"O'nu dinleyen herkes, zekâsına ve verdiği cevaplara hayran kaldı."},{"n":"48","t":"Annesi babası O'nu görünce şaşırdılar. Annesi O'na, \"Çocuğum, bize bunu niçin yaptın? Bak, babanla ben büyük kaygı içinde seni arayıp durduk\" dedi."},{"n":"49","t":"O da onlara, \"Beni niçin arayıp durdunuz?\" dedi. \"Babamın evinde bulunmam gerektiğini bilmiyor muydunuz?\""},{"n":"50","t":"Ne var ki onlar, bu sözle ne demek istediğini anlamadılar."},{"n":"51","t":"İsa onlarla birlikte yola çıkıp Nasıra'ya döndü. Onların sözünü dinlerdi. Annesi bütün bu olup bitenleri yüreğinde sakladı."},{"n":"52","t":"İsa bilgelikte ve boyda gelişiyor, Tanrı'nın ve insanların beğenisini kazanıyordu."}]},{"ch":3,"verses":[{"n":"1","t":"Sezar Tiberyus'un egemenliğinin on beşinci yılıydı. Yahudiye'de Pontiyus Pilatus'un valiliği sürüyordu. Celile'de Hirodes, İtureya ve Trahonitis bölgesinde Hirodes'in kardeşi Filipus, Abilini'de de Lisanyas yönetimin başındaydı."},{"n":"2","t":"Hanna ile Kayafa başkâhinlik ediyorlardı. Bu sırada Tanrı, sözünü çölde bulunan Zekeriya oğlu Yahya'ya duyurdu."},{"n":"3","t":"O da Şeria nehrinin çevresindeki tüm bölgeyi dolaşarak insanları, günahlarının bağışlanması için tövbe edip vaftiz olmaya çağırdı."},{"n":"4","t":"Nitekim Yeşaya peygamberin sözlerini içeren kitapta şöyle yazılmıştır:\n\"Çölde yükselen ses,\n'Rab'bin yolunu hazırlayın,\ngeçeceği patikaları düzleyin' diyor."},{"n":"5","t":"'Her dere doldurulacak,\nher dağ ve her tepe alçaltılacak.\nEğri yollar doğrultulacak,\nengebeli yollar düzleştirilecek."},{"n":"6","t":"Ve tüm insanlar\nTanrı'nın sağladığı kurtuluşu görecektir.'\""},{"n":"7","t":"Yahya, vaftiz olmak için kendisine akın eden kalabalıklara şöyle seslendi: \"Ey engerekler soyu! Gelecek olan gazaptan kaçmanız için sizi kim uyardı?"},{"n":"8","t":"Bundan böyle tövbeye yaraşır meyveler verin! Kendi kendinize, 'Biz İbrahim'in soyundanız' demeye kalkmayın. Ben size şunusöyleyeyim: Tanrı, İbrahim'e şu taşlardan çocuk yaratacak güçtedir."},{"n":"9","t":"Balta daha şimdiden ağaçların köküne dayanmıştır. İyi meyve vermeyen her ağaç kesilip ateşe atılacak.\""},{"n":"10","t":"Halk ona, \"Öyleyse biz ne yapalım?\" diye sordu."},{"n":"11","t":"Yahya onlara, \"İki mintanı olan, birini hiç mintanı olmayana versin; yiyeceği olan da bunu hiç yiyeceği olmayanla paylaşsın\" cevabını verdi."},{"n":"12","t":"Bazı vergi görevlileri de vaftiz olmaya gelerek ona, \"Öğretmenimiz, biz ne yapalım?\" dediler."},{"n":"13","t":"Yahya onlara, \"Size buyrulandan daha çok vergi almayın\" dedi."},{"n":"14","t":"Bazı askerler de ona, \"Ya biz ne yapalım?\" diye sordular.\nO da onlara şöyle dedi: \"Kaba kuvvetle ya da yalan suçlamalarla kimseden para koparmayın, ücretinizle yetinin.\""},{"n":"15","t":"Halk umut içinde bekliyordu. Yahya'yla ilgili olarak herkesin aklında, \"Acaba Mesih bu mu?\" sorusu vardı."},{"n":"16","t":"Yahya ise hepsine şöyle cevap verdi: \"Ben sizi suyla vaftiz ediyorum, ama benden daha güçlü Olan geliyor. Ben O'nun çarıklarının bağını çözmeye bile layık değilim. O sizi Kutsal Ruh'la ve ateşle vaftiz edecek."},{"n":"17","t":"Harman yerini temizlemek ve buğdayı toplayıp ambarına yığmak için yabası elinde hazır duruyor. Samanı ise sönmeyen ateşte yakacaktır.\""},{"n":"18","t":"Yahya daha başka birçok konuda halka çağrıda bulunuyor, Müjde'yi duyuruyordu."},{"n":"19-20","t":"Ne var ki bölgenin kralı Hirodes, kardeşinin karısı Hirodiya'yla ilgili olayı ve kendi yapmış olduğu bütün kötülükleri yüzüne vuran Yahya'yı hapse attırarak tüm kötülüklerine bir yenisini ekledi."},{"n":"21-22","h":"İsa'nın vaftiz olması","t":"Bütün halk vaftiz olduktan sonra İsa da vaftiz oldu. İsa dua ederken gök açıldı ve Kutsal Ruh, bedensel bir görünüm alarak güvercin biçiminde O'nun üzerine indi. Gökten gelen bir ses de, \"Sen benim sevgili Oğlumsun, senden hoşnudum\" dedi."},{"n":"23","h":"İsa'nın soyu","t":"İsa görevine başladığı zaman otuz yaşlarındaydı. Yusuf'un oğlu olarak biliniyordu.\nYusuf da Eli oğlu,"},{"n":"24","t":"Matat oğlu, Levi oğlu, Malki oğlu, Yanay oğlu, Yusuf oğlu,"},{"n":"25","t":"Matitya oğlu, Amos oğlu, Nahum oğlu, Hesli oğlu, Nagay oğlu,"},{"n":"26","t":"Mahat oğlu, Matitya oğlu, Şimi oğlu, Yoseh oğlu, Yoda oğlu,"},{"n":"27","t":"Yohanan oğlu, Reşa oğlu, Zerubabel oğlu, Şaltiyel oğlu, Neri oğlu,"},{"n":"28","t":"Malki oğlu, Addi oğlu, Kosam oğlu, Elmadam oğlu, Er oğlu,"},{"n":"29","t":"Yeşu oğlu, Eliyezer oğlu, Yorim oğlu, Matat oğlu, Levi oğlu,"},{"n":"30","t":"Şimon oğlu, Yahuda oğlu, Yusuf oğlu, Yonam oğlu, Elyakim oğlu,"},{"n":"31","t":"Mala oğlu, Menna oğlu, Matata oğlu, Natan oğlu, Davut oğlu,"},{"n":"32","t":"İşay oğlu, Obed oğlu, Boaz oğlu, Salmon oğlu, Nahşon oğlu,"},{"n":"33","t":"Aminadab oğlu, Ram oğlu, Hesron oğlu, Peres oğlu, Yahuda oğlu,"},{"n":"34","t":"Yakup oğlu, İshak oğlu, İbrahim oğlu, Terah oğlu, Nahor oğlu,"},{"n":"35","t":"Seruk oğlu, Reyu oğlu, Pelek oğlu, Eber oğlu, Şalah oğlu,"},{"n":"36","t":"Kenan oğlu, Arfakşat oğlu, Sam oğlu, Nuh oğlu, Lamek oğlu,"},{"n":"37","t":"Metuşelah oğlu, Hanok oğlu, Yaret oğlu, Mahalalel oğlu, Kenan oğlu,"},{"n":"38","t":"Enoş oğlu, Şit oğlu, Âdem oğlu, Tanrı Oğluydu."}]},{"ch":4,"verses":[{"n":"1-2","t":"Kutsal Ruh'la dolu olarak Şeria nehrinden dönen İsa, Ruh'un yönlendirmesiyle çölde dolaştırılarak kırk gün süreyle İblis tarafından sınandı. O günlerde hiçbir şey yemedi. Dolayısıyla bu sürenin sonunda acıktı."},{"n":"3","t":"Bunun üzerine İblis O'na, \"Tanrı'nın Oğluysan, şu taşa söyle de ekmek olsun\" dedi."},{"n":"4","t":"İsa ona şöyle karşılık verdi: \"'İnsan yalnız ekmekle yaşamaz' diye yazılmıştır.\""},{"n":"5","t":"Sonra İblis İsa'yı yükseklere çıkararak bir anda O'na dünyanın bütün ülkelerini gösterdi."},{"n":"6","t":"O'na, \"Tüm egemenlik ve görkemleriyle bunları sana vereceğim\" dedi. \"Bunlar bana teslim edildi, ben de dilediğim kişiye veririm."},{"n":"7","t":"Bana taparsan, hepsi senin olacak.\""},{"n":"8","t":"İsa ona şu karşılığı verdi: \"'Tanrın olan Rab'be tap, yalnız O'na kulluk et' diye yazılmıştır.\""},{"n":"9","t":"İblis O'nu Kudüs'e götürüp tapınağın tepesine çıkardı. \"Tanrı'nın Oğluysan, kendini buradan aşağı at\" dedi."},{"n":"10","t":"\"Çünkü şöyle yazılmıştır:\n'Tanrı, seni korumaları için\nmeleklerine buyruk verecek.'"},{"n":"11","t":"'Ayağın bir taşa çarpmasın diye\nseni elleri üzerinde taşıyacaklar.'\""},{"n":"12","t":"İsa ona şöyle karşılık verdi: \"'Tanrın olan Rab'bi sınama!' diye buyrulmuştur.\""},{"n":"13","t":"İblis, İsa'yı her bakımdan sınadıktan sonra bir süre için O'nun yanından ayrıldı."},{"n":"14","h":"İsa Celile'de","t":"İsa, Ruh'un gücüyle donanmış olarak Celile'ye döndü. Kendisiyle ilgili haber bütün bölgeye yayıldı."},{"n":"15","t":"Oranın havralarında ders veriyor ve herkes tarafından yüceltiliyordu."},{"n":"16-17","t":"İsa, büyümüş olduğu yer olan Nasıra'ya geldiğinde her zaman yaptığı gibi Sept günü havraya gitti. Kutsal Yazılardan okumak üzere ayağa kalkınca O'na Yeşaya peygamberin kitabı verildi. Kitabı açarakşu sözlerin yazılı olduğu yeri buldu:"},{"n":"18-19","t":"\"Rab'bin Ruhu benim üzerimdedir.\nÇünkü O beni, müjdeyi yoksullara iletmek için meshetti.\nTutsaklara serbest bırakılacaklarını,\nkörlere gözlerinin açılacağını duyurmak için,\nezilenleri özgürlüğe kavuşturmak\nve Rab'bin lütuf yılını ilan etmek için\nbeni gönderdi.\""},{"n":"20","t":"Sonra kitabı kapattı, görevliye geri verip oturdu. Havradakilerin hepsi gözlerini O'na dikmiş bakıyorlardı."},{"n":"21","t":"İsa söz alıp onlara, \"Dinlediğiniz bu Yazı bugün yerine gelmiştir\" dedi."},{"n":"22","t":"Herkes İsa'yı övüyor, ağzından çıkan lütufkâr sözlere hayran kalıyordu. \"Yusuf'un oğlu değil mi bu?\" diyorlardı."},{"n":"23","t":"İsa onlara şöyle dedi: \"Kuşkusuz bana şu deyimi hatırlatacaksınız: 'Ey hekim, önce kendini iyileştir! Kefernahum'da yaptıklarını duyduk. Aynısını burada, kendi memleketinde de yap.'\""},{"n":"24","t":"\"Size doğrusunu söyleyeyim\" diye devam etti İsa, \"hiçbir peygamber kendi memleketinde iyi karşılanmaz."},{"n":"25","t":"Yine size gerçeği söyleyeyim, gökyüzünün üç yıl altı ay kapalı kaldığı, tüm ülkede korkunç bir kıtlığın baş gösterdiği İlyas'ın zamanında İsrail'de çok sayıda dul kadın vardı."},{"n":"26","t":"İlyas bunlardan hiçbirine gönderilmediği halde, Sayda diyarının Sarafat kentinde bulunan dul bir kadına gönderildi."},{"n":"27","t":"Elişa peygamberin zamanında İsrail'de çok sayıda cüzamlı vardı. Bunlardan hiçbiri iyileştirilmediği halde, Suriyeli Naman iyileştirildi.\""},{"n":"28","t":"Havradakilerin hepsi, bu sözleri duyunca öfkeden kudurdular."},{"n":"29","t":"Ayağa kalkıp İsa'yı kentin dışına sürdüler. O'nu uçurumdan aşağı atmak için kentin kurulduğu tepenin yamacına götürdüler."},{"n":"30","t":"Ama İsa onların arasından geçerek oradan uzaklaştı."},{"n":"31","h":"İsa kötü bir ruhu kovuyor","t":"Sonra İsa Celile'nin Kefernahum kentine gitti. Sept günü halka ders veriyordu."},{"n":"32","t":"Yetkiyle konuştuğu için O'nun öğretişine şaşıp kaldılar."},{"n":"33-34","t":"Havrada cine tutsak, içinde kötü ruh olan bir adam vardı. Adam yüksek sesle, \"Ey Nasıralı İsa, bırak bizi! Bizden ne istiyorsun?\" diye bağırdı. \"Bizi mahvetmeye mi geldin? Senin kim olduğunu biliyorum, Tanrı'nın Kutsalısın sen!\""},{"n":"35","t":"İsa, \"Sus, çık o adamdan!\" diyerek cini azarladı. Cin, herkesin önünde adamı yere yıktıktan sonra, ona hiç zarar vermeden içinden çıktı."},{"n":"36","t":"Herkes şaşkına dönmüştü. Birbirlerine, \"Bu nasıl söz? Güç ve yetkiyle kötü ruhlara çıkmalarını buyuruyor, onlar da çıkıyorlar!\" diyorlardı."},{"n":"37","t":"Ve İsa'yla ilgili haber o bölgenin her yanında yankılandı."},{"n":"38","h":"İsa birçok hastayı iyileştiriyor","t":"İsa havradan ayrılarak Simun'un evine gitti. Simun'un yüksek ateşle hasta yatan kaynanasına yardım etmesi için O'na rica ettiler."},{"n":"39","t":"İsa kadının başucunda durup ateşi azarlayınca, ateş kadını bırakıverdi. Kadın hemen ayağa kalkıp onlara hizmet etmeye başladı."},{"n":"40","t":"Güneş batarken herkes, çeşitli hastalıklara tutulmuş olan yakınlarını İsa'ya getirdi. O da her birinin üzerine ellerini koyarak onları iyileştirdi."},{"n":"41","t":"Birçoğunun içinden de cinler, \"Sen Tanrı'nın Oğlusun!\" diye bağırarak çıkıyordu. Ne var ki, İsa onları azarladı, konuşmalarına izin vermedi. Çünkü kendisinin Mesih olduğunu biliyorlardı."},{"n":"42","t":"Sabah olunca İsa dışarı çıktı, ıssız bir yere gitti. Halk ise O'nu arıyordu. Bulunduğu yere geldiklerinde O'nu yanlarında alıkoymaya çalıştılar."},{"n":"43","t":"Ama İsa, \"Öbür kentlerde de Tanrı'nın Egemenliğiyle ilgili müjdeyi yaymam gerek\" dedi. \"Çünkü ben bunun için gönderildim.\""},{"n":"44","t":"Böylece Yahudiye'deki havralarda Tanrı sözünü duyurmaya devam etti."}]},{"ch":5,"verses":[{"n":"1","t":"Halk, Ginesar gölünün kıyısında duran İsa'nın çevresini sarmış, Tanrı'nın sözünü dinliyordu."},{"n":"2","t":"İsa, gölün kıyısında iki kayık gördü. Balıkçılar kayıklarından inmiş ağlarını yıkıyorlardı."},{"n":"3","t":"İki kayıktan Simun'a ait olanına binen İsa, ona kıyıdan biraz açılmasını rica etti. Sonra oturdu, kayığın içinden halka ders vermeye devam etti."},{"n":"4","t":"Konuşmasını bitirince Simun'a, \"Derin sulara açılın, balık tutmak için ağlarınızı salın\" dedi."},{"n":"5","t":"Simun şu karşılığı verdi: \"Efendimiz, bütün gece çabaladık, hiçbir şey tutamadık. Yine de senin sözün üzerine ağları salacağım.\""},{"n":"6","t":"Bunu yapınca öyle çok balık yakaladılar ki, ağları yırtılmaya başladı."},{"n":"7","t":"Öbür kayıktaki ortaklarına işaret vererek gelip yardım etmelerini istediler. Onlar da geldiler ve her iki kayığı balıkla doldurdular; öyle ki, kayıklar az kalsın batıyordu."},{"n":"8","t":"Simun Petrus bunu görünce, \"Rab, uzaklaş benden, ben günahlı bir adamım\" diyerek İsa'nın dizlerine kapandı."},{"n":"9","t":"Kendisi ve yanındakiler, tutmuş oldukları balıkların çokluğuna şaşıp kalmışlardı."},{"n":"10","t":"Simun'un ortakları olan Zebedi oğulları Yakup'la Yuhanna'yı da aynı şaşkınlık almıştı.\nİsa Simun'a, \"Korkma\" dedi, \"bundan böyle balık yerine insan tutacaksın.\""},{"n":"11","t":"Sonra onlar kayıkları karaya çektiler ve her şeyi bırakıp İsa'nın ardından gittiler."},{"n":"12","h":"İsa bir cüzamlıyı iyileştiriyor","t":"İsa kentlerden birindeyken, her yanını cüzam kaplamış bir adamlakarşılaştı. Adam İsa'yı görünce yüzüstü yere kapanıp O'na yalvardı: \"Rab, eğer istersen beni temiz kılabilirsin\" dedi."},{"n":"13","t":"İsa, elini uzatıp adama dokundu. \"İsterim, temiz ol!\" dedi. Adam hemen o anda cüzamdan kurtuldu."},{"n":"14","t":"İsa ona, bundan hiç kimseye söz etmemesini buyurdu. \"Git, kâhine görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musa'nın buyurduğu adakları sun\" dedi."},{"n":"15","t":"Ne var ki, İsa'yla ilgili haber daha da çok yayıldı. Kalabalık halk toplulukları İsa'yı dinlemek ve hastalıklarından kurtulmak amacıyla akın akın geliyordu."},{"n":"16","t":"Kendisi ise ıssız yerlere çekiliyor, dua ediyordu."},{"n":"17","h":"Bir felçlinin iyileştirilmesi","t":"Bir gün İsa ders veriyordu. Celile'nin ve Yahudiye'nin bütün köylerinden ve Kudüs'ten gelmiş olan Ferisilerle Kutsal Yasa öğretmenleri O'nun çevresinde oturuyorlardı. İsa, Rab'bin gücü sayesinde hastaları iyileştiriyordu."},{"n":"18","t":"O sırada birkaç kişi, şilte üzerinde taşıdıkları felçli bir adamı evden içeri sokup İsa'nın önüne koymaya çalışıyorlardı."},{"n":"19","t":"Kalabalıktan ötürü onu içeri sokacak yol bulamayınca dama çıktılar, kiremitleri kaldırıp adamı şilteyle birlikte ortaya, İsa'nın önüne indirdiler."},{"n":"20","t":"Onların imanını gören İsa, \"Dostum, günahların bağışlandı\" dedi."},{"n":"21","t":"Din bilginleriyle Ferisiler, \"Tanrı'ya küfreden bu adam kim? Tek Tanrı'dan başka kim günahları bağışlayabilir?\" diye düşünmeye başladılar."},{"n":"22","t":"Akıllarından geçenleri sezen İsa onlara şöyle seslendi: \"Aklınızdan neden böyle şeyler geçiriyorsunuz?"},{"n":"23","t":"Hangisi daha kolay, 'Günahların bağışlandı' demek mi, yoksa 'Kalk, yürü' demek mi?"},{"n":"24","t":"Ne var ki, İnsanoğlu'nun yeryüzünde günahları bağışlama yetkisine sahip olduğunu bilesiniz diye…\" Sonra felçli adama, \"Sana söylüyorum, kalk, şilteni toplayıp evine git!\" dedi."},{"n":"25","t":"Adam onların gözü önünde hemen ayağa kalktı, üzerinde yattığı şilteyi topladı ve Tanrı'yı yücelterek evine gitti."},{"n":"26","t":"Herkesi bir şaşkınlık almıştı. Tanrı'yı yüceltiyor, büyük korku içinde, \"Bugün şaşılacak işler gördük!\" diyorlardı."},{"n":"27","h":"Levi'nin öğrencilere katılması","t":"Bu olaydan sonra İsa dışarı çıktı, vergi toplama kulübesinde oturan Levi adında bir vergi görevlisini gördü. Adama, \"Ardımdan gel\" dedi."},{"n":"28","t":"O da kalktı, her şeyi bırakıp İsa'nın ardından gitti."},{"n":"29","t":"Sonra Levi, evinde İsa'nın onuruna büyük bir şölen verdi. Vergi görevlileri ve daha başka kişilerden oluşan büyük bir kalabalık onlarla birlikte yemeğe oturmuştu."},{"n":"30","t":"Ferisilerle onların din bilginleri söylenmeye başladılar. İsa'nın öğrencilerine, \"Siz neden vergi görevlileri ve günahkârlarla birlikte yiyip içiyorsunuz?\" dediler."},{"n":"31","t":"İsa onlara şu karşılığı verdi: \"Sağlıklı olanların değil,hastaların hekime ihtiyacı var."},{"n":"32","t":"Ben doğru kişileri değil, günahkârları tövbeye çağırmaya geldim.\""},{"n":"33","h":"Oruçla ilgili soru","t":"Onlar İsa'ya, \"Yahya'nın öğrencileri sık sık oruç tutup dua ediyorlar, Ferisilerin öğrencileri de öyle. Seninkiler ise yiyip içiyorlar\" dediler."},{"n":"34","t":"İsa şöyle karşılık verdi: \"Güvey aralarında olduğu sürece davetlilere hiç oruç tutturabilir misiniz?"},{"n":"35","t":"Ama güveyin aralarından alınacağı günler gelecek, onlar işte o zaman, o günler oruç tutacaklar.\""},{"n":"36","t":"İsa onlara şu benzetmeyi de anlattı: \"Hiç kimse yeni giysiden bir parça yırtıp eski giysiyi yamamaz. Yoksa hem yeni giysi yırtılmış olur, hem de o giysiden koparılan yama eskisine uymaz."},{"n":"37","t":"Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa yeni şarap tulumları patlatır; hem şarap dökülür, hem de tulumlar mahvolur."},{"n":"38","t":"Yeni şarabı yeni tulumlara doldurmak gerek."},{"n":"39","t":"Üstelik hiç kimse eski şarabı içtikten sonra yenisini istemez. 'Eskisi güzel' der.\""}]},{"ch":6,"verses":[{"n":"1","t":"Bir Sept günü İsa ekinler arasından geçiyordu. Öğrencileri başakları koparıyor, avuçları içinde ufalayıp yiyorlardı."},{"n":"2","t":"Ferisilerden bazıları, \"Sept günü yapılması yasak olanı neden yapıyorsunuz?\" dediler."},{"n":"3","t":"İsa onlara şöyle karşılık verdi: \"Davut'un, kendisi ve yanındakiler acıkınca ne yaptığını okumadınız mı?"},{"n":"4","t":"Tanrı'nın evine girdi, kâhinlerden başkasının yemesi yasak olan adak ekmeklerini alıp yedi ve yanındakilere de verdi.\""},{"n":"5","t":"Sonra İsa onlara, \"İnsanoğlu Sept gününün de Rabbidir\" dedi."},{"n":"6","t":"Bir başka Sept günü İsa havraya girmiş ders veriyordu. Orada sağ eli sakat bir adam vardı."},{"n":"7","t":"İsa'yı suçlamak için fırsat kollayan din bilginleriyle Ferisiler, Sept günü hastaları iyileştirecek mi diye O'nu gözlüyorlardı."},{"n":"8","t":"İsa, onların ne düşündüklerini biliyordu. Eli sakat olan adama, \"Ayağa kalk, ortaya çık\" dedi. O da kalktı, orta yerde durdu."},{"n":"9","t":"İsa onlara, \"Size sorayım\" dedi, \"Kutsal Yasa'ya göre Sept günü iyilik yapmak mı doğru, kötülük yapmak mı? Can kurtarmak mı doğru, öldürmek mi?\""},{"n":"10","t":"Gözlerini hepsinin üzerinde gezdirdikten sonra adama, \"Elini uzat\" dedi. Adam elini uzattı, eli eskisi gibi sağlam oluverdi."},{"n":"11","t":"Onlar ise öfkeden deliye döndüler ve aralarında İsa'ya ne yapabileceklerini tartışmaya başladılar."},{"n":"12","h":"İsa on iki elçisini seçiyor","t":"O günlerde İsa, dua etmek için dağa çıktı ve bütün geceyi Tanrı'ya dua ederek geçirdi."},{"n":"13-16","t":"Gün doğunca öğrencilerini yanına çağırdı ve onların arasından, 'elçi' diye adlandırdığı şu on iki kişiyi seçti: Petrus adını verdiği Simun, onun kardeşi Andreya, Yakup, Yuhanna, Filipus, Bartalmay, Matta, Tomas, Alfay oğlu Yakup, Yurtsever diye tanınan Simun, Yakup oğlu Yahuda ve sonradan İsa'yı ele veren Yahuda İskariyot."},{"n":"17","t":"İsa bunlarla birlikte aşağı inip düzlük bir yerde durdu. Öğrencilerinden büyük bir kalabalık ve tüm Yahudiye'den, Kudüs'ten, Sur'la Sayda yakınlarındaki kıyı bölgesinden gelen büyük bir halk topluluğu da oradaydı."},{"n":"18","t":"İsa'yı dinlemek ve hastalıklarından şifa bulmak amacıyla gelmişlerdi. Kötü ruhlardan sıkıntı çekenler de iyileştiriliyordu."},{"n":"19","t":"Kalabalıkta herkes İsa'ya dokunmak için çabalıyordu. Çünkü O'nun içinden akan bir güç herkese şifa veriyordu."},{"n":"20","h":"Mutlular ve mutsuzlar","t":"İsa, gözlerini öğrencilerine çevirerek şöyle dedi:\n\"Ey yoksul olanlar, ne mutlu size,\nTanrı'nın Egemenliği sizindir!"},{"n":"21","t":"Şimdi açlık çekenler, ne mutlu size,\nsiz doyurulacaksınız!\nŞimdi ağlayanlar, ne mutlu size,\nsiz güleceksiniz!"},{"n":"22","t":"İnsanoğlu'na olan bağlılığınızdan ötürü\ninsanlar sizden nefret ettikleri,\nsizi toplum dışı edip aşağıladıkları\nve adınızı kötüleyip sizi reddettikleri zaman\nsize ne mutlu!"},{"n":"23","t":"O gün sevinin, coşkuyla zıplayın!\nÇünkü gökteki ödülünüz büyüktür.\nNitekim onların ataları da\npeygamberlere böyle davrandılar."},{"n":"24","t":"Ama vay halinize, ey zenginler,\ntesellinizi almış bulunuyorsunuz!"},{"n":"25","t":"Şimdi karnı tok olan sizler, vay halinize,\naçlık çekeceksiniz!\nEy şimdi gülenler, vay halinize,\nyas tutup ağlayacaksınız!"},{"n":"26","t":"Tüm insanlar sizin için iyi sözler söyledikleri zaman,\nvay halinize!\nÇünkü onların ataları da\nsahte peygamberlere böyle davrandılar.\""},{"n":"27-28","h":"Düşmanlarınızı sevin","t":"\"Ama beni dinleyen sizlere şunu söylüyorum: düşmanlarınızı sevin, sizden nefret edenlere iyilik yapın, size lanet edenler için iyilik dileyin, size hakaret edenler için dua edin."},{"n":"29","t":"Bir yanağınıza tokat atana öbür yanağınızı da çevirin. Abanızı alandan mintanınızı da esirgemeyin."},{"n":"30","t":"Sizden bir şey dileyen herkese verin, malınızı alandan onu geri istemeyin."},{"n":"31","t":"İnsanların size nasıl davranmasını istiyorsanız, siz de onlara öyle davranın."},{"n":"32","t":"\"Eğer yalnız sizi sevenleri severseniz, bu size ne övgü kazandırır? Günahkârlar bile kendilerini sevenleri sever."},{"n":"33","t":"Size iyilik yapanlara iyilik yaparsanız, bu size ne övgü kazandırır? Günahkârlar bile böyle yapar."},{"n":"34","t":"Verdiğinizi geri almak umudunda olduğunuz kişilere ödünç verirseniz, bu size ne övgü kazandırır? Günahkârlar bile verdikleri kadarını geri almak koşuluyla günahkârlara ödünç verirler."},{"n":"35","t":"Ama siz düşmanlarınızı sevin, iyilik yapın, hiçbir karşılık beklemeden ödünç verin. Alacağınız ödül büyük olacak, en yüce Olan'ın oğulları olacaksınız. Çünkü O, nankör ve kötü kişilere karşı iyi yüreklidir."},{"n":"36","t":"Babanız merhametli olduğu gibi, siz de merhametli olun."},{"n":"37","h":"Başkasını yargılamayın","t":"\"Başkasını yargılamayın, siz de yargılanmazsınız. Suçlu çıkarmayın, siz de suçlu çıkarılmazsınız. Başkasını bağışlayın, siz de bağışlanırsınız."},{"n":"38","t":"Sizde olanı verin, size verilecek. İyice bastırılmış, silkelenmiş ve taşmış, dolu bir ölçekle kucağınıza boşaltılacak. Hangi ölçekle ölçerseniz, size de aynı ölçek uygulanacak.\""},{"n":"39","t":"İsa onlara şu benzetmeyi de anlattı: \"Kör köre kılavuzluk edebilir mi? Her ikisi de çukura düşmez mi?"},{"n":"40","t":"Öğrenci öğretmeninden üstün değildir, ama eğitimini tamamlayan her öğrenci öğretmeni gibi olacaktır."},{"n":"41","t":"\"Sen neden kardeşinin gözündeki çöpü görürsün de kendi gözündeki merteği farketmezsin?"},{"n":"42","t":"Kendi gözündeki merteği görmezken, nasıl olur da kardeşine, 'Kardeş, izin ver de gözündeki çöpü çıkarayım' dersin? Seni ikiyüzlü! Önce kendi gözündeki merteği çıkar, o zaman kardeşinin gözündeki çöpü çıkarmak için daha iyi görürsün."},{"n":"43","h":"Ağaç ve meyvesi","t":"\"İyi ağaç kötü meyve vermez. Kötü ağaç da iyi meyve vermez."},{"n":"44","t":"Her ağaç meyvesinden tanınır. Dikenli bitkilerden incir toplanmaz, çalılardan üzüm devşirilmez."},{"n":"45","t":"İyi insan, yüreğindeki iyilik hazinesinden iyilik, kötü insan ise içindeki kötülük hazinesinden kötülük çıkarır. İnsanın ağzı, yüreğinden taşanı söyler."},{"n":"46","t":"\"Niçin beni 'Rab, Rab' diye çağırıyorsunuz da söylediklerimi yapmıyorsunuz?"},{"n":"47","t":"Bana gelen ve sözlerimi duyup uygulayan kişinin kime benzediğini size anlatayım."},{"n":"48","t":"Böyle bir kişi, evini yaparken toprağı kazan, derinlere inip temeli kaya üzerine atan adama benzer. Selsularıyla kabaran ırmak o eve saldırmışsa da, onu sarsamamış. Çünkü ev sağlam yapılmış."},{"n":"49","t":"Ama sözlerimi duyup da uygulamayan kişi, temel koymaksızın evini toprağın üzerinde kuran adama benzer. Kabaran ırmak saldırınca ev hemen çökmüş. Evin yıkılışı da korkunç olmuş.\""}]},{"ch":7,"verses":[{"n":"1","t":"İsa, kendisini dinleyen halka bütün bu sözleri söyledikten sonra Kefernahum'a gitti."},{"n":"2","t":"Orada bir yüzbaşının çok değer verdiği kölesi ölüm döşeğinde hasta yatıyordu."},{"n":"3","t":"İsa'yla ilgili haberleri duyan yüzbaşı, gelip kölesini iyileştirmesini rica etmek üzere O'na Yahudilerin bazı ihtiyarlarını gönderdi."},{"n":"4","t":"Bunlar İsa'nın yanına gelince içten bir yalvarışla O'na şöyle dediler: \"Bu adam senin yardımına layıktır."},{"n":"5","t":"Çünkü ulusumuzu seviyor. Havramızı yaptıran da kendisidir.\""},{"n":"6","t":"İsa onlarla birlikte yola çıktı. Eve yaklaştığı sırada, yüzbaşı bazı dostlarını yollayıp O'na şu haberi gönderdi: \"Rab, zahmet etme; ben layık değilim ki, çatımın altına giresin."},{"n":"7","t":"Nitekim senin yanına gelmeye de kendimi layık görmedim. Sen yeter ki bir söz söyle, uşağım iyileşir."},{"n":"8","t":"Ben de buyruk altında bir görevliyim, benim de buyruğumda askerlerim var. Birine, 'Git' derim, gider; bir diğerine, 'Gel' derim, gelir; köleme, 'Şunu yap' derim, yapar.\""},{"n":"9","t":"Bu sözleri duyan İsa yüzbaşıya hayran kaldı. Ardından gelen kalabalığa dönerek, \"Size şunu söyleyeyim\" dedi, \"İsrail'de bile böyle iman görmedim.\""},{"n":"10","t":"Ve gönderilenler eve döndüklerinde köleyi iyileşmiş buldular."},{"n":"11","h":"İsa bir dulun oğlunu diriltiyor","t":"Bundan kısa bir süre sonra İsa, Nain denilen bir kente gitti. Öğrencileri ve büyük bir kalabalık da O'nunla birlikte gidiyordu."},{"n":"12","t":"İsa kentin kapısına tam yaklaştığı sırada, dul anasının tek oğlu olan bir adamın cenazesi kaldırılıyordu. Kent halkından büyük bir kalabalık da kadınla birlikteydi."},{"n":"13","t":"Rab kadını görünce ona acıdı. Kadına, \"Ağlama\" dedi."},{"n":"14","t":"Yaklaşıp cenaze sedyesine dokundu, sedyeyi taşıyanlar da durdular. İsa, \"Delikanlı\" dedi, \"sana kalk diyorum!\""},{"n":"15","t":"Ölü doğrulup oturdu ve konuşmaya başladı. İsa onu annesine geri verdi."},{"n":"16","t":"Herkesi bir korku almıştı. \"Aramızda büyük bir peygamber ortaya çıktı!\" ve \"Tanrı, halkının yardımına geldi!\" diyerek Tanrı'yı yüceltmeye başladılar."},{"n":"17","t":"İsa'yla ilgili bu haber bütün Yahudiye'ye ve çevre bölgelere yayıldı."},{"n":"18-19","h":"İsa ve Vaftizci Yahya","t":"Yahya'nın öğrencileri, bütün bu olup bitenleri kendisine bildirdiler. Öğrencilerinden ikisini yanına çağıran Yahya, \"Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?\" diye sormaları için onları Rab'be gönderdi."},{"n":"20","t":"Adamlar İsa'nın yanına gelince şöyle dediler: \"Bizi sana Vaftizci Yahya gönderdi. 'Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?' diye soruyor.\""},{"n":"21","t":"Tam o sırada İsa, çeşitli hastalıklara, illetlere ve kötü ruhlara tutulmuş birçok kişiyi iyileştirdi, kör olan birçok kişinin gözlerini açtı."},{"n":"22","t":"Sonra Yahya'nın öğrencilerine şöyle karşılık verdi: \"Gidin, görüp işittiklerinizi Yahya'ya bildirin. Körlerin gözleri açılıyor, kötürümler yürüyor, cüzamlılar temiz kılınıyor, sağırlar işitiyor, ölüler diriliyor ve Müjde yoksullara duyuruluyor."},{"n":"23","t":"Benden ötürü sendeleyip düşmeyene ne mutlu!\""},{"n":"24","t":"Yahya'nın gönderdiği haberciler gittikten sonra İsa, halka Yahya'dan söz etmeye başladı. \"Çöle ne görmeye gittiniz?\" dedi. \"Rüzgârda sallanan bir kamış mı?"},{"n":"25","t":"Söyleyin, ne görmeye gittiniz? Zarif giysilere bürünmüş bir adam mı? Oysa görkemli giysiler giyip bolluk içinde yaşayanlar kralların saraylarında bulunur."},{"n":"26","t":"Öyleyse ne görmeye gittiniz? Bir peygamber mi? Evet! Ve size şunu söyleyeyim, gördüğünüz kişi peygamberden de üstündür."},{"n":"27","t":"'Bak, habercimi senin önünden gönderiyorum;\no önden gidip senin yolunu hazırlayacak'\ndiye yazılmış olan sözler onunla ilgilidir."},{"n":"28","t":"Size şunu söyleyeyim, kadından doğanlar arasında Yahya'dan daha üstün olanı yoktur. Bununla birlikte Tanrı'nın Egemenliğinde en küçük olan, ondan üstündür.\""},{"n":"29","t":"Yahya tarafından vaftiz edilmiş olan bütün halk, hatta vergi görevlileri bile bunu duyunca Tanrı'nın adil olduğunu doğruladılar."},{"n":"30","t":"Oysa Yahya tarafından vaftiz edilmeye yanaşmamış olan Ferisilerle Kutsal Yasa uzmanları, Tanrı'nın kendileriyle ilgili tasarısını reddettiler."},{"n":"31","t":"İsa, \"Ben bu kuşağın insanlarını neye benzeteyim? Bunlar neye benziyorlar?\" dedi."},{"n":"32","t":"\"Çarşı meydanında oturup birbirlerine,\n'Size kaval çaldık, oynamadınız;\nağıt yaktık, ağlamadınız'\ndiye seslenen çocuklara benziyorlar."},{"n":"33","t":"Vaftizci Yahya geldiği zaman oruç tutup şaraptan kaçındı, ona 'cinli' diyorsunuz."},{"n":"34","t":"İnsanoğlu geldiği zaman hem yedi, hem içti. Bu kez de diyorsunuz ki, 'Şu obur ve ayyaş adama bakın! Vergi görevlileri ve günahkârlarla dost oldu!'"},{"n":"35","t":"Ne var ki bilgelik, onu benimseyen herkes tarafından doğrulanır.\""},{"n":"36","h":"İsa ve günahkâr kadın","t":"Ferisilerden biri İsa'yı yemeğe çağırdı. O da Ferisi'nin evine gidip sofraya oturdu."},{"n":"37-38","t":"O sırada, kentte günahkâr olarak tanınan bir kadın, İsa'nın Ferisi'nin evinde yemek yediğini öğrenincekaymaktaşından bir kap içinde hoş kokulu yağ getirdi. İsa'nın arkasında, ayaklarının dibinde durup ağlayarak, gözyaşlarıyla O'nun ayaklarını ıslatmaya başladı. Saçlarıyla ayaklarını sildi, öptü ve yağı üzerlerine sürdü."},{"n":"39","t":"İsa'yı evine çağırmış olan Ferisi bunu görünce kendi kendine, \"Bu adam peygamber olsaydı, kendisine dokunan bu kadının kim ve ne tür bir kadın olduğunu, günahkâr biri olduğunu anlardı\" dedi."},{"n":"40","t":"O zaman İsa söz alıp ona, \"Simun\" dedi, \"sana bir söyleyeceğim var.\"\nO da, \"Buyur, öğretmenim\" dedi."},{"n":"41","t":"\"İki kişinin bir alacaklıya borcu varmış. Biri beş yüz, öbürü de elli dinar borçluymuş."},{"n":"42","t":"Borçlarını ödeyecek durumda olmadıklarından, alacaklı her ikisinin de borcunu bağışlamış. Buna göre, hangisi onu daha çok sevecek?\""},{"n":"43","t":"Simun, \"Sanırım, kendisine daha çok bağışlanan\" diye cevap verdi.\nİsa ona, \"Doğru söyledin\" dedi."},{"n":"44","t":"Sonra kadına dönerek Simun'a şunları söyledi: \"Bu kadını görüyor musun? Ben senin evine geldim, ayaklarım için bana su vermedin. Bu kadın ise ayaklarımı gözyaşlarıyla ıslatıp saçlarıyla sildi."},{"n":"45","t":"Sen beni öpmedin, ama bu kadın eve girdiğimden beri ayaklarımı öpüp duruyor."},{"n":"46","t":"Sen başıma zeytinyağı sürmedin, ama bu kadın ayaklarıma hoş kokulu bir yağ sürdü."},{"n":"47","t":"Bu nedenle sana şunu söyleyeyim, kendisinin çok olan günahları bağışlanmıştır. Çok sevgi göstermesinin nedeni budur. Oysa kendisine az bağışlanan, az sever.\""},{"n":"48","t":"Sonra kadına, \"Günahların bağışlandı\" dedi."},{"n":"49","t":"İsa'yla birlikte sofrada oturanlar kendi aralarında, \"Günahları bile bağışlayan bu adam kim?\" şeklinde konuşmaya başladılar."},{"n":"50","t":"İsa ise kadına, \"İmanın seni kurtardı, esenlikle git\" dedi."}]},{"ch":8,"verses":[{"n":"1","t":"Bundan kısa bir süre sonra İsa, on iki öğrencisiyle birlikte köy kent dolaşmaya başladı. Tanrı'nın Egemenliğini duyurup müjdeliyordu."},{"n":"2-3","t":"Kötü ruhlardan ve hastalıklardan kurtulmuş olan bazı kadınlar, içinden yedi cin çıkmış olan Mecdelli denilen Meryem, Hirodes'in kâhyası Kuza'nın karısı Yohana, Suzana ve daha birçokları İsa'yla birlikte dolaşıyordu. Bunlar, kendi olanaklarıyla İsa'ya ve öğrencilerine yardım ediyorlardı."},{"n":"4-5","h":"Tohum benzetmesi","t":"Büyük bir kalabalığın toplandığı, insanların her kentten kendisine akın akın geldiği bir sırada İsa şu benzetmeyi anlattı: \"Ekincinin biri tohum ekmeye çıkmış. Ektiği tohumlardan kimi yol kenarına düşmüş, ayak altında çiğnenip gökteki kuşlara yem olmuş."},{"n":"6","t":"Kimi kayalık yere düşmüş, filizlenince susuzluktan kuruyup gitmiş."},{"n":"7","t":"Kimi, dikenler arasına düşmüş. Filizlerle birlikte büyüyen dikenler filizleri boğmuş."},{"n":"8","t":"Kimi ise iyi toprağa düşmüş, büyüyünce yüz kat ürün vermiş.\" Bunları söyledikten sonra, \"İşitecek kulağı olan işitsin!\" diye seslendi."},{"n":"9-10","t":"İsa, bu benzetmenin anlamını kendisinden soran öğrencilerine, \"Tanrı Egemenliğinin sırlarını anlama yeteneği size verildi\" dedi. \"Ama başkalarına benzetmelerle sesleniyorum. Öyle ki,\n'Gördükleri halde görmesinler,\nduydukları halde anlamasınlar.'"},{"n":"11","t":"\"Benzetmenin anlamı şudur: tohum Tanrı'nın sözüdür."},{"n":"12","t":"Yol kenarındakiler sözü işiten kişilerdir. Ama sonra İblis gelir, inanıp kurtulmasınlar diye sözü yüreklerinden alır götürür."},{"n":"13","t":"Kayalık yere düşenler, işittikleri sözü sevinçle kabul eden, ama kök salamadıkları için ancak bir süre inanan kişilerdir. Böyleleri sınandıkları zaman imandan dönerler."},{"n":"14","t":"Dikenler arasına düşenler, sözü işiten ama zamanla yaşamın kaygıları, zenginlikleri ve zevkleri içinde boğulan, dolayısıyla olgun ürün vermeyenlerdir."},{"n":"15","t":"İyi toprağa düşenler ise, sözü işitince onu iyi ve sağlam bir yürekte saklayanlardır. Bunlar sabırla dayanarak ürün verirler."},{"n":"16","h":"Her şey ışığa çıkacak","t":"\"Hiç kimse kandil yakıp bunu bir kapla örtmez, ya da yatağın altına koymaz. Tersine, içeri girenler ışığı görsünler diye onu kandilliğe koyar."},{"n":"17","t":"Çünkü açığa çıkarılmayacak gizli hiçbir şey yok; bilinmeyecek, aydınlığa çıkmayacak saklı hiçbir şey yoktur."},{"n":"18","t":"Bunun için, nasıl dinlediğinize dikkat edin. Kimde varsa, ona daha çok verilecek. Ama kimde yoksa, kendisinde var sandığı bile elinden alınacak.\""},{"n":"19","h":"İsa'nın yakınları","t":"İsa'nın annesiyle kardeşleri O'na geldiler, ama kalabalıktan ötürü yanına yaklaşamadılar."},{"n":"20","t":"İsa'ya, \"Annenle kardeşlerin dışarıda duruyor, seni görmek istiyorlar\" diye haber verildi."},{"n":"21","t":"İsa haberi getirenlere şöyle karşılık verdi: \"Annemle kardeşlerim, Tanrı'nın sözünü işiten ve uygulayanlardır.\""},{"n":"22","h":"İsa fırtınayı dindiriyor","t":"Bir gün İsa öğrencileriyle birlikte bir kayığa binerek onlara, \"Gölün karşı yakasına geçelim\" dedi. Böylece kıyıdan açıldılar."},{"n":"23","t":"Kayıkta giderlerken İsa uykuya daldı. O sırada gölde bir fırtına koptu. Kayık su almaya başlayınca tehlikeli bir duruma düştüler."},{"n":"24","t":"Gidip İsa'yı uyandırarak, \"Efendimiz, Efendimiz, batıyoruz!\"dediler. İsa kalkıp rüzgârı ve kabaran dalgaları azarladı. Fırtına dindi ve ortalık sütliman oldu."},{"n":"25","t":"İsa öğrencilerine, \"Nerede imanınız?\" dedi.\nOnlar korku ve şaşkınlık içindeydiler. Birbirlerine, \"Bu adam kim ki, rüzgâra ve suya bile buyruk veriyor, onlar da sözünü dinliyor!\" dediler."},{"n":"26","h":"Cinli bir adamın iyileştirilmesi","t":"Celile'nin karşısında bulunan Gerasalıların memleketine vardılar."},{"n":"27","t":"İsa karaya çıkınca kentten bir adam O'nu karşıladı. Cinlere tutsak olan ve uzun zamandan beri giysi giymeyen bu adam evde değil, mezarlık mağaralarda yaşıyordu."},{"n":"28","t":"Adam İsa'yı görünce bir çığlık atıp O'nun önünde yere kapandı. Yüksek sesle, \"Ey İsa, yüce Tanrı'nın Oğlu, benden ne istiyorsun?\" dedi. \"Sana yalvarırım, bana işkence etme!\""},{"n":"29","t":"Çünkü İsa, kötü ruha adamın içinden çıkmasını buyurmuştu. Kötü ruh adamı sık sık etkisi altına alıyordu. Adam zincirler ve kösteklerle bağlanıp başına nöbetçi konulduğu halde bağlarını paralıyor ve cin tarafından ıssız yerlere sürülüyordu."},{"n":"30","t":"İsa ona, \"Adın ne?\" diye sordu.\nO da, \"Tümen\" cevabını verdi. Çünkü onun içine bir sürü cin girmişti."},{"n":"31","t":"Bunlar, dipsiz derinliklere gitmelerini buyurmasın diye İsa'ya yalvarıp durdular."},{"n":"32","t":"Orada, dağın yamacında otlayan büyük bir domuz sürüsü vardı. Cinler, domuzların içine girmelerine izin vermesi için İsa'ya yalvardılar. O da onlara izin verdi."},{"n":"33","t":"Adamdan çıkan cinler domuzların içine girdiler. Sürü dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu."},{"n":"34","t":"Domuzları güdenler olup biteni görünce kaçtılar, kentte ve köylerde olayın haberini yaydılar."},{"n":"35","t":"Bunun üzerine halk olup biteni görmeye çıktı. İsa'nın yanına geldikleri zaman, cinlerden kurtulan adamı giyinmiş ve aklı başına gelmiş olarak İsa'nın ayakları dibinde oturmuş buldular ve korktular."},{"n":"36","t":"Olayı görenler, cinlere tutsak olan adamın nasıl kurtulduğunu halka anlattılar."},{"n":"37","t":"O zaman Gerasa yöresinden gelmiş olan tüm kalabalık büyük bir korkuya kapılarak İsa'nın yanlarından ayrılmasını rica ettiler. O da geri dönmek üzere kayığa bindi."},{"n":"38-39","t":"Cinlerden kurtulan adam İsa'nın yanında kalmak için O'na yalvardı. Ama İsa, \"Evine dön, Tanrı'nın senin için neler yaptığını anlat\" diyerek onu salıverdi. Adam da gitti, İsa'nın kendisi için neler yaptığını bütün kentte duyurdu."},{"n":"40","h":"Dirilen kız, iyileşen kadın","t":"Karşı yakaya dönen İsa'yı halk sevinçle karşıladı. Çünkü herkes O'nu bekliyordu."},{"n":"41","t":"O sırada, havra yöneticisi olan Yair adında bir adam gelip İsa'nın ayaklarına kapandı, evine gelmesi için yalvardı."},{"n":"42","t":"Çünkü on iki yaşlarında olan biricik kızı ölmek üzereydi.\nİsa oraya giderken kalabalık O'nu her yandan sıkıştırıyordu."},{"n":"43","t":"On iki yıldır kanaması olan bir kadın da oradaydı. Varını yoğunu hekimlere harcamıştı; ama hiçbiri onu iyileştirememişti."},{"n":"44","t":"İsa'nın arkasından yetişip giysisinin eteğine dokundu ve o anda kanaması kesildi."},{"n":"45","t":"İsa, \"Bana kim dokundu?\" dedi.\nHerkes inkâr ederken Petrus, \"Efendimiz, kalabalık seni çepeçevre sarmış sıkıştırıyor\" dedi."},{"n":"46","t":"Ama İsa, \"Birisi bana dokundu\" dedi. \"İçimden bir gücün akıp gittiğini hissettim.\""},{"n":"47","t":"Yaptığını gizleyemeyeceğini anlayan kadın titreyerek geldi, İsa'nın ayaklarına kapandı. Bütün halkın önünde, O'na neden dokunduğunu ve o anda nasıl iyileştiğini anlattı."},{"n":"48","t":"İsa ona, \"Kızım\" dedi, \"imanın seni kurtardı. Esenlikle git.\""},{"n":"49","t":"İsa daha konuşurken havra yöneticisinin evinden biri geldi. Yöneticiye, \"Kızın öldü\" dedi, \"artık öğretmeni rahatsız etme.\""},{"n":"50","t":"İsa bunu duyunca havra yöneticisine şöyle dedi: \"Korkma, sadece iman et, kızın kurtulacak.\""},{"n":"51","t":"İsa eve gelince Petrus, Yuhanna, Yakup ve kızın annesi babası dışında hiç kimsenin kendisiyle birlikte içeri girmesine izin vermedi."},{"n":"52","t":"Herkes kız için ağlıyor, dövünüyordu. İsa, \"Ağlamayın\" dedi, \"kız ölmedi, sadece uyuyor.\""},{"n":"53","t":"Kızın öldüğünü bildikleri için İsa'yla alay ettiler."},{"n":"54","t":"O ise kızın elinden tutarak, \"Kızım, kalk!\" diye seslendi."},{"n":"55","t":"Ruhu yeniden bedenine dönen kız hemen ayağa kalktı. İsa, kıza yiyecek bir şey verilmesini buyurdu."},{"n":"56","t":"Kızın annesi babası şaşkınlık içindeydiler. İsa, olanları hiç kimseye anlatmamaları için onları uyardı."}]},{"ch":9,"verses":[{"n":"1","t":"İsa, Onikileri yanına çağırarak onlara tüm cinleri kovmak ve hastalıkları iyileştirmek için güç ve yetki verdi."},{"n":"2","t":"Sonra onları Tanrı'nın Egemenliğini duyurmaya ve hastalara şifa vermeye gönderdi."},{"n":"3","t":"Onlara şöyle dedi: \"Yolculuk için yanınıza hiçbir şey almayın - ne değnek, ne torba, ne ekmek, ne para, ne de yedek mintan."},{"n":"4","t":"Hangi eve girerseniz, kentten ayrılıncaya dek orada kalın."},{"n":"5","t":"Sizi kabul etmeyenler olursa, kentten ayrılırken onlara uyarı olsun diye ayaklarınızın tozunu silkin.\""},{"n":"6","t":"Onlar da yola çıktılar, her yerde Müjde'yi yayarak ve hastaları iyileştirerek köy köy dolaştılar."},{"n":"7-8","t":"Bölgenin kralı Hirodes bütün bu olanları duyunca şaşkına döndü. Çünkü bazıları Yahya'nın ölümden dirildiğini, bazıları İlyas'ın göründüğünü, daha başkaları ise eski peygamberlerden birinin dirildiğini söylüyordu."},{"n":"9","t":"Hirodes, \"Yahya'nın başını ben kestirdim. Şimdi hakkında böyle haberler duyduğum bu adam kim?\" diyor ve İsa'yı görmenin bir yolunu arıyordu."},{"n":"10","h":"İsa beş bin kişiyi doyuruyor","t":"Elçiler geri dönünce, yaptıkları her şeyi İsa'ya anlattılar. Sonra İsa yalnızca onları yanına alıp Beytsayda denilen bir kente çekildi."},{"n":"11","t":"Bunu öğrenen halk O'nun ardından gitti. İsa onları ilgiyle karşıladı, kendilerine Tanrı'nın Egemenliğinden söz etti ve şifaya ihtiyacı olanları iyileştirdi."},{"n":"12","t":"Günbatımına doğru Onikiler gelip O'na, \"Halkı salıver de çevredeki köylere ve çiftliklere gidip kendilerine barınak ve yiyecek bulsunlar. Çünkü burada ıssız bir yerdeyiz\" dediler."},{"n":"13","t":"O ise kendilerine, \"Onlara siz yiyecek verin\" dedi.\n\"Beş ekmekle iki balıktan başka bir şeyimiz yok\" dediler. \"Yoksa biz mi gidip bütün bu halk için yiyecek alalım?\""},{"n":"14","t":"Orada yaklaşık beş bin erkek vardı.\nİsa öğrencilerine, \"Halkı yaklaşık ellişer kişilik kümeler halinde yere oturtun\" dedi."},{"n":"15","t":"Öğrenciler öyle yapıp herkesi yere oturttular."},{"n":"16","t":"İsa, beş ekmekle iki balığı aldı, gözlerini göğe dikerek şükran duasını yaptı; sonra bunları böldü ve halka dağıtmaları için öğrencilerine verdi."},{"n":"17","t":"Herkes yiyip doyduktan sonra on iki sepet dolusu yemek artığı toplandı."},{"n":"18","h":"Petrus'un Mesih'i tanıması","t":"Bir gün İsa tek başına dua ediyordu, öğrencileri de yanındaydı. İsa onlara, \"Halk benim kim olduğumu söylüyor?\" diye sordu."},{"n":"19","t":"Onlar şöyle cevap verdiler: \"Vaftizci Yahya diyorlar. Ama kimi İlyas diyor, kimi de eski peygamberlerden birinin dirilmiş olduğunu söylüyor.\""},{"n":"20","t":"İsa onlara, \"Ya siz\" dedi, \"ben kimim dersiniz?\"\nPetrus, \"Sen Tanrı'nın Mesihisin\" cevabını verdi."},{"n":"21","t":"İsa, onları uyararak bunu hiç kimseye söylememelerini buyurdu."},{"n":"22","t":"\"İnsanoğlu'nun çok acı çekmesi, ihtiyarlar, başkâhinler ve din bilginlerince reddedilmesi, öldürülmesi ve üçüncü gün dirilmesi gerektir\" dedi."},{"n":"23","t":"Sonra herkese şunları söyledi: \"Ardımdan gelmek isteyen, kendini inkâr etsin, her gün çarmıhını yüklenip beni izlesin."},{"n":"24","t":"Canını kurtarmak isteyen onu yitirecek; canını benim uğruma yitiren ise onu kurtaracaktır."},{"n":"25","t":"İnsan bütün dünyayı kazanıp da canını yitirirse, canından olursa, bunun kendisine ne yararı olur?"},{"n":"26","t":"Kim benden ve benim sözlerimden utanırsa, İnsanoğlu da kendisinin, Babasının ve kutsal meleklerin görkemi içinde geldiğinde o kişiden utanacaktır."},{"n":"27","t":"Size gerçeği söyleyeyim, burada bulunanlar arasında, Tanrı'nın Egemenliğini görmeden ölümü tatmayacak olanlar var.\""},{"n":"28","h":"İsa'nın görünümü değişiyor","t":"Bu sözleri söyledikten yaklaşık sekiz gün sonra İsa, yanına Petrus, Yuhanna ve Yakup'u alarak dua etmek üzere dağa çıktı."},{"n":"29","t":"İsadua ederken yüzünün görünümü değişti, giysileri şimşek gibi parıldayan bir beyazlığa büründü."},{"n":"30-31","t":"O anda görkemli bir şekilde ortalıkta beliren iki kişi İsa'yla konuşmaya başladılar. Bunlar Musa ile İlyas'tı. İsa'nın yakında Kudüs'te gerçekleşecek olan ayrılışını konuşuyorlardı."},{"n":"32","t":"Petrus ile yanındakilerin üzerine uyku çökmüştü. Ama uykuları iyice dağılınca İsa'nın görkemini ve yanında duran iki kişiyi gördüler."},{"n":"33","t":"Bunlar İsa'nın yanından ayrılırken Petrus İsa'ya, \"Efendimiz\" dedi, \"burada bulunmamız ne iyi oldu! Üç çardak kuralım: biri sana, biri Musa'ya, biri de İlyas'a.\" Aslında ne söylediğinin farkında değildi."},{"n":"34","t":"Petrus daha bunları söylerken bir bulut gelip onları gölgeledi. Bulut onların etrafını sarınca korktular."},{"n":"35","t":"Buluttan gelen bir ses, \"Bu benim Oğlumdur, seçilmiş Olan'dır. O'nu dinleyin!\" dedi."},{"n":"36","t":"Ses kesilince İsa'nın tek başına olduğu görüldü. Öğrenciler bunu gizli tuttular ve o günlerde hiç kimseye gördüklerinden söz etmediler."},{"n":"37","h":"Cine tutsak bir çocuğun iyileştirilmesi","t":"Ertesi gün dağdan indikleri zaman, İsa'yı büyük bir kalabalık karşıladı."},{"n":"38","t":"Kalabalığın içinden bir adam, \"Öğretmenim\" diye seslendi, \"yalvarırım sana, oğluma bakıver, o benim bir taneciğimdir."},{"n":"39","t":"Bir ruh onu yakalıyor, o da birdenbire bağırmaya başlıyor. Ruh onu, ağzından köpükler akıtana dek şiddetle sarsıyor. Yara bere içinde bırakıyor, kendisinden zor ayrılıyor."},{"n":"40","t":"Ruhu kovmaları için öğrencilerine yalvardım, ama başaramadılar.\""},{"n":"41","t":"İsa şöyle karşılık verdi: \"Ey imansız ve sapmış kuşak! Sizinle daha ne kadar kalıp size katlanacağım? Oğlunu buraya getir.\""},{"n":"42","t":"Çocuk daha İsa'ya yaklaşırken cin onu yere vurup şiddetle sarstı. Ama İsa kötü ruhu azarladı, çocuğu iyileştirerek babasına geri verdi."},{"n":"43-44","t":"Herkes Tanrı'nın büyük gücüne şaşıp kaldı.\nHerkes İsa'nın tüm yaptıkları karşısında hayret içindeyken, İsa öğrencilerine, \"Siz şu sözlerime iyice kulak verin\" dedi. \"İnsanoğlu, insanların eline teslim edilecek.\""},{"n":"45","h":"İsa ölüp dirileceğini tekrar bildiriyor","t":"Onlar bu sözü anlamadılar. Sözü kavramasınlar diye anlamı kendilerinden gizlenmişti. Üstelik İsa'ya bu sözle ilgili soru sormaktan korkuyorlardı."},{"n":"46","h":"En büyük kim?","t":"Öğrenciler, aralarında kimin en büyük olduğunu tartışmaya başladılar."},{"n":"47-48","t":"Akıllarından geçeni bilen İsa, küçük bir çocuğu tutup yanına çekti ve onlara şöyle dedi: \"Bu çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur. Aranızda en küçük kim ise, işte en büyük odur.\""},{"n":"49","t":"Yuhanna buna karşılık, \"Efendimiz\" dedi, \"senin adınla cin kovan birini gördük, ama bizimle birlikte seni izlemediği için ona engel olmaya çalıştık.\""},{"n":"50","t":"İsa, \"Ona engel olmayın!\" dedi. \"Size karşı olmayan, sizden yanadır.\""},{"n":"51","h":"Samiriyeliler İsa'yı istemiyor","t":"Göğe alınacağı gün yaklaşınca İsa, kararlı adımlarla Kudüs'e doğru yola çıktı."},{"n":"52","t":"Kendi önünden haberciler gönderdi. Bunlar, kendisi için hazırlık yapmak üzere gidip Samiriyelilere ait bir köye girdiler."},{"n":"53","t":"Ama Samiriyeliler Kudüs'e gitmekte olan İsa'yı kabul etmediler."},{"n":"54","t":"Öğrencilerden Yakup'la Yuhanna bunu görünce, \"Rab, bunları yok etmek için bir buyrukla gökten ateş yağdırmamızı ister misin?\" dediler."},{"n":"55","t":"Ama İsa dönüp onları azarladı."},{"n":"56","t":"Sonra başka bir köye gittiler."},{"n":"57","h":"İsa'yı izlemenin bedeli","t":"Yolda giderlerken bir adam İsa'ya, \"Nereye gidersen, senin ardından geleceğim\" dedi."},{"n":"58","t":"İsa ona, \"Tilkilerin ini, gökte uçan kuşların yuvası var, ama İnsanoğlu'nun başını yaslayacak bir yeri yok\" dedi."},{"n":"59","t":"Bir başkasına, \"Ardımdan gel\" dedi.\nAdam ise, \"İzin ver de önce gidip babamı gömeyim\" dedi."},{"n":"60","t":"İsa ona şöyle dedi: \"Ölüleri bırak, kendi ölülerini kendileri gömsünler. Sen gidip, Tanrı'nın Egemenliğini duyur.\""},{"n":"61","t":"Bir başkası, \"Rab\" dedi, \"senin ardından geleceğim ama, izin ver, önce evimdekilerle vedalaşayım.\""},{"n":"62","t":"İsa ona, \"Sabanı tutup da geriye bakan, Tanrı'nın Egemenliğine layık değildir\" dedi."}]},{"ch":10,"verses":[{"n":"1","t":"Bu olaylardan sonra Rab yetmiş kişi daha görevlendirdi. Bunları ikişer ikişer, kendisinin gideceği her kente, her yere kendi önünden gönderdi."},{"n":"2","t":"Onlara şöyle dedi: \"Ürün bol, ama işçi az. Bu nedenle, ürünün sahibi olan Rab'be yalvarın da, ürününü kaldıracak işçiler göndersin."},{"n":"3","t":"Haydi gidin! İşte, kurtların arasına kuzular gibi gönderiyorum sizi."},{"n":"4","t":"Yanınıza ne kese, ne torba, ne de çarık alın. Yolda hiç kimseyle selamlaşmayın."},{"n":"5","t":"Hangi eve girerseniz, önce, 'Bu eve esenlik olsun!' deyin."},{"n":"6","t":"Orada esenliksever biri varsa, dilediğiniz esenlik onun üzerinde kalacak; yoksa, size dönecektir."},{"n":"7","t":"Girdiğiniz evde kalın, size ne verirlerse onu yiyip için. Çünkü işçi kendi ücretini hak eder. Evden eve taşınmayın."},{"n":"8","t":"\"Bir kente girdiğinizde sizi kabul ederlerse, önünüze konulanı yiyin."},{"n":"9","t":"Orada bulunan hastaları iyileştirin ve kendilerine, 'Tanrı'nınEgemenliği size yaklaştı' deyin."},{"n":"10-11","t":"Ama bir kente girdiğinizde sizi kabul etmezlerse, o kentin caddelerine çıkıp şöyle deyin: 'Kentinizde ayaklarımıza yapışan tozu bile size karşı siliyoruz. Yine de şunu bilin ki, Tanrı'nın Egemenliği yaklaştı.'"},{"n":"12","t":"Size şunu söyleyeyim, yargı günü Sodom kentinin hali o kentin halinden daha dayanılır olacak."},{"n":"13","t":"\"Vay haline, ey Horazin! Vay haline, ey Beytsayda! Sizlerde yapılan mucizeler Sur ve Sayda'da yapılmış olsaydı, onlar çoktan çulla örtünüp kül içinde oturarak tövbe etmiş olurlardı."},{"n":"14","t":"Ama yargı günü Sur ve Sayda'nın hali sizinkinden daha dayanılır olacak."},{"n":"15","t":"Ya sen, ey Kefernahum, göğe mi çıkarılacaksın? Hayır, sen ta ölüler diyarına ineceksin!"},{"n":"16","t":"\"Sizi dinleyen, beni dinlemiş olur; sizi reddeden, beni reddetmiş olur. Beni reddeden de beni göndereni reddetmiş olur.\""},{"n":"17","t":"Yetmişler sevinç içinde döndüler. \"Rab\" dediler, \"senin adını andığımızda cinler bile bize boyun eğiyor.\""},{"n":"18","t":"İsa onlara şöyle dedi: \"Şeytan'ın gökten yıldırım gibi düştüğünü gördüm."},{"n":"19","t":"Ben size, yılanları ve akrepleri ayak altında ezmek ve düşmanın bütün gücünü alt etmek için yetki verdim. Hiçbir şey size zarar vermeyecektir."},{"n":"20","t":"Bununla birlikte, ruhların size boyun eğmesine sevinmeyin, adlarınızın gökte yazılmış olmasına sevinin.\""},{"n":"21","t":"O anda İsa Kutsal Ruh'un etkisiyle coşarak şöyle dedi: \"Baba, göğün ve yerin Rabbi! Bu gerçekleri bilge ve akıllı kişilerden gizleyip küçük çocuklara açtığın için sana şükrederim. Evet Baba, bunun böyle olması senin isteğindi."},{"n":"22","t":"\"Babam her şeyi bana emanet etti. Oğul'un kim olduğunu Baba'dan başka kimse bilmez. Baba'nın kim olduğunu da Oğul ve Oğul'un O'nu tanıtmayı dilediği kişilerden başkası bilmez.\""},{"n":"23","t":"Sonra öğrencilerine dönüp özel olarak şöyle dedi: \"Sizin gördüklerinizi gören gözlere ne mutlu!"},{"n":"24","t":"Size şunu söyleyeyim, nice peygamberler, nice krallar sizin gördüklerinizi görmek istediler, ama göremediler. Sizin işittiklerinizi işitmek istediler, ama işitemediler.\""},{"n":"25","h":"İyi Samiriyeli","t":"Bir Kutsal Yasa uzmanı İsa'yı sınamak amacıyla gelip şöyle dedi: \"Öğretmenim, sonsuz yaşamı miras almak için ne yapmalıyım?\""},{"n":"26","t":"İsa ona, \"Kutsal Yasa'da ne yazılmıştır?\" diye sordu. \"Orada ne okursun?\""},{"n":"27","t":"Adam şöyle karşılık verdi: \"Tanrın olan Rab'bi bütün yüreğinle, bütün canınla, bütün gücünle ve bütün aklınla sev. Komşunu da kendin gibi sev.\""},{"n":"28","t":"İsa ona, \"Doğru cevap verdin\" dedi. \"Bunu yap ve yaşayacaksın.\""},{"n":"29","t":"Oysa adam kendini haklı çıkarmak isteyerek İsa'ya, \"Peki, komşum kim?\" dedi."},{"n":"30","t":"İsa şöyle cevap verdi: \"Adamın biri Kudüs'ten Eriha'ya inerken haydutların eline düşmüş. Onu soyup dövmüşler ve yarı ölü halde bırakıp gitmişler."},{"n":"31","t":"Bir rastlantı olarak o yoldan bir kâhin geçiyormuş. Adamı görünce yolun öbür tarafından geçip gitmiş."},{"n":"32","t":"BirLevili de o yere varıp adamı görünce aynı şekilde geçip gitmiş."},{"n":"33","t":"O yoldan geçen bir Samiriyeli ise adamın bulunduğu yere gelip onu görünce, yüreği sızlamış."},{"n":"34","t":"Adamın yanına gitmiş, yaralarının üzerine yağla şarap dökerek onları sarmış. Sonra adamı kendi hayvanına bindirip bir hana götürmüş ve onunla ilgilenmiş."},{"n":"35","t":"Ertesi gün iki dinar çıkararak hancıya vermiş. 'Ona iyi bak' demiş, 'bundan fazla ne harcarsan, dönüşümde sana öderim.'"},{"n":"36","t":"\"Sence bu üç kişiden hangisi haydutlar arasına düşen adama komşu gibi davranmış?\""},{"n":"37","t":"Yasa uzmanı, \"Ona acıyıp yardım eden\" dedi.\nİsa ona, \"Git, sen de öyle yap\" dedi."},{"n":"38","h":"İsa, Marta ve Meryem'in evinde","t":"İsa, öğrencileriyle birlikte yola devam edip bir köye girdi. Marta adında bir kadın İsa'yı evinde konuk etti."},{"n":"39","t":"Marta'nın Meryem adındaki kızkardeşi, Rab'bin ayakları dibine oturmuş O'nun konuşmasını dinliyordu."},{"n":"40","t":"Marta ise işlerinin çokluğundan ötürü telaş içindeydi. İsa'nın yanına gelerek, \"Rab\" dedi, \"kardeşimin beni hizmet işlerinde yalnız bırakmasına aldırmıyor musun? Ona söyle de bana yardım etsin.\""},{"n":"41","t":"Rab ona şu karşılığı verdi: \"Marta, Marta, sen çok şey için kaygılanıp telaşlanıyorsun."},{"n":"42","t":"Oysa gerekli olan tek bir şey var. Meryem iyi olanı seçmiştir ve bu kendisinden alınmayacaktır.\""}]},{"ch":11,"verses":[{"n":"1","t":"İsa bir yerde dua ediyordu. Duasını bitirince öğrencilerinden biri O'na, \"Rab\" dedi, \"Yahya'nın kendi öğrencilerine öğrettiği gibi sen de bize dua etmesini öğret.\""},{"n":"2","t":"İsa onlara dedi ki, \"Dua ettiğiniz zaman şöyle deyin:\n'Baba, adın kutsal kılınsın.\nEgemenliğin gelsin."},{"n":"3","t":"Her gün bize gündelik ekmeğimizi ver."},{"n":"4","t":"Günahlarımızı bağışla.\nÇünkü biz de bize karşı suç işleyen herkesi\nbağışlıyoruz.\nAyartılmamıza izin verme.'\""},{"n":"5-7","t":"Sonra onlara şöyle dedi: \"Sizlerden birinin bir arkadaşı olur da gece yarısı ona gidip, 'Dostum, bana üç ekmek ödünç ver. Dostlarımdan biri yoldan geldi, onun önüne koyacak bir şeyim yok' derse, öbürü içerden, 'Beni rahatsız etme! Kapı artık kapandı, çocuklarım da yanımda yatıyor. Kalkıp sana bir şey veremem' diye cevap verir mi hiç?"},{"n":"8","t":"Size şunu söyleyeyim, arkadaşlık gereği kalkıp ona istediğini vermese bile, adamın yüzsüzlüğünden ötürü kalkar, ihtiyacı neyse ona verir."},{"n":"9","t":"\"Ben size şunu söyleyeyim: dileyin, size verilecek; arayın, bulacaksınız; kapıyı çalın, size açılacaktır."},{"n":"10","t":"Çünkü her dileyen alır, arayan bulur, kapıyı çalana kapı açılır."},{"n":"11","t":"\"Aranızda hangi baba, ekmek isteyen oğluna taş verir? Ya da balık isterse ona balık yerine yılan verir?"},{"n":"12","t":"Ya da yumurta isterse ona akrep verir?"},{"n":"13","t":"Sizler kötü yürekli olduğunuz halde çocuklarınıza güzel armağanlar vermeyi biliyorsanız, gökteki Baba'nın, kendisinden dileyenlere Kutsal Ruh'u vereceği çok daha kesin değil mi?\""},{"n":"14","h":"İsa ve Beelzebub","t":"İsa adamın birinden dilsiz bir cini kovuyordu. Cin çıkınca adamın dili çözüldü. Halk hayret içinde kaldı."},{"n":"15","t":"Ama içlerinden bazıları, \"Cinleri, cinlerin reisi Beelzebub'un gücüyle kovuyor\" dediler."},{"n":"16","t":"Bazıları ise O'nu sınamak amacıyla gökten bir belirti göstermesini istediler."},{"n":"17","t":"Onların ne düşündüğünü bilen İsa şöyle dedi: \"Kendi içinde bölünmüş her ülke yıkıma uğrar, kendi içinde bölünmüş her ev yıkılır."},{"n":"18","t":"Şeytan da kendi içinde bölünmüşse, onun egemenliği nasıl ayakta kalabilir? Siz, benim Beelzebub'un gücüyle cinleri kovduğumu söylüyorsunuz."},{"n":"19","t":"Eğer ben cinleri Beelzebub'un gücüyle kovuyorsam, sizin adamlarınız kimin gücüyle kovuyorlar? Sizi bu durumda kendi adamlarınız yargılayacak."},{"n":"20","t":"Ama ben cinleri Tanrı'nın eliyle kovuyorsam, Tanrı'nın Egemenliği üzerinize gelmiş demektir."},{"n":"21","t":"\"Tepeden tırnağa silahlanmış güçlü bir adam kendi evini koruduğu sürece, malları güvenlik içinde olur."},{"n":"22","t":"Ne var ki, ondan daha güçlü biri saldırıp onu alt ettiğinde güvendiği bütün silahları elinden alır ve mallarını yağmalayarak bölüştürür."},{"n":"23","t":"Benden yana olmayan bana karşıdır, benimle birlikte toplamayan dağıtıyor demektir."},{"n":"24","t":"\"Kötü ruh kişinin içinden çıkınca kurak yerlerde dolanıp huzur arar. Bulamayınca da, 'Çıktığım eve, kendi evime döneyim' der."},{"n":"25","t":"Eve gelince orayı süpürülmüş ve düzeltilmiş bulur."},{"n":"26","t":"Bunun üzerine gider, kendisinden kötü yedi ruh daha alır ve eve girip yerleşirler. Böylece o kişinin son durumu ilkinden beter olur.\""},{"n":"27","t":"İsa bu sözleri söylerken kalabalığın içinden bir kadın O'na, \"Ne mutlu seni taşımış olan rahme, seni emzirmiş olan memelere!\" diye seslendi."},{"n":"28","t":"İsa, \"Daha doğrusu, ne mutlu Tanrı'nın sözünü dinleyip uygulayanlara!\" dedi."},{"n":"29","h":"Yunus'un belirtisi","t":"Çevredeki kalabalık büyürken İsa konuşmaya başladı. \"Şimdiki kuşak kötü bir kuşak\" dedi. \"Doğaüstü bir belirti istiyor, ama ona Yunus'un belirtisinden başka bir belirti gösterilmeyecek."},{"n":"30","t":"Yunus nasıl Ninova halkına bir belirti olduysa, İnsanoğlu da bu kuşak için öyle olacaktır."},{"n":"31","t":"Güney Kraliçesi, yargı günü bu kuşağın adamlarıyla birlikte kalkıp onları yargılayacak. Çünkü kraliçe, Süleyman'ınbilgece sözlerini dinlemek için dünyanın ta öbür ucundan gelmişti. Bakın, Süleyman'dan daha üstün olan buradadır."},{"n":"32","t":"Ninova halkı, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü Ninovalılar, Yunus'un çağrısı üzerine tövbe ettiler. Bakın, Yunus'tan daha üstün olan buradadır."},{"n":"33","h":"Bedenin ışığı","t":"\"Hiç kimse kandil yakıp onu gizli bir yere ya da tahıl ölçeği altına koymaz. Tersine, içeri girenler ışığı görsünler diye onu kandilliğe koyar."},{"n":"34","t":"Bedenin ışığı gözdür. Gözün sağlamsa, tüm bedenin de aydınlık olur. Gözün bozuksa, bedenin de karanlık olur."},{"n":"35","t":"Öyleyse dikkat et, sendeki 'ışık' karanlık olmasın."},{"n":"36","t":"Eğer bütün bedenin aydınlık olur ve hiçbir yanı karanlık kalmazsa, kandilin seni ışınlarıyla aydınlattığı zamanki gibi, bedenin tümden aydınlık olur.\""},{"n":"37","h":"Vay halinize, Ferisiler!","t":"İsa konuşmasını bitirince bir Ferisi O'nu evine yemeğe çağırdı. O da içeri girerek sofraya oturdu."},{"n":"38","t":"İsa'nın yemekten önce yıkanmadığını gören Ferisi şaştı."},{"n":"39","t":"Rab ona şöyle dedi: \"Siz Ferisiler, bardağın ve tabağın dışını temizlersiniz, ama içiniz açgözlülük ve kötülükle doludur."},{"n":"40","t":"Behey akılsızlar! Dışı yapanla içi yapan aynı değil mi?"},{"n":"41","t":"Siz kaplarınızın içindekini sadaka olarak verin, o zaman sizin için her şey temiz olur."},{"n":"42","t":"\"Ama vay halinize, ey Ferisiler! Siz nanenin, sedef otunun ve her tür sebzenin ondalığını verirsiniz de, adaleti ve Tanrı sevgisini ihmal edersiniz. Ondalık vermeyi ihmal etmeden esas bunları yerine getirmeniz gerekirdi."},{"n":"43","t":"Vay halinize, ey Ferisiler! Havralarda en seçkin yerlere kurulmaya, meydanlarda selamlanmaya bayılırsınız."},{"n":"44","t":"Vay halinize! İnsanların, farkında olmadan üzerlerinde gezindiği belirsiz mezarlara benziyorsunuz.\""},{"n":"45","t":"Kutsal Yasa uzmanlarından biri söz alıp İsa'ya, \"Öğretmenim, bunları söylemekle bize de hakaret etmiş oluyorsun\" dedi."},{"n":"46","t":"İsa, \"Sizin de vay halinize, ey Yasa uzmanları!\" dedi. \"İnsanlara taşınması güç yükler yüklersiniz, kendiniz ise bu yükleri kaldırmak için bir tek parmağınızı kıpırdatmazsınız."},{"n":"47","t":"Vay halinize! Peygamberlerin türbelerini yaparsınız, oysa onları sizin atalarınız öldürmüştür."},{"n":"48","t":"Böylelikle atalarınızın yaptıklarına tanıklık ederek bunları onaylamış oluyorsunuz. Çünkü onlar peygamberleri öldürdüler, siz de türbelerini yapıyorsunuz."},{"n":"49","t":"İşte bunun için Tanrı'nın Bilgeliği şöyle demiştir: 'Ben onlara peygamberler ve elçiler göndereceğim, bunlardan kimini öldürecek, kimine zulmedecekler.'"},{"n":"50-51","t":"Böylece bu kuşak, Habil'in kanından tutun da, sunakla tapınak arasında öldürülen Zekeriya'nın kanına değin, dünyanın kuruluşundan beri akıtılan tüm peygamberlerin kanından sorumlu tutulacaktır. Evet, size söylüyorum, bu kuşak sorumlu tutulacaktır."},{"n":"52","t":"Vay halinize, ey Yasa uzmanları!Bilgi kapısının anahtarını alıp götürdünüz. Kendiniz bu kapıdan girmediniz, girmek isteyenlere de engel oldunuz.\""},{"n":"53","t":"İsa oradan ayrılınca, din bilginleriyle Ferisiler O'nu şiddetle sıkıştırarak birçok konuda ağzını aramaya başladılar."},{"n":"54","t":"Ağzından çıkacak bir sözle O'nu tuzağa düşürmek için fırsat kolluyorlardı."}]},{"ch":12,"verses":[{"n":"1","t":"O sırada halktan binlerce kişi birbirlerini ezercesine toplanmıştı. İsa önce kendi öğrencilerine şunları söylemeye başladı: \"Ferisilerin mayasından - yani, ikiyüzlülükten - kaçının."},{"n":"2","t":"Örtülü olup da açığa çıkarılmayacak, gizli olup da bilinmeyecek hiçbir şey yoktur."},{"n":"3","t":"Bunun için karanlıkta söylediğiniz her söz gün ışığında duyulacak, kapalı kapılar ardında kulağa fısıldadıklarınız damlardan duyurulacaktır."},{"n":"4","t":"\"Siz dostlarıma söylüyorum, bedeni öldüren, ama ondan sonra başka bir şey yapamayanlardan korkmayın."},{"n":"5","t":"Kimden korkmanız gerektiğini size açıklayayım: kişiyi öldürdükten sonra cehenneme atma yetkisine sahip olan Tanrı'dan korkun. Evet, size söylüyorum, O'ndan korkun."},{"n":"6","t":"Beş serçe iki meteliğe satılmıyor mu? Ama bunlardan bir teki bile Tanrı katında unutulmuş değildir."},{"n":"7","t":"Nitekim başınızdaki saçlar bile tek tek sayılıdır. Korkmayın, siz birçok serçeden daha değerlisiniz."},{"n":"8","t":"\"Size şunu söyleyeyim, insanların önünde beni açıkça kabul eden herkesi, İnsanoğlu da Tanrı'nın melekleri önünde açıkça kabul edecek."},{"n":"9","t":"Ama kim beni insanlar önünde inkâr ederse, kendisi de Tanrı'nın melekleri önünde inkâr edilecek."},{"n":"10","t":"İnsanoğlu'na karşı bir söz söyleyen herkes bağışlanacak. Oysa Kutsal Ruh'a küfreden bağışlanmayacaktır."},{"n":"11","t":"\"Sizi havra topluluklarının, yöneticilerin ve yetkililerin önüne çıkardıkları zaman, 'Kendimizi neyle, nasıl savunacağız?' ya da, 'Ne söyleyeceğiz?' diye kaygılanmayın."},{"n":"12","t":"Kutsal Ruh o anda size ne söylemeniz gerektiğini öğretecektir.\""},{"n":"13","h":"Zengin budala","t":"Kalabalığın içinden biri İsa'ya, \"Öğretmenim, kardeşime söyle de mirası benimle paylaşsın\" dedi."},{"n":"14","t":"İsa ona şöyle dedi: \"Behey adam! Kim beni üzerinizde yargıç ya da hakem yaptı?\""},{"n":"15","t":"Sonra onlara, \"Dikkatli olun!\" dedi. \"Her türlü açgözlülükten sakının. Çünkü insanın yaşamı, malının çokluğundan ibaret değildir.\""},{"n":"16","t":"İsa onlara şu benzetmeyi anlattı: \"Zengin bir adamın toprakları bol ürün vermiş."},{"n":"17","t":"Adam kendi kendine, 'Ne yapmalıyım? Ürünlerimi koyacak yerim yok' diye düşünmüş."},{"n":"18","t":"Sonra, 'Şöyle yapacağım' demiş. 'Ambarlarımı yıkıp daha büyüklerini yapacağım, bütün tahıllarımı ve mallarımı oraya yığacağım."},{"n":"19","t":"Ve kendime, ey canım, yıllarca yetecek kadar birikmiş bol malın var. Rahatına bak, ye, iç, yaşamın tadını çıkar diyeceğim.'"},{"n":"20","t":"\"Ama Tanrı ona, 'Behey akılsız!' demiş. 'Bu gece canın senden istenecek. Hazırladığın bu şeyler kime kalacak?'"},{"n":"21","t":"\"Kendisi için servet biriktiren, ama Tanrı katında zengin olmayan kişinin sonu böyle olur.\""},{"n":"22","h":"Kaygılanmayın","t":"İsa öğrencilerine şöyle dedi: \"Bu nedenle size şunu söylüyorum: 'Ne yiyeceğiz?' diye canınız için, ya da 'Ne giyeceğiz?' diye bedeniniz için kaygılanmayın."},{"n":"23","t":"Can yiyecekten, beden de giyecekten daha önemlidir."},{"n":"24","t":"Kargalara bakın! Ne eker, ne biçerler; ne kilerleri, ne ambarları vardır. Tanrı yine de onları doyurur. Siz kuşlardan ne kadar daha değerlisiniz!"},{"n":"25","t":"Hangi biriniz kaygılanmakla ömrünü bir anlık uzatabilir?"},{"n":"26","t":"Bu küçücük işe bile gücünüz yetmediğine göre, öbür konularda neden kaygılanıyorsunuz?"},{"n":"27","t":"\"Zambakların nasıl büyüdüğüne bakın! Ne çalışırlar, ne de iplik eğirirler. Ama size şunu söyleyeyim, tüm görkemine rağmen Süleyman bile bunlardan biri gibi giyinmiş değildi."},{"n":"28","t":"Bugün var olup yarın ocağa atılacak olan kır otunu böyle giydiren Tanrı'nın sizi de giydireceği ne kadar daha kesindir, ey imanı kıt olanlar!"},{"n":"29","t":"'Ne yiyeceğiz, ne içeceğiz?' diye düşünüp tasalanmayın."},{"n":"30","t":"Dünya ulusları hep bu şeylerin peşinden giderler. Oysa Babanız, bunları gereksindiğinizi bilir."},{"n":"31","t":"Siz O'nun egemenliğinin ardından gidin, o zaman size bunlar da verilecektir."},{"n":"32","t":"\"Korkma, ey küçük sürü! Çünkü Babanız, egemenliği size vermeyi uygun gördü."},{"n":"33","t":"Mallarınızı satın, sadaka olarak verin. Kendinize eskimeyen keseler, göklerde tükenmeyen bir hazine edinin. Orada ne hırsız ona yaklaşır, ne de güve onu yer."},{"n":"34","t":"Hazineniz neredeyse, yüreğiniz de orada olacak."},{"n":"35","h":"Uyanık ve hazırlıklı olun","t":"\"Kuşaklarınız belinizde bağlı ve kandilleriniz yanar durumda hazır olun."},{"n":"36","t":"Düğün şenliğinden dönecek olan efendilerinin gelip kapıyı çaldığı an kapıyı ona hemen açmaya hazır bekleyenler gibi olun."},{"n":"37","t":"Efendileri geldiğinde uyanık bulunan kölelere ne mutlu! Size doğrusunu söyleyeyim, efendileri beline kuşağını bağlayacak, kölelerini sofraya oturtacak ve gelip onlara hizmet edecek."},{"n":"38","t":"Efendi gecenin ister ikinci, ister üçüncü nöbetinde gelsin, uyanık bulacağı kölelere ne mutlu!"},{"n":"39","t":"Ama şunu bilin ki, ev sahibi, hırsızın hangi saatte geleceğini bilse, evinin soyulmasına fırsat vermez."},{"n":"40","t":"Siz de hazır olun. Çünkü İnsanoğlu, ummadığınız bir saatte gelecektir.\""},{"n":"41","t":"Petrus, \"Rab\" dedi, \"bu benzetmeyi bizim için mi anlatıyorsun, yoksa herkes için mi?\""},{"n":"42","t":"Rab da şöyle dedi: \"Efendinin, uşaklarına yemek paylarını vaktinde vermek için üzerlerinde yetkili kılacağı güvenilir ve akıllı kâhya kimdir?"},{"n":"43","t":"Efendisi eve döndüğünde işinin başında bulacağı o köleye ne mutlu!"},{"n":"44","t":"Size gerçeği söyleyeyim, efendisi onu tüm malının üzerindeyetkili kılacak."},{"n":"45-46","t":"Ama o köle kendi kendine, 'Efendim gelmekte gecikiyor' derse ve kadın erkek diğer hizmetkârları dövmeye, yiyip içip sarhoş olmaya başlarsa, efendisi, onun beklemediği bir günde, ummadığı bir saatte gelecek, onu şiddetle cezalandıracak ve imansızlarla bir tutacaktır."},{"n":"47","t":"\"Efendisinin isteğini bilip de hazırlık yapmayan, onun isteğini yerine getirmeyen köle çok dayak yiyecek."},{"n":"48","t":"Oysa bilmeden köteği hak eden davranışlarda bulunan, az dayak yiyecek. Kime çok verilmişse, ondan çok istenecek. Kime çok şey emanet edilmişse, kendisinden daha fazlası istenecektir."},{"n":"49","t":"\"Ben dünyaya ateş yağdırmaya geldim. Keşke bu ateş daha şimdiden alevlenmiş olsaydı!"},{"n":"50","t":"Katlanmam gereken bir vaftiz var. Bu vaftiz gerçekleşinceye dek nasıl da sıkıntı çekiyorum!"},{"n":"51","t":"Yeryüzüne barış getirmeye mi geldiğimi sanıyorsunuz? Size hayır diyorum, ben ayrılık getirmeye geldim."},{"n":"52","t":"Bundan böyle bir evde beş kişi, ikiye karşı üç, üçe karşı iki bölünmüş olacak."},{"n":"53","t":"Baba oğluna karşı, oğul babasına karşı, anne kızına karşı, kız annesine karşı, kaynana gelinine karşı, gelin kaynanasına karşı olacaktır.\""},{"n":"54","h":"Belirtileri anlamak","t":"İsa halka şunları da söyledi: \"Batıda bir bulutun yükseldiğini görünce siz hemen, 'Sağanak geliyor' diyorsunuz, ve öyle oluyor."},{"n":"55","t":"Yelin güneyden estiğini görünce, 'Çok sıcak olacak' diyorsunuz, ve öyle oluyor."},{"n":"56","t":"Sizi ikiyüzlüler! Yeryüzünün ve gökyüzünün görünümünden bir anlam çıkarabiliyorsunuz da, şimdiki vaktin anlamını nasıl oluyor da çıkaramıyorsunuz?"},{"n":"57","t":"\"Doğru olanı neden kendiliğinizden ayırt etmiyorsunuz?"},{"n":"58","t":"Sizden davacı olan kişiyle birlikte yargıcın önüne çıkmak üzere daha yolda giderken onunla anlaşmak için elinizden geleni yapın. Yoksa o sizi yargıcın önüne sürükler, yargıç gardiyanın eline verir, gardiyan da sizi hapse atar."},{"n":"59","t":"Size şunu söyleyeyim, son kuruşu ödemedikçe oradan asla çıkamazsınız.\""}]},{"ch":13,"verses":[{"n":"1","t":"O sırada bazı kişiler gelip İsa'ya bir haber getirdiler. Pilatus'un nasıl bazı Celilelileri öldürüp kanlarını kendi kestikleri kurbanların kanına kattığını anlattılar."},{"n":"2","t":"İsa onlara şöyle karşılık verdi: \"Böyle acı çeken bu Celilelilerin, diğer bütün Celilelilerden daha mı çok günahlı olduğunu sanıyorsunuz?"},{"n":"3","t":"Size hayır diyorum. Ama tövbe etmezseniz, hepiniz böyle mahvolacaksınız."},{"n":"4","t":"Ya da, Şiloha'daki kule üzerlerine yıkılınca ölen o on sekiz kişinin, Kudüs'te yaşayan diğer insanların hepsinden daha mı çok suçlu olduğunu sanıyorsunuz?"},{"n":"5","t":"Size hayır diyorum. Ama tövbe etmezseniz, hepiniz böyle mahvolacaksınız.\""},{"n":"6","h":"Meyve vermeyen ağaç","t":"İsa şu benzetmeyi anlattı: \"Adamın birinin bağında dikili bir incir ağacı varmış. Adam gelip ağaçta meyve aramış, ama bulamamış."},{"n":"7","t":"Bağcıya, 'Bak' demiş, 'ben üç yıldır gelip bu incir ağacında meyve arıyorum, bulamıyorum. Onu kes. Toprağın besinini neden boş yere tüketsin?'"},{"n":"8","t":"\"Bağcı, 'Efendim' diye karşılık vermiş, 'ağacı bir yıl daha bırak, bu arada ben çevresini kazıp gübreleyeyim."},{"n":"9","t":"Gelecek yıl meyve verirse, ne âlâ; yok eğer vermezse, onu kesersin.'\""},{"n":"10","h":"Beli bükük bir kadının iyileştirilmesi","t":"Bir Sept günü İsa, havralardan birinde ders veriyordu."},{"n":"11","t":"On sekiz yıldır içinde hastalık ruhu bulunan bir kadın da oradaydı. İki büklüm olmuş, belini hiç doğrultamıyordu."},{"n":"12","t":"İsa onu görünce yanına çağırdı. \"Kadın\" dedi, \"hastalığından kurtuldun.\""},{"n":"13","t":"Ellerini kadının üzerine koydu, o da hemen doğruldu ve Tanrı'yı yüceltmeye başladı."},{"n":"14","t":"İsa'nın hastayı Sept günü iyileştirmesine kızan havra yöneticisi kalabalığa seslenerek, \"Çalışmak için altı gün vardır\" dedi. \"O günler gelip iyileşin, Sept günü değil.\""},{"n":"15","t":"Rab ona şu karşılığı verdi: \"Sizi ikiyüzlüler! Her biriniz Sept günü kendi öküzünü ya da eşeğini yemlikten çözüp suya götürmez mi?"},{"n":"16","t":"Buna göre, Şeytan'ın on sekiz yıldır bağlı tuttuğu, İbrahim'in bir kızı olan bu kadının da Sept günü bu bağdan çözülmesi gerekmez miydi?\""},{"n":"17","t":"İsa'nın bu sözleri, kendisine karşı gelenlerin hepsini utandırdı. Bütün kalabalık ise O'nun yaptığı görkemli işlerin tümünü sevinçle karşıladı."},{"n":"18","h":"Hardal tanesi ve maya","t":"Sonra İsa şunları söyledi: \"Tanrı'nın Egemenliği neye benzer, onu neye benzeteyim?"},{"n":"19","t":"Tanrı'nın Egemenliği, bir adamın alıp bahçesine ektiği hardal tanesine benzer. Tane gelişip ağaç olmuş ve gökte uçan kuşlar ağacın dallarında barınmış.\""},{"n":"20","t":"İsa yine, \"Tanrı'nın Egemenliğini neye benzeteyim?\" dedi."},{"n":"21","t":"\"O, bir kadının alıp tüm hamuru kabartmak için üç ölçek una karıştırdığı mayaya benzer.\""},{"n":"22","h":"Dar kapı","t":"İsa köy kent dolaşıp ders vererek Kudüs'e doğru yol alıyordu."},{"n":"23-24","t":"Biri O'na, \"Rab\" dedi, \"kurtulanların sayısı az mı olacak?\"\nİsa oradakilere şöyle dedi: \"Dar kapıdan girmeye gayret edin. Size şunu söyleyeyim, çok kişi içeri girmek isteyecek, ama giremeyecek."},{"n":"25","t":"Ev sahibi kalkıp kapıyı kapattı mı, siz dışarıda dikilip, 'Rab, kapıyı aç bize!' diyerek kapıyı vurmaya başlayacaksınız.\n\"O da size, 'Kim olduğunuzu, nereden geldiğinizi bilmiyorum' diyekarşılık verecek."},{"n":"26","t":"\"Siz o zaman, 'Biz senin önünde yiyip içtik, sen de bizim sokaklarımızda ders verdin' demeye başlayacaksınız."},{"n":"27","t":"\"O da size şöyle diyecek: 'Kim olduğunuzu, nereden geldiğinizi bilmiyorum. Çekilin önümden hepiniz, ey kötülük yapanlar!'"},{"n":"28","t":"\"İbrahim'i, İshak'ı, Yakup'u ve tüm peygamberleri Tanrı'nın Egemenliğinde, kendinizi ise dışarı atılmış gördüğünüz zaman, aranızda ağlayış ve diş gıcırtısı olacaktır."},{"n":"29","t":"İnsanlar doğudan batıdan, kuzeyden güneyden gelecek ve Tanrı'nın Egemenliğinde sofraya oturacaklar."},{"n":"30","t":"Ve işte, sonuncu olan bazıları birinci olacak, birinci olan bazıları da sonuncu olacak.\""},{"n":"31","h":"Ey Kudüs!","t":"Tam o sırada bazı Ferisiler gelip İsa'ya, \"Buradan ayrılıp başka yere git. Hirodes seni öldürmek istiyor\" dediler."},{"n":"32","t":"İsa onlara şöyle dedi: \"Gidin, o tilkiye söyleyin, 'Bugün ve yarın cinleri kovup hastaları iyileştireceğim ve üçüncü gün hedefime ulaşacağım.'"},{"n":"33","t":"Yine de bugün, yarın ve öbür gün yoluma devam etmem gerek. Çünkü bir peygamberin Kudüs'ün dışında ölmesi düşünülemez!"},{"n":"34","t":"\"Ey Kudüs! Peygamberleri öldüren, kendisine gönderilenleri taşlayan Kudüs! Bir tavuk, civcivlerini kanatları altına nasıl toplarsa, ben de kaç kez çocuklarınızı öylece toplamak istedim, ama siz istemediniz."},{"n":"35","t":"Bakın, eviniz ıssız bırakılacak! Size şunu söyleyeyim: 'Rab'bin adıyla gelene övgüler olsun!' diyeceğiniz zamana dek beni bir daha görmeyeceksiniz.\""}]},{"ch":14,"verses":[{"n":"1","t":"Bir Sept günü İsa Ferisilerin ileri gelenlerinden birinin evine yemek yemeye gitti. Herkes O'nu dikkatle gözlüyordu."},{"n":"2","t":"Önünde, vücudu su toplamış bir adam vardı."},{"n":"3","t":"İsa, Kutsal Yasa uzmanlarına ve Ferisilere, \"Sept günü bir hastayı iyileştirmek Kutsal Yasa'ya uygun mudur, değil midir?\" diye sordu."},{"n":"4","t":"Onlar ses çıkarmadılar. İsa da adamı tutup iyileştirdi, sonra onu salıverdi."},{"n":"5","t":"İsa onlara şöyle dedi: \"Oğlu ya da öküzü kuyuya düşen hangi biriniz, Sept günü bile olsa onu hemen oradan çıkarmaz?\""},{"n":"6","t":"Onlar buna hiçbir karşılık veremediler."},{"n":"7-9","t":"Yemeğe çağrılanların başköşeleri seçtiğini farkeden İsa, onlara şu benzetmeyi anlattı: \"Biri seni düğüne çağırdığı zaman başköşeye kurulma. Aksi halde, senden daha üstün sayılan biri çağrılmışsa, ikinizi çağıran kişi sana gelip, 'Yerini bu adama ver' diyebilir. Sen de o zaman utanç içinde kalkıp en arkaya geçersin."},{"n":"10","t":"Sen çağrıldığın zaman gidip en arkada otur. Öyle ki, seni çağıran gelince, 'Dostum, daha öne geçmez misin?' desin. O zaman seninle birlikte sofrada oturan herkesin önünde onurlandırılmış olursun."},{"n":"11","t":"Kendini yücelten herkesalçaltılacak, kendini alçaltan yüceltilecektir.\""},{"n":"12","h":"Kimleri yemeğe çağırmalı","t":"İsa kendisini yemeğe çağırmış olana da şöyle dedi: \"Bir öğlen ya da akşam yemeği verdiğin zaman dostlarını, kardeşlerini, akrabalarını ve zengin komşularını çağırma. Yoksa onlar da seni çağırıp karşılığını verirler."},{"n":"13","t":"Ama bir ziyafet verdiğin zaman yoksulları, kötürümleri, sakatları, körleri çağır."},{"n":"14","t":"Böylece mutlu olursun. Çünkü bunlar sana karşılık verecek durumda değildirler. Karşılığı sana, doğru kişiler dirildiği zaman verilecektir.\""},{"n":"15","t":"İsa'yla birlikte sofrada oturanlardan biri bu sözleri duyunca O'na, \"Tanrı'nın Egemenliğinde yemek yiyecek olana ne mutlu!\" dedi."},{"n":"16","t":"İsa ona şöyle dedi: \"Adamın biri büyük bir şölen hazırlayıp birçok konuk çağırmış."},{"n":"17","t":"Şölen saati gelince davetlilere, 'Buyurun, artık her şey hazır' diye haber vermek üzere kölesini göndermiş."},{"n":"18","t":"\"Ne var ki, hepsi anlaşmışçasına özür dilemeye başlamışlar. Birincisi ona, 'Bir tarla satın aldım, gidip görmem gerek. Rica ederim, beni hoş gör' demiş."},{"n":"19","t":"\"Bir başkası, 'Beş çift öküz aldım, onları denemeye gidiyorum. Rica ederim, beni hoş gör' demiş."},{"n":"20","t":"\"Yine bir başkası, 'Yeni evlendim, bu nedenle gelemiyorum' demiş."},{"n":"21","t":"\"Köle geri dönüp durumu efendisine bildirmiş. Bunun üzerine ev sahibi öfkelenerek kölesine, 'Çabuk ol' demiş, 'çıkıp kentin caddelerini, sokaklarını dolaş; yoksul, kötürüm, kör, sakat olanları al getir.'"},{"n":"22","t":"\"Köle, 'Efendim, buyruğun yerine getirilmiştir, ama daha yer var' demiş."},{"n":"23","t":"\"Efendisi köleye, 'Çıkıp yolları ve çit boylarını dolaş, bulduklarını gelmeye zorla da evim dolsun' demiş."},{"n":"24","t":"'Size şunu söyleyeyim, ilk çağrılan o adamlardan hiçbiri benim yemeğimden tatmayacaktır.'\""},{"n":"25-26","h":"İsa'nın öğrencileri","t":"Kalabalık halk toplulukları İsa'yla birlikte yol alıyordu. İsa dönüp onlara şöyle dedi: \"Biri bana gelip de babasını, annesini, karısını, çocuklarını, kardeşlerini, hatta kendi canını bile gözden çıkarmazsa, benim öğrencim olamaz."},{"n":"27","t":"Çarmıhını yüklenip ardımdan gelmeyen, benim öğrencim olamaz."},{"n":"28","t":"\"Aranızdan biri bir kule yapmak isterse, bunu tamamlayacak kadar parası var mı yok mu diye önce oturup yapacağı masrafı hesap etmez mi?"},{"n":"29-30","t":"Çünkü temel atıp da işi bitiremezse, durumu gören herkes, 'Bu adam inşaata başladı, ama bitiremedi' diyerek onunla eğlenmeye başlar."},{"n":"31","t":"\"Ya da başka bir kralla savaşmaya gidecek olan hangi kral, üzerine yirmi bin askerle yürüyen düşmana on bin askerle karşı koyabilir miyim diye önce oturup bir değerlendirme yapmaz?"},{"n":"32","t":"Eğer karşı koyamayacaksa, öbürü henüz uzaktayken elçiler gönderip barış koşullarını ister."},{"n":"33","t":"Aynı şekilde sizden kim varını yoğunu gözden çıkarmazsa, benim öğrencim olamaz."},{"n":"34","t":"\"Tuz yararlıdır. Ama tuz tadını yitirirse, tuzluluğunu tekrar nasıl kazanabilir?"},{"n":"35","t":"Ne toprağa, ne de gübreye yarar; onu çöpe atarlar. İşitecek kulağı olan işitsin.\""}]},{"ch":15,"verses":[{"n":"1","t":"Bütün vergi görevlileriyle günahkârlar İsa'yı dinlemek için O'na akın ediyordu."},{"n":"2","t":"Ferisilerle din bilginleri ise, \"Bu adam günahkârları kabul ediyor, onlarla birlikte yemek yiyor\" diye söyleniyorlardı."},{"n":"3-4","t":"Bunun üzerine İsa onlara şu benzetmeyi anlattı: \"Sizlerden birinin yüz koyunu olsa ve bunlardan bir tanesini kaybetse, doksan dokuzu bozkırda bırakarak kaybolanı bulana dek onun ardına düşmez mi?"},{"n":"5-6","t":"Onu bulunca da sevinç içinde omuzlarına alır, evine döner; arkadaşlarını, komşularını çağırıp onlara, 'Benimle birlikte sevinin, kaybolan koyunumu buldum!' der."},{"n":"7","t":"Size şunu söyleyeyim, aynı şekilde gökte, tövbe eden tek bir günahkâr için, tövbeyi gereksinmeyen doksan dokuz doğru kişi için duyulandan daha büyük sevinç duyulacaktır."},{"n":"8","h":"Kaybolan para benzetmesi","t":"\"Ya da on gümüş parası olan bir kadın bunlardan bir tanesini kaybetse, kandil yakıp evi süpürerek parayı bulana dek her tarafı dikkatle aramaz mı?"},{"n":"9","t":"Parayı bulunca da arkadaşlarını, komşularını çağırıp, 'Benimle birlikte sevinin, kaybettiğim parayı buldum!' der."},{"n":"10","t":"Size şunu söyleyeyim, aynı şekilde Tanrı'nın melekleri de tövbe eden bir tek günahkâr için sevinç duyacaklar.\""},{"n":"11","h":"Kaybolan oğul benzetmesi","t":"İsa, \"Bir adamın iki oğlu varmış\" dedi."},{"n":"12","t":"\"Bunlardan küçüğü babasına, 'Baba' demiş, 'malından payıma düşeni ver bana.' Baba da servetini iki oğlu arasında paylaştırmış."},{"n":"13","t":"\"Bundan birkaç gün sonra küçük oğul her şeyini toplayıp uzak bir ülkeye gitmiş. Orada sefahat içinde bir yaşam sürerek varını yoğunu çarçur etmiş."},{"n":"14","t":"Delikanlı her şeyini harcadıktan sonra, o ülkede şiddetli bir kıtlık baş göstermiş ve o da yokluk çekmeye başlamış."},{"n":"15","t":"Bunun üzerine gidip o ülkenin vatandaşlarından birinin hizmetine girmiş. Adam onu, domuz gütmek üzere otlaklarına yollamış."},{"n":"16","t":"Delikanlı, domuzların yediği keçiboynuzlarıyla karnını doyurmaya can atıyormuş. Ama hiç kimse ona bir şey vermemiş."},{"n":"17","t":"\"Aklı başına gelince şöyle demiş: 'Babamın nice işçisinin fazlasıyla yiyeceği var, bense burada açlıktan ölüyorum."},{"n":"18","t":"Kalkıp babamın yanına döneceğim ve ona, Baba diyeceğim, Tanrı'ya ve sana karşı günah işledim."},{"n":"19","t":"Ben artık senin oğlun olarak anılmaya layıkdeğilim. Beni işçilerinden biri gibi kabul et.'"},{"n":"20","t":"\"Böylece kalkıp babasının yanına dönmüş. Kendisi daha uzaktayken babası onu görmüş, ona acımış, koşup boynuna sarılmış ve onu öpmüş."},{"n":"21","t":"Oğlu ona, 'Baba' demiş, 'Tanrı'ya ve sana karşı günah işledim. Ben artık senin oğlun olarak anılmaya layık değilim.'"},{"n":"22","t":"\"Babası ise kölelerine, 'Çabuk, en iyi kaftanı getirip ona giydirin!' demiş. 'Parmağına bir yüzük takın, ayaklarına çarık giydirin!"},{"n":"23","t":"Besili danayı getirip kesin, yiyelim ve eğlenelim."},{"n":"24","t":"Çünkü benim bu oğlum ölmüştü, yaşama döndü; kaybolmuştu, bulundu.' Böylece eğlenmeye başlamışlar."},{"n":"25","t":"\"Babanın büyük oğlu ise tarladaymış. Gelip eve yaklaştığında çalgı ve oyun seslerini duymuş."},{"n":"26","t":"Uşaklardan birini yanına çağırıp, 'Ne oluyor?' diye sormuş."},{"n":"27","t":"\"O da ona, 'Kardeşin geldi, baban da ona sağ salim kavuştuğu için besili danayı kesti' demiş."},{"n":"28-29","t":"\"Büyük oğul öfkelenmiş, içeri girmek istememiş. Babası dışarı çıkıp ona yalvarmış. Ama o, babasına şöyle cevap vermiş: 'Bak, bunca yıl senin için köle gibi çalıştım, hiçbir zaman buyruğundan çıkmadım. Ne var ki sen bana, arkadaşlarımla eğleneyim diye hiçbir zaman bir oğlak bile vermedin."},{"n":"30","t":"Oysa senin malını fahişelerle yiyen şu oğlun eve dönünce, onun için besili danayı kestin.'"},{"n":"31","t":"\"Babası ona, 'Oğlum, sen her zaman benim yanımdasın, neyim varsa senindir' demiş."},{"n":"32","t":"'Ama sevinip eğlenmek gerekiyordu. Çünkü bu kardeşin ölmüştü, yaşama döndü; kaybolmuştu, bulundu!'\""}]},{"ch":16,"verses":[{"n":"1","t":"İsa öğrencilerine şunları da anlattı: \"Zengin bir adamın bir kâhyası varmış. Kâhya, efendisinin mallarını çarçur ediyor diye efendisine ihbar edilmiş."},{"n":"2","t":"Efendisi kâhyayı çağırıp ona, 'Nedir bu senin hakkında duyduklarım? Kâhyalığının hesabını ver. Çünkü sen artık kâhyalık edemezsin' demiş."},{"n":"3","t":"\"Kâhya kendi kendine, 'Ne yapacağım ben?' demiş. 'Efendim kâhyalığı elimden alıyor. Toprak kazmaya gücüm yetmez, dilenmekten utanırım."},{"n":"4","t":"Kâhyalıktan kovulduğum zaman başkaları beni evlerine kabul etsinler diye ne yapacağımı biliyorum.'"},{"n":"5","t":"\"Böylelikle efendisine borcu olanların hepsini tek tek yanına çağırmış. Birincisine, 'Efendime ne kadar borcun var?' demiş."},{"n":"6","t":"\"Adam, 'Yüz ölçek zeytinyağı' karşılığını vermiş.\n\"Kâhya ona, 'Borç senedini al ve hemen otur, elli ölçek diye yaz' demiş."},{"n":"7","t":"\"Sonra bir başkasına, 'Senin borcun ne kadar?' demiş.\n\"'Yüz ölçek buğday' demiş öteki.\n\"Ona da, 'Borç senedini al, seksen ölçek diye yaz' demiş."},{"n":"8","t":"\"Efendisi de, dürüst olmayan kâhyayı, akıllıca davrandığı için övmüş. Gerçekten bu çağın insanları, kendilerine benzer kişilerle ilişkilerinde, ışıkta yürüyenlerden daha akıllı oluyorlar."},{"n":"9","t":"Size şunusöyleyeyim, dünyanın aldatıcı servetini [] kendinize dost edinmek için kullanın ki, bu servet yok olunca sizi sonsuza dek kalacak konutlara kabul etsinler."},{"n":"10","h":"Servet ve güvenilirlik","t":"\"Küçücük bir işte güvenilir olan kişi, büyük işte de güvenilir olur. Küçücük bir işte dürüst olmayan kişi, büyük işte de dürüst olmaz."},{"n":"11","t":"Dünyanın aldatıcı serveti konusunda güvenilir değilseniz, gerçek serveti size kim emanet eder?"},{"n":"12","t":"Başkasının malı konusunda güvenilir değilseniz, kendi malınız olmak üzere size kim bir şey verir?"},{"n":"13","t":"\"Hiçbir uşak iki efendiye kulluk edemez. Ya birinden nefret edip öbürünü sever, ya da birine bağlanıp öbürünü hor görür. Siz hem Tanrı'ya, hem paraya kulluk edemezsiniz.\""},{"n":"14","t":"Parayı seven Ferisiler bütün bu sözleri duyunca İsa'yla alay etmeye başladılar."},{"n":"15","t":"O da onlara şöyle dedi: \"Siz insanlar önünde kendinizi temize çıkarıyorsunuz, ama Tanrı yüreğinizi biliyor. İnsanların gururlandıkları ne varsa, Tanrı'ya iğrenç gelir."},{"n":"16","t":"\"Kutsal Yasa ve peygamberlerin devri Yahya'nın zamanına dek sürdü. O zamandan bu yana Tanrı'nın Egemenliği müjdeleniyor ve herkes oraya zorla girmeye çalışıyor."},{"n":"17","t":"Göğün ve yerin ortadan kalkması, Kutsal Yasa'nın ufacık bir noktasının yok olmasından daha kolaydır."},{"n":"18","t":"\"Karısını boşayıp başkasıyla evlenen her adam zina etmiş olur. Kocasından boşanmış bir kadınla evlenen de zina etmiş olur."},{"n":"19","h":"Dilenci ile zengin adam","t":"\"Zengin bir adam varmış. Mor renkli ve ince ketenden giysiler giyer, bolluk içinde her gün eğlenirmiş."},{"n":"20-21","t":"Buna karşılık, her tarafı yara içinde olup bu zenginin kapısının önüne bırakılan Lazar adında yoksul bir adam, zenginin sofrasından düşen kırıntılarla karnını doyurmaya can atarmış. Bir yandan da köpekler gelip onun yaralarını yalarmış."},{"n":"22","t":"\"Bir gün yoksul adam ölmüş, melekler onu alıp İbrahim'in yanına götürmüşler. Sonra zengin adam da ölmüş ve gömülmüş."},{"n":"23","t":"Ölüler diyarında ıstırap çeken zengin adam başını kaldırıp uzakta İbrahim'i ve onun yanında Lazar'ı görmüş."},{"n":"24","t":"'Ey babamız İbrahim, acı bana!' diye seslenmiş. 'Lazar'ı gönder de parmağının ucunu suya batırıp dilimi serinletsin. Bu alevlerin içinde azap çekiyorum.'"},{"n":"25","t":"\"İbrahim, 'Oğlum' demiş, 'yaşamın boyunca senin iyilik payını, Lazar'ın da kötülük payını aldığını unutma. Şimdiyse o burada teselli ediliyor, sen de azap çekiyorsun."},{"n":"26","t":"Üstelik, sizinle bizim aramıza öyle büyük bir uçurum yerleştirilmiştir ki, ne buradan size geçmek isteyenler geçebilir, ne de oradan kimse bize geçebilir.'"},{"n":"27","t":"\"Zengin adam şöyle demiş: 'Öyleyse baba, sana rica ederim, Lazar'ı babamın evine gönder."},{"n":"28","t":"Çünkü beş kardeşim var. Lazar onları uyarsın ki, onlar da bu ıstırap yerine düşmesinler.'"},{"n":"29","t":"\"İbrahim, 'Onlarda Musa'nın ve peygamberlerin sözleri var, onları dinlesinler' demiş."},{"n":"30","t":"\"Zengin adam, 'Hayır, İbrahim baba, dinlemezler!' demiş. 'Ancak ölüler arasından biri onlara giderse, tövbe ederler.'"},{"n":"31","t":"\"İbrahim ona, 'Eğer Musa ile peygamberleri dinlemezlerse, ölüler arasından biri dirilse bile ikna olmazlar' demiş.\""}]},{"ch":17,"verses":[{"n":"1","t":"İsa öğrencilerine şöyle dedi: \"İnsanı günaha düşüren tuzakların olması kaçınılmazdır. Ama bu tuzaklara aracılık eden kişinin vay haline!"},{"n":"2","t":"Böyle bir kişi bu küçüklerden birini günaha düşüreceğine, boynuna bir değirmen taşı geçirilip denize atılsa, kendisi için daha iyi olur."},{"n":"3","t":"Yaşayışınıza dikkat edin! Kardeşiniz günah işlerse, onu azarlayın; tövbe ederse, bağışlayın."},{"n":"4","t":"Günde yedi kez size karşı günah işler ve yedi kez size geri gelip, 'Tövbe ediyorum' derse, onu bağışlayın.\""},{"n":"5","t":"Elçiler Rab'be, \"İmanımızı artır!\" dediler."},{"n":"6","t":"Rab şöyle dedi: \"Bir hardal tanesi kadar imanınız olsa, şu dut ağacına, 'Kökünden sökül ve denizin içine dikil' dersiniz, o da sözünüzü dinler."},{"n":"7","t":"\"Hanginizin çift süren ya da çobanlık eden bir kölesi olur da, tarladan dönüşünde ona, 'Çabuk gel, sofraya otur' der?"},{"n":"8","t":"Tersine ona, 'Yemeğimi hazırla, kuşağını bağla ve ben yiyip içerken bana hizmet et. Ondan sonra da sen yiyip içersin' demez mi?"},{"n":"9","t":"Verdiği buyrukları yerine getirdi diye köleye teşekkür eder mi hiç?"},{"n":"10","t":"Siz de böylece, size verilen buyrukların hepsini yerine getirdikten sonra, 'Biz değersiz kullarız; sadece yapmamız gerekeni yaptık' deyin.\""},{"n":"11","h":"On cüzamlı","t":"Kudüs'e doğru yoluna devam eden İsa, Samiriye ile Celile arasındaki sınır bölgesinden geçiyordu."},{"n":"12-13","t":"Köyün birine girerken O'nu cüzamlı on adam karşıladı. Bunlar uzakta durarak, \"İsa, Efendimiz, halimize acı!\" diye seslendiler."},{"n":"14","t":"İsa onları görünce, \"Gidin, kâhinlere görünün\" dedi. Adamlar yolda giderken cüzamdan temizlendiler."},{"n":"15-16","t":"Onlardan biri, iyileştiğini görünce yüksek sesle Tanrı'yı yücelterek geri döndü, yüzüstü İsa'nın ayaklarına kapanıp O'na teşekkür etti. Bu adam Samiriyeliydi."},{"n":"17","t":"İsa, \"İyileşenler on kişi değil miydi?\" diye sordu. \"Diğer dokuzu nerede?"},{"n":"18","t":"Tanrı'yı yüceltmek için bu yabancıdan başka geri dönen olmadı mı?\""},{"n":"19","t":"Sonra adama, \"Ayağa kalk, git\" dedi. \"İmanın seni kurtardı.\""},{"n":"20","h":"Tanrı'nın Egemenliği ne zaman gelecek?","t":"Ferisiler İsa'ya, \"Tanrı'nın Egemenliği ne zaman gelecek?\" diyesordular.\nİsa onlara şöyle cevap verdi: \"Tanrı'nın Egemenliği göze görünür bir şekilde gelmez."},{"n":"21","t":"İnsanlar da, 'İşte burada' ya da, 'İşte şurada' demeyecekler. Çünkü Tanrı'nın Egemenliği içinizdedir.\""},{"n":"22","t":"İsa öğrencilerine şöyle dedi: \"Öyle günler gelecek ki, siz İnsanoğlu'nun günlerinden birini görmeyi özleyeceksiniz, ama görmeyeceksiniz."},{"n":"23","t":"İnsanlar size, 'İşte orada', 'İşte burada' diyecekler. Gitmeyin, onların arkasından koşmayın."},{"n":"24","t":"Şimşek çakıp göğü bir ucundan öbür ucuna dek nasıl aydınlatırsa, İnsanoğlu kendi gününde öyle olacaktır."},{"n":"25","t":"Ama önce O'nun çok acı çekmesi ve bu kuşak tarafından reddedilmesi gerekir."},{"n":"26","t":"\"Nuh'un günlerinde nasıl olduysa, İnsanoğlu'nun günlerinde de öyle olacak."},{"n":"27","t":"Nuh'un gemiye bindiği güne dek insanlar yiyip içiyor, evlenip evlendiriliyorlardı. Sonra tufan gelip hepsini yok etti."},{"n":"28","t":"Lut'un günlerinde de durum aynıydı. İnsanlar yiyip içiyor, alıp satıyor, tohum ekiyor, ev yapıyorlardı."},{"n":"29","t":"Ama Lut'un Sodom'dan ayrıldığı gün gökten ateşle kükürt yağdı ve hepsini yok etti."},{"n":"30","t":"\"İnsanoğlu'nun ortaya çıkacağı gün durum aynı olacaktır."},{"n":"31","t":"O gün damda olan, evdeki eşyalarını almak için aşağı inmesin. Tarlada olan da geri dönmesin."},{"n":"32","t":"Lut'un karısını hatırlayın!"},{"n":"33","t":"Canını esirgemek isteyen onu yitirecek. Canını yitiren ise onu yaşatacaktır."},{"n":"34","t":"Size şunu söyleyeyim, o gece aynı yatakta olan iki kişiden biri alınacak, öbürü bırakılacak."},{"n":"35-36","t":"Birlikte buğday öğüten iki kadından biri alınacak, öbürü bırakılacak.\""},{"n":"37","t":"Onlar İsa'ya, \"Bu olaylar nerede olacak, Rab?\" diye sordular.\nO da onlara, \"Leş neredeyse, akbabalar da oraya üşüşecek\" dedi."}]},{"ch":18,"verses":[{"n":"1-2","t":"İsa öğrencilerine, hiç usanmadan, her zaman dua etmeleri gerektiğini belirten şu benzetmeyi anlattı: \"Kentin birinde Tanrı'dan korkmayan, insana saygı duymayan bir yargıç varmış."},{"n":"3","t":"Yine o kentte bir dul kadın varmış. Yargıca sürekli gidip, 'Davacı olduğum kişiden hakkımı al' diyormuş."},{"n":"4-5","t":"\"Yargıç bir süre ilgisiz kalmış. Ama sonunda kendi kendine, 'Ben her ne kadar Tanrı'dan korkmaz, insana saygı duymazsam da, bu dul kadın beni rahatsız ettiği için onun hakkını alacağım. Yoksa tekrar tekrar gelip beni canımdan bezdirecek' demiş.\""},{"n":"6","t":"Rab şöyle devam etti: \"Adaletsiz yargıcın ne söylediğini duydunuz."},{"n":"7","t":"Tanrı da, gece gündüz kendisine yakaran seçilmişlerinin hakkını almayacak mı? Onları çok bekletecek mi?"},{"n":"8","t":"Size şunu söyleyeyim, onların hakkını tez alacaktır. Ama İnsanoğlu geldiği zaman acaba yeryüzünde iman bulacak mı?\""},{"n":"9-10","h":"Ferisi ve vergi görevlisi","t":"Kendi doğruluklarına güvenip başkalarına tepeden bakan bazıkişilere İsa şu benzetmeyi anlattı: \"Biri Ferisi, öbürü vergi görevlisi iki kişi dua etmek üzere tapınağa çıkmış."},{"n":"11","t":"Ferisi ayakta dikilip kendi kendine şöyle dua etmiş: 'Tanrım, diğer insanlar gibi soyguncu, hak yiyici ve zina edici olmadığım için, hatta şu vergi görevlisi gibi olmadığım için sana şükrederim."},{"n":"12","t":"Haftada iki gün oruç tutuyor, bütün kazancımın ondalığını veriyorum.'"},{"n":"13","t":"\"Vergi görevlisi ise uzakta durmuş, gözlerini göğe doğru kaldırmak bile istemiyor, ancak göğsünü döverek, 'Tanrım, ben günahkâra merhamet et' diyormuş."},{"n":"14","t":"\"Size şunu söyleyeyim, Ferisi'den çok, bu adam aklanmış olarak evine dönmüş. Çünkü kendini yücelten herkes alçaltılacak, kendini alçaltan ise yüceltilecektir.\""},{"n":"15","h":"İsa küçük çocukları kutsuyor","t":"Bazıları bebekleri bile İsa'ya getiriyor, onlara dokunmasını istiyorlardı. Bunu gören öğrenciler onları azarladılar."},{"n":"16","t":"Ama İsa çocukları yanına çağırarak, \"Bırakın, çocuklar bana gelsin, onlara engel olmayın!\" dedi. \"Çünkü Tanrı'nın Egemenliği böylelerinindir."},{"n":"17","t":"Size doğrusunu söyleyeyim, Tanrı'nın Egemenliğini bir çocuk gibi kabul etmeyen, bu egemenliğe asla giremez.\""},{"n":"18","h":"Zenginlik ve sonsuz yaşam","t":"İleri gelenlerden biri İsa'ya, \"İyi öğretmenim, sonsuz yaşama kavuşmak için ne yapmalıyım?\" diye sordu."},{"n":"19","t":"İsa ona, \"Bana neden iyi diyorsun?\" dedi. \"İyi olan tek biri var, O da Tanrı'dır."},{"n":"20","t":"O'nun buyruklarını biliyorsun: 'Zina etme, adam öldürme, hırsızlık yapma, yalan yere tanıklık etme, annene babana saygı göster.'\""},{"n":"21","t":"\"Bunların hepsini gençliğimden beri yerine getiriyorum\" dedi adam."},{"n":"22","t":"İsa bunu duyunca ona, \"Hâlâ bir eksiğin var\" dedi. \"Neyin varsa hepsini sat, parasını yoksullara dağıt; böylece göklerde hazinen olur. Sonra gel, beni izle.\""},{"n":"23","t":"Adam bu sözleri duyunca çok üzüldü. Çünkü son derece zengindi."},{"n":"24","t":"Onun üzüntüsünü gören İsa, \"Varlıklı kişilerin Tanrı Egemenliğine girmesi ne kadar güç!\" dedi."},{"n":"25","t":"\"Nitekim devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliğine girmesinden daha kolaydır.\""},{"n":"26","t":"Bunu işitenler, \"Öyleyse kim kurtulabilir?\" dediler."},{"n":"27","t":"İsa, \"İnsanlar için imkânsız olan, Tanrı için mümkündür\" dedi."},{"n":"28","t":"Petrus, \"Bak, biz her şeyimizi bırakıp senin ardından geldik\" dedi."},{"n":"29-30","t":"İsa onlara şöyle dedi: \"Size doğrusunu söyleyeyim, Tanrı'nın Egemenliği uğruna evini, karısını, kardeşlerini, anne babasını ya da çocuklarını bırakıp da bu çağda bunların kat kat fazlasına ve gelecek çağda sonsuz yaşama kavuşmayacak hiç kimse yoktur.\""},{"n":"31","h":"İsa, ölüp dirileceğini üçüncü kez bildiriyor","t":"İsa, Onikileri bir yana çekip onlara şöyle dedi: \"Şimdi Kudüs'e gidiyoruz. Peygamberlerin İnsanoğlu'yla ilgili yazdıklarının tümü yerine gelecektir."},{"n":"32-33","t":"O, diğer uluslara teslim edilecek. O'nunla alay edecek, O'na hakaret edecekler; üzerine tükürecek ve O'nu kamçılayıp öldürecekler. Ne var ki O, üçüncü gün dirilecek.\""},{"n":"34","t":"Öğrenciler bu sözlerden hiçbir şey anlamadılar. Bu sözlerin anlamı onlardan gizlenmişti ve anlatılanları kavrayamıyorlardı."},{"n":"35","h":"Bir körün gözleri açılıyor","t":"İsa Eriha'ya yaklaşırken kör bir adam yol kenarında oturmuş dileniyordu."},{"n":"36","t":"Adam oradan geçen kalabalığı duyunca, \"Ne oluyor?\" diye sordu."},{"n":"37","t":"Ona, \"Nasıralı İsa geçiyor\" diye açıklamada bulundular."},{"n":"38","t":"O da, \"Ey Davut Oğlu İsa, halime acı!\" diye bağırdı."},{"n":"39","t":"Önden gidenler onu azarlayarak susturmak istedilerse de o, \"Ey Davut Oğlu, halime acı!\" diyerek daha çok bağırdı."},{"n":"40-41","t":"İsa durdu, adamın kendisine getirilmesini buyurdu. Adam yaklaşınca İsa ona, \"Senin için ne yapmamı istiyorsun?\" diye sordu.\nO da, \"Rab, gözlerim görsün\" dedi."},{"n":"42","t":"İsa ona, \"Gözlerin görsün\" dedi. \"İmanın seni kurtardı.\""},{"n":"43","t":"Adam o anda yeniden görmeye başladı ve Tanrı'yı yücelterek İsa'nın ardından gitti. Bunu gören bütün halk Tanrı'ya övgüler sundu."}]},{"ch":19,"verses":[{"n":"1","t":"İsa Eriha'ya girmiş kentin içinden geçiyordu."},{"n":"2","t":"Orada vergi görevlilerinin başı olan, Zakay adında zengin bir adam vardı."},{"n":"3","t":"İsa'nın kim olduğunu görmek istiyor, ama boyu kısa olduğu için kalabalıktan ötürü göremiyordu."},{"n":"4","t":"İsa'yı görebilmek için ileriye koşup bir yabani incir ağacına tırmandı. Çünkü İsa oradan geçecekti."},{"n":"5","t":"İsa oraya varınca yukarı bakıp ona, \"Zakay, çabuk aşağı in!\" dedi. \"Bugün senin evinde kalmam gerek.\""},{"n":"6","t":"Zakay hızla aşağı indi ve sevinç içinde İsa'yı evine buyur etti."},{"n":"7","t":"Bunu görenlerin hepsi söylenmeye başladı: \"Gidip günahkâr birine konuk oldu!\" dediler."},{"n":"8","t":"Zakay ayağa kalkıp Rab'be şöyle dedi: \"Rab, işte malımın yarısını yoksullara veriyorum. Bir kimseden haksızlıkla bir şey aldımsa, dört katını geri vereceğim.\""},{"n":"9","t":"İsa dedi ki, \"Bu ev bugün kurtuluşa kavuştu. Çünkü bu adam da İbrahim'in bir oğludur."},{"n":"10","t":"Nitekim İnsanoğlu, kaybolmuş olanı arayıp kurtarmak için geldi.\""},{"n":"11","h":"Güvenilirlik sınavı","t":"Oradakiler bu sözleri dinlerken İsa konuşmasını bir benzetmeyle sürdürdü. Çünkü Kudüs'e yaklaşmıştı ve onlar, Tanrı'nın Egemenliğinin hemen ortaya çıkacağını sanıyorlardı."},{"n":"12","t":"Bu nedenle İsa şöyle dedi: \"Soylu bir adam, kral atanıp dönmek üzere uzak bir ülkeye gitmiş."},{"n":"13","t":"Gitmeden önce kölelerinden onunu çağırıp onlara birer mina vermiş. 'Ben dönünceye dek bu paraları işletin' demiş."},{"n":"14","t":"\"Ne var ki, ülkesinin halkı adamdan nefret ediyormuş. Arkasından temsilciler göndererek, 'Bu adamın üzerimize kral olmasını istemiyoruz' diye haber iletmişler."},{"n":"15","t":"\"Adam kral atanmış olarak geri döndüğünde, parayı vermiş olduğu köleleri çağırtıp ne kazandıklarını öğrenmek istemiş."},{"n":"16","t":"Birincisi gelmiş, 'Efendimiz' demiş, 'senin bir minan on mina daha kazandı.'"},{"n":"17","t":"\"Efendisi ona, 'Aferin, iyi köle!' demiş. 'Küçücük bir işte güvenilir olduğunu gösterdiğin için sen on kent üzerinde yetkili olacaksın.'"},{"n":"18","t":"\"İkincisi gelip, 'Efendimiz, senin bir minan beş mina daha kazandı' demiş."},{"n":"19","t":"\"Efendisi ona da, 'Sen beş kent üzerinde yetkili olacaksın' demiş."},{"n":"20","t":"\"Bir diğeri gelmiş, 'Efendimiz' demiş, 'işte senin minan! Onu bir mendile sarıp sakladım."},{"n":"21","t":"Çünkü senden korktum, sert adamsın; kendinden koymadığını alır, ekmediğini biçersin.'"},{"n":"22","t":"\"Efendisi ona, 'Ey kötü köle, seni kendi ağzından çıkan sözle yargılayacağım' demiş. 'Kendinden koymadığını alan, ekmediğini biçen sert bir adam olduğumu biliyordun ha?"},{"n":"23","t":"Öyleyse neden paramı faizcilere vermedin? Ben de geldiğimde onu faiziyle geri alırdım.'"},{"n":"24","t":"\"Sonra çevrede duranlara, 'Elindeki minayı alın, on minası olana verin' demiş."},{"n":"25","t":"\"Ona, 'Efendimiz' demişler, 'onun zaten on minası var!'"},{"n":"26","t":"\"O da, 'Size şunu söyleyeyim, kimde varsa ona daha çok verilecek. Ama kimde yoksa, kendisinde olan da elinden alınacak' demiş."},{"n":"27","t":"'Beni kral olarak istemeyen o düşmanlarıma gelince, onları buraya getirin ve gözümün önünde kılıçtan geçirin!'\""},{"n":"28","h":"İsa'nın Kudüs'e girişi","t":"İsa, bu sözleri söyledikten sonra önden yürüyerek Kudüs'e doğru ilerledi."},{"n":"29-30","t":"Zeytin dağının yamacında bulunan Beytfacı ile Beytanya'ya yaklaştığında öğrencilerinden ikisini şu sözlerle köye gönderdi: \"Karşıdaki köye gidin. Köye girince, üzerine daha hiç kimsenin binmediği, bağlı duran bir sıpa bulacaksınız. Onu çözüp bana getirin."},{"n":"31","t":"Biri size, 'Onu niçin çözüyorsunuz?' diye sorarsa, 'Rab'bin ona ihtiyacı var' dersiniz.\""},{"n":"32","t":"Gönderilen öğrenciler gittiler, her şeyi İsa'nın kendilerine anlattığı gibi buldular."},{"n":"33","t":"Sıpayı çözerlerken hayvanın sahipleri onlara, \"Sıpayı niye çözüyorsunuz?\" dediler."},{"n":"34","t":"Onlar da, \"Rab'bin ona ihtiyacı var\" karşılığını verdiler."},{"n":"35","t":"Sıpayı İsa'ya getirdiler, üzerine kendi giysilerini atarak İsa'yıüstüne bindirdiler."},{"n":"36","t":"İsa ilerlerken halk, giysilerini yola seriyordu."},{"n":"37","t":"İsa Zeytin dağından aşağı inen yola yaklaştığı sırada, öğrencilerinden oluşan kalabalığın tümü, görmüş oldukları bütün mucizelerden ötürü, sevinç içinde yüksek sesle Tanrı'yı övmeye başladılar."},{"n":"38","t":"\"Rab'bin adıyla gelen Kral'a övgüler olsun!\nGökte esenlik, en yücelerde yücelik olsun!\" diyorlardı."},{"n":"39","t":"Kalabalığın içinden bazı Ferisiler O'na, \"Öğretmen, öğrencilerini sustur!\" dediler."},{"n":"40","t":"İsa, \"Size şunu söyleyeyim, bunlar susacak olsa, taşlar bağıracaktır!\" diye karşılık verdi."},{"n":"41","h":"İsa, Kudüs için ağlıyor","t":"İsa Kudüs'e yaklaşıp kenti görünce orası için ağladı."},{"n":"42","t":"\"Keşke bugün sen de esenliğe giden yolu bilseydin\" dedi. \"Ama bu şimdi senin gözlerinden gizlenmiştir."},{"n":"43","t":"Senin için öyle günler gelecek ki, düşmanların seni setlerle çevirecek, kuşatıp her yandan sıkıştıracaklar."},{"n":"44","t":"Seni ve sende oturan çocuklarını yere çalacak, sende taş üstünde taş bırakmayacaklar. Çünkü Tanrı'nın senin yardımına geldiği zamanı farketmedin.\""},{"n":"45","h":"İsa satıcıları tapınaktan kovuyor","t":"Sonra İsa tapınağın avlusuna girerek satıcıları dışarı kovmaya başladı."},{"n":"46","t":"Onlara, \"'Benim evim dua evi olacak' diye yazılmıştır. Ama siz burayı haydut inine çevirdiniz\" dedi."},{"n":"47-48","t":"İsa her gün tapınakta ders veriyordu. Başkâhinler, din bilginleri ve halkın ileri gelenleri ise O'nu yok etmek istiyor, ama bunu nasıl yapacaklarını kestiremiyorlardı. Çünkü bütün halk O'nu can kulağıyla dinliyordu."}]},{"ch":20,"verses":[{"n":"1","t":"O günlerden birinde, İsa tapınakta halka ders verip Müjde'yi duyururken, başkâhinler ve din bilginleri, ihtiyarlarla birlikte çıkageldiler."},{"n":"2","t":"O'na, \"Söyle bize, bunları hangi yetkiyle yapıyorsun? Bu yetkiyi sana kim verdi?\" diye sordular."},{"n":"3-4","t":"İsa onlara şu karşılığı verdi: \"Ben de size bir soru soracağım. Söyleyin bana, Yahya'nın vaftiz etme yetkisi Tanrı'dan mıydı, insanlardan mıydı?\""},{"n":"5","t":"Bunu aralarında şöyle tartıştılar: \"'Tanrı'dan' dersek, 'Ona niçin inanmadınız?' diyecek."},{"n":"6","t":"Yok eğer 'İnsanlardan' dersek, bütün halk bizitaşa tutacak. Çünkü Yahya'nın peygamber olduğuna inanmışlardır.\""},{"n":"7","t":"Sonunda, \"Nereden olduğunu bilmiyoruz\" cevabını verdiler."},{"n":"8","t":"İsa da onlara, \"Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim\" dedi."},{"n":"9","h":"Bağ kiracıları benzetmesi","t":"İsa sözüne devam ederek halka şu benzetmeyi anlattı: \"Adamın biri bağ dikmiş ve bunu bağcılara kiralayıp uzun bir süre için yolculuğa çıkmış."},{"n":"10","t":"Mevsimi gelince, bağın ürününden kendisine düşen payı vermeleri için bağcılara bir köle yollamış. Ama bağcılar köleyi dövmüş ve eli boş göndermişler."},{"n":"11","t":"Bağ sahibi başka bir köle daha yollamış. Bağcılar onu da dövüp aşağılamış ve eli boş göndermişler."},{"n":"12","t":"Adam bir üçüncüsünü yollamış, bağcılar onu da yaralayıp kovmuşlar."},{"n":"13","t":"\"Bağın sahibi, 'Ne yapsam ki?' demiş. 'Sevgili oğlumu göndereyim. Belki onu sayarlar.'"},{"n":"14","t":"\"Ama bağcılar onu görünce aralarında şöyle konuşmuşlar: 'Mirasçı bu; onu öldürelim de miras bize kalsın.'"},{"n":"15","t":"Böylece, onu bağdan dışarı atıp öldürmüşler.\n\"Bu durumda bağın sahibi onlara ne yapacak?"},{"n":"16","t":"Gelip o bağcıları yok edecek, bağı da başkalarına verecek.\"\nHalk bunu duyunca, \"Tanrı korusun!\" dedi."},{"n":"17","t":"İsa gözlerini onlara dikip şöyle dedi: \"Öyleyse Kutsal Yazılardaki şu sözün anlamı nedir?\n'Yapıcıların reddettiği taş,\nişte köşenin baş taşı oldu.'"},{"n":"18","t":"O taşın üzerine düşen herkes paramparça olacak, taş da kimin üzerine düşerse onu ezip toz edecek.\""},{"n":"19","t":"İsa'nın bu benzetmeyi kendilerine karşı anlattığını farkeden din bilginleriyle başkâhinler O'nu o anda yakalamak istediler, ama halkın tepkisinden korktular."},{"n":"20","h":"Sezar'ın hakkı Sezar'a","t":"İsa'yı dikkatle gözlüyorlardı. O'na, kendilerine doğru kişiler süsü veren muhbirler gönderdiler. O'nu, söyleyeceği bir sözle tuzağa düşürmek ve böylelikle valinin yetki ve yargısına teslim etmek istiyorlardı."},{"n":"21-22","t":"Muhbirler O'na, \"Öğretmenimiz, senin doğru olanı söyleyip öğrettiğini, insanlar arasında ayrım yapmaksızın Tanrı yolunu dürüstçe öğrettiğini biliyoruz. Sezar'a vergi vermemiz Kutsal Yasa'ya uygun mu, değil mi?\" diye sordular."},{"n":"23-24","t":"Onların hilesini anlayan İsa onlara, \"Bana bir dinar gösterin\" dedi. \"Üzerindeki resim ve yazı kimin?\"\n\"Sezar'ın\" dediler."},{"n":"25","t":"O da onlara, \"Öyleyse Sezar'ın hakkını Sezar'a, Tanrı'nın hakkını da Tanrı'ya verin\" dedi."},{"n":"26","t":"Onlar İsa'yı, halkın önünde söylediği sözlerle tuzağa düşüremediler. Verdiği cevaba şaşarak susup kaldılar."},{"n":"27-28","h":"Dirilişle ilgili soru","t":"Ölümden sonra diriliş olmadığını söyleyen Sadukilerden bazıları İsa'ya gelip şunu sordular: \"Öğretmenimiz, Musa yazılarında bize şöyle buyurmuştur: 'Eğer bir adamın evli olan kardeşi çocuksuz ölürse, o adam ölenin karısını alıp soyunu sürdürsün.'"},{"n":"29","t":"Yedi kardeş vardı. Birincisi kendine bir eş aldı, ama çocuksuz öldü."},{"n":"30-31","t":"İkincisi de, üçüncüsü de kadını aldı; böylece kardeşlerin yedisi de çocuk bırakmadan öldü."},{"n":"32","t":"Son olarak kadın da öldü."},{"n":"33","t":"Buna göre, diriliş günü kadın bunlardan hangisinin karısı olacak? Çünkü yedisi de onunla evlendi.\""},{"n":"34","t":"İsa onlara şöyle dedi: \"Bu çağın insanları evlenip evlendirilirler."},{"n":"35","t":"Ama gelecek çağa ve ölülerin dirilişine erişmeye layık görülenler ne evlenir, ne evlendirilir."},{"n":"36","t":"Bir daha ölmeleri de söz konusu değildir. Çünkü meleklere benzerler ve dirilişin çocukları olarak Tanrı'nın çocuklarıdırlar."},{"n":"37","t":"Musa bile alevlenen çalıyla ilgili bölümde Rab için, 'İbrahim'in Tanrısı, İshak'ın Tanrısı ve Yakup'un Tanrısı' deyimini kullanarak ölülerin dirileceğine işaret etmişti."},{"n":"38","t":"Tanrı ölülerin değil, yaşayanların Tanrısıdır. Çünkü O'na göre bütün insanlar yaşamaktadır.\""},{"n":"39-40","t":"Artık O'na başka soru sormaya cesaret edemeyen din bilginlerinden bazıları, \"Öğretmenimiz, güzel konuştun\" dediler."},{"n":"41","h":"Mesih kimin oğlu?","t":"İsa onlara şöyle dedi: \"Nasıl oluyor da, 'Mesih Davut'un Oğludur' diyorlar?"},{"n":"42-43","t":"Çünkü Davut'un kendisi Mezmurlar kitabında şöyle diyor:\n'Rab Rabbime dedi ki,\nBen düşmanlarını\nsenin ayaklarının altına serinceye dek\nsağımda otur.'"},{"n":"44","t":"Davut O'ndan 'Rab' diye söz ettiğine göre, O nasıl Davut'un Oğlu olur?\""},{"n":"45-46","t":"Bütün halk dinlerken İsa öğrencilerine şöyle dedi: \"Uzun kaftanlar içinde dolaşmaktan hoşlanan, meydanlarda selamlanmaya, havralarda en seçkin yerlere, şölenlerde başköşelere kurulmaya bayılan din bilginlerinden sakının."},{"n":"47","t":"Dul kadınların malını mülkünü sömüren, gösteriş için uzun uzun dua eden bu kişilerin cezası daha da ağır olacaktır.\""}]},{"ch":21,"verses":[{"n":"1","t":"İsa başını kaldırdı ve bağış kutusuna bağışlarını atan zenginleri gördü."},{"n":"2-3","t":"Fakir bir dul kadının da oraya iki bakır para attığını görünce, \"Size gerçeği söyleyeyim\" dedi, \"bu yoksul dul kadın herkesten daha çok verdi."},{"n":"4","t":"Çünkü bunların hepsi kutuya, zenginliklerinden artanı attılar. Bu kadın ise yoksulluğuna rağmen, geçinmek için elinde ne varsa hepsini verdi.\""},{"n":"5-6","h":"Sonun belirtileri","t":"Bazı kişiler tapınağın nasıl güzel taşlar ve adaklarla süslenmiş olduğundan söz edince İsa, \"Burada gördüklerinize gelince, öyle günler gelecek ki, taş üstünde taş kalmayacak, hepsi yıkılacak!\" dedi."},{"n":"7","t":"Onlar da O'na, \"Peki, öğretmenimiz, bu dediklerin ne zaman olacak? Bunların gerçekleşmek üzere olduğunu gösteren belirti ne olacak?\" diye sordular."},{"n":"8","t":"İsa, \"Sakın sizi saptırmasınlar\" dedi. \"Birçokları, 'Ben O'yum' ve 'Zaman yaklaştı' diyerek benim adımla gelecekler. Onların ardından gitmeyin."},{"n":"9","t":"Savaş ve isyan haberleri duyunca telaşlanmayın. Önce bunların olması gerek. Ama son hemen gelmez.\""},{"n":"10","t":"Sonra onlara şöyle dedi: \"Ulus ulusa, devlet devlete savaş açacak."},{"n":"11","t":"Şiddetli depremler, yer yer kıtlıklar ve salgın hastalıklar, korkunç olaylar ve gökte olağanüstü belirtiler olacak."},{"n":"12","t":"\"Ama bütün bu olaylardan önce sizi yakalayıp zulmedecekler. Sizi havralara teslim edecek, zindanlara atacaklar. Benim adımdan ötürü kralların ve valilerin önüne çıkarılacaksınız."},{"n":"13","t":"Bu size tanıklık etme fırsatı olacak."},{"n":"14","t":"Buna göre kendinizi nasıl savunacağınızı önceden düşünmemekte kararlı olun."},{"n":"15","t":"Çünkü ben size öyle bir konuşma yeteneği, öyle bir bilgelik vereceğim ki, size karşı çıkanların hiçbiri buna karşı direnemeyecek, bir şey diyemeyecek."},{"n":"16","t":"Anne babalarınız, kardeşleriniz, akraba ve dostlarınız bile sizi ele verecek ve bazılarınızı öldürtecekler."},{"n":"17","t":"Benim adımdan ötürü herkes sizden nefret edecek."},{"n":"18","t":"Ne var ki, başınızdaki saçlardan bir tel bile yok olmayacaktır."},{"n":"19","t":"Dayanmakla canlarınızı kazanacaksınız."},{"n":"20","t":"\"Kudüs'ün ordular tarafından kuşatıldığını görünce bilin ki, kentin yıkılacağı zaman yaklaşmıştır."},{"n":"21","t":"O zaman Yahudiye'de olanlar dağlara kaçsın, kentte olanlar dışarı çıksın, tarlalarda bulunanlar da kente girmesin."},{"n":"22","t":"Çünkü o günler, yazılmış olanların tümünün gerçekleşeceği ceza günleridir."},{"n":"23","t":"O günlerde gebe olan, çocuk emziren kadınların vay haline! Çünkü ülke büyük sıkıntıya düşecek ve bu halk gazaba uğrayacaktır."},{"n":"24","t":"Kılıçtan geçirilecek, tutsak olarak tüm uluslar arasına sürülecekler. Kudüs, diğer ulusların dönemleri tamamlanıncaya dek onların ayakları altında çiğnenecektir."},{"n":"25","t":"\"Güneşte, ayda ve yıldızlarda belirtiler görülecek. Yeryüzünde uluslar denizin ve dalgaların uğultusundan şaşkına dönecek, dehşete düşecekler."},{"n":"26","t":"Dünyanın üzerine gelecek felaketleri bekleyen insanlar korkudan bayılacak. Çünkü göksel güçler sarsılacak."},{"n":"27","t":"O zamanİnsanoğlu'nun bulut içinde büyük güç ve görkemle geldiğini görecekler."},{"n":"28","t":"Bu olaylar gerçekleşmeye başlayınca doğrulun ve başlarınızı kaldırın. Çünkü kurtuluşunuz yakın demektir.\""},{"n":"29","t":"İsa onlara şu benzetmeyi anlattı: \"İncir ağacına ya da herhangi bir ağaca bakın."},{"n":"30","t":"Bunların yapraklandığını gördüğünüz zaman yaz mevsiminin pek yakın olduğunu kendiliğinizden anlarsınız."},{"n":"31","t":"Aynı şekilde, bu olayların gerçekleştiğini gördüğünüzde bilin ki, Tanrı'nın Egemenliği yakındır."},{"n":"32","t":"Size doğrusunu söyleyeyim, bütün bunlar olmadan, bu kuşak ortadan kalkmayacak."},{"n":"33","t":"Gök ve yer ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır."},{"n":"34-35","t":"\"Kendinize dikkat edin! Yürekleriniz sefahat, sarhoşluk ve bu yaşamın kaygılarıyla ağırlaşmasın. O gün, üzerinize bir tuzak gibi aniden inmesin. Çünkü o gün bütün yeryüzünde yaşayan herkesin üzerine gelecektir."},{"n":"36","t":"Her an uyanık durun, gerçekleşmek üzere olan bütün bu olaylardan kurtulabilmek ve İnsanoğlu'nun önünde durabilmek için dua edin.\""},{"n":"37","t":"İsa gündüz tapınakta ders veriyor, geceleri ise kentten dışarı çıkıp Zeytin dağında sabahlıyordu."},{"n":"38","t":"Sabah erkenden bütün halk O'nu tapınakta dinlemek için O'na akın ediyordu."}]},{"ch":22,"verses":[{"n":"1","t":"Fısıh denilen Mayasız Ekmek bayramı yaklaşmıştı."},{"n":"2","t":"Başkâhinlerle din bilginleri İsa'yı ortadan kaldırmak için bir yol arıyor, ama halktan korkuyorlardı."},{"n":"3","t":"Şeytan, Onikilerden biri olup İskariyot diye adlandırılan Yahuda'nın yüreğine girdi."},{"n":"4","t":"Yahuda gitti, başkâhinler ve tapınak koruyucularının komutanlarıyla İsa'yı nasıl ele verebileceğini görüştü."},{"n":"5","t":"Onlar buna sevindiler ve kendisine para vermeye razı oldular."},{"n":"6","t":"Bunu kabul eden Yahuda, kalabalığın olmadığı bir zamanda İsa'yı ele vermek için fırsat kollamaya başladı."},{"n":"7","h":"Fısıh yemeği","t":"Fısıh kurbanının kesilmesi gereken Mayasız Ekmek günü geldi."},{"n":"8","t":"İsa, Petrus'la Yuhanna'yı şu sözlerle önden gönderdi: \"Gidin, Fısıh yemeğini yiyebilmemiz için hazırlık yapın.\""},{"n":"9","t":"O'na, \"Nerede hazırlık yapmamızı istersin?\" diye sordular."},{"n":"10-11","t":"İsa onlara, \"Bakın\" dedi, \"kente girdiğinizde karşınıza su testisi taşıyan bir adam çıkacak. Adamı, gideceği eve kadar izleyin ve evin sahibine şöyle deyin: 'Öğretmen, öğrencilerimle birlikte Fısıh yemeğini yiyeceğim konuk odası nerede? diye soruyor.'"},{"n":"12","t":"Ev sahibi size, üst katta, döşenmiş büyük bir oda gösterecek. Orada hazırlık yapın.\""},{"n":"13","t":"Onlar da gittiler, her şeyi İsa'nın kendilerine söylemiş olduğu gibi buldular ve Fısıh yemeği için hazırlık yaptılar."},{"n":"14-15","t":"Yemek saati gelince İsa, elçileriyle birlikte sofraya oturdu ve onlara şöyle dedi: \"Ben acı çekmeden önce bu Fısıh yemeğini sizinle birlikte yemeyi çok arzulamıştım."},{"n":"16","t":"Size şunu söyleyeyim, Fısıh yemeğini, Tanrı'nın Egemenliğinde yetkinliğe erişeceği zamana dek, bir daha yemeyeceğim.\""},{"n":"17","t":"Sonra kâseyi alarak şükretti ve, \"Bunu alın, aranızda paylaşın\" dedi."},{"n":"18","t":"\"Size şunu söyleyeyim, Tanrı'nın Egemenliği gelene dek, asmanın ürününden bir daha içmeyeceğim.\""},{"n":"19","t":"Sonra eline ekmek aldı, şükredip ekmeği böldü ve onlara verdi. \"Bu sizin uğrunuza feda edilen bedenimdir. Beni anmak için böyle yapın\" dedi."},{"n":"20","t":"Aynı şekilde, yemekten sonra kâseyi alıp şöyle dedi: \"Bu kâse, sizin uğrunuza akıtılan kanımla gerçekleşen yeni antlaşmadır."},{"n":"21","t":"Ama beni ele verecek olan kişinin eli şu anda benimkiyle birlikte sofradadır."},{"n":"22","t":"İnsanoğlu, belirlenmiş olan yoldan gidiyor. Ama O'nu ele veren adamın vay haline!\""},{"n":"23","t":"Elçiler, içlerinden hangisinin bunu yapacağını aralarında soruşturmaya başladılar."},{"n":"24","t":"Ayrıca aralarında hangisinin en büyük sayılacağı konusunda bir çekişme oldu."},{"n":"25","t":"İsa onlara, \"Ulusların kralları, kendi uluslarını egemenlik hırsıyla yönetirler. İleri gelenleri de kendilerine iyiliksever unvanını yakıştırırlar\" dedi."},{"n":"26","t":"\"Ama siz böyle olmayacaksınız. Aranızda en büyük olan, en küçük gibi olsun; yöneten, hizmet eden gibi olsun."},{"n":"27","t":"Hangisi daha büyük, sofrada oturan mı, hizmet eden mi? Sofrada oturan değil mi? Oysa ben aranızda hizmet eden biri gibi oldum."},{"n":"28","t":"Sınandığım zamanlarda benimle birlikte dayanmış olanlar sizlersiniz."},{"n":"29","t":"Babam bana nasıl bir egemenlik verdiyse, ben de size bir egemenlik veriyorum."},{"n":"30","t":"Öyle ki, egemenliğimde benim soframda yiyip içesiniz ve tahtlar üzerinde oturarak İsrail'in on iki oymağını yargılayasınız."},{"n":"31","t":"\"Simun, Simun, Şeytan sizleri buğday gibi kalburdan geçirmek için izin almıştır."},{"n":"32","t":"Ama ben, imanını yitirmeyesin diye senin için dua ettim. Geri döndüğün zaman kardeşlerini güçlendir.\""},{"n":"33","t":"Simun İsa'ya, \"Rab, ben seninle birlikte zindana da, ölüme de gitmeye hazırım\" dedi."},{"n":"34","t":"İsa, \"Sana şunu söyleyeyim, Petrus, bu gece horoz ötmeden sen beni tanıdığını üç kez inkâr edeceksin\" dedi."},{"n":"35","t":"Sonra İsa onlara, \"Ben sizi kesesiz, torbasız ve çarıksız gönderdiğim zaman, herhangi bir eksiğiniz oldu mu?\" diye sordu.\n\"Hiçbir eksiğimiz olmadı\" dediler."},{"n":"36","t":"O da onlara, \"Şimdi ise kesesi olan onu yanına alsın, torbası olan da onu alsın\" dedi. \"Kılıcı olmayan, abasını satıp bir kılıç alsın."},{"n":"37","t":"Size şunu söyleyeyim, yazılmış olan şu sözün bende yerine gelmesi gerekiyor: 'O, suçlularla bir sayıldı.' Gerçekten de benimle ilgili yazılmış olanlar yerine gelmektedir.\""},{"n":"38","t":"\"Rab, işte burada iki kılıç var\" dediler.\nO da onlara, \"Yeter!\" dedi."},{"n":"39","h":"Zeytin dağındaki dua","t":"İsa dışarı çıktı, her zamanki gibi Zeytin dağına gitti. Öğrenciler de O'nun ardından gittiler."},{"n":"40","t":"Oraya varınca İsa onlara, \"Dua edin ki ayartılmayasınız\" dedi."},{"n":"41-42","t":"Onlardan bir taş atımı kadar uzaklaştı ve diz çökerek şöyle dua etti: \"Baba, senin isteğine uygunsa, bu kâseyi benden uzaklaştır. Yine de benim değil, senin istediğin olsun.\""},{"n":"43","t":"Gökten bir melek İsa'ya görünerek O'nu güçlendirdi."},{"n":"44","t":"Derin bir acı içinde olan İsa daha hararetle dua etti. Teri, toprağa düşen kan damlalarına benziyordu."},{"n":"45","t":"İsa duadan kalkıp öğrencilerin yanına dönünce onları üzüntüden uyumuş buldu."},{"n":"46","t":"Onlara, \"Niçin uyuyorsunuz?\" dedi. \"Kalkıp dua edin ki ayartılmayasınız.\""},{"n":"47-48","h":"İsa tutuklanıyor","t":"İsa daha konuşurken bir kalabalık çıkageldi. Onikilerden biri, Yahuda adındaki kişi, kalabalığa öncülük ediyordu. İsa'yı öpmek üzere yaklaşınca İsa ona, \"Yahuda\" dedi, \"İnsanoğlu'nu bir öpücükle mi ele veriyorsun?\""},{"n":"49","t":"İsa'nın çevresindekiler olacakları anlayınca, \"Rab, kılıçla vuralım mı?\" dediler."},{"n":"50","t":"İçlerinden biri başkâhinin kölesine vurarak sağ kulağını uçurdu."},{"n":"51","t":"Ama İsa, \"Bırakın, yeter!\" dedi, ve kölenin kulağına dokunarak onu iyileştirdi."},{"n":"52","t":"İsa, üzerine yürüyen başkâhinler, tapınak koruyucularının komutanları ve ihtiyarlara şöyle dedi: \"Bir haydudun peşindeymiş gibi, kılıç ve sopalarla mı geldiniz?"},{"n":"53","t":"Her gün tapınakta sizinle birlikteydim, bana el sürmediniz. Ama bu saat sizindir, karanlığın egemen olduğu saattir.\""},{"n":"54","t":"İsa'yı tutukladılar, alıp başkâhinin evine götürdüler. Petrus onları uzaktan izliyordu."},{"n":"55","t":"Avlunun ortasında ateş yakıp çevresinde oturduklarında Petrus da gelip onlarla birlikte oturdu."},{"n":"56","t":"Bir hizmetçi kız ateşin ışığında oturan Petrus'u gördü. Onu dikkatle süzerek, \"Bu da O'nunla birlikteydi\" dedi."},{"n":"57","t":"Ama Petrus, \"Kadın, ben O'nu tanımıyorum\" diye inkâr etti."},{"n":"58","t":"Biraz sonra onu gören başka biri, \"Sen de onlardansın\" dedi.\nPetrus, \"Be adam, onlardan değilim\" dedi."},{"n":"59","t":"Yaklaşık bir saat sonra yine bir başkası ısrarla, \"Gerçekten bu da O'nunla birlikteydi\" dedi. \"Çünkü Celilelidir.\""},{"n":"60","t":"Petrus, \"Sen ne diyorsun be adam, anlamıyorum!\" dedi. Tam o anda, Petrus daha konuşurken horoz öttü."},{"n":"61-62","t":"Rab arkasına dönüp Petrus'a baktı. O zaman Petrus, Rab'bin kendisine, \"Bu gece horoz ötmeden sen beni üç kez inkâr edeceksin\" dediğini hatırladı ve dışarı çıkıp acı acı ağladı."},{"n":"63","t":"İsa'yı göz altında tutan adamlar O'nunla alay ediyor, O'nu dövüyorlardı."},{"n":"64","t":"Gözlerini bağlayıp, \"Peygamberliğini göster bakalım, sana vuran kim?\" diye soruyorlardı."},{"n":"65","t":"Ve kendisine daha bir sürü küfür yağdırdılar."},{"n":"66","h":"İsa Yüksek Kurul'un önünde","t":"Gün doğunca halkın ihtiyarları, başkâhinler ve din bilginleri toplandılar. İsa, bunlardan oluşan Yüksek Kurul'un önüne çıkarıldı."},{"n":"67","t":"O'na, \"Sen Mesih isen, söyle bize\" dediler.\nİsa onlara şöyle dedi: \"Size söylesem, inanmazsınız."},{"n":"68","t":"Size soru sorsam, cevap vermezsiniz."},{"n":"69","t":"Ne var ki, bundan böyle İnsanoğlu, kudretli Tanrı'nın sağında oturacaktır.\""},{"n":"70","t":"Onların hepsi, \"Yani, sen Tanrı'nın Oğlu musun?\" diye sordular.\nO da onlara, \"Söylediğiniz gibi, ben O'yum\" dedi."},{"n":"71","t":"\"Artık tanıklığa ne ihtiyacımız var?\" dediler. \"İşte kendimiz O'nun ağzından işittik!\""}]},{"ch":23,"verses":[{"n":"1","t":"Sonra bütün kurul üyeleri kalkıp İsa'yı Pilatus'a götürdüler."},{"n":"2","t":"O'nu şöyle suçlamaya başladılar: \"Bu adamın ulusumuzu yoldan saptırdığını gördük. Sezar'a vergi ödenmesine engel oluyor, kendisinin de Mesih, yani bir kral olduğunu söylüyor.\""},{"n":"3","t":"Pilatus İsa'ya, \"Sen Yahudilerin Kralı mısın?\" diye sordu.\nİsa, \"Söylediğin gibidir\" diye cevap verdi."},{"n":"4","t":"Pilatus, başkâhinlerle halka, \"Bu adamda hiçbir suç görmüyorum\" dedi."},{"n":"5","t":"Ama onlar üstelediler: \"Yahudiye'nin her tarafında öğretisini yayarak halkı kışkırtıyor; Celile'den başlayıp ta buraya kadar geldi\" dediler."},{"n":"6","t":"Pilatus bunu duyunca, \"Bu adam Celileli mi?\" diye sordu."},{"n":"7","t":"İsa'nın, Hirodes'in yönetimindeki bölgeden geldiğini öğrenince, kendisini o sırada Kudüs'te bulunan Hirodes'e gönderdi."},{"n":"8","t":"Hirodes İsa'yı görünce çok sevindi. O'na ilişkin haberleri duyduğu için çoktandır O'nu görmek istiyor, O'nun yapacağı bir mucizeye tanık olmayı umuyordu."},{"n":"9","t":"O'na birçok soru sordu, ama O hiç karşılık vermedi."},{"n":"10","t":"Orada duran başkâhinlerle din bilginleri, İsa'yı ağır bir dille suçladılar."},{"n":"11","t":"Hirodes de askerleriyle birlikte O'nu aşağılayıp alay etti. O'na gösterişli bir kaftan giydirip Pilatus'a geri gönderdi."},{"n":"12","t":"Bu olaydan önce birbirine düşman olan Hirodes'le Pilatus, o gün dost oldular."},{"n":"13-14","h":"Pilatus'un kararı","t":"Pilatus, başkâhinleri, yöneticileri ve halkı toplayarak onlara, \"Siz bu adamı bana, halkı saptırıyor diye getirdiniz\" dedi. \"Oysa ben bu adamı sizin önünüzde sorguya çektim ve kendisini suçladığınız konularda O'nda hiçbir suç bulmadım."},{"n":"15","t":"Hirodes de bulmamış olmalı ki, O'nu bize geri gönderdi. Görüyorsunuz, ölüm cezasını gerektiren hiçbirşey yapmadı."},{"n":"16-17","t":"Bu nedenle ben O'nu dövdürüp salıvereceğim.\""},{"n":"18","t":"Ama onlar hep bir ağızdan, \"Yok et bu adamı, bize Barabas'ı salıver!\" diye bağırdılar."},{"n":"19","t":"Barabas, kentte çıkan bir ayaklanmaya katılmaktan ve adam öldürmekten hapse atılmıştı."},{"n":"20","t":"İsa'yı salıvermek isteyen Pilatus onlara yeniden seslendi."},{"n":"21","t":"Onlar ise, \"O'nu çarmıha ger, çarmıha ger!\" diye bağrışıp durdular."},{"n":"22","t":"Pilatus üçüncü kez onlara, \"Bu adam ne kötülük yaptı ki?\" dedi. \"Ölüm cezasını gerektirecek hiçbir suç bulmadım O'nda. Bu nedenle O'nu dövdürüp salıvereceğim.\""},{"n":"23-24","t":"Ne var ki onlar, yüksek sesle bağrışarak İsa'nın çarmıha gerilmesi için direttiler. Sonunda bağırışları baskın çıktı ve Pilatus, onların isteğinin yerine getirilmesine karar verdi."},{"n":"25","t":"İstedikleri adamı, ayaklanmaya katılmaktan ve adam öldürmekten hapse atılmış olan adamı salıverdi. İsa'yı ise onların isteğine bıraktı."},{"n":"26","h":"İsa çarmıha geriliyor","t":"Askerler İsa'yı götürürken, kırdan gelmekte olan Simun adında Kireneli bir adamı yakaladılar, çarmıhı sırtına yükleyip İsa'nın arkasından yürüttüler."},{"n":"27","t":"Büyük bir halk topluluğu da İsa'nın ardından gidiyordu. Aralarında İsa için dövünüp ağıt yakan kadınlar vardı."},{"n":"28","t":"İsa bu kadınlara dönerek, \"Ey Kudüs kızları, benim için ağlamayın\" dedi. \"Kendiniz ve çocuklarınız için ağlayın."},{"n":"29","t":"Çünkü öyle günler gelecek ki, 'Kısır olan kadınlara, hiç doğurmamış olan rahimlere, emzirmemiş olan memelere ne mutlu!' diyecekler."},{"n":"30","t":"O zaman dağlara, 'Üzerimize düşün!' ve tepelere, 'Bizi örtün!' diyecekler."},{"n":"31","t":"Çünkü yaş ağaca böyle yaparlarsa, kuruya neler olacaktır?\""},{"n":"32","t":"İsa'yla birlikte idam edilmek üzere ayrıca iki suçlu da götürülüyordu."},{"n":"33","t":"Kafatası denilen yere vardıklarında İsa'yı, biri sağında öbürü solunda olmak üzere, iki suçluyla birlikte çarmıha gerdiler."},{"n":"34","t":"İsa, \"Baba, onları bağışla\" dedi. \"Çünkü ne yaptıklarını bilmiyorlar.\" O'nun giysilerini aralarında paylaşmak için kura çektiler."},{"n":"35","t":"Halk orada durmuş, olanları seyrediyordu. Yöneticiler ise İsa'yla alay ederek, \"Başkalarını kurtardı; eğer Tanrı'nın Mesihi, Tanrı'nın seçtiği O ise, kendini de kurtarsın\" diyorlardı."},{"n":"36-37","t":"Askerler de yaklaşıp İsa'yla eğlendiler. O'na ekşi şarap sunarak, \"Sen Yahudilerin Kralıysan, kurtar kendini!\" dediler."},{"n":"38","t":"Başının üzerinde şu yafta vardı:"},{"n":"39","h":"'YAHUDİLERİN KRALI BUDUR'.","t":"Çarmıhta asılı duran suçlulardan biri O'na, \"Sen Mesih değil misin? Haydi, kendini de bizi de kurtar!\" diye küfür etti."},{"n":"40","t":"Ne var ki, öbür suçlu onu azarladı. \"Sende Tanrı korkusu da mı yok?\" diye karşılık verdi. \"Sen de aynı cezayı çekiyorsun."},{"n":"41","t":"Nitekim biz haklı olarak cezalandırılıyor, yaptıklarımızın karşılığını alıyoruz. Oysa bu adam hiçbir kötülük yapmamıştır.\""},{"n":"42","t":"Sonra, \"Ey İsa, kendi egemenliğine girdiğinde beni an\" dedi."},{"n":"43","t":"İsa ona, \"Sana doğrusunu söyleyeyim, sen bugün benimle birlikte cennette olacaksın\" dedi."},{"n":"44-45","h":"İsa'nın ölümü","t":"Saat öğleyin on iki sularında güneş karardı ve bütün ülkenin üzerine saat üçe kadar süren bir karanlık çöktü. Tapınaktaki perde ortasından yırtıldı."},{"n":"46","t":"İsa yüksek sesle, \"Baba, ruhumu senin ellerine bırakıyorum!\" diye seslendi. Bunu söyledikten sonra son nefesini verdi."},{"n":"47","t":"Olanları gören yüzbaşı, \"Bu adam gerçekten doğru biriydi\" diyerek Tanrı'yı yüceltmeye başladı."},{"n":"48","t":"Olayı seyretmek için birikmiş olan halkın tümü olup bitenleri görünce göğüslerini döve döve geri döndüler."},{"n":"49","t":"Ama İsa'nın bütün tanıdıkları ve Celile'den O'nun peşinden gelmiş olan kadınlar uzakta durmuş, olanları seyrediyorlardı."},{"n":"50","h":"İsa'nın gömülmesi","t":"Yüksek Kurul üyelerinden Yusuf adında iyi ve doğru bir adam vardı."},{"n":"51","t":"Bir Yahudi kenti olan Aramatya'dan olup Tanrı'nın Egemenliğini ümitle bekleyen Yusuf, Kurul'un kararını ve eylemini onaylamamıştı."},{"n":"52","t":"Pilatus'a gidip İsa'nın cesedini istedi."},{"n":"53","t":"Cesedi çarmıhtan indirip keten beze sardı ve daha hiç kimsenin konulmadığı, kayaya oyulmuş bir mezara yatırdı."},{"n":"54","t":"Hazırlık günüydü ve Sept günü başlamak üzereydi."},{"n":"55","t":"İsa'yla birlikte Celile'den gelmiş olan kadınlar da Yusuf'un ardından giderek mezarı ve İsa'nın cesedinin oraya nasıl konulduğunu gördüler."},{"n":"56","t":"Evlerine dönerek baharat ve hoş kokulu yağlar hazırladılar. Ama Sept günü, Tanrı'nın buyruğu uyarınca dinlendiler."}]},{"ch":24,"verses":[{"n":"1","t":"Kadınlar haftanın ilk günü, sabah çok erkenden, hazırlamış oldukları baharatları alıp mezara gittiler."},{"n":"2","t":"Taşı mezarın girişinden yuvarlanmış buldular."},{"n":"3","t":"Ama içeri girince Rab İsa'nın cesedini görmediler."},{"n":"4","t":"Onlar bu durum karşısında şaşırıp kalmışken, şimşek gibi parıldayan giysilere bürünmüş iki kişi yanlarında beliriverdi."},{"n":"5","t":"Korkuya kapılan kadınlar başlarını yere eğdiler. Adamlar ise onlara, \"Diri olanı neden ölüler arasında arıyorsunuz?\" dediler."},{"n":"6","t":"\"O burada yok, dirildi. Daha Celile'deyken size söylediğini anımsayın."},{"n":"7","t":"İnsanoğlu'nun günahlı insanların eline verilmesi, çarmıha gerilmesi ve üçüncü gün dirilmesi gerektiğini bildirmişti.\""},{"n":"8","t":"O zaman İsa'nın sözlerini anımsadılar."},{"n":"9","t":"Mezardan dönen kadınlar bütün bunları Onbirlere ve diğerlerinin hepsine bildirdiler."},{"n":"10","t":"Bunları elçilere anlatanlar, Mecdelli Meryem,Yohana, Yakup'un annesi Meryem ve bunlarla birlikte bulunan diğer kadınlardı."},{"n":"11","t":"Ne var ki, bu sözler elçilere saçma geldi ve kadınlara inanmadılar."},{"n":"12","t":"Yine de, Petrus kalkıp mezara koştu. Eğilip içeri baktığında keten bezlerden başka bir şey görmedi. Olay karşısında şaşkına dönmüş bir halde oradan uzaklaştı."},{"n":"13","h":"Emayus yolunda iki öğrenci","t":"Aynı gün öğrencilerden ikisi, Kudüs'ten altmış ok atımı uzaklıkta bulunan ve Emayus denilen bir köye gitmekteydiler."},{"n":"14","t":"Bütün bu olup bitenleri kendi aralarında konuşuyorlardı."},{"n":"15","t":"Bunları konuşup tartışırlarken İsa'nın kendisi yanlarına geldi ve onlarla birlikte yürümeye başladı."},{"n":"16","t":"Ama onların gözleri O'nu tanıma gücünden yoksun bırakılmıştı."},{"n":"17","t":"İsa onlara, \"Yolda birbirinizle ne tartışıp duruyorsunuz?\" dedi.\nÜzgün bir halde, oldukları yerde durdular."},{"n":"18","t":"Bunlardan adı Kleyopas olan O'na, \"Kudüs'te bulunup da bu günlerde orada olup bitenleri bilmeyen tek yabancı sen misin?\" diye karşılık verdi."},{"n":"19","t":"İsa onlara, \"Hangi olup bitenleri?\" dedi.\nO'na, \"Nasıralı İsa'yla ilgili olayları\" dediler. \"O adam, Tanrı'nın ve bütün halkın önünde gerek söz, gerek eylemde güçlü bir peygamberdi."},{"n":"20-23","t":"Başkâhinlerle yöneticilerimiz O'nu, ölüm cezasına çarptırmak için valiye teslim ederek çarmıha gerdirdiler; oysa biz O'nun, İsrail'i kurtaracak kişi olduğunu ummuştuk. Dahası var, bu olaylar olalı üç gün oldu ve aramızdan bazı kadınlar bizi şaşkına çevirdiler. Bu sabah erkenden mezara gittiklerinde, O'nun cesedini bulamamışlar. Sonra geldiler, bir görümde, İsa'nın yaşamakta olduğunu bildiren melekler gördüklerini söylediler."},{"n":"24","t":"Bizimle birlikte olanlardan bazıları mezara gitmiş ve durumu, tam kadınların anlatmış olduğu gibi bulmuşlar. Ama O'nu görmemişler.\""},{"n":"25","t":"İsa onlara, \"Sizi akılsızlar! Peygamberlerin tüm söylediklerine inanmakta ağır davranan kişiler!"},{"n":"26","t":"Mesih'in bu acıları çekmesi ve yüceliğine kavuşması gerekli değil miydi?\" dedi."},{"n":"27","t":"Sonra Musa'nın ve tüm peygamberlerin yazılarından başlayarak, Kutsal Yazıların hepsinde kendisiyle ilgili olanları onlara açıkladı."},{"n":"28-29","t":"Gitmekte oldukları köye yaklaştıkları sırada İsa, yoluna devam edecekmiş gibi davrandı. Ama onlar, \"Bizimle kal. Neredeyse akşam olacak, gün batmak üzere\" diyerek O'nu zorladılar. Böylece İsa onlarla birlikte kalmak üzere içeri girdi."},{"n":"30","t":"Onlarla sofrada otururken İsa ekmek aldı, şükran duasını yaptı ve ekmeği bölüp onlara verdi."},{"n":"31","t":"O zaman onların gözleri açıldı ve kendisini tanıdılar. İsa ise gözlerinin önünden kayboldu."},{"n":"32","t":"Onlar birbirine, \"Yolda kendisi bizimle konuşurken ve Kutsal Yazıları bize açıklarken yüreklerimiz nasıl da sevinçle çarpıyordu, değil mi?\" dediler."},{"n":"33","t":"Kalkıp hemen Kudüs'e döndüler. Onbirleri ve onlarla beraber olanları toplanmış buldular."},{"n":"34","t":"Bunlar, \"Rab gerçekten dirildi, Simun'a görünmüş!\" diyorlardı."},{"n":"35","t":"Kendileri de yolda olup bitenleri ve ekmeği böldüğü zaman İsa'yı nasıl tanıdıklarını anlattılar."},{"n":"36","h":"İsa Onbirlere görünüyor","t":"Bunları anlatırlarken İsa'nın kendisi gelip aralarında dikildi. Onlara, \"Size esenlik olsun!\" dedi."},{"n":"37","t":"Ürktüler, bir hayalet gördüklerini sanarak korkuya kapıldılar."},{"n":"38","t":"İsa onlara, \"Neden telaşlanıyorsunuz? İçinizde neden böyle kuşkular doğuyor?\" dedi."},{"n":"39","t":"\"Ellerime, ayaklarıma bakın; işte ben'im! Bana dokunun da görün. Bir hayalette et ve kemik olmaz, ama görüyorsunuz, bende var.\""},{"n":"40","t":"Bunu söyledikten sonra onlara ellerini ve ayaklarını gösterdi."},{"n":"41","t":"Sevinçten hâlâ inanamayan, şaşkınlık içinde olan öğrencilerine İsa, \"Sizde yiyecek bir şey var mı?\" diye sordu."},{"n":"42","t":"Kendisine bir parça kızarmış balık verdiler."},{"n":"43","t":"İsa onu aldı ve onların gözleri önünde yedi."},{"n":"44","t":"Sonra onlara, \"Ben daha sizlerle birlikteyken size şu sözleri söylemiştim: 'Musa'nın Yasasında, peygamberlerin yazılarında ve Mezmurlarda benimle ilgili yazılmış olanların tümünün gerçekleşmesi gerektir'\" dedi."},{"n":"45","t":"Bundan sonra İsa, Kutsal Yazıları anlayabilmeleri için zihinlerini açtı."},{"n":"46-47","t":"Onlara dedi ki, \"Şöyle yazılmıştır: Mesih acı çekecek ve üçüncü gün ölümden dirilecek; günahların bağışlanması için tövbe çağrısı da Kudüs'ten başlayarak tüm uluslara O'nun adıyla duyurulacak."},{"n":"48","t":"Sizler bu olayların tanıklarısınız."},{"n":"49","t":"Ben de Babamın vaat ettiğini size göndereceğim. Ama siz, gökten gelecek güçle kuşanıncaya dek kentte kalın.\""},{"n":"50","h":"İsa'nın göğe yükselmesi","t":"İsa onları kentin dışına, Beytanya'nın yakınlarına kadar götürdü. Ellerini kaldırarak onları kutsadı."},{"n":"51","t":"Ve onları kutsarken yanlarından ayrıldı, göğe alındı."},{"n":"52","t":"Öğrencileri O'na tapındılar ve büyük sevinç içinde Kudüs'e döndüler."},{"n":"53","t":"Sürekli tapınakta bulunuyor, Tanrı'yı övüyorlardı."}]}]},{"id":"yuhanna","name":"Yuhanna","chapters":[{"ch":1,"verses":[{"n":"1","h":"Başlangıçta Söz vardı","t":"Başlangıçta Söz vardı. Söz Tanrı'yla birlikteydi ve Söz Tanrı'ydı."},{"n":"2","t":"Başlangıçta O, Tanrı'yla birlikteydi."},{"n":"3","t":"Her şey O'nun aracılığıyla var oldu, var olan hiçbir şey O'nsuz olmadı."},{"n":"4","t":"Yaşam O'ndaydı ve yaşam insanların ışığıydı."},{"n":"5","t":"Işık karanlıkta parlar ve karanlık onu alt edememiştir."},{"n":"6","t":"Tanrı'nın gönderdiği Yahya adlı bir adam ortaya çıktı."},{"n":"7","t":"O, tanıklık için, ışığa tanıklık etsin ve herkes onun aracılığıyla iman etsin diye geldi."},{"n":"8","t":"Kendisi o ışık değildi, ama ışığa tanıklık etmeye geldi."},{"n":"9","t":"Dünyaya gelen, her insanı aydınlatan gerçek ışık vardı."},{"n":"10","t":"O, dünyadaydı, dünya O'nun aracılığıyla var oldu, ama dünya O'nu tanımadı."},{"n":"11","t":"Kendi yurduna geldi, ama kendi halkı O'nu kabul etmedi."},{"n":"12","t":"Ancak, kendisini kabul edip adına iman edenlerin hepsine Tanrı'nın çocukları olma hakkını verdi."},{"n":"13","t":"Onlar ne kandan, ne bedenin isteğinden, ne de insanın isteğinden doğdular; tersine, Tanrı'dan doğdular."},{"n":"14","t":"Söz insan olup aramızda yaşadı. Biz de O'nun yüceliğini, Baba'dan gelen, lütuf ve gerçekle dolu olan biricik Oğul'un yüceliğini gördük."},{"n":"15","t":"Yahya O'na tanıklık etti. Yüksek sesle şöyle dedi: \"'Benden sonra gelen benden üstündür. Çünkü O benden önce vardı' diye sözünü ettiğim kişi budur.\""},{"n":"16","t":"Nitekim hepimiz O'nun doluluğundan lütuf üzerine lütuf aldık."},{"n":"17","t":"Kutsal Yasa Musa aracılığıyla verildi, ama lütuf ve gerçek İsa Mesih aracılığıyla geldi."},{"n":"18","t":"Tanrı'yı hiçbir zaman hiç kimse görmemiştir. O'nu, Baba'nın bağrında bulunan ve Tanrı olan biricik Oğul tanıttı."},{"n":"19-20","h":"Yahya peygamberin ortaya çıkışı","t":"Yahudiler Yahya'ya, \"Sen kimsin?\" diye sormak üzere Kudüs'ten kâhinlerle Levilileri gönderdikleri zaman Yahya'nın tanıklığı şöyle oldu - açıkça konuştu, inkâr etmedi - \"Ben Mesih değilim\" diye açıkça konuştu."},{"n":"21","t":"Onlar da kendisine, \"Öyleyse sen kimsin? İlyas mısın?\" diye sordular.\nO da, \"Değilim\" dedi.\n\"Sen beklediğimiz peygamber misin?\" sorusuna,\n\"Hayır\" cevabını verdi."},{"n":"22","t":"O zaman ona, \"Kimsin, söyle de bizi gönderenlere bir cevap verelim\" dediler. \"Kendin için ne diyorsun?\""},{"n":"23","t":"Yahya, \"Yeşaya peygamberin dediği gibi, 'Rab'bin yolunu düzleyin' diye çölde yükselen sesim ben\" dedi."},{"n":"24-25","t":"Yahya'ya gönderilen bazı Ferisiler ona, \"Sen Mesih, İlyas ya da beklediğimiz peygamber değilsen, niye vaftiz ediyorsun?\" diye sordular."},{"n":"26","t":"Yahya onlara şöyle cevap verdi: \"Ben suyla vaftiz ediyorum, ama aranızda tanımadığınız biri duruyor."},{"n":"27","t":"Benden sonra gelenO'dur. Ben O'nun çarığının bağını çözmeye bile layık değilim.\""},{"n":"28","t":"Bütün bunlar Şeria nehrinin ötesinde bulunan Beytanya'da, Yahya'nın vaftiz ettiği yerde oldu."},{"n":"29","h":"Tanrı Kuzusu","t":"Yahya ertesi gün İsa'nın kendisine doğru geldiğini görünce şöyle dedi: \"İşte, dünyanın günahını ortadan kaldıran Tanrı Kuzusu!"},{"n":"30","t":"Kendisi için, 'Benden sonra biri geliyor, O benden üstündür. Çünkü O benden önce vardı' dediğim kişi işte budur."},{"n":"31","t":"Ben O'nu tanımıyordum, ama İsrail'in O'nu tanıması için ben suyla vaftiz ederek geldim.\""},{"n":"32","t":"Yahya tanıklığını şöyle sürdürdü: \"Ruh'un güvercin gibi gökten indiğini, O'nun üzerinde durduğunu gördüm."},{"n":"33","t":"Ben O'nu tanımıyordum. Ama suyla vaftiz etmek için beni gönderen, 'Ruh'un kimin üzerine inip durduğunu görürsen, Kutsal Ruh'la vaftiz eden O'dur' dedi."},{"n":"34","t":"Ben de gördüm ve 'Tanrı'nın Oğlu budur' diye tanıklık ettim.\""},{"n":"35","h":"İsa'nın ilk öğrencileri","t":"Ertesi gün Yahya yine öğrencilerinden ikisiyle birlikteydi."},{"n":"36","t":"Oradan geçmekte olan İsa'ya bakarak, \"İşte Tanrı Kuzusu!\" dedi."},{"n":"37","t":"İki öğrenci onun söylediklerini işitince İsa'nın ardından gittiler."},{"n":"38","t":"İsa arkasına dönüp ardından geldiklerini görünce onlara, \"Ne arıyorsunuz?\" diye sordu.\nOnlar da, \"Nerede oturuyorsun, Rabbî?\" dediler. 'Rabbî', öğretmenim anlamına gelir."},{"n":"39","t":"İsa, \"Gelin, görün\" dedi.\nGidip O'nun nerede oturduğunu gördüler ve o gün O'nunla kaldılar. Saat dört sularıydı."},{"n":"40","t":"Yahya'yı işitip İsa'nın ardından giden iki kişiden biri Simun Petrus'un kardeşi Andreya'ydı."},{"n":"41","t":"Andreya önce kendi kardeşi Simun'u bularak ona, \"Biz Mesih'i bulduk\" dedi. 'Mesih', meshedilmiş anlamına gelir."},{"n":"42","t":"Andreya kardeşini İsa'ya götürdü. İsa ona baktı, \"Sen Yuhanna'nın oğlu Simun'sun. Kefas diye çağrılacaksın\" dedi. 'Kefas', Kaya anlamına gelir."},{"n":"43","t":"Ertesi gün İsa, Celile'ye gitmeye karar verdi. Filipus'u bulup ona, \"Ardımdan gel\" dedi."},{"n":"44","t":"Filipus da Andreya ile Petrus'un kenti olan Beytsayda'dandı."},{"n":"45","t":"Filipus, Natanyel'i bularak ona, \"Musa'nın Kutsal Yasa'da hakkında yazdığı, peygamberlerin de sözünü ettiği kişiyi, Yusuf'un oğlu Nasıralı İsa'yı bulduk\" dedi."},{"n":"46","t":"Natanyel Filipus'a, \"Nasıra'dan iyi bir şey çıkabilir mi?\" diye sordu.\nFilipus, \"Gel de gör\" dedi."},{"n":"47","t":"İsa, Natanyel'in kendisine doğru geldiğini görünce onun için, \"İşte, içinde hile olmayan gerçek bir İsrailli!\" dedi."},{"n":"48","t":"Natanyel, \"Beni nereden tanıyorsun?\" diye sordu.\nİsa, \"Filipus çağırmadan önce seni incir ağacının altında gördüm\" cevabını verdi."},{"n":"49","t":"Natanyel, \"Rabbî, sen Tanrı'nın Oğlusun, sen İsrail'in Kralısın!\" dedi."},{"n":"50","t":"İsa ona dedi ki, \"Seni incir ağacının altında gördüğümü söylediğim için mi inanıyorsun? Bunlardan daha büyük şeylergöreceksin.\""},{"n":"51","t":"Sonra da, \"Size doğrusunu söyleyeyim, göğün açıldığını, Tanrı'nın meleklerinin İnsanoğlu üzerinde yükselip indiklerini göreceksiniz\" dedi."}]},{"ch":2,"verses":[{"n":"1","h":"İsa'nın ilk mucizesi","t":"Üçüncü gün Celile'nin Kana köyünde bir düğün vardı. İsa'nın annesi oradaydı."},{"n":"2","t":"İsa ve öğrencileri de düğüne çağrılmışlardı."},{"n":"3","t":"Şarap tükenince İsa'nın annesi O'na, \"Şarapları kalmadı\" dedi."},{"n":"4","t":"İsa, \"Anne, benden ne istiyorsun? Benim saatim daha gelmedi\" dedi."},{"n":"5","t":"Annesi hizmet edenlere, \"Size ne derse onu yapın\" dedi."},{"n":"6","t":"Yahudilerin geleneksel temizliği için oraya konmuş, her biri seksenle yüz yirmi litre alan altı taş küp vardı."},{"n":"7","t":"İsa hizmet edenlere, \"Küpleri suyla doldurun\" dedi. Küpleri ağızlarına kadar doldurdular."},{"n":"8","t":"Sonra hizmet edenlere, \"Şimdi bundan alın, şölen başkanına götürün\" dedi.\nOnlar da götürdüler."},{"n":"9-10","t":"Şölen başkanı, şaraba dönüşmüş suyu tattı. Bunun nereden geldiğini bilemedi, oysa suyu küpten alan hizmetkârlar biliyorlardı. Şölen başkanı güveyi çağırıp ona dedi ki, \"Herkes önce iyi şarabı, çok içildikten sonra da kötüsünü sunar. Ama sen iyi şarabı şimdiye dek saklamışsın.\""},{"n":"11","t":"İsa bu ilk mucizesini Celile'nin Kana köyünde yaptı ve yüceliğini gösterdi. Öğrencileri de O'na iman ettiler."},{"n":"12","h":"İsa satıcıları tapınaktan kovuyor","t":"Bundan sonra İsa, annesi, kardeşleri ve öğrencileri Kefernahum'a gidip orada birkaç gün kaldılar."},{"n":"13","t":"Yahudilerin Fısıh bayramı yakındı. İsa da Kudüs'e gitti."},{"n":"14","t":"Tapınağın avlusunda sığır, koyun ve güvercin satanlarla orada oturmuş para bozanları gördü."},{"n":"15","t":"İpten bir kamçı yaparak hepsini, koyunlar ve sığırlarla birlikte tapınaktan kovdu, para bozanların paralarını döktü ve masalarını devirdi."},{"n":"16","t":"Güvercin satanlara, \"Bunları buradan kaldırın, Babamın evini pazar yerine çevirmeyin!\" dedi."},{"n":"17","t":"Öğrencileri, \"Senin evin için gösterdiğim gayret beni yiyip bitirecek\" diye yazılmış olan sözü hatırladılar."},{"n":"18","t":"Yahudiler İsa'ya, \"Bunları yaptığına göre, bize nasıl bir mucize göstereceksin?\" diye sordular."},{"n":"19","t":"İsa şu cevabı verdi: \"Bu tapınağı yıkın, üç günde onu yeniden kuracağım.\""},{"n":"20","t":"Yahudiler, \"Bu tapınak kırk altı yılda yapıldı, sen onu üç günde mi kuracaksın?\" dediler."},{"n":"21","t":"Ama İsa'nın sözünü ettiği tapınak kendi bedeniydi."},{"n":"22","t":"İsa ölümden dirilince öğrencileri bu sözü söylediğini hatırladılar, Kutsal Yazı'ya ve İsa'nın söylediği bu söze iman ettiler."},{"n":"23","t":"Fısıh bayramında İsa'nın Kudüs'te bulunduğu sırada yaptığı mucizeleri gören birçokları O'nun adına iman ettiler."},{"n":"24","t":"Ama İsa bütün insanların yüreğini bildiği için onlara güvenmiyordu."},{"n":"25","t":"İnsan hakkında kimsenin O'na bir şey söylemesine gerek yoktu. Çünkü kendisi insanın içinden geçenleri biliyordu."}]},{"ch":3,"verses":[{"n":"1-2","t":"Yahudilerin Nikodim adlı bir önderi vardı. Ferisilerden olan bu adam bir gece İsa'ya gelerek, \"Rabbî, senin Tanrı'dan gelmiş bir öğretmen olduğunu biliyoruz. Çünkü Tanrı kendisiyle birlikte olmadıkça hiç kimse senin yaptığın bu mucizeleri yapamaz\" dedi."},{"n":"3","t":"İsa ona şu karşılığı verdi: \"Sana doğrusunu söyleyeyim, bir kimse yeniden doğmadıkça Tanrı'nın Egemenliğini göremez.\""},{"n":"4","t":"Nikodim, \"Yaşlanmış bir adam nasıl doğabilir? Annesinin rahmine ikinci kez girip doğabilir mi?\" diye sordu."},{"n":"5","t":"İsa şöyle cevap verdi: \"Sana doğrusunu söyleyeyim, bir kimse sudan ve Ruh'tan doğmadıkça Tanrı'nın Egemenliğine giremez."},{"n":"6","t":"Bedenden doğan bedendir, Ruh'tan doğan ruhtur."},{"n":"7","t":"Sana, 'Yeniden doğmalısınız' dediğime şaşma."},{"n":"8","t":"Yel dilediği yerde eser; sesini işitirsin, ama nereden gelip nereye gittiğini bilemezsin. Ruh'tan doğan her adam da böyledir.\""},{"n":"9","t":"Nikodim İsa'ya, \"Bunlar nasıl olabilir?\" diye sordu."},{"n":"10","t":"İsa ona şöyle cevap verdi: \"Sen İsrail'in öğretmeni olduğun halde bunları anlamıyor musun?"},{"n":"11","t":"Sana doğrusunu söyleyeyim, biz bildiğimizi söylüyoruz, gördüğümüze tanıklık ediyoruz. Sizler ise bizim tanıklığımızı kabul etmiyorsunuz."},{"n":"12","t":"Sizlere yeryüzüyle ilgili şeyleri söylediğim zaman inanmazsanız, gökle ilgili şeyleri söylediğimde nasıl inanacaksınız?"},{"n":"13","t":"Gökten inmiş olan İnsanoğlu'ndan başka hiç kimse göğe çıkmamıştır."},{"n":"14","t":"Musa çölde yılanı nasıl yukarı kaldırdıysa, İnsanoğlu'nun da öylece yukarı kaldırılması gerekir."},{"n":"15","t":"Öyle ki, O'na iman eden herkes sonsuz yaşama kavuşsun."},{"n":"16","t":"\"Çünkü Tanrı dünyayı o kadar çok sevdi ki, biricik Oğlunu verdi. Öyle ki, O'na iman edenlerin hiçbiri mahvolmasın, ama hepsi sonsuz yaşama kavuşsun."},{"n":"17","t":"Tanrı, Oğlunu dünyayı yargılamak için dünyaya göndermedi, dünya O'nun aracılığıyla kurtulsun diye gönderdi."},{"n":"18","t":"O'na iman eden yargılanmaz, iman etmeyen ise zaten yargılanmıştır. Çünkü Tanrı'nın biricik Oğlunun adına iman etmemiştir."},{"n":"19","t":"Yargı da şudur: dünyaya ışık geldi, ama insanlar ışığın yerine karanlığı sevdiler. Çünkü yaptıkları işler kötüydü."},{"n":"20","t":"Kötülük yapan herkes ışıktan nefret eder ve işleri açığa çıkmasın diye ışığa gelmez."},{"n":"21","t":"Ama gerçeği uygulayan kişi, yaptıklarını Tanrı'ya dayanarak yaptığı belli olsun diye ışığa gelir.\""},{"n":"22","h":"Yahya'nın tanıklığı","t":"Bundan sonra İsa'yla öğrencileri Yahudiye diyarına gittiler. İsa onlarla birlikte orada bir süre kalarak vaftiz etti."},{"n":"23","t":"Yahya da Salim yakınındaki Aynon'da vaftiz ediyordu. Çünkü orada bol su vardı. İnsanlar gelip vaftiz oluyorlardı."},{"n":"24","t":"Yahya henüz hapse atılmamıştı."},{"n":"25","t":"O sıralarda Yahya'nın öğrencileriyle bir Yahudi arasında temizlenme konusunda bir tartışma çıktı."},{"n":"26","t":"ÖğrencileriYahya'ya gelerek, \"Rabbî\" dediler, \"Şeria nehrinin ötesinde birlikte olduğun ve kendisi için tanıklık ettiğin adam var ya, işte o adam vaftiz ediyor, herkes de O'na gidiyor.\""},{"n":"27","t":"Yahya şöyle cevap verdi: \"İnsan, kendisine gökten verilmedikçe hiçbir şey alamaz."},{"n":"28","t":"'Ben Mesih değilim, ama O'nun öncüsü olarak gönderildim' dediğime siz kendiniz tanıksınız."},{"n":"29","t":"Gelin kiminse, güvey odur. Ama güveyin yanında duran ve onu dinleyen dostu onun sesini işitince çok sevinir. İşte benim sevincim böylece tamamlandı."},{"n":"30","t":"O büyümeli, bense küçülmeliyim.\""},{"n":"31","t":"Yukarıdan gelen, herkesten üstündür. Dünyadan olan dünyaya aittir ve dünyadan söz eder. Gökten gelen ise, herkesten üstündür."},{"n":"32","t":"Ne görmüş ne işitmişse ona tanıklık eder, ama tanıklığını kimse kabul etmez."},{"n":"33","t":"O'nun tanıklığını kabul eden, Tanrı'nın gerçek olduğuna mührünü basmıştır."},{"n":"34","t":"Tanrı'nın gönderdiği kişi Tanrı'nın sözlerini söyler. Çünkü Tanrı, Ruh'u ölçüyle vermez."},{"n":"35","t":"Baba Oğul'u sever ve her şeyi O'na emanet etmiştir."},{"n":"36","t":"Oğul'a iman edenin sonsuz yaşamı vardır. Ama Oğul'un sözünü dinlemeyen yaşamı görmeyecektir. Tanrı'nın gazabı böylesinin üzerinde kalır."}]},{"ch":4,"verses":[{"n":"1-3","h":"İsa ile Samiriyeli kadın","t":"Ferisiler İsa'nın Yahya'dan daha çok öğrenci edinip vaftiz ettiğini duydular. (Aslında İsa'nın kendisi değil, öğrencileri vaftiz ediyorlardı.) İsa bunu öğrenince Yahudiye'den ayrılıp yine Celile'ye gitti."},{"n":"4","t":"Giderken Samiriye'den geçmesi gerekti."},{"n":"5","t":"Böylece Samiriye'nin Sihar denilen kentine geldi. Burası Yakup'un kendi oğlu Yusuf'a vermiş olduğu toprağın yakınındaydı."},{"n":"6","t":"Yakup'un kuyusu da oradaydı. İsa, yolculuktan yorulmuş olduğu için kuyunun yanına oturmuştu. Saat on iki sularıydı."},{"n":"7","t":"Samiriyeli bir kadın su çekmeye geldi.\nİsa ona, \"Bana su ver, içeyim\" dedi."},{"n":"8","t":"İsa'nın öğrencileri yiyecek satın almak için kente gitmişlerdi."},{"n":"9","t":"Samiriyeli kadın, \"Sen Yahudisin, bense Samiriyeli bir kadınım\" dedi, \"nasıl olur da benden su istersin?\" Çünkü Yahudilerin Samiriyelilerle ilişkileri yoktur."},{"n":"10","t":"İsa kadına şu cevabı verdi: \"Eğer sen Tanrı'nın armağanını ve sana, 'Bana su ver, içeyim' diyenin kim olduğunu bilseydin, sen O'ndan dilerdin, O da sana yaşam suyunu verirdi.\""},{"n":"11","t":"Kadın, \"Efendim\" dedi, \"su çekecek bir şeyin yok, kuyu da derin. Böyle olunca yaşam suyunu nereden bulacaksın?"},{"n":"12","t":"Sen, bu kuyuyu bize vermiş, kendisi, oğulları ve davarları ondan içmiş olan atamız Yakup'tan daha mı büyüksün?\""},{"n":"13","t":"İsa şöyle cevap verdi: \"Bu sudan her içen yine susayacak."},{"n":"14","t":"Oysa benim vereceğim sudan içen sonsuza dek susamaz. Benim vereceğim su, içende sonsuz yaşam için fışkıran bir su kaynağı olacak.\""},{"n":"15","t":"Kadın, \"Efendim\" dedi, \"bu suyu bana ver. Böylece ne susayayım, ne de su çekmek için buraya kadar geleyim.\""},{"n":"16","t":"İsa, \"Git, kocanı çağır ve buraya gel\" dedi."},{"n":"17","t":"Kadın, \"Kocam yok\" cevabını verdi.\nİsa, \"Kocam yok demekle doğruyu söyledin\" dedi."},{"n":"18","t":"\"Beş kocaya vardın. Şimdi birlikte yaşadığın adamsa kocan değildir. Doğruyu söyledin.\""},{"n":"19","t":"Kadın, \"Efendim, anlıyorum, sen bir peygambersin\" dedi."},{"n":"20","t":"\"Atalarımız bu dağda tapındılar, ama sizler tapınılması gereken yerin Kudüs'te olduğunu söylüyorsunuz.\""},{"n":"21","t":"İsa ona şöyle dedi: \"Kadın, bana inan, öyle bir saat geliyor ki, Baba'ya ne bu dağda, ne de Kudüs'te tapınacaksınız!"},{"n":"22","t":"Siz bilmediğinize tapınıyorsunuz, biz bildiğimize tapınıyoruz. Çünkü kurtuluş Yahudilerdendir."},{"n":"23","t":"Ama içtenlikle tapınanların Baba'ya ruhta ve gerçekte tapınacakları saat geliyor. İşte, o saat şimdidir. Baba da kendisine böyle tapınanları arıyor."},{"n":"24","t":"Tanrı ruhtur, O'na tapınanlar da ruhta ve gerçekte tapınmalıdırlar.\""},{"n":"25","t":"Kadın İsa'ya, \"Mesih denilen meshedilmiş Olan'ın geleceğini biliyorum\" dedi, \"O gelince bize her şeyi bildirecektir.\""},{"n":"26","t":"İsa, \"Seninle konuşan ben, O'yum\" dedi."},{"n":"27","t":"Bu sırada İsa'nın öğrencileri geldiler. O'nun bir kadınla konuşmasına şaştılar. Bununla birlikte hiçbiri, \"Ne istiyorsun?\" ya da, \"O kadınla neden konuşuyorsun?\" demedi."},{"n":"28-29","t":"Sonra kadın su testisini bırakarak kente gitti ve halka şöyle dedi: \"Gelin, yapmış olduğum her şeyi bana söyleyen adamı görün. Acaba Mesih bu mudur?\""},{"n":"30","t":"Halk da kentten çıkıp İsa'ya doğru gelmeye başladı."},{"n":"31","t":"Bu arada öğrencileri O'na, \"Rabbî, yemek ye!\" diye rica ediyorlardı."},{"n":"32","t":"Ama İsa, \"Benim, sizin bilmediğiniz bir yiyeceğim var\" dedi."},{"n":"33","t":"Öğrenciler birbirlerine, \"Acaba biri O'na yiyecek mi getirdi?\" diye sordular."},{"n":"34","t":"İsa, \"Benim yemeğim, beni gönderenin isteğini yerine getirmek ve O'nun işini tamamlamaktır\" dedi."},{"n":"35","t":"\"Sizler, 'Ekinleri biçmeye daha dört ay var' demiyor musunuz? İşte, size söylüyorum, başınızı kaldırıp tarlalara bakın. Ekinler sararmış, biçilmeye hazır!"},{"n":"36","t":"Eken ve biçen birlikte sevinsinler diye, biçen kişi şimdiden ücretini alır ve sonsuz yaşam için ürün toplar."},{"n":"37","t":"' Biri eker, başkası biçer' sözü bu durumda doğrudur."},{"n":"38","t":"Ben sizi, emek vermediğiniz bir ürünü biçmeye gönderdim. Başkaları emek verdiler, siz ise onların emeğinden yararlandınız.\""},{"n":"39","t":"O kentten birçok Samiriyeli, \"Yapmış olduğum her şeyi bana söyledi\" diye tanıklık eden kadının sözü üzerine İsa'ya iman etti."},{"n":"40","t":"Samiriyeliler O'na gelip yanlarında kalması için rica ettiler. O da orada iki gün kaldı."},{"n":"41","t":"O'nun sözü üzerine daha birçokları iman etti."},{"n":"42","t":"Bunlar kadına: \"Bizim iman etmemizin nedeni artık senin sözlerin değildir\" diyorlardı. \"Kendimiz işittik, O'nun gerçekten dünyanın Kurtarıcısı olduğunu biliyoruz.\""},{"n":"43","h":"Bir memurun oğlu iyileştiriliyor","t":"Bu iki günden sonra İsa oradan ayrılıp Celile'ye gitti."},{"n":"44","t":"İsa'nın kendisi, bir peygamberin kendi memleketinde saygı görmediğine tanıklık etmişti."},{"n":"45","t":"Celile'ye geldiği zaman Celileliler O'nu iyi karşıladılar. Çünkü onlar da bayram için gitmişler ve bayramda O'nun Kudüs'te yaptığı her şeyi görmüşlerdi."},{"n":"46","t":"İsa yine, suyu şaraba çevirdiği Celile'nin Kana köyüne geldi. Orada saraya bağlı bir memur vardı. Oğlu Kefernahum'da hastaydı."},{"n":"47","t":"Adam, İsa'nın Yahudiye'den Celile'ye geldiğini işitince yanına gitti, ölmek üzere olan oğlunu gelip iyileştirmesi için O'na yalvardı."},{"n":"48","t":"O zaman İsa adama, \"Sizler, belirtiler ve harikalar görmedikçe iman etmeyeceksiniz\" dedi."},{"n":"49","t":"Saray memuru İsa'ya, \"Efendim, çocuğum ölmeden önce yetiş!\" dedi."},{"n":"50","t":"İsa, \"Git, oğlun yaşayacak\" dedi.\nAdam İsa'nın söylediği söze iman ederek gitti."},{"n":"51","t":"Daha yoldayken köleleri onu karşılayıp oğlunun yaşamakta olduğunu bildirdiler."},{"n":"52","t":"Adam onlara, oğlunun iyileşmeye başladığı saati sordu. \"Dün öğle üstü saat birde ateşi düştü\" dediler."},{"n":"53","t":"Baba bunun, İsa'nın, \"Oğlun yaşayacak\" dediği saat olduğunu anladı. Kendisi ve bütün ev halkı iman etti."},{"n":"54","t":"Bu, İsa'nın Yahudiye'den Celile'ye gelişinde yaptığı ikinci mucizeydi."}]},{"ch":5,"verses":[{"n":"1","h":"Havuzdaki kötürüm iyileştiriliyor","t":"İsa bundan sonra Yahudilerin bir bayramı nedeniyle Kudüs'e gitti."},{"n":"2","t":"Kudüs'te Koyun Kapısı yanında, İbranicede Beytesta denilen beş eyvanlı bir havuz vardır."},{"n":"3-4","t":"Bu eyvanların altında kör, kötürüm, felçli hastalardan bir kalabalık yatardı."},{"n":"5","t":"Orada otuz sekiz yıldır hasta olan bir adam vardı."},{"n":"6","t":"İsa hasta yatan bu adamı görünce ve onun uzun zamandır bu durumda olduğunu anlayınca ona, \"İyi olmak ister misin?\" diye sordu."},{"n":"7","t":"Hasta şöyle cevap verdi: \"Efendim, su çalkandığı zaman beni havuza indirecek kimsem yok, tam gireceğim an benden önce başkası giriyor.\""},{"n":"8","t":"İsa ona, \"Kalk, döşeğini topla ve yürü\" dedi."},{"n":"9","t":"Adam o anda iyileşti. Döşeğini toplayıp yürümeye başladı.\nO gün Sept günüydü."},{"n":"10","t":"Bu yüzden Yahudiler iyileşen adama, \"Bugün Sept günü\" dediler, \"döşeğini toplaman yasaktır.\""},{"n":"11","t":"Ama adam onlara şöyle cevap verdi: \"Beni iyileştiren kişi bana, 'Döşeğini topla ve yürü' dedi.\""},{"n":"12","t":"\"Sana, 'Döşeğini topla ve yürü' diyen adam kim?\" diye sordular."},{"n":"13","t":"İyileşen adam ise O'nun kim olduğunu bilmiyordu. Çünkü orası kalabalık olduğundan İsa çekilmişti."},{"n":"14","t":"İsa daha sonra adamı tapınakta buldu. \"Bak, iyi oldun. Artık günah işleme de başına daha kötü bir şey gelmesin\" dedi."},{"n":"15","t":"Adam Yahudilere gidip kendisini iyileştirenin İsa olduğunu bildirdi."},{"n":"16","t":"Sept günü böyle şeyler yaptığı için Yahudiler İsa'ya zulmetmeye başladılar."},{"n":"17","t":"Ama İsa onlara şu karşılığı verdi: \"Babam hâlâ çalışmaktadır, ben de çalışıyorum.\""},{"n":"18","t":"İşte bu nedenle Yahudiler O'nu öldürmek için daha çok gayret ettiler. Çünkü yalnız Sept günü düzenini bozmakla kalmamış, Tanrı'nın kendi Babası olduğunu söyleyerek kendisini Tanrı'ya eşit kılmıştı."},{"n":"19","h":"Yaşam veren İsa","t":"İsa Yahudilere şöyle karşılık verdi: \"Size doğrusunu söyleyeyim, Oğul, Baba'nın yaptıklarını görmedikçe kendiliğinden bir şey yapamaz. Baba ne yaparsa Oğul da aynı şeyi yapar."},{"n":"20","t":"Çünkü Baba Oğul'u sever ve yaptıklarının hepsini O'na gösterir. Şaşasınız diye O'na bunlardan daha büyük işler de gösterecektir."},{"n":"21","t":"Baba nasıl ölüleri diriltip onlara yaşam veriyorsa, Oğul da dilediği kimselere öylece yaşam verir."},{"n":"22","t":"Baba kimseyi yargılamaz, tüm yargılama işini Oğul'a vermiştir."},{"n":"23","t":"Öyle ki, herkes Baba'yı onurlandırdığı gibi Oğul'u onurlandırsın. Oğul'u onurlandırmayan, O'nu gönderen Baba'yı da onurlandırmaz."},{"n":"24","t":"\"Size doğrusunu söyleyeyim, sözümü işitip beni gönderene iman edenin sonsuz yaşamı vardır. Böyle biri yargılanmaz, ölümden yaşama geçmiştir."},{"n":"25","t":"Size doğrusunu söyleyeyim, ölülerin Tanrı Oğlunun sesini işitecekleri ve işitenlerin yaşayacakları saat geliyor, geldi bile."},{"n":"26","t":"Çünkü Baba, kendisinde yaşam olduğu gibi, Oğul'a da kendisinde yaşam olma özelliğini verdi."},{"n":"27","t":"O'na yargılama yetkisini de verdi. Çünkü O İnsanoğlu'dur."},{"n":"28","t":"Buna şaşmayın. Mezarda olanların hepsinin O'nun sesini işitecekleri saat geliyor."},{"n":"29","t":"Ve onlar mezarlarından çıkacaklar. İyilik yapmış olanlar yaşamak, kötülük yapmış olanlar yargılanmak üzere dirilecekler."},{"n":"30","h":"İsa'ya tanıklık","t":"\"Ben kendiliğimden hiçbir şey yapamam. İşittiğim gibi yargılarım ve benim yargım adildir. Çünkü amacım kendi istediğimi değil, beni gönderenin istediğini yapmaktır."},{"n":"31","t":"Eğer kendim için ben tanıklık edersem, tanıklığım geçerli olmaz."},{"n":"32","t":"Ama benim için tanıklık eden başka biri vardır. O'nun benim için ettiği tanıklığın geçerli olduğunu bilirim."},{"n":"33","t":"Siz Yahya'ya adamlar gönderdiniz, o da gerçeğe tanıklık etti."},{"n":"34","t":"İnsandan tanıklık kabul ettiğim için değil, kurtulmanız için bunları söylüyorum."},{"n":"35","t":"Yahya, yanan ve ışık saçan bir çıraydı. Sizler onun ışığında bir süre için coşmak istediniz."},{"n":"36","t":"Ama benim, Yahya'nınkinden daha büyük bir tanıklığım var. Tamamlamam için Baba'nın bana verdiği işler, şu yaptığım işler, beni Baba'nın gönderdiğine tanıklık ediyor."},{"n":"37","t":"Beni gönderen Baba da benim için tanıklık etmiştir. Siz hiçbir zaman O'nun ne sesini işittiniz, ne de şeklini gördünüz."},{"n":"38","t":"O'nun sözü sizde yaşamıyor. Çünkü O'nun gönderdiği kişiye iman etmiyorsunuz."},{"n":"39","t":"Kutsal Yazıları araştırıyorsunuz. Çünkü bunlarda sonsuz yaşama sahip olduğunuzu sanıyorsunuz. Bana tanıklık eden de bu yazılardır!"},{"n":"40","t":"Öyleyken siz, yaşama kavuşmak için bana gelmek istemiyorsunuz."},{"n":"41","t":"\"İnsanlardan övgü kabul etmiyorum."},{"n":"42","t":"Ama ben sizi bilirim, içinizde Tanrı sevgisi yoktur."},{"n":"43","t":"Ben Babamın adına geldim, ama beni kabul etmiyorsunuz. Oysa başka birisi kendi adına gelirse, onu kabul edeceksiniz."},{"n":"44","t":"Birbirinizden övgüler kabul ediyor, ama tek olan Tanrı'nın övgüsünü kazanmaya çalışmıyorsunuz. Bu durumda nasıl iman edebilirsiniz?"},{"n":"45","t":"Baba'nın önünde sizi suçlayacağımı sanmayın. Sizi suçlayan, umut bağladığınız Musa'dır."},{"n":"46","t":"Musa'ya iman etmiş olsaydınız, bana da iman ederdiniz. Çünkü o benim hakkımda yazmıştır."},{"n":"47","t":"Ama onun yazılarına iman etmezseniz, benimsözlerime nasıl iman edeceksiniz?\""}]},{"ch":6,"verses":[{"n":"1","h":"İsa beş bin kişiyi doyuruyor","t":"Bundan sonra İsa, Celile (Taberiye) gölünün karşı yakasına geçti."},{"n":"2","t":"Büyük bir kalabalık O'nun ardından gidiyordu. Çünkü hastalar üzerinde yaptığı mucizeleri görmüşlerdi."},{"n":"3","t":"İsa dağa çıkıp orada öğrencileriyle birlikte oturdu."},{"n":"4","t":"Yahudilerin Fısıh bayramı yakındı."},{"n":"5","t":"İsa başını kaldırıp büyük bir kalabalığın kendisine doğru geldiğini görünce Filipus'a, \"Bunları doyurmak için nereden ekmek alalım?\" diye sordu."},{"n":"6","t":"Bu sözü onu sınamak için söyledi, kendisi ne yapacağını biliyordu."},{"n":"7","t":"Filipus O'na şu cevabı verdi: \"Her birinin az bir şey yiyebilmesi için iki yüz dinarlık ekmek bile yetmez.\""},{"n":"8-9","t":"Öğrencilerinden biri, Simun Petrus'un kardeşi Andreya, İsa'ya dedi ki, \"Burada beş arpa ekmeğiyle iki balığı olan bir çocuk var. Ama bu kadar adam için bunlar nedir ki?\""},{"n":"10","t":"İsa, \"Halkı yere oturtun\" dedi.\nOrası çimenlik bir yerdi. Böylece halk yere oturdu. Oradaki erkeklerin sayısı beş bin kadardı."},{"n":"11","t":"İsa ekmekleri aldı, şükrettikten sonra oturanlara istedikleri kadar dağıttı. Balıklarla da aynı şeyi yaptı."},{"n":"12","t":"Herkes doyunca İsa öğrencilerine, \"Artıkları toplayın, hiçbir şey ziyan olmasın\" dedi."},{"n":"13","t":"Beş arpa ekmeğinden yiyenlerin bıraktığı artıkları topladılar ve bunlarla on iki sepet doldurdular."},{"n":"14","t":"Halk, İsa'nın yaptığı mucizeyi görünce, \"Gerçekten dünyaya gelecek olan peygamber budur\" dedi."},{"n":"15","t":"İsa onların gelip kendisini kral yapmak üzere zorla götüreceklerini bildiğinden tek başına yine dağa çekildi."},{"n":"16","h":"İsa su üstünde yürüyor","t":"Akşam olunca öğrencileri göle indiler."},{"n":"17","t":"Bir kayığa binerek gölün karşı yakasındaki Kefernahum'a doğru yol aldılar. Karanlık basmıştı ve İsa henüz yanlarına gelmemişti."},{"n":"18","t":"Güçlü bir rüzgâr estiğinden göl kabarmaya başladı."},{"n":"19","t":"Öğrenciler üç mil kadar kürek çektikten sonra, İsa'nın gölün üstünde yürüyerek kayığa yaklaştığını görünce korktular."},{"n":"20","t":"Ama İsa onlara, \"Ben'im, korkmayın!\" dedi."},{"n":"21","t":"Bunun üzerine O'nu kayığa almak istediler. O anda kayık gitmekte oldukları karaya vardı."},{"n":"22","t":"Ertesi gün, gölün karşı yakasında kalmış olan halk, önceden orada sadece bir tek kayık bulunduğunu, İsa'nın kendi öğrencileriyle birlikte bu kayığa binmediğini, öğrencilerinin yalnız gittiklerini anladı."},{"n":"23","t":"Rab'bin şükretmesinden sonra halkın ekmek yediği yerin yakınına Taberiye'den başka kayıklar geldi."},{"n":"24","t":"Halk, İsa'nın ve öğrencilerinin orada olmadığını görünce kayıklara binerek Kefernahum'a, İsa'yı aramaya gitti."},{"n":"25","t":"O'nugölün karşı yakasında buldukları zaman, \"Rabbî, buraya ne zaman geldin?\" diye sordular."},{"n":"26","h":"Yaşam ekmeği","t":"İsa şöyle cevap verdi: \"Size doğrusunu söyleyeyim, mucizeler gördüğünüz için değil, ekmeklerden yiyip doyduğunuz için beni arıyorsunuz."},{"n":"27","t":"Geçici olan yiyecek için değil, sonsuz yaşam boyunca kalan yiyecek için çalışın. Bunu size İnsanoğlu verecek. Çünkü Baba Tanrı O'na bu onayı vermiştir.\""},{"n":"28","t":"Onlar da şunu sordular: \"Tanrı'nın istediği işleri yapmak için ne yapmalıyız?\""},{"n":"29","t":"İsa, \"Tanrı'nın işi O'nun gönderdiği kişiye iman etmenizdir\" diye cevap verdi."},{"n":"30","t":"Bunun üzerine, \"Görüp sana iman etmemiz için nasıl bir mucize yaratacaksın? Ne yapacaksın?\" dediler."},{"n":"31","t":"\"Atalarımız çölde man yediler. Yazılmış olduğu gibi, 'Yemeleri için onlara gökten ekmek verdi.'\""},{"n":"32","t":"İsa onlara dedi ki, \"Size doğrusunu söyleyeyim, gökten ekmeği size Musa vermedi, gökten size gerçek ekmeği Babam verir."},{"n":"33","t":"Çünkü Tanrı'nın ekmeği, gökten inen ve dünyaya yaşam verendir.\""},{"n":"34","t":"Onlar da, \"Efendimiz, bizlere her zaman bu ekmeği ver!\" dediler."},{"n":"35","t":"İsa, \"Yaşam ekmeği ben'im. Bana gelen asla acıkmaz, bana iman eden hiçbir zaman susamaz\" dedi."},{"n":"36","t":"\"Ama ben size dedim ki, 'Beni gördünüz, yine de iman etmiyorsunuz.’"},{"n":"37","t":"Baba'nın bana verdiklerinin hepsi bana gelecek ve bana geleni ben asla kovmam."},{"n":"38","t":"Çünkü kendi isteğimi değil, beni gönderenin isteğini yerine getirmek için gökten indim."},{"n":"39","t":"Beni gönderenin isteği şudur: bana verdiklerinden hiçbirini yitirmeyeyim, ama son günde hepsini dirilteyim."},{"n":"40","t":"Çünkü Babamın isteği, Oğul'u gören ve O'na iman eden herkesin sonsuz yaşama kavuşmasıdır. Ben de böylelerini son günde dirilteceğim.\""},{"n":"41","t":"\"Gökten inmiş olan ekmek ben'im\" dediği için Yahudiler O'na karşı söylenmeye başladılar."},{"n":"42","t":"\"Yusuf'un oğlu İsa değil mi bu?\" diyorlardı. \"Annesini de, babasını da tanıyoruz. Şimdi nasıl oluyor da, 'gökten indim' diyor?\""},{"n":"43","t":"İsa, \"Aranızda söylenmeyin\" diye cevap verdi."},{"n":"44","t":"\"Beni gönderen Baba bir kimseyi bana çekmedikçe, o kimse bana gelemez. Bana geleni de son günde dirilteceğim."},{"n":"45","t":"Peygamberlerin yazdığı gibi, 'Tanrı onların hepsine kendi yollarını öğretecektir.' Baba'yı işiten ve O'ndan öğrenen herkes bana gelir."},{"n":"46","t":"Bu, bir kimsenin Baba'yı gördüğü anlamına gelmez. Baba'yı sadece Tanrı'dan gelen görmüştür."},{"n":"47","t":"Size doğrusunu söyleyeyim, iman edenin sonsuz yaşamı vardır."},{"n":"48","t":"Yaşam ekmeği ben'im."},{"n":"49","t":"Atalarınız çölde man yediler, yine de öldüler."},{"n":"50","t":"Gökten inen öyle bir ekmek var ki, ondan yiyen ölmeyecek."},{"n":"51","t":"Gökten inmiş olan diri ekmek ben'im. Bu ekmekten yiyen sonsuza dek yaşayacak. Dünyanın yaşamı uğruna vereceğim ekmek de benim bedenimdir.\""},{"n":"52","t":"Bunun üzerine Yahudiler, \"Bu adam yememiz için bedenini bize nasıl verebilir?\" diyerek birbirleriyle çekişmeye başladılar."},{"n":"53","t":"İsa onlara şöyle dedi: \"Size doğrusunu söyleyeyim, İnsanoğlu'nun bedenini yiyip kanını içmedikçe, sizde yaşam olmaz."},{"n":"54","t":"Bedenimi yiyenin, kanımı içenin sonsuz yaşamı vardır ve ben onuson günde dirilteceğim."},{"n":"55","t":"Çünkü bedenim gerçek yiyecek, kanım gerçek içecektir."},{"n":"56","t":"Bedenimi yiyip kanımı içen bende yaşar, ben de onda."},{"n":"57","t":"Yaşayan Baba beni gönderdiği ve ben Baba'nın aracılığıyla yaşadığım gibi, bedenimi yiyen de benim aracılığımla yaşayacak."},{"n":"58","t":"İşte gökten inmiş olan ekmek budur. Atalarınızın yedikleri man gibi değildir. Atalarınız öldüler. Oysa bu ekmeği yiyen sonsuza dek yaşar.\""},{"n":"59","t":"İsa bu sözleri Kefernahum'da havrada ders verirken söyledi."},{"n":"60","h":"Birçok kişi İsa'yı terk ediyor","t":"Öğrencilerinin birçoğu bunu işitince, \"Bu söz çetindir, bunu kim kabul edebilir?\" dediler."},{"n":"61","t":"Öğrencilerinin buna karşı söylendiğini anlayan İsa, \"Bu sizi şaşırtıyor mu?\" dedi."},{"n":"62","t":"\"Ya İnsanoğlu'nun önceden bulunduğu yere yükseldiğini görürseniz…?"},{"n":"63","t":"Yaşam veren Ruh'tur. Beden bir yarar sağlamaz. Sizlere söylediğim sözler ruhtur, yaşamdır."},{"n":"64","t":"Yine de aranızda iman etmeyenler var.\" İsa iman etmeyenlerin ve kendisini ele verecek olanın kim olduğunu başlangıçtan biliyordu."},{"n":"65","t":"\"Sizlere, 'Baba'nın bana yöneltmediği hiç kimse bana gelemez' dememin nedeni budur\" dedi."},{"n":"66","t":"Bunun üzerine öğrencilerinin birçoğu geri döndüler, artık O'nunla dolaşmaz oldular."},{"n":"67","t":"İsa o zaman Onikilere, \"Siz de mi ayrılmak istiyorsunuz?\" diye sordu."},{"n":"68","t":"Simun Petrus şu cevabı verdi: \"Rab, biz kime gidelim? Sonsuz yaşamın sözleri sendedir."},{"n":"69","t":"İman ediyor ve biliyoruz ki, sen Tanrı'nın Kutsalısın.\""},{"n":"70","t":"İsa onlara şu karşılığı verdi: \"Siz Onikileri seçen ben değil miyim? Yine de aranızdan biri iblistir.\""},{"n":"71","t":"Simun İskariyot'un oğlu Yahuda'dan söz ediyordu. Çünkü Yahuda Onikilerden biri olduğu halde İsa'yı ele verecekti."}]},{"ch":7,"verses":[{"n":"1","h":"İsa Kudüs'e gidiyor","t":"Bundan sonra İsa Celile'de dolaşmaya başladı. Yahudiler O'nu öldürmeyi amaçladıkları için Yahudiye'de dolaşmak istemiyordu."},{"n":"2","t":"Yahudilerin Çardak bayramı yaklaşmıştı."},{"n":"3","t":"Bu nedenle İsa'nın kardeşleri O'na, \"Buradan ayrıl, Yahudiye'ye git\" dediler, \"öğrencilerin de yaptığın işleri görsünler."},{"n":"4","t":"Çünkü kendini açıkça tanıtmak isteyen bir kimse yaptıklarını gizlemez. Madem ki bu şeyleri yapıyorsun, kendini dünyaya göster!\""},{"n":"5","t":"Kardeşleri bile O'na iman etmiyorlardı."},{"n":"6","t":"İsa onlara, \"Benim zamanım daha gelmedi\" dedi, \"oysa sizin için zaman hep uygundur."},{"n":"7","t":"Dünya sizden nefret edemez, ama benden nefret ediyor. Çünkü yaptıklarının kötü olduğuna tanıklık ediyorum."},{"n":"8","t":"Siz bu bayramı kutlamaya gidin. Ben şimdilik gitmeyeceğim. Çünkü benim zamanım daha dolmadı.\""},{"n":"9","t":"İsa bu sözleri söyleyip Celile'de kaldı."},{"n":"10","t":"Ne var ki, kardeşleri bayramı kutlamaya gidince, kendisi de gitti. Ancak açıktan açığa değil, gizlice gitti."},{"n":"11","t":"Yahudiler de O'nu bayram sırasında arıyor, \"O nerede?\" diye soruyorlardı."},{"n":"12","t":"Kalabalık arasında O'nunla ilgili bir sürü laf fısıldanıyordu. Bazıları, \"İyi adamdır\", bazıları da, \"Hayır, tam tersine, halkı saptırıyor\" diyorlardı."},{"n":"13","t":"Bununla birlikte Yahudilerden korktukları için, hiç kimse O'ndan açıkça söz etmiyordu."},{"n":"14","t":"Bayramın yarısı geçmişti. İsa da tapınağa gidip ders vermeye başladı."},{"n":"15","t":"Yahudiler şaşırmışlardı. \"Bu adam hiç öğrenim görmediği halde, nasıl bu kadar bilgili olabilir?\" diyorlardı."},{"n":"16","t":"İsa onlara, \"Benim öğretim benim değil, beni gönderenindir\" diye karşılık verdi."},{"n":"17","t":"\"Eğer bir kimse Tanrı'nın isteğini yerine getirmek istiyorsa, bu öğretinin Tanrı'dan mı olduğunu, yoksa kendiliğimden mi konuştuğumu bilecektir."},{"n":"18","t":"Kendiliğinden konuşan kendini yüceltmek ister, ama kendisini göndereni yüceltmek isteyen doğrudur ve O'nda haksızlık yoktur."},{"n":"19","t":"Musa size Kutsal Yasa'yı vermedi mi? Yine de hiçbiriniz Yasa'yı yerine getirmiyor. Neden beni öldürmek istiyorsunuz?\""},{"n":"20","t":"Kalabalık, \"Cin çarptı seni!\" dedi. \"Seni öldürmek isteyen kim?\""},{"n":"21","t":"İsa, \"Ben bir mucize yaptım, hepiniz şaşkına döndünüz\" diye cevap verdi."},{"n":"22","t":"\"Musa size sünneti buyurduğu için - aslında bu, Musa'dan değil, atalarınızdan kalmadır - Sept günü birini sünnet edersiniz."},{"n":"23","t":"Musa'nın Yasası bozulmasın diye Sept günü biri sünnet ediliyor da, Sept günü bir adamı tamamen iyileştirdim diye bana neden kızıyorsunuz?"},{"n":"24","t":"Dış görünüşe göre yargılamayın, yargınız adil olsun.\""},{"n":"25","h":"İsa, Mesih midir?","t":"Kudüslülerin bazıları, \"Öldürmek istedikleri adam bu değil mi?\" diyorlardı."},{"n":"26","t":"\"Bakın, açıkça konuşuyor, O'na bir şey demiyorlar. Yoksa önderler O'nun Mesih olduğunu gerçekten kabul ettiler mi?"},{"n":"27","t":"Ama biz bu adamın nereden geldiğini biliyoruz. Oysa Mesih geldiği zaman O'nun nereden geldiğini kimse bilmeyecek.\""},{"n":"28","t":"O sırada tapınakta ders veren İsa yüksek sesle şöyle dedi: \"Hem beni tanıyorsunuz, hem de nereden olduğumu biliyorsunuz! Ben kendiliğimden gelmedim. Beni gönderen gerçektir. O'nu siz tanımıyorsunuz."},{"n":"29","t":"Ben O'nu tanırım. Çünkü ben O'ndanım, beni O gönderdi.\""},{"n":"30","t":"Bunun üzerine O'nu yakalamak istediler, ama kimse O'na el sürmedi. Çünkü O'nun saati henüz gelmemişti."},{"n":"31","t":"Halktan birçok kişi ise O'na iman etti. \"Mesih gelince, bunun yaptıklarından daha mı çok mucize yapacak?\" diyorlardı."},{"n":"32","t":"Ferisiler halkın İsa hakkında böyle fısıldaştığını duydular. Başkâhinler ve Ferisiler O'nu yakalamak için görevliler gönderdiler."},{"n":"33","t":"İsa, \"Kısa bir süre daha sizinleyim\" dedi, \"sonra beni gönderene gideceğim."},{"n":"34","t":"Beni arayacaksınız, ama bulamayacaksınız. Ve benim bulunduğum yere siz gelemezsiniz.\""},{"n":"35","t":"Bunun üzerine Yahudiler birbirlerine, \"Bu adam nereye gidecek de biz O'nu bulamayacağız?\" dediler. \"Yoksa Grekler arasında dağılmış olanlara gidip Greklere mi ders verecek?"},{"n":"36","t":"'Beni arayacaksınız, ama bulamayacaksınız. Ve benim bulunduğum yere siz gelemezsiniz' diyor. Ne demek istiyor?\""},{"n":"37","t":"Bayramın son ve en önemli günü İsa ayağa kalktı, yüksek sesleşöyle dedi: \"Bir kimse susamışsa bana gelsin, içsin."},{"n":"38","t":"Kutsal Yazı ‘da dendiği gibi, bana iman edenin 'içinden diri su ırmakları akacaktır.’\""},{"n":"39","t":"Bunu, kendisine iman edenlerin alacağı Ruh'la ilgili olarak söylüyordu. Ruh henüz verilmemişti. Çünkü İsa henüz yüceltilmemişti."},{"n":"40","t":"Halktan bazıları bu sözleri işitince, \"Gerçekten beklediğimiz peygamber budur\" dediler."},{"n":"41","t":"Bazıları da, \"Bu Mesih'tir\" diyorlardı.\nBaşkaları ise, \"Olamaz! Mesih Celile'den mi gelecek?\" dediler."},{"n":"42","t":"\"Kutsal Yazı'da, 'Mesih, Davut'un soyundan, Davut'un yaşadığı Beytlehem köyünden gelecek' denmemiş midir?\""},{"n":"43","t":"Böylece İsa'dan dolayı halk arasında ayrılık doğdu."},{"n":"44","t":"Bazıları O'nu yakalamak istedilerse de, kimse O'na el sürmedi."},{"n":"45","h":"Yahudi önderlerin imansızlığı","t":"Görevliler geri dönünce, başkâhinlerle Ferisiler, \"Niçin O'nu getirmediniz?\" diye sordular."},{"n":"46","t":"Görevliler, \"Hiç kimse hiçbir zaman bu adamın konuştuğu gibi konuşmamıştır\" karşılığını verdiler."},{"n":"47","t":"Ferisiler, \"Yoksa siz de mi aldandınız?\" dediler."},{"n":"48","t":"\"Önderlerden ya da Ferisilerden O'na iman eden oldu mu hiç?"},{"n":"49","t":"Kutsal Yasa'yı bilmeyen bu halk lanetlidir.\""},{"n":"50-51","t":"İçlerinden biri, daha önce İsa'ya gelmiş olan Nikodim, onlara şöyle dedi: \"Yasamıza göre, bir adamı dinlemeden, ne yaptığını öğrenmeden onu yargılamak doğru mu?\""},{"n":"52","t":"Ona, \"Yoksa sen de mi Celile'densin?\" diye karşılık verdiler. \"Araştır, bak, Celile'den peygamber çıkmaz.\""},{"n":"53","t":"Bundan sonra herkes evine gitti."}]},{"ch":8,"verses":[{"n":"1","h":"Zinada yakalanan kadın","t":"İsa ise Zeytin dağına gitti."},{"n":"2","t":"Ertesi sabah erkenden yine tapınağa döndü. Bütün halk O'nun yanına geliyordu. O da oturup onlara ders vermeye başladı."},{"n":"3-4","t":"Din bilginleri ve Ferisiler, zina ederken yakalanmış bir kadın getirdiler. Kadını orta yere çıkararak İsa'ya, \"Öğretmen, bu kadın tam zina ederken yakalandı\" dediler."},{"n":"5","t":"\"Musa, Yasa'da bize böyle kadınların taşlanmasını buyurdu, sen ne dersin?\""},{"n":"6","t":"Bunları İsa'yı sınamak amacıyla söylüyorlardı; O'nu suçlayabilmek için bir neden arıyorlardı.\nİsa eğilmiş, parmağıyla toprağa yazı yazıyordu."},{"n":"7","t":"Durmadan aynı soruyu sormaları üzerine doğruldu ve, \"Aranızda günahsız olan, ona ilk taşı atsın!\" dedi."},{"n":"8","t":"Sonra yine eğildi, toprağa yazmaya koyuldu."},{"n":"9","t":"Bunu işittikleri zaman, başta yaşlılar olmak üzere, birer birer dışarı çıkıp İsa'yı yalnız bıraktılar. Kadın ise orta yerde duruyordu."},{"n":"10","t":"İsa doğrulup ona, \"Kadın, nerede onlar? Hiçbiri seni yargılamadı mı?\" diye sordu."},{"n":"11","t":"Kadın, \"Hiçbiri, efendim\" dedi.\nİsa, \"Ben de seni yargılamıyorum\" dedi. \"Git, artık bundan sonra günah işleme!\""},{"n":"12","h":"Geçerli tanıklık","t":"İsa yine halka seslenip şöyle dedi: \"Ben dünyanın ışığıyım. Benim ardımdan gelen, asla karanlıkta yürümez, yaşam ışığına sahip olur.\""},{"n":"13","t":"Ferisiler, \"Sen kendin için tanıklık ediyorsun, tanıklığın geçerli değil\" dediler."},{"n":"14","t":"İsa onlara şu karşılığı verdi: \"Kendim için tanıklık etsem bile tanıklığım geçerlidir. Çünkü nereden geldiğimi ve nereye gideceğimi biliyorum. Oysa siz nereden geldiğimi, nereye gideceğimi bilmiyorsunuz."},{"n":"15","t":"Siz insan gözüyle yargılıyorsunuz. Ben kimseyi yargılamam."},{"n":"16","t":"Ama yargılasam bile benim yargım doğrudur. Çünkü ben yalnız değilim, ben ve beni gönderen Baba, birlikte yargılarız."},{"n":"17","t":"Yasanızda da, 'İki kişinin tanıklığı geçerlidir' diye yazılmıştır."},{"n":"18","t":"Kendim için tanıklık eden bir ben varım, bir de beni gönderen Baba benim için tanıklık ediyor.\""},{"n":"19","t":"O zaman O'na, \"Baban nerede?\" diye sordular.\nİsa şu karşılığı verdi: \"Siz ne beni tanırsınız, ne de Babamı. Beni tanısaydınız, Babamı da tanırdınız.\""},{"n":"20","t":"İsa bu sözleri tapınakta ders verirken, bağış toplanan yerde söyledi. Kimse O'nu yakalamadı. Çünkü saati henüz gelmemişti."},{"n":"21","t":"İsa yine onlara, \"Ben gidiyorum. Beni arayacaksınız ve günahınızın içinde öleceksiniz. Benim gideceğim yere siz gelemezsiniz\" dedi."},{"n":"22","t":"Yahudiler, \"Yoksa kendini mi öldürecek?\" dediler. \"Çünkü, 'Benim gideceğim yere siz gelemezsiniz' diyor.\""},{"n":"23","t":"İsa onlara, \"Siz aşağıdansınız, ben yukarıdanım\" dedi. \"Siz bu dünyadansınız, ben bu dünyadan değilim."},{"n":"24","t":"İşte bu nedenle size, 'Günahlarınızın içinde öleceksiniz' dedim. Benim O olduğuma iman etmezseniz, günahlarınızın içinde öleceksiniz.\""},{"n":"25","t":"O'na, \"Sen kimsin?\" diye sordular.\nİsa, \"Başlangıçtan beri size ne söyledimse, O'yum\" dedi."},{"n":"26","t":"\"Sizinle ilgili söyleyecek ve sizleri yargılayacak çok şeyim var. Beni gönderen gerçektir. Ben O'ndan işittiklerimi dünyaya bildiriyorum.\""},{"n":"27","t":"İsa'nın kendilerine Baba'dan söz ettiğini anlamadılar."},{"n":"28","t":"Bu nedenle İsa şöyle dedi: \"İnsanoğlu'nu yukarı kaldırdığınız zaman benim O olduğumu, kendiliğimden hiçbir şey yapmadığımı, ama tıpkı Baba'nın bana öğrettiği gibi konuştuğumu anlayacaksınız."},{"n":"29","t":"Beni gönderen benimledir, O beni yalnız bırakmadı. Çünkü ben her zaman O'nu hoşnut edeni yaparım.\""},{"n":"30","t":"Bu sözler üzerine birçokları O'na iman etti."},{"n":"31-32","h":"İbrahim'in çocukları, İblis'in çocukları","t":"İsa kendisine iman etmiş olan Yahudilere, \"Eğer benim sözüme bağlı kalırsanız, gerçekten öğrencilerim olursunuz. Gerçeği bileceksiniz ve gerçek sizi özgür kılacak\" dedi."},{"n":"33","t":"\"Biz İbrahim'in soyundanız\" diye karşılık verdiler, \"hiçbir zaman kimseye kölelik etmedik. Nasıl oluyor da sen, 'Özgür olacaksınız' diyorsun?\""},{"n":"34","t":"İsa, \"Size doğrusunu söyleyeyim, günah işleyen herkes günahın kölesidir\" dedi."},{"n":"35","t":"\"Köle ev halkının sürekli bir üyesi değildir, ama oğul sürekli üyesidir."},{"n":"36","t":"Bunun için, Oğul sizi özgür kılarsa,gerçekten özgür olursunuz."},{"n":"37","t":"İbrahim'in soyundan olduğunuzu biliyorum. Yine de beni öldürmek istiyorsunuz. Çünkü yüreğinizde sözüme yer vermiyorsunuz."},{"n":"38","t":"Ben Babamın yanında gördüklerimi söylüyorum, siz de babanızdan işittiklerinizi yapıyorsunuz.\""},{"n":"39","t":"\"Bizim babamız İbrahim'dir\" diye karşılık verdiler.\nİsa, \"İbrahim'in çocukları olsaydınız, İbrahim'in yaptıklarını yapardınız\" dedi."},{"n":"40","t":"\"Ama şimdi beni - Tanrı'dan işittiği gerçeği sizlere bildireni - öldürmek istiyorsunuz. İbrahim bunu yapmadı."},{"n":"41","t":"Siz babanızın yaptıklarını yapıyorsunuz.\"\n\"Biz zinadan doğmadık. Bir tek Babamız var, o da Tanrı'dır\" dediler."},{"n":"42","t":"İsa, \"Tanrı Babanız olsaydı, beni severdiniz\" dedi. \"Çünkü ben Tanrı'dan çıkıp geldim. Kendiliğimden gelmedim, beni O gönderdi."},{"n":"43","t":"Söylediklerimi neden anlamıyorsunuz? Benim sözümü dinlemeye dayanamıyorsunuz da ondan."},{"n":"44","t":"Siz babanız İblis'tensiniz ve babanızın arzularını yerine getirmek istiyorsunuz. O başlangıçtan beri katildi. Gerçeğe bağlı kalmadı. Çünkü onda gerçek yoktur. Yalan söylemesi doğaldır. Çünkü o yalancıdır ve yalanın babasıdır."},{"n":"45","t":"Ama ben gerçeği söylüyorum. İşte bunun için bana iman etmiyorsunuz."},{"n":"46","t":"Hanginiz bana günahlı olduğumu kanıtlayabilir? Gerçeği söylüyorsam, niçin bana iman etmiyorsunuz?"},{"n":"47","t":"Tanrı'dan olan, Tanrı'nın sözlerini dinler. İşte siz Tanrı'dan olmadığınız için dinlemiyorsunuz.\""},{"n":"48","h":"İsa'nın yüceliği","t":"Yahudiler O'na şu karşılığı verdiler: \"'Sen, cin çarpmış bir Samiriyelisin' demekte haklı değil miyiz?\""},{"n":"49","t":"İsa, \"Beni cin çarpmadı\" dedi. \"Ben Babamı onurlandırıyorum, ama siz beni aşağılıyorsunuz."},{"n":"50","t":"Ben kendimi yüceltmek istemiyorum, ama bunu isteyen ve yargılayan biri vardır."},{"n":"51","t":"Size doğrusunu söyleyeyim, bir kimse sözüme uyarsa, ölümü asla görmeyecektir.\""},{"n":"52","t":"Yahudiler, \"Seni cin çarptığını şimdi anlıyoruz\" dediler. \"İbrahim öldü, peygamberler de öldü. Oysa sen, 'Bir kimse sözüme uyarsa, ölümü asla tatmayacaktır' diyorsun."},{"n":"53","t":"Yoksa sen babamız İbrahim'den üstün müsün? O öldü, peygamberler de öldü. Sen kendini kim sanıyorsun?\""},{"n":"54","t":"İsa şu karşılığı verdi: \"Eğer ben kendimi yüceltirsem, yüceliğim hiçtir. Beni yücelten, 'Tanrımız' diye çağırdığınız Babamdır."},{"n":"55","t":"Siz O'nu tanımıyorsunuz, ama ben tanırım. O'nu tanımadığımı söylersem, sizin gibi yalancı olurum. Ama ben O'nu tanırım ve sözüne uyarım."},{"n":"56","t":"Babanız İbrahim günümü göreceği için sevinçle coşmuştu. Gördü ve sevindi.\""},{"n":"57","t":"Yahudiler, \"Sen daha elli yaşında bile değilsin. İbrahim'i de mi gördün?\" dediler."},{"n":"58","t":"İsa, \"Size doğrusunu söyleyeyim, İbrahim doğmadan önce ben varım\" dedi."},{"n":"59","t":"O zaman İsa'yı taşlamak için yerden taş aldılar, ama O gizlenip tapınaktan çıktı."}]},{"ch":9,"verses":[{"n":"1","h":"Kör bir adam iyileştiriliyor","t":"İsa yolda giderken doğuştan kör bir adam gördü."},{"n":"2","t":"Öğrencileri İsa'ya, \"Rabbî, kim günah işledi de bu adam kör doğdu? Kendisi mi, yoksa annesi babası mı?\" diye sordular."},{"n":"3","t":"İsa şu cevabı verdi: \"Ne kendisi, ne de annesi babası günah işledi. Tanrı'nın işleri onun yaşamında görülsün diye kör doğdu."},{"n":"4","t":"Beni gönderenin işlerini vakit daha gündüzken yapmalıyız. Gece geliyor, o zaman kimse çalışamaz."},{"n":"5","t":"Dünyada olduğum sürece dünyanın ışığı ben'im.\""},{"n":"6","t":"Bu sözleri söyledikten sonra yere tükürdü, tükürükle çamur yaptı ve çamuru adamın gözlerine sürdü."},{"n":"7","t":"Adama, \"Git, Şiloha havuzunda yıkan\" dedi. Şiloha, 'gönderilmiş' anlamına gelir.\nAdam gidip yıkandı, gözleri açılmış olarak döndü."},{"n":"8","t":"Komşuları ve onu daha önce dilenirken görenler, \"Oturup dilenen adam değil mi bu?\" dediler."},{"n":"9","t":"Kimi, \"Evet, odur\" dedi, kimi de \"Hayır, ama ona benziyor\" dedi.\nKendisi ise, \"Ben oyum\" dedi."},{"n":"10","t":"\"Öyleyse, gözlerin nasıl açıldı?\" diye sordular."},{"n":"11","t":"O da şöyle cevap verdi: \"İsa adındaki adam çamur yapıp gözlerime sürdü ve bana, 'Şiloha'ya git, yıkan' dedi. Ben de gidip yıkandım ve gözlerim açıldı.\""},{"n":"12","t":"Ona, \"Nerede O?\" diye sordular.\n\"Bilmiyorum\" dedi."},{"n":"13","h":"Ferisilerin soruşturması","t":"Eskiden kör olan adamı Ferisilerin yanına götürdüler."},{"n":"14","t":"İsa'nın çamur yapıp adamın gözlerini açtığı gün Sept günüydü."},{"n":"15","t":"Bu nedenle Ferisiler de adama gözlerinin nasıl açıldığını sordular. O da, \"İsa gözlerime çamur sürdü, yıkandım ve şimdi görüyorum\" dedi."},{"n":"16","t":"Bunun üzerine Ferisilerin bazıları, \"Bu adam Tanrı'dan değildir\" dediler. \"Çünkü Sept günüyle ilgili buyruğa uymuyor.\"\nAma başkaları, \"Günahkâr bir adam nasıl böyle mucizeler yapabilir?\" dediler.\nBöylece aralarında ayrılık doğdu."},{"n":"17","t":"Eskiden kör olan adama yine sordular: \"Senin gözlerini açtığına göre, O'nun hakkında sen ne diyorsun?\"\nAdam, \"O bir peygamberdir\" dedi."},{"n":"18","t":"Yahudiler, gözleri açılmış olan adamın annesiyle babasını çağırmadan onun daha önce kör olduğuna ve gözlerinin açıldığına inanmadılar."},{"n":"19","t":"Onlara, \"Kör doğdu dediğiniz oğlunuz bu mu? Peki, şimdi nasıl görüyor?\" diye sordular."},{"n":"20","t":"Adamın annesiyle babası şu karşılığı verdiler: \"Bunun bizim oğlumuz olduğunu ve kör doğduğunu biliyoruz."},{"n":"21","t":"Ama şimdi nasıl gördüğünü, gözlerini kimin açtığını bilmiyoruz, ona sorun. Ergin yaştadır, kendisi için kendisi konuşsun.\""},{"n":"22","t":"Yahudilerden korktukları için böyle konuştular. Çünkü Yahudiler, İsa'nın Mesih olduğunu açıkça söyleyeni havra dışı etmek için aralarında sözbirliği etmişlerdi."},{"n":"23","t":"Bundan dolayı adamın annesiyle babası, \"Ergin yaştadır, ona sorun\" dediler."},{"n":"24","t":"Eskiden kör olan adamı ikinci kez çağırıp, \"Tanrı hakkı içindoğruyu söyle\" dediler, \"biz bu adamın günahkâr olduğunu biliyoruz.\""},{"n":"25","t":"O da şöyle cevap verdi: \"O'nun günahkâr olup olmadığını bilmiyorum. Bildiğim bir şey var, kördüm, şimdi görüyorum.\""},{"n":"26","t":"O zaman ona, \"Sana ne yaptı? Gözlerini nasıl açtı?\" dediler."},{"n":"27","t":"Onlara, \"Size demin söyledim, ama dinlemediniz\" dedi. \"Niçin yeniden işitmek istiyorsunuz? Yoksa siz de mi O'nun öğrencileri olmak niyetindesiniz?\""},{"n":"28","t":"Adama söverek, \"O'nun öğrencisi sensin!\" dediler. \"Biz Musa'nın öğrencileriyiz."},{"n":"29","t":"Tanrı'nın Musa'yla konuştuğunu biliriz. Ama bu adamın nereden geldiğini bilmiyoruz.\""},{"n":"30","t":"Adam onlara şu karşılığı verdi: \"Şaşılacak şey! O'nun nereden geldiğini bilmiyorsunuz, ama gözlerimi O açtı."},{"n":"31","t":"Tanrı'nın, günahkârları dinlemediğini biliriz. Ama Tanrı, kendisine tapan ve isteğini yerine getiren kişiyi dinler."},{"n":"32","t":"Dünya var olalı, bir kimsenin doğuştan kör olan birinin gözlerini açtığı duyulmamıştır."},{"n":"33","t":"Bu adam Tanrı'dan olmasaydı, hiçbir şey yapamazdı.\""},{"n":"34","t":"Onlar buna karşılık, \"Tamamen günah içinde doğdun, sen mi bize ders vereceksin?\" diyerek onu dışarı attılar."},{"n":"35","h":"Ruhsal körlük","t":"İsa adamı kovduklarını duydu. Onu bularak, \"Sen İnsanoğlu'na iman ediyor musun?\" diye sordu."},{"n":"36","t":"Adam şu cevabı verdi: \"Efendim, O kimdir? Söyle de kendisine iman edeyim.\""},{"n":"37","t":"İsa, \"O'nu gördün. Şimdi seninle konuşan O'dur\" dedi."},{"n":"38","t":"Adam, \"Rab, iman ediyorum!\" diyerek İsa'ya tapındı."},{"n":"39","t":"İsa, \"Görmeyenler görsün, görenler kör olsun diye yargıçlık etmek üzere bu dünyaya geldim\" dedi."},{"n":"40","t":"O'nun yanında bulunan bazı Ferisiler bu sözleri işitince, \"Yoksa biz de mi körüz?\" diye sordular."},{"n":"41","t":"İsa, \"Kör olsaydınız günahınız olmazdı\" dedi, \"ama şimdi, 'Görüyoruz' dediğiniz için günahınız duruyor."}]},{"ch":10,"verses":[{"n":"1","h":"İyi çoban","t":"\"Size doğrusunu söyleyeyim, koyun ağılına kapıdan girmeyip başka yoldan giren kişi hırsız ve hayduttur."},{"n":"2","t":"Kapıdan giren ise koyunların çobanıdır."},{"n":"3","t":"Kapıyı bekleyen ona kapıyı açar. Koyunlar çobanın sesini işitirler, o da kendi koyunlarını adlarıyla çağırır ve onları dışarı götürür."},{"n":"4","t":"Kendi koyunlarının hepsini dışarı çıkarınca önlerinden gider, koyunlar da onu izler. Çünkü onun sesini tanırlar."},{"n":"5","t":"Bir yabancının peşinden gitmezler, ondan kaçarlar. Çünkü yabancıların sesini tanımazlar.\""},{"n":"6","t":"İsa onlara bu örneği anlattıysa da, ne demek istediğini anlamadılar."},{"n":"7","t":"Bunun için İsa yine, \"Size doğrusunu söyleyeyim\" dedi, \"ben koyunların kapısıyım."},{"n":"8","t":"Benden önce gelenlerin hepsi hırsız ve hayduttu, ama koyunlar onları dinlemedi."},{"n":"9","t":"Kapı ben'im. Bir kimsebenim aracılığımla içeri girerse kurtulur. Girer, çıkar ve otlak bulur."},{"n":"10","t":"Hırsız ancak çalıp öldürmek ve yok etmek için gelir. Bense insanlar yaşama, bol yaşama sahip olsunlar diye geldim."},{"n":"11","t":"Ben iyi çobanım. İyi çoban koyunları uğruna canını verir."},{"n":"12","t":"Koyunların çobanı ve sahibi olmayan ücretli adam, kurdun geldiğini görünce koyunları bırakıp kaçar. Kurt da onları kapar ve dağıtır."},{"n":"13","t":"Adam kaçar. Çünkü ücretlidir ve koyunlar için kaygı duymaz."},{"n":"14-15","t":"Ben iyi çobanım. Benimkileri tanırım. Baba beni tanıdığı, ben de Baba'yı tanıdığım gibi, benimkiler de beni tanır. Ben koyunlarımın uğruna canımı veririm."},{"n":"16","t":"Bu ağıldan olmayan başka koyunlarım var. Onları da getirmeliyim. Benim sesimi işitecekler ve tek sürü, tek çoban olacak."},{"n":"17","t":"Canımı, tekrar geri almak üzere veririm. Bunun için Baba beni sever."},{"n":"18","t":"Canımı kimse benden alamaz; ben onu kendiliğimden veririm. Onu vermeye de tekrar geri almaya da yetkim var. Bu buyruğu Babamdan aldım.\""},{"n":"19","t":"Bu sözlerden dolayı Yahudiler arasında yine ayrılık doğdu."},{"n":"20","t":"Birçoğu, \"O'nu cin çarpmış, delidir. Niçin O'nu dinliyorsunuz?\" diyordu."},{"n":"21","t":"Başkaları ise, \"Bunlar, cin çarpmış bir adamın sözleri değildir\" dediler. \"Cin, körlerin gözlerini açabilir mi?\""},{"n":"22","h":"İsa'ya karşı tepkiler büyüyor","t":"O sırada Kudüs'te tapınağın açılışını anma bayramı kutlanıyordu. Mevsim kıştı."},{"n":"23","t":"İsa tapınağın avlusunda, Süleyman'ın Eyvanında yürüyordu."},{"n":"24","t":"Yahudiler O'nun çevresini sararak, \"Bizi daha ne kadar zaman kuşkuda bırakacaksın?\" dediler. \"Eğer Mesih isen, bize açıkça söyle.\""},{"n":"25","t":"İsa onlara şu karşılığı verdi: \"Size söyledim, ama iman etmiyorsunuz. Babamın adıyla yaptığım işler bana tanıklık ediyor."},{"n":"26","t":"Ama siz iman etmiyorsunuz. Çünkü benim koyunlarımdan değilsiniz."},{"n":"27","t":"Koyunlarım sesimi işitir. Ben onları tanırım, onlar da beni izler."},{"n":"28","t":"Onlara sonsuz yaşam veririm; asla mahvolmayacaklar. Onları hiç kimse elimden kapamaz."},{"n":"29","t":"Onları bana veren Babam her şeyden üstündür. Onları Baba'nın elinden kapmaya kimsenin gücü yetmez."},{"n":"30","t":"Ben ve Baba biriz.\""},{"n":"31","t":"Yahudiler O'nu taşlamak için yerden yine taş aldılar."},{"n":"32","t":"İsa onlara, \"Size Baba'dan kaynaklanan birçok iyi işler gösterdim\" dedi. \"Bu işlerden hangisi için beni taşlıyorsunuz?\""},{"n":"33","t":"Yahudiler şöyle cevap verdiler: \"Seni iyi işlerden ötürü değil, küfür ettiğin için taşlıyoruz. İnsan olduğun halde Tanrı olduğunu ileri sürüyorsun.\""},{"n":"34","t":"İsa şu karşılığı verdi: \"Yasanızda, 'Siz ilahlarsınız, dedim' diye yazılı değil mi?"},{"n":"35","t":"Tanrı, kendilerine sözünü gönderdiği kimseleri ilahlar diye adlandırır. Kutsal Yazı da geçerliliğini yitirmez."},{"n":"36","t":"Baba beni kendine ayırıp dünyaya gönderdi. Öyleyse 'Tanrı'nın Oğluyum' dediğim için bana nasıl 'Küfür ediyorsun' dersiniz?"},{"n":"37","t":"Eğer Babamın işlerini yapmıyorsam, bana iman etmeyin."},{"n":"38","t":"Ama yapıyorsam, bana iman etmeseniz bile, yaptığım işlere iman edin. Öyle ki, Baba'nın bende, benim de Baba'da olduğumu bilesiniz ve anlayasınız.\""},{"n":"39","t":"O'nu yine yakalamaya çalıştılarsa da, ellerinden sıyrılıp kurtuldu."},{"n":"40","t":"Tekrar Şeria nehrinin ötesine, Yahya'nın başlangıçta vaftiz ettiği yere gitti ve orada kaldı."},{"n":"41","t":"Birçokları, \"Yahya hiç mucize yapmadı, ama bu adam için söylediklerinin hepsi doğru çıktı\" diyerek İsa'ya geldiler."},{"n":"42","t":"Ve orada birçokları O'na iman etti."}]},{"ch":11,"verses":[{"n":"1","h":"Lazar'ın ölümü","t":"Meryem ile kızkardeşi Marta'nın köyü olan Beytanya'dan Lazar adında bir adam hastalanmıştı."},{"n":"2","t":"Meryem, Rab'be hoş kokulu yağ sürüp saçlarıyla O'nun ayaklarını silen kadındı. Hasta Lazar ise Meryem'in kardeşiydi."},{"n":"3","t":"İki kızkardeş İsa'ya, \"Rab, sevdiğin kişi hasta\" diye haber gönderdiler."},{"n":"4","t":"İsa bunu işitince, \"Bu hastalık ölümle sonuçlanmayacak; Tanrı'nın yüceliğine, Tanrı Oğlunun yüceltilmesine hizmet edecek\" dedi."},{"n":"5","t":"İsa Marta'yı, kızkardeşini ve Lazar'ı severdi."},{"n":"6-7","t":"Bu nedenle, Lazar'ın hasta olduğunu duyunca bulunduğu yerde iki gün daha kaldıktan sonra öğrencilere, \"Yahudiye'ye dönelim\" dedi."},{"n":"8","t":"Öğrenciler O'na, \"Rabbî\" dediler, \"Yahudiler demin seni taşlamaya kalkıştılar. Yine oraya mı gidiyorsun?\""},{"n":"9","t":"İsa şu karşılığı verdi: \"Günün on iki saati yok mu? Gündüz yürüyen sendelemez. Çünkü bu dünyanın ışığını görür."},{"n":"10","t":"Oysa gece yürüyen sendeler. Çünkü kendisinde ışık yoktur.\""},{"n":"11","t":"Bu sözleri söyledikten sonra, \"Dostumuz Lazar uyumuştur\" diye ekledi, \"ama onu uyandırmaya gidiyorum.\""},{"n":"12","t":"Öğrenciler, \"Rab\" dediler, \"uyumuşsa iyileşecektir.\""},{"n":"13","t":"İsa Lazar'ın ölümünden söz ediyordu, ama onlar olağan uykudan söz ettiğini sanmışlardı."},{"n":"14","t":"Bunun üzerine İsa açıkça, \"Lazar öldü\" dedi."},{"n":"15","t":"\"İman etmeniz için, orada bulunmadığıma sizin yararınıza seviniyorum. Şimdi onun yanına gidelim.\""},{"n":"16","t":"'İkiz' diye anılan Tomas diğer öğrencilere, \"Biz de gidelim, O'nunla birlikte ölelim!\" dedi."},{"n":"17","h":"Marta ile Meryem'in yası","t":"İsa Beytanya'ya yaklaşınca Lazar'ın dört gündür mezarda olduğunu öğrendi."},{"n":"18","t":"Beytanya, Kudüs'e on beş ok atımı kadar uzaklıktaydı."},{"n":"19","t":"Yahudilerin birçoğu Marta ile Meryem'i kardeşlerinin ölümünden dolayı teselli etmek için yanlarına gelmişlerdi."},{"n":"20","t":"Marta İsa'nın geldiğini duyunca O'nu karşılamaya çıktı, Meryem ise evde kaldı."},{"n":"21","t":"Marta İsa'ya, \"Rab\" dedi, \"burada olsaydın, kardeşim ölmezdi."},{"n":"22","t":"Şimdi bile, Tanrı'dan ne dilersen Tanrı'nın onu sana vereceğini biliyorum.\""},{"n":"23","t":"İsa, \"Kardeşin dirilecektir\" dedi."},{"n":"24","t":"Marta, \"Son gün, diriliş günü onun dirileceğini biliyorum\" dedi."},{"n":"25","t":"İsa ona, \"Diriliş ve yaşam ben'im\" dedi. \"Bana iman eden kişi ölse de yaşayacaktır."},{"n":"26","t":"Yaşayan ve bana iman eden asla ölmeyecek. Buna iman ediyor musun?\""},{"n":"27","t":"Marta, \"Evet, Rab\" dedi. \"Senin, dünyaya gelecek olanTanrı'nın Oğlu Mesih olduğuna iman ettim.\""},{"n":"28","t":"Bunu söyledikten sonra gidip kızkardeşi Meryem'i gizlice çağırdı. \"Öğretmen burada, seni çağırıyor\" dedi."},{"n":"29","t":"Meryem bunu işitince hemen kalkıp İsa'nın yanına gitti."},{"n":"30","t":"İsa henüz köye varmamıştı, hâlâ Marta'nın kendisini karşıladığı yerdeydi."},{"n":"31","t":"Meryem'le birlikte evde bulunan ve kendisini teselli eden Yahudiler, onun hızla kalkıp dışarı çıktığını gördüler. Ağlamak için mezara gittiğini sanarak onu izlediler."},{"n":"32","t":"Meryem İsa'nın bulunduğu yere vardı. O'nu görünce ayaklarına kapanarak, \"Rab\" dedi, \"burada olsaydın, kardeşim ölmezdi.\""},{"n":"33","t":"Meryem'in ve onunla gelen Yahudilerin ağladığını gören İsa'nın ruhunu hüzün kapladı, yüreği sızladı."},{"n":"34","t":"\"Onu nereye koydunuz?\" diye sordu.\nO'na, \"Rab, gel gör\" dediler."},{"n":"35","t":"İsa ağladı."},{"n":"36","t":"Yahudiler, \"Bakın, onu ne kadar seviyormuş!\" dediler."},{"n":"37","t":"Ama içlerinden bazıları, \"Körün gözlerini açan bu kişi, Lazar'ın ölümünü de önleyemez miydi?\" dediler."},{"n":"38","h":"İsa, Lazar'ı diriltiyor","t":"İsa yine derinden hüzünlenerek mezara vardı. Mezar bir mağaraydı, girişinde de bir taş duruyordu."},{"n":"39","t":"İsa, \"Taşı kaldırın!\" dedi.\nÖlenin kızkardeşi Marta, \"Rab, o artık kokmuştur, öleli dört gün oldu\" dedi."},{"n":"40","t":"İsa ona, \"Ben sana, 'iman edersen Tanrı'nın yüceliğini göreceksin' demedim mi?\" dedi."},{"n":"41","t":"Bunun üzerine taşı kaldırdılar. İsa gözlerini gökyüzüne dikerek şöyle dedi: \"Baba, beni işittiğin için sana şükrediyorum."},{"n":"42","t":"Beni her zaman işittiğini biliyordum. Ama bunu, çevrede duran halk için, beni senin gönderdiğine iman etsinler diye söyledim.\""},{"n":"43","t":"Bunları söyledikten sonra yüksek sesle, \"Lazar, dışarı çık!\" diye bağırdı."},{"n":"44","t":"Ölü, elleri ayakları sargılarla bağlı, yüzü bezle sarılmış olarak dışarı çıktı. İsa oradakilere, \"Onu çözün ve bırakın gitsin\" dedi."},{"n":"45","t":"O zaman, Meryem'e gelen ve İsa'nın yaptıklarını gören Yahudilerin birçoğu İsa'ya iman etti."},{"n":"46","t":"Ama içlerinden bazıları Ferisilere giderek İsa'nın yaptıklarını onlara bildirdiler."},{"n":"47","h":"İsa'yı öldürme tasarısı","t":"Bunun üzerine başkâhinler ve Ferisiler, Yüksek Kurul'u toplayıp dediler ki, \"Ne yapacağız? Bu adam birçok mucize yapıyor."},{"n":"48","t":"Böyle devam etmesine izin verirsek, herkes O'na iman edecek. Romalılar da gelip kutsal yerimizi ve ulusumuzu ortadan kaldıracaklar.\""},{"n":"49","t":"İçlerinden biri, o yıl başkâhin olan Kayafa, \"Hiçbir şey bilmiyorsunuz\" dedi."},{"n":"50","t":"\"Bütün ulus yok olacağına, halk uğruna bir tek adamın ölmesi sizin için daha uygun. Bunu anlamıyor musunuz?\""},{"n":"51-52","t":"Bunu kendiliğinden söylemiyordu. O yılın başkâhini olarak İsa'nın, ulusun uğruna, ve yalnız ulusun uğruna değil, Tanrı'nındağılmış çocuklarını toplayıp birleştirmek için de öleceğine ilişkin peygamberlikte bulunuyordu."},{"n":"53","t":"Böylece o günden itibaren İsa'yı öldürmek için düzen kurmaya başladılar."},{"n":"54","t":"Bu yüzden İsa artık Yahudiler arasında açıkça dolaşmaz oldu. Oradan ayrılarak çöle yakın bir yere, Efraim denilen kente gitti. Öğrencileriyle birlikte orada kaldı."},{"n":"55","t":"Yahudilerin Fısıh bayramı yakındı. Taşradakilerin birçoğu bayramdan önce arınmak için Kudüs'e gitti."},{"n":"56","t":"Orada İsa'yı arayıp durdular. Tapınaktayken birbirlerine, \"Ne dersiniz, bayrama hiç gelmeyecek mi?\" diye soruyorlardı."},{"n":"57","t":"Başkâhinlerle Ferisiler O'nu yakalayabilmek için, yerini bilenlerin haber vermesini buyurmuşlardı."}]},{"ch":12,"verses":[{"n":"1","h":"İsa Beytanya'da","t":"İsa, Fısıh bayramından altı gün önce, ölümden dirilttiği Lazar'ın bulunduğu Beytanya'ya geldi."},{"n":"2","t":"Orada kendisi için bir ziyafet düzenlediler. Marta hizmet ediyordu. İsa'yla birlikte sofrada oturanlardan biri de Lazar'dı."},{"n":"3","t":"Meryem, çok değerli saf hintsümbülü yağından yarım litre kadar getirerek İsa'nın ayaklarına sürdü ve saçlarıyla ayaklarını sildi. Ev yağın güzel kokusuyla doldu."},{"n":"4-5","t":"Ama öğrencilerinden biri, İsa'yı sonradan ele verecek olan Yahuda İskariyot, \"Bu yağ neden üç yüz dinara satılıp parası yoksullara verilmedi?\" dedi."},{"n":"6","t":"Bunu, yoksullarla ilgilendiği için değil, hırsız olduğu için söylüyordu. Ortak para kutusu ondaydı ve kutuya konulandan aşırıyordu."},{"n":"7","t":"İsa, \"Kadını rahat bırak\" dedi. \"Bunu benim gömüleceğim gün için saklasın."},{"n":"8","t":"Yoksullar her zaman aranızdadır, ama ben her zaman aranızda olmayacağım.\""},{"n":"9","t":"Yahudilerden büyük bir kalabalık İsa'nın Beytanya'da bulunduğunu öğrendi ve yalnız İsa için değil, O'nun ölümden dirilttiği Lazar'ı da görmek için oraya geldi."},{"n":"10","t":"Başkâhinler ise Lazar'ı da öldürmeyi tasarladılar."},{"n":"11","t":"Çünkü onun yüzünden birçok Yahudi gidip İsa'ya iman ediyordu."},{"n":"12","h":"İsa'nın Kudüs'e girişi","t":"Ertesi gün, bayramı kutlamaya gelen büyük kalabalık İsa'nın Kudüs'e gelmekte olduğunu duydu."},{"n":"13","t":"Hurma dalları alarak O'nu karşılamaya çıktılar. \"Hozana! Rab'bin adıyla gelene, İsrail'in Kralına övgüler olsun!\" diye bağırıyorlardı."},{"n":"14-15","t":"İsa bir sıpa bulup üzerine bindi. Yazılmış olduğu gibi,\n\"Korkma, ey Siyon kızı!\nBak, Kralın bir sıpaya binmiş geliyor.\""},{"n":"16","t":"Öğrencileri ilkin bunları anlamadılar. Ama İsa yüceltildikten sonra bu sözlerin O'nun hakkında yazıldığını, halkın bunlarıO'nun için yapmış olduğunu hatırladılar."},{"n":"17","t":"Lazar'ı mezardan çağırıp ölümden dirilttiği sırada İsa'yla birlikte bulunan kalabalık buna tanıklık etti."},{"n":"18","t":"İsa'nın bu mucizeyi yaptığını duyan halk O'nu karşılamaya çıktı."},{"n":"19","t":"Ferisiler ise birbirlerine, \"Görüyorsunuz, elinizden hiçbir şey gelmiyor. Tüm dünya O'nun peşine takıldı\" dediler."},{"n":"20","h":"İsa öleceğini önceden bildiriyor","t":"Bayramda tapınmak üzere Kudüs'e gidenler arasında bazı Grekler vardı."},{"n":"21","t":"Bunlar, Celile'nin Beytsayda kentinden olan Filipus'a gelerek, \"Efendimiz, İsa'yı görmek istiyoruz\" diye rica ettiler."},{"n":"22","t":"Filipus gitti, bunu Andreya'ya bildirdi. Andreya ve Filipus da gidip İsa'ya haber verdiler."},{"n":"23","t":"İsa, \"İnsanoğlu'nun yüceltileceği saat geldi\" diye karşılık verdi."},{"n":"24","t":"\"Size doğrusunu söyleyeyim, buğday tanesi toprağa düşüp ölmedikçe yalnız kalır. Ama ölürse çok ürün verir."},{"n":"25","t":"Canını seven, onu yitirir. Ama bu dünyada canını gözden çıkaran, onu sonsuz yaşam için koruyacaktır."},{"n":"26","t":"Bana hizmet etmek isteyen, ardımdan gelsin. Ben neredeysem bana hizmet eden de orada olacak. Baba, bana hizmet edeni onurlandıracaktır."},{"n":"27","t":"Şimdi yüreğim sıkılıyor, ne diyeyim? 'Baba, beni bu saatten kurtar' mı diyeyim? Ama ben bu amaç için bu saate geldim."},{"n":"28","t":"Baba, adını yücelt!\"\nBunun üzerine gökten bir ses geldi: \"Adımı yücelttim ve yine yücelteceğim.\""},{"n":"29","t":"Orada duran ve bunu işiten kalabalık, \"Gök gürledi\" dedi.\nBaşkaları, \"Bir melek O'nunla konuştu\" dedi."},{"n":"30","t":"İsa, \"Bu ses benim için değil, sizin içindi\" dedi."},{"n":"31","t":"\"Bu dünya şimdi yargılanıyor. Bu dünyanın egemeni şimdi dışarı atılacak."},{"n":"32","t":"Ben yerden yukarı kaldırıldığım zaman bütün insanları kendime çekeceğim.\""},{"n":"33","t":"İsa bunu, nasıl öleceğini belirtmek için söylüyordu."},{"n":"34","t":"Kalabalık O'na şöyle karşılık verdi: \"Kutsal Yasa'dan öğrendiğimize göre Mesih sonsuza dek kalacaktır. Nasıl oluyor da sen, 'İnsanoğlu yukarı kaldırılmalıdır' diyorsun? Kimdir bu İnsanoğlu?\""},{"n":"35","t":"İsa, \"Işık, kısa bir süre daha aranızdadır\" dedi. \"Karanlıkta kalmamak için ışığınız varken yürüyün. Karanlıkta yürüyen nereye gittiğini bilmez."},{"n":"36","t":"Sizde ışık varken ışığa iman edin ki, ışığın oğulları olasınız.\"\nİsa bu sözleri söyledikten sonra uzaklaşıp onlardan gizlendi."},{"n":"37","h":"Halkın inadı","t":"Gözleri önünde bunca mucize yaptığı halde O'na iman etmediler."},{"n":"38","t":"Bütün bunlar Yeşaya peygamberin söylediği şu söz yerine gelsin diye oldu:\n\"Rab, verdiğimiz habere kim inandı?\nRab'bin gücü kime gösterildi?\""},{"n":"39-40","t":"İşte bu yüzden iman edemiyorlardı. Nitekim Yeşaya başka bir yerde de şöyle demişti:\n\"Tanrı onların gözlerini kör etti\nve yüreklerini nasırlaştırdı.\nÖyle ki, gözleri görmesin,\nyürekleri anlamasın\nve bana dönmesinler.\nDönselerdi, onları iyileştirirdim.\""},{"n":"41","t":"Bunları söyleyen Yeşaya, İsa'nın yüceliğini görmüş ve O'nun hakkında konuşmuştu."},{"n":"42","t":"Bununla beraber, önderlerin bile birçoğu İsa'ya iman etti. Ama Ferisiler yüzünden, havra dışı edilmemek için iman ettiklerini açıkça söylemediler."},{"n":"43","t":"Çünkü insandan gelen övgüyü, Tanrı'dan gelen övgüden daha çok seviyorlardı."},{"n":"44","t":"İsa yüksek sesle, \"Bana iman eden bana değil, beni gönderene iman etmiş olur\" dedi."},{"n":"45","t":"\"Beni gören, beni göndereni de görür."},{"n":"46","t":"Bana iman eden hiç kimse karanlıkta kalmasın diye, dünyaya ışık olarak geldim."},{"n":"47","t":"Sözlerimi işitip de onlara uymayanı ben yargılamam. Çünkü ben dünyayı yargılamaya değil, dünyayı kurtarmaya geldim."},{"n":"48","t":"Beni reddeden ve sözlerimi kabul etmeyen kişiyi yargılayacak biri var. O kişiyi son günde yargılayacak olan, söylediğim sözdür."},{"n":"49","t":"Çünkü ben kendiliğimden konuşmadım. Beni gönderen Baba'nın kendisi ne söylemem ve ne konuşmam gerektiğini bana buyurdu."},{"n":"50","t":"O'nun buyruğunun sonsuz yaşam olduğunu biliyorum. Bunun için ne söylüyorsam, Baba'nın bana söylediği gibi söylüyorum.\""}]},{"ch":13,"verses":[{"n":"1","h":"Alçakgönüllülük örneği","t":"Fısıh bayramından önceydi. İsa, bu dünyadan ayrılıp Baba'ya gideceği saatin geldiğini biliyordu. Dünyada kendisine ait olanları sevmiş olarak sonuna kadar sevdi."},{"n":"2","t":"Akşam yemeği sırasında İblis, Simun oğlu Yahuda İskariyot'un yüreğine İsa'yı ele verme isteğini koymuştu bile."},{"n":"3","t":"İsa, Baba'nın her şeyi kendisine emanet ettiğini, kendisinin Tanrı'dan çıkıp geldiğini ve Tanrı'ya döneceğini biliyordu."},{"n":"4","t":"Yemekten kalktı, üstlüğünü bir yana koydu, bir havlu alıp beline doladı."},{"n":"5","t":"Sonra bir leğene su doldurup öğrencilerin ayaklarını yıkamaya ve beline doladığı havluyla kurulamaya başladı."},{"n":"6","t":"İsa, Simun Petrus'a geldi. Simun, \"Rab, ayaklarımı sen mi yıkayacaksın?\" dedi."},{"n":"7","t":"İsa ona şu cevabı verdi: \"Ne yaptığımı şimdi anlayamazsın, ama sonra anlayacaksın.\""},{"n":"8","t":"Petrus, \"Benim ayaklarımı asla yıkamayacaksın!\" dedi.\nİsa, \"Seni yıkamazsam yanımda yerin olmaz\" cevabını verdi."},{"n":"9","t":"Simun Petrus, \"Rab, o halde yalnız ayaklarımı değil, ellerimi ve başımı da yıka!\" dedi."},{"n":"10","t":"İsa ona dedi ki, \"Yıkanmış olan tamamen temizdir; ayaklarının yıkanmasından başka şeye ihtiyacı yoktur. Sizler temizsiniz, ama hepiniz değil.\""},{"n":"11","t":"İsa, kendisini kimin ele vereceğini biliyordu. Bu nedenle, \"Hepiniz temiz değilsiniz\" demişti."},{"n":"12","t":"Onların ayaklarını yıkadıktan sonra giyinip yine sofraya oturdu. Onlara, \"Size ne yaptığımı anlıyor musunuz?\" dedi."},{"n":"13","t":"\"Sizbeni Öğretmen ve Rab diye çağırıyorsunuz. Doğru söylüyorsunuz, öyleyim."},{"n":"14","t":"Ben Rab ve Öğretmen olduğum halde ayaklarınızı yıkadım; öyleyse, sizler de birbirinizin ayaklarını yıkamalısınız."},{"n":"15","t":"Size yaptığımın aynısını yapmanız için bir örnek verdim."},{"n":"16","t":"Size doğrusunu söyleyeyim, köle efendisinden üstün değildir. Elçi de kendisini gönderenden üstün değildir."},{"n":"17","t":"Bildiğiniz bu şeyleri yaparsanız, size ne mutlu!"},{"n":"18","h":"İsa'ya ihanet","t":"\"Hepiniz için söylemiyorum, ben seçtiklerimi bilirim. Ama, 'Ekmeğimi yiyen bana el kaldırdı' diyen Kutsal Yazı'nın yerine gelmesi için böyle olacak."},{"n":"19","t":"Size şimdiden, bunlar olmadan önce söylüyorum ki, bunlar olunca, benim O olduğuma inanasınız."},{"n":"20","t":"Size doğrusunu söyleyeyim, benim gönderdiğim herhangi bir kimseyi kabul eden beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur.\""},{"n":"21","t":"İsa bunları söyledikten sonra ruhunda derin bir sıkıntı duydu. Açıkça konuşarak, \"Size doğrusunu söyleyeyim, sizden biri beni ele verecek\" dedi."},{"n":"22","t":"Öğrenciler, kimden söz ettiğini merak ederek birbirlerine baktılar."},{"n":"23","t":"Öğrencilerinden biri İsa'nın göğsüne yaslanmıştı. İsa onu severdi."},{"n":"24","t":"Simun Petrus bu öğrenciye, kimden söz ettiğini İsa'ya sorması için işaret etti."},{"n":"25","t":"O da İsa'nın göğsüne yaslanmış durumda, \"Rab, o kimdir?\" diye sordu."},{"n":"26","t":"İsa, \"Lokmayı sahana batırıp kime verirsem odur\" diye cevap verdi. Sonra lokmayı batırıp Simun İskariyot'un oğlu Yahuda'ya verdi."},{"n":"27","t":"Yahuda lokmayı alır almaz Şeytan onun içine girdi. İsa da ona, \"Yapacağını tez yap!\" dedi."},{"n":"28","t":"Sofrada oturanların hiçbiri, İsa'nın ona bu sözleri neden söylediğini anlamadı."},{"n":"29","t":"Para kutusu Yahuda'da olduğundan, bazıları İsa'nın ona, \"Bayram için bize gerekli şeyleri al\" ya da, \"Yoksullara bir şey ver\" demek istediğini sandılar."},{"n":"30","t":"Yahuda lokmayı aldıktan hemen sonra dışarı çıktı. Gece olmuştu."},{"n":"31","h":"Birbirinizi sevin","t":"Yahuda dışarı çıkınca İsa, \"İnsanoğlu şimdi yüceltilmiştir\" dedi. \"Tanrı da O'nda yüceltilmiş bulunuyor."},{"n":"32","t":"Tanrı O'nda yüceltildiğine göre, Tanrı da O'nu kendinde yüceltecek, ve hemen yüceltecektir."},{"n":"33","t":"Çocuklar! Kısa bir süre daha sizinleyim. Beni arayacaksınız, ama Yahudilere söylediğim gibi, şimdi size de söylüyorum, benim gideceğim yere siz gelemezsiniz."},{"n":"34","t":"Size yeni bir buyruk veriyorum: birbirinizi sevin. Sizi sevdiğim gibi siz de birbirinizi sevin."},{"n":"35","t":"Birbirinize sevginiz olursa, herkes bununla benim öğrencilerim olduğunuzu anlayacaktır.\""},{"n":"36","h":"Petrus, İsa'yı inkâr edecek","t":"Simun Petrus O'na, \"Rab, nereye gidiyorsun?\" diye sordu.\nİsa, \"Gideceğim yere şimdi ardımdan gelemezsin, ama sonra geleceksin\" diye cevap verdi."},{"n":"37","t":"Petrus O'na, \"Rab, neden şimdi senin ardından gelemeyeyim? Senin için canımı veririm!\" dedi."},{"n":"38","t":"İsa şöyle cevap verdi: \"Benim için canını mı vereceksin? Sana doğrusunu söyleyeyim, horoz ötmeden sen beni üç kez inkâr edeceksin.\""}]},{"ch":14,"verses":[{"n":"1","h":"İsa - Tanrı'ya giden yol","t":"\"Yüreğiniz sıkılmasın. Tanrı'ya iman edin, bana da iman edin."},{"n":"2","t":"Babamın evinde yaşanacak çok yerler vardır. Öyle olmasa size söylerdim. Çünkü size yer hazırlamaya gidiyorum."},{"n":"3","t":"Gider ve size yer hazırlarsam, siz de benim bulunduğum yerde olasınız diye yine gelip sizi yanıma alacağım."},{"n":"4","t":"Benim gideceğim yerin yolunu biliyorsunuz.\""},{"n":"5","t":"Tomas, \"Rab, senin nereye gideceğini bilmiyoruz, yolu nasıl bilebiliriz?\" dedi."},{"n":"6","t":"İsa ona, \"Yol, gerçek ve yaşam ben'im\" dedi. \"Benim aracılığım olmadan Baba'ya kimse gelemez."},{"n":"7","t":"Beni tanısaydınız, Babamı da tanırdınız. Artık O'nu tanıyorsunuz, O'nu gördünüz.\""},{"n":"8","t":"Filipus, \"Rab, bize Baba'yı göster, bu bize yeter\" dedi."},{"n":"9","t":"İsa, \"Filipus\" dedi, \"bunca zamandır sizinle birlikteyim. Beni daha tanımadın mı? Beni görmüş olan, Baba'yı görmüştür. Sen nasıl, 'Bize Baba'yı göster' diyorsun?"},{"n":"10","t":"Benim Baba'da, Baba'nın da bende olduğuna inanmıyor musun? Size söylediğim sözleri kendiliğimden söylemiyorum, ama bende yaşayan Baba kendi işlerini yapıyor."},{"n":"11","t":"Bana iman edin; ben Baba'dayım, Baba da bendedir. Hiç değilse bu işlerden dolayı iman edin."},{"n":"12","t":"Size doğrusunu söyleyeyim, benim yaptığım işleri, bana iman eden de yapacak; hatta daha büyüklerini yapacaktır. Çünkü ben Baba'ya gidiyorum."},{"n":"13","t":"Baba Oğul'da yüceltilsin diye, benim adımla dilediğiniz her şeyi yapacağım."},{"n":"14","t":"Benim adımla benden ne dilerseniz yapacağım."},{"n":"15","h":"Kutsal Ruh vaadi","t":"\"Beni seviyorsanız, buyruklarımı yerine getirirsiniz."},{"n":"16-17","t":"Ben de Baba'dan dileyeceğim ve O, sonsuza dek sizinle birlikte olsun diye size başka bir Yardımcı, Gerçeğin Ruhunu verecek. Dünya O'nu kabul edemez. Çünkü O'nu ne görür, ne de tanır. Siz O'nu tanıyorsunuz. Çünkü O aranızda yaşıyor ve içinizde olacaktır."},{"n":"18","t":"Sizi öksüz bırakmayacağım, size geri döneceğim."},{"n":"19","t":"Az sonra dünya artık beni görmeyecek, ama siz beni göreceksiniz. Ben yaşadığım için siz de yaşayacaksınız."},{"n":"20","t":"O gün anlayacaksınız ki, ben Babamdayım, siz bendesiniz, ben de sizdeyim."},{"n":"21","t":"Kim buyruklarımı bilir ve yerine getirirse, işte beni seven odur. Beni seveni Babam da sevecektir. Ben de onu seveceğim ve kendimi ona göstereceğim.\""},{"n":"22","t":"Yahuda - İskariyot değil - O'na, \"Rab, nasıl olur da kendini dünyaya göstermeyip bize göstereceksin?\" diye sordu."},{"n":"23","t":"İsa ona şu karşılığı verdi: \"Beni seven sözüme uyar, Babam da onu sever. Biz de ona gelir, onunla birlikte yaşarız."},{"n":"24","t":"Beni sevmeyen, sözlerime uymaz. İşittiğiniz söz benim değil, benigönderen Baba'nındır."},{"n":"25","t":"\"Ben daha aranızdayken size bunları söyledim."},{"n":"26","t":"Ama Baba'nın benim adımla göndereceği Yardımcı, Kutsal Ruh, size her şeyi öğretecek, bütün söylediklerimi size hatırlatacak."},{"n":"27","t":"Size esenlik bırakıyorum, size kendi esenliğimi veriyorum. Ben size dünyanın verdiği gibi vermiyorum. Yüreğiniz sıkılmasın ve korkmasın."},{"n":"28","t":"Size, 'Gidiyorum, ama yanınıza döneceğim' dediğimi işittiniz. Beni sevseydiniz, Baba'ya gideceğim için sevinirdiniz. Çünkü Baba benden üstündür."},{"n":"29","t":"Bunları size şimdiden, her şey olup bitmeden önce söyledim. Öyle ki, bunlar olunca inanasınız."},{"n":"30","t":"Artık sizinle uzun uzun konuşmayacağım. Çünkü bu dünyanın egemeni geliyor. Onun benim üzerimde hiçbir yetkisi yoktur."},{"n":"31","t":"Ama dünyanın, Baba'yı sevdiğimi ve Baba'nın bana buyurduğu her şeyi yerine getirdiğimi anlamasını istiyorum. Haydi kalkın, buradan gidelim."}]},{"ch":15,"verses":[{"n":"1","h":"Asma ile çubuklar","t":"\"Ben gerçek asmayım ve Babam bağcıdır."},{"n":"2","t":"Bende olup meyve vermeyen her çubuğu kesip atar, her meyve vereni de daha çok versin diye budayıp temizler."},{"n":"3","t":"Size söylediğim sözle siz şimdiden temizsiniz."},{"n":"4","t":"Bende kalın, ben de sizde kalayım. Çubuk asmada kalmazsa kendiliğinden meyve veremez. Bunun gibi, siz de bende kalmazsanız meyve veremezsiniz."},{"n":"5","t":"Ben asmayım, siz çubuklarsınız. Bende kalan ve benim kendisinde kaldığım kişi çok meyve verir. Bensiz hiçbir şey yapamazsınız."},{"n":"6","t":"Bir kimse bende kalmazsa, çubuk gibi dışarı atılır ve kurur. Böylelerini toplar, ateşe atıp yakarlar."},{"n":"7","t":"Siz bende kalırsanız ve sözlerim sizde kalırsa, ne isterseniz dileyin, size verilecektir."},{"n":"8","t":"Babam çok meyve vermenizle yüceltilir. Böylelikle öğrencilerim olursunuz."},{"n":"9","t":"\"Baba'nın beni sevdiği gibi, ben de sizi sevdim. Benim sevgimde kalın."},{"n":"10","t":"Eğer buyruklarımı yerine getirirseniz sevgimde kalırsınız, tıpkı benim de Babamın buyruklarını yerine getirdiğim ve sevgisinde kaldığım gibi…"},{"n":"11","t":"Bunları size, sevincim sizde olsun ve sevinciniz tamamlansın diye söyledim."},{"n":"12","t":"Benim buyruğum şudur: sizi sevdiğim gibi birbirinizi sevin."},{"n":"13","t":"Hiç kimsede, insanın, dostları uğruna canını vermesinden daha büyük bir sevgi yoktur."},{"n":"14","t":"Size buyurduklarımı yaparsanız, benim dostlarım olursunuz."},{"n":"15","t":"Artık size kul demem. Çünkü kul efendisinin ne yaptığını bilmez. Size dost dedim. Çünkü Babamdan bütün işittiklerimi size bildirdim."},{"n":"16","t":"Siz beni seçmediniz, ben sizi seçtim. Gidip meyve veresiniz, meyveniz de kalıcı olsun diye sizi ben atadım. Öyle ki, benim adımla Baba'dan ne dilerseniz size versin."},{"n":"17","t":"Size şu buyruğu veriyorum: birbirinizi sevin!"},{"n":"18","h":"Dünyanın nefreti","t":"\"Dünya sizden nefret ederse, sizden önce benden nefret etmiş olduğunu bilin."},{"n":"19","t":"Dünyadan olsaydınız, dünya kendisine ait olanı severdi. Ne var ki, dünyanın değilsiniz; ben sizi dünyadan seçtim. Bunun için dünya sizden nefret ediyor."},{"n":"20","t":"Size söylediğim sözü hatırlayın: 'Köle, efendisinden üstün değildir.' Banazulmettilerse, size de zulmedecekler. Benim sözüme uydularsa, sizinkine de uyacaklar."},{"n":"21","t":"Bütün bunları size benim adımdan ötürü yapacaklar. Çünkü beni göndereni tanımıyorlar."},{"n":"22","t":"Eğer gelmemiş ve onlara söylememiş olsaydım, günahları olmazdı; ama şimdi günahları için özürleri yoktur."},{"n":"23","t":"Benden nefret eden, Babamdan da nefret eder."},{"n":"24","t":"Başka hiç kimsenin yapmadığı işleri onların arasında yapmamış olsaydım, günahları olmazdı. Şimdiyse yaptıklarımı gördükleri halde hem benden hem de Babamdan nefret ettiler."},{"n":"25","t":"Bu, yasalarında yazılı, 'Hiçbir neden yokken benden nefret ettiler' sözü yerine gelsin diye oldu."},{"n":"26","t":"\"Baba'dan size göndereceğim Yardımcı, yani Baba'dan çıkan Gerçeğin Ruhu geldiği zaman, O bana tanıklık edecek."},{"n":"27","t":"Siz de tanıklık edeceksiniz. Çünkü başlangıçtan beri benimle birliktesiniz."}]},{"ch":16,"verses":[{"n":"1","t":"\"Bunları size, sendeleyip düşmeyesiniz diye söyledim."},{"n":"2","t":"Sizi havra dışı edecekler. Evet, öyle bir saat geliyor ki, sizi öldüren herkes Tanrı'ya hizmet ettiğini sanacak."},{"n":"3","t":"Bunları, ne Baba'yı ne de beni tanımadıkları için yapacaklar."},{"n":"4","t":"Bunları size şimdiden bildiriyorum. Öyle ki, saati gelince bunları size söylediğimi hatırlayasınız. Başlangıçta bunları size söylemedim. Çünkü sizinle birlikteydim."},{"n":"5","h":"Kutsal Ruh'un işleyişi","t":"\"Şimdiyse beni gönderenin yanına gidiyorum. Ne var ki, içinizden hiçbiri bana, 'Nereye gidiyorsun?' diye sormuyor."},{"n":"6","t":"Ama size bunları söylediğim için yüreğiniz kederle doldu."},{"n":"7","t":"Size gerçeği söylüyorum, benim gidişim sizin yararınızadır. Gitmezsem, Yardımcı size gelmez. Ama gidersem, O'nu size gönderirim."},{"n":"8","t":"O gelince dünyanın günah, doğruluk ve gelecek yargı konusundaki suçluluğunu dünyaya gösterecektir."},{"n":"9","t":"Günah konusunda - çünkü bana iman etmezler."},{"n":"10","t":"Doğruluk konusunda - çünkü Baba'ya gidiyorum, artık beni görmeyeceksiniz."},{"n":"11","t":"Yargı konusunda - çünkü bu dünyanın egemeni yargılanmış bulunuyor."},{"n":"12","t":"\"Size daha çok söyleyeceklerim var, ama şimdi bunlara dayanamazsınız."},{"n":"13","t":"Ne var ki O, yani Gerçeğin Ruhu gelince, sizi her gerçeğe yöneltecek. O kendiliğinden konuşmayacak, yalnız işittiklerini söyleyecek ve gelecekte olacakları size bildirecek."},{"n":"14","t":"O beni yüceltecek. Çünkü benim olandan alacak ve size bildirecek."},{"n":"15","t":"Baba'nın her nesi varsa benimdir. 'Benim olandan alacak ve size bildirecek' dememin nedeni budur."},{"n":"16","t":"\"Kısa süre sonra beni artık görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz.\""},{"n":"17","h":"Kederiniz sevince dönüşecek","t":"Öğrencilerinden bazıları birbirlerine şöyle dediler: \"'Kısa süre sonra beni görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz' ve 'Çünkü Baba'ya gidiyorum' diyor. Bize ne söylemek istiyor?\""},{"n":"18","t":"Bu yüzden, \"'Kısa süre' dediği nedir?Söylediklerini anlamıyoruz\" deyip durdular."},{"n":"19","t":"İsa kendisine soru sormak istediklerini anladı. Onlara dedi ki, \"'Kısa süre sonra beni görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz' dedim. Birbirinizle bu sözü mü tartışıyorsunuz?"},{"n":"20","t":"Size doğrusunu söyleyeyim, siz ağlayıp yas tutacaksınız, dünya ise sevinecektir. Kederleneceksiniz, ama kederiniz sevince dönüşecek."},{"n":"21","t":"Kadın doğum yapacağı zaman ağrı çeker. Çünkü saati gelmiştir. Ama doğurunca, dünyaya bir çocuk getirmenin sevinciyle çektiği acıyı unutur."},{"n":"22","t":"Bunun gibi, siz de şimdi kederleniyorsunuz, ama sizi yine göreceğim ve yüreğiniz sevinecek. Sevincinizi kimse sizden alamaz."},{"n":"23","t":"O gün bana hiçbir şey sormayacaksınız. Size doğrusunu söyleyeyim, benim adımla Baba'dan ne dilerseniz, onu size verecektir."},{"n":"24","t":"Şimdiye dek benim adımla bir şey dilemediniz. Dileyin, alacaksınız. Öyle ki, sevinciniz tam olsun."},{"n":"25","t":"\"Size bunları örneklerle anlattım. Öyle bir saat geliyor ki, artık örneklerle konuşmayacağım; Baba'yı size açıkça tanıtacağım."},{"n":"26","t":"O gün dileyeceğinizi benim adımla dileyeceksiniz. Sizin için Baba'dan istekte bulunacağımı söylemiyorum."},{"n":"27","t":"Çünkü beni sevdiğiniz ve Baba'dan çıkıp geldiğime iman ettiğiniz için Baba'nın kendisi sizi seviyor."},{"n":"28","t":"Ben Baba'dan çıkıp dünyaya geldim. Şimdi dünyayı bırakıp Baba'ya dönüyorum.\""},{"n":"29","t":"Öğrencileri, \"İşte, şimdi açıkça konuşuyorsun, hiç örnek kullanmıyorsun\" dediler."},{"n":"30","t":"\"Şimdi senin her şeyi bildiğini anlıyoruz. Kimsenin sana soru sormasına gerek yok. Tanrı'dan geldiğine bunun için iman ediyoruz.\""},{"n":"31","t":"İsa onlara, \"Şimdi iman ediyor musunuz?\" diye karşılık verdi."},{"n":"32","t":"\"İşte, hepinizin evlerinize gitmek üzere dağılacağınız ve beni yalnız bırakacağınız saat geliyor, geldi bile. Ama ben yalnız değilim, Baba benimle birliktedir."},{"n":"33","t":"Bunları size, bende esenliğiniz olsun diye söyledim. Dünyada sıkıntınız olacak. Ama cesur olun, ben dünyayı yendim!\""}]},{"ch":17,"verses":[{"n":"1","h":"İsa dua ediyor","t":"İsa bunları söyledikten sonra, gözlerini gökyüzüne dikip şöyle dedi: \"Baba, saat geldi. Oğlunu yücelt ki, Oğul da seni yüceltsin."},{"n":"2","t":"Çünkü sen O'na tüm insanlık üzerinde yetki verdin. Öyle ki, O'na verdiklerinin hepsine sonsuz yaşam versin."},{"n":"3","t":"Sonsuz yaşam, tek gerçek Tanrı olan seni ve gönderdiğin İsa Mesih'i tanımalarıdır."},{"n":"4","t":"Yapmam için bana verdiğin işi tamamlamakla seni yeryüzünde yücelttim."},{"n":"5","t":"Baba, dünya var olmadan önce ben senin yanındayken sahip olduğum yücelikle şimdi beni yanında yücelt."},{"n":"6","t":"\"Dünyadan bana verdiğin insanlara senin adını açıkladım. Onlar senindiler, bana verdin ve senin sözüne uydular."},{"n":"7","t":"Bana verdiğin her şeyin senden olduğunu şimdi biliyorlar."},{"n":"8","t":"Çünkü bana ilettiğin sözleri onlara ilettim, onlar da kabul ettiler. Senden çıkıp geldiğimi gerçekten anladılar, beni senin gönderdiğine iman ettiler."},{"n":"9","t":"Onlar için istekte bulunuyorum. Dünya için değil, bana verdiğin kimseler için istekte bulunuyorum. Çünkü onlar senindir."},{"n":"10","t":"Benim olan her şey senindir, seninkiler de benimdir. Benonlarda yüceltildim."},{"n":"11","t":"Ben artık dünyada değilim, ama onlar dünyadalar. Ben sana geliyorum. Kutsal Baba, onları bana verdiğin kendi adınla koru ki, bizim gibi bir olsunlar."},{"n":"12","t":"Kendileriyle birlikte olduğum sürece, bana verdiğin kendi adınla onları esirgeyip korudum. Kutsal Yazı yerine gelsin diye, mahva giden adamdan başka içlerinden hiçbiri mahvolmadı."},{"n":"13","t":"\"İşte şimdi sana geliyorum. Sevincimin onlarda tamamlanması için bunları ben dünyadayken söylüyorum."},{"n":"14","t":"Ben onlara senin sözünü ilettim, dünya ise onlardan nefret etti. Çünkü ben dünyadan olmadığım gibi, onlar da dünyadan değiller."},{"n":"15","t":"Onları dünyadan uzaklaştırmanı değil, kötü olandan korumanı istiyorum."},{"n":"16","t":"Ben dünyadan olmadığım gibi, onlar da dünyadan değiller."},{"n":"17","t":"Onları gerçekle kutsal kıl. Senin sözün gerçektir."},{"n":"18","t":"Sen beni dünyaya gönderdiğin gibi, ben de onları dünyaya gönderdim."},{"n":"19","t":"Onlar da gerçekle kutsal kılınsınlar diye kendimi onların uğruna adıyorum."},{"n":"20-21","t":"\"Yalnız onlar için değil, onların sözüyle bana iman edenler için de istekte bulunuyorum, hepsi bir olsunlar. Baba, senin bende olduğun ve benim sende olduğum gibi, onlar da bizde olsunlar. Dünya da beni senin gönderdiğine iman etsin."},{"n":"22","t":"Bana verdiğin yüceliği onlara verdim. Öyle ki, bizim bir olduğumuz gibi bir olsunlar."},{"n":"23","t":"Ben onlarda, sen bende olmak üzere tam bir birlik içinde bulunsunlar ki, dünya beni senin gönderdiğini, beni sevdiğin gibi onları da sevdiğini anlasın."},{"n":"24","t":"Baba, bana verdiklerinin de bulunduğum yerde benimle birlikte olmalarını ve benim yüceliğimi, bana verdiğin yüceliği görmelerini istiyorum. Çünkü dünyanın kuruluşundan önce sen beni sevdin."},{"n":"25","t":"Adil Baba, dünya seni tanımıyor, ama ben seni tanıyorum. Bunlar da beni senin gönderdiğini biliyorlar."},{"n":"26","t":"Bana beslediğin sevgi onlarda olsun, ben de onlarda olayım diye senin adını onlara bildirdim ve bildirmeye devam edeceğim.\""}]},{"ch":18,"verses":[{"n":"1","h":"İsa tutuklanıyor","t":"İsa bu sözleri söyledikten sonra öğrencileriyle birlikte dışarı çıkıp Kidron vadisinin ötesine geçti. Orada bir bahçe vardı. İsa'yla öğrencileri bu bahçeye girdiler."},{"n":"2","t":"O'nu ele veren Yahuda da burayı biliyordu. Çünkü İsa, öğrencileriyle orada sık sık buluşurdu."},{"n":"3","t":"Böylece Yahuda yanına bir bölük askerle başkâhinlerin ve Ferisilerin gönderdiği görevlileri alarak oraya geldi. Onların ellerinde fenerler, meşaleler ve silahlar vardı."},{"n":"4","t":"İsa, başına geleceklerin hepsini biliyordu. Öne çıkıp onlara, \"Kimi arıyorsunuz?\" diye sordu."},{"n":"5","t":"\"Nasıralı İsa'yı\" diye karşılık verdiler.\nİsa onlara, \"Ben'im\" dedi.\nO'nu ele veren Yahuda da onlarla birlikte duruyordu."},{"n":"6","t":"İsa, \"Ben'im\" deyince gerileyip yere düştüler."},{"n":"7","t":"Bunun üzerine İsa onlara yine, \"Kimi arıyorsunuz?\" diye sordu.\n\"Nasıralı İsa'yı\" dediler."},{"n":"8","t":"İsa, \"Size söyledim, ben'im\" dedi. \"Eğer beni arıyorsanız,bunları bırakın gitsinler.\""},{"n":"9","t":"Kendisinin daha önce söylediği, \"Senin bana verdiklerinden hiçbirini yitirmedim\" şeklindeki sözü yerine gelsin diye böyle konuştu."},{"n":"10","t":"Simun Petrus yanında taşıdığı kılıcı çekti, başkâhinin Malkus adındaki kölesine vurup sağ kulağını kopardı."},{"n":"11","t":"İsa Petrus'a, \"Kılıcını kınına koy! Baba'nın bana verdiği kâseden içmeyeyim mi?\" dedi."},{"n":"12","t":"Bunun üzerine komutanla buyruğundaki asker bölüğü ve Yahudi görevliler İsa'yı tutup bağladılar."},{"n":"13","t":"O'nu önce, o yıl başkâhin olan Kayafa'nın kayınbabası Hanna'ya götürdüler."},{"n":"14","t":"Halkın uğruna bir tek adamın ölmesinin daha uygun olacağını Yahudilere telkin eden Kayafa idi."},{"n":"15","h":"Petrus'un ilk inkârı","t":"Simun Petrus'la başka bir öğrenci İsa'nın ardından gidiyorlardı. O öğrenci başkâhinin tanıdığı olduğu için İsa'yla birlikte başkâhinin avlusuna girdi."},{"n":"16","t":"Petrus ise dışarıda, kapının yanında duruyordu. Başkâhinin tanıdığı öğrenci dışarı çıkıp kapıcı kızla konuştu ve Petrus'u içeri getirdi."},{"n":"17","t":"Kapıcı kız Petrus'a, \"Sen de bu adamın öğrencilerinden değil misin?\" diye sordu.\nPetrus, \"Hayır, değilim\" dedi."},{"n":"18","t":"Hava soğuk olduğu için köleler ve nöbetçiler yaktıkları kömür ateşinin çevresinde durmuş ısınıyorlardı. Petrus da onlarla birlikte durmuş ısınıyordu."},{"n":"19","h":"Başkâhinin soruşturması","t":"Başkâhin İsa'ya, öğrencileri ve öğretisiyle ilgili sorular sordu."},{"n":"20","t":"İsa ona şöyle cevap verdi: \"Ben söylediklerimi dünyaya açıkça söyledim. Her zaman bütün Yahudilerin toplandıkları havralarda ve tapınakta ders verdim. Gizli hiçbir şey söylemedim."},{"n":"21","t":"Beni neden sorguya çekiyorsun? Konuştuklarımı işitenlerden sor. Onlar ne söylediğimi biliyorlar.\""},{"n":"22","t":"İsa bunları söyleyince, yanında duran görevlilerden biri, \"Başkâhine nasıl böyle karşılık verirsin?\" diyerek O'na bir tokat attı."},{"n":"23","t":"İsa ona, \"Eğer yanlış bir şey söyledimse, yanlışımı göster!\" diye cevap verdi. \"Ama söylediklerim doğruysa, niçin bana vuruyorsun?\""},{"n":"24","t":"Bunun üzerine Hanna O'nu bağlı olarak başkâhin Kayafa'ya gönderdi."},{"n":"25","h":"Petrus'un ikinci ve üçüncü inkârı","t":"Simun Petrus hâlâ ateşin yanında durmuş ısınıyordu. O'na, \"Sen de O'nun öğrencilerinden değil misin?\" dediler.\n\"Hayır, değilim\" diyerek inkâr etti."},{"n":"26","t":"Başkâhinin kölelerinden biri, Petrus'un, kulağını kestiği adamın akrabasıydı. Bu köle Petrus'a, \"Bahçede, seni O'nunlabirlikte görmedim mi?\" diye sordu."},{"n":"27","t":"Petrus yine inkâr etti ve tam o anda horoz öttü."},{"n":"28","h":"İsa, vali Pilatus'un önünde","t":"Sabah erkenden Yahudiler İsa'yı Kayafa'nın yanından alarak vali konağına götürdüler. Dinsel kuralları bozmamak ve Fısıh yemeğini yiyebilmek için kendileri vali konağına girmediler."},{"n":"29","t":"Bunun üzerine Pilatus dışarı çıkıp yanlarına geldi. \"Bu adamı neyle suçluyorsunuz?\" diye sordu."},{"n":"30","t":"Ona şu karşılığı verdiler: \"Bu adam kötülük eden biri olmasaydı, O'nu sana getirmezdik.\""},{"n":"31","t":"Pilatus onlara, \"O'nu siz alın, kendi yasanıza göre yargılayın\" dedi.\nYahudiler, \"Bizim hiç kimseyi ölüm cezasına çarptırmaya yetkimiz yok\" dediler."},{"n":"32","t":"Bu, İsa'nın nasıl öleceğini belirtmek için söylediği sözler yerine gelsin diye oldu."},{"n":"33","t":"Pilatus yine vali konağına girdi. İsa'yı çağırıp O'na, \"Sen Yahudilerin Kralı mısın?\" diye sordu."},{"n":"34","t":"İsa şöyle karşılık verdi: \"Bunu kendiliğinden mi söylüyorsun, yoksa benim hakkımda başkaları mı sana söyledi?\""},{"n":"35","t":"Pilatus, \"Ben Yahudi miyim?\" dedi. \"Seni bana kendi ulusun ve başkâhinlerin teslim ettiler. Ne yaptın?\""},{"n":"36","t":"İsa, \"Benim krallığım bu dünyadan değildir\" diye karşılık verdi. \"Krallığım bu dünyadan olsaydı, yandaşlarım, Yahudilere teslim edilmemem için savaşırlardı. Oysa benim krallığım buradan değildir.\""},{"n":"37","t":"Pilatus, \"Demek sen bir kralsın, öyle mi?\" dedi.\nİsa, \"Söylediğin gibi, ben kralım\" karşılığını verdi. \"Ben gerçeğe tanıklık etmek için doğdum, bunun için dünyaya geldim. Gerçekten yana olan herkes benim sesimi işitir.\""},{"n":"38","t":"Pilatus O'na, \"Gerçek nedir?\" diye sordu.\nBunu söyledikten sonra Pilatus yine dışarıya, Yahudilerin yanına çıktı. Onlara, \"Ben O'nda hiçbir suç görmüyorum\" dedi."},{"n":"39","t":"\"Ama sizin bir geleneğiniz var, her Fısıh bayramında sizin için birini salıveriyorum. Yahudilerin Kralını sizin için salıvermemi ister misiniz?\""},{"n":"40","t":"Onlar yine, \"Bu adamı değil, Barabas'ı isteriz!\" diye bağrıştılar.\nOysa Barabas bir hayduttu."}]},{"ch":19,"verses":[{"n":"1","h":"İsa ölüme mahkûm ediliyor","t":"O zaman Pilatus İsa'yı tutup kamçılattı."},{"n":"2","t":"Askerler de dikenlerden bir taç örüp O'nun başına geçirdiler. Sonra O'na mor bir kaftan giydirdiler."},{"n":"3","t":"Önüne geliyor, \"Selam, ey Yahudilerin Kralı!\" diyor, yüzüne tokat atıyorlardı."},{"n":"4","t":"Pilatus yine dışarı çıktı. Yahudilere, \"İşte, O'nu dışarıya, size getiriyorum. O'nda hiçbir suç bulmadığımı bilesiniz\" dedi."},{"n":"5","t":"Böylece İsa, başındaki dikenli taç ve üzerindeki mor kaftanla dışarı çıktı. Pilatus onlara, \"İşte o adam!\" dedi."},{"n":"6","t":"Başkâhinler ve görevliler İsa'yı görünce, \"Çarmıha ger, çarmıha ger!\" diye bağrıştılar.\nPilatus, \"O'nu kendiniz alın, çarmıha gerin!\" dedi. \"Ben O'nda bir suç görmüyorum!\""},{"n":"7","t":"Yahudiler şu karşılığı verdiler: \"Bizim bir yasamız var, o yasaya göre O'nun ölmesi gerekir. Çünkü kendisinin Tanrı Oğlu olduğunu ileri sürüyor.\""},{"n":"8","t":"Pilatus bu sözü işitince daha çok korktu."},{"n":"9","t":"Yine vali konağına girip İsa'ya, \"Sen nereden geliyorsun?\" diye sordu.\nİsa ona cevap vermedi."},{"n":"10","t":"Pilatus, \"Benimle konuşmayacak mısın?\" dedi. \"Seni salıvermeye yetkim olduğu gibi, çarmıha germeye de yetkim olduğunu bilmiyor musun?\""},{"n":"11","t":"İsa, \"Sana gökten verilmemiş olsaydı, benim üzerimde hiçbir yetkin olmazdı\" diye karşılık verdi. \"Bu nedenle beni sana teslim edenin günahı daha büyüktür.\""},{"n":"12","t":"Bunun üzerine Pilatus İsa'yı salıvermek istedi. Ama Yahudiler, \"Bu adamı salıverirsen, Sezar'ın dostu değilsin!\" diye bağrıştılar. \"Kral olduğunu ileri süren herkes Sezar'a karşı gelmiş olur.\""},{"n":"13","t":"Pilatus bu sözleri işitince İsa'yı dışarı çıkardı. Taş Döşeme - İbranicede Gabata - denilen yerde yargı kürsüsüne oturdu."},{"n":"14","t":"O gün Fısıh bayramına hazırlık günüydü. Saat on iki sularıydı. Pilatus Yahudilere, \"İşte, sizin Kralınız!\" dedi."},{"n":"15","t":"Onlar, \"Yok et O'nu! Yok et, çarmıha ger!\" diye bağrıştılar.\nPilatus, \"Kralınızı mı çarmıha gereyim?\" diye sordu.\nBaşkâhinler, \"Sezar'dan başka kralımız yok!\" karşılığını verdiler."},{"n":"16","t":"Bunun üzerine Pilatus İsa'yı, çarmıha gerilmek üzere onlara teslim etti."},{"n":"17","h":"İsa çarmıha geriliyor","t":"Askerler İsa'yı alıp götürdüler. İsa çarmıhını kendisi taşıyıp Kafatası - İbranicede Golgota - denilen yere çıktı."},{"n":"18","t":"O'nu orada çarmıha gerdiler. O'nunla birlikte iki kişiyi daha, İsa ortada, onlar da iki yanında olmak üzere çarmıha gerdiler."},{"n":"19","t":"Pilatus bir de yafta yazıp çarmıhın üzerine astırdı. Yaftada şöyle yazılıydı:"},{"n":"20","h":"'NASIRALI İSA - YAHUDİLERİN KRALI.'","t":"İsa'nın çarmıha gerildiği yer kente yakındı. Böylece İbranice, Latince ve Grekçe yazılmış olan bu yaftayı Yahudilerin birçoğu okudu."},{"n":"21","t":"Bu yüzden Yahudi başkâhinler Pilatus'a, \"'Yahudilerin Kralı' diye yazma\" dediler. \"Kendisi, 'Ben Yahudilerin Kralıyım dedi' diye yaz.\""},{"n":"22","t":"Pilatus, \"Ne yazdımsa, yazdım\" karşılığını verdi."},{"n":"23","t":"Askerler İsa'yı çarmıha gerdikten sonra O'nun giysilerini aldılar. Her birine birer pay düşecek biçimde dört parçaya böldüler. Mintanını da aldılar. Mintan boydan boya dikişsiz bir dokumaydı."},{"n":"24","t":"Birbirlerine, \"Bunu yırtmayalım\" dediler, \"kiminolacak diye kura çekelim.\"\nBu olay, şu Kutsal Yazı yerine gelsin diye oldu:\n\"Giysilerimi aralarında paylaştılar,\nelbisem üzerine kura çektiler.\"\nBunları askerler yaptı."},{"n":"25","t":"İsa'nın çarmıhının yanında ise annesi, annesinin kızkardeşi, Klopa'nın karısı Meryem ve Mecdelli Meryem duruyordu."},{"n":"26","t":"İsa, annesiyle sevdiği öğrencinin yakınında durduğunu görünce annesine, \"Anne, işte oğlun!\" dedi."},{"n":"27","t":"Sonra öğrenciye, \"İşte, annen!\" dedi.\nO andan itibaren bu öğrenci İsa'nın annesini kendi evine aldı."},{"n":"28","h":"İsa'nın ölümü","t":"Daha sonra İsa, her şeyin artık tamamlandığını bilerek Kutsal Yazı'nın yerine gelmesi için, \"Susadım!\" dedi."},{"n":"29","t":"Orada ekşi şarapla dolu bir kap vardı. Şaraba batırılmış bir süngeri zufa dalına takarak O'nun ağzına uzattılar."},{"n":"30","t":"İsa şarabı tadınca, \"Tamamlandı!\" dedi ve başını eğerek ruhunu teslim etti."},{"n":"31","t":"Yahudiler Pilatus'tan çarmıha gerilmiş adamların bacaklarının kırılmasını ve cesetlerin kaldırılmasını istediler. Hazırlık günü olduğundan, cesetlerin Sept günü çarmıhta kalmasını istemiyorlardı. Çünkü o Sept günü büyük bayramdı."},{"n":"32","t":"Bunun üzerine askerler gidip birinci adamın, sonra da İsa'yla birlikte çarmıha gerilmiş olan öteki adamın bacaklarını kırdılar."},{"n":"33","t":"İsa'ya gelince O'nun ölmüş olduğunu gördüler. Onun için bacaklarını kırmadılar."},{"n":"34","t":"Ama askerlerden biri O'nun böğrünü mızrakla deldi. Böğründen hemen kan ve su aktı."},{"n":"35","t":"Bunu gören adam tanıklık etmiştir ve tanıklığı doğrudur. Doğruyu söylediğini bilir. Siz de iman edesiniz diye tanıklık etmiştir."},{"n":"36","t":"Bunlar, \"O'nun bir tek kemiği kırılmayacaktır\" diyen Kutsal Yazı'nın yerine gelmesi için olmuştur."},{"n":"37","t":"Yine başka bir Yazı'da, \"Bedenini deştikleri adama bakacaklar\" deniyor."},{"n":"38","h":"İsa'nın gömülmesi","t":"Bundan sonra Aramatyalı Yusuf, İsa'nın cesedini kaldırmak için Pilatus'a başvurdu. Yusuf, İsa'nın öğrencisiydi, ama Yahudilerden korktuğundan bunu gizli tutuyordu. Pilatus izin verince, Yusuf gelip İsa'nın cesedini kaldırdı."},{"n":"39","t":"Daha önce geceleyin İsa'nın yanına gelmiş olan Nikodim de otuz litre kadar karışık mür ve sarısabır özü alarak geldi."},{"n":"40","t":"İkisi, İsa'nın cesedini alıp Yahudilerin gömme geleneğine uygun olarak onu baharatla keten bezlere sardılar."},{"n":"41","t":"İsa'nın çarmıha gerildiği yerde bir bahçe, bu bahçenin içinde de henüz hiç kimsenin konulmadığı yeni bir mezar vardı."},{"n":"42","t":"O gün Yahudilerin Hazırlık günüydü. Mezar da yakın olduğundan İsa'yı oraya koydular."}]},{"ch":20,"verses":[{"n":"1","h":"İsa'nın dirilişi","t":"Haftanın ilk günü erkenden, ortalık daha karanlıkken Mecdelli Meryem mezara gitti. Taşın mezarın girişinden kaldırılmış olduğunu gördü."},{"n":"2","t":"Koşarak Simun Petrus'a ve İsa'nın sevdiği öbür öğrenciye geldi. Onlara, \"Rab'bi mezardan almışlar, nereye koyduklarını da bilmiyoruz\" dedi."},{"n":"3","t":"Bunun üzerine Petrus'la öteki öğrenci dışarı çıkıp mezara yöneldiler."},{"n":"4","t":"İkisi birlikte koşuyordu. Ama öteki öğrenci Petrus'tan daha hızlı koşarak mezara önce vardı."},{"n":"5","t":"Eğilip içeri baktı, keten bezleri orada serili gördü, ama içeri girmedi."},{"n":"6-7","t":"Ardından Simun Petrus geldi ve mezara girdi. Orada serili duran bezleri ve İsa'nın başına sarılmış olan mendili gördü. Mendil, keten bezlerle birlikte değildi, ayrı bir yerde dürülmüş duruyordu."},{"n":"8","t":"O zaman mezara ilk varan öteki öğrenci de içeri girdi. Olanları gördü ve iman etti."},{"n":"9","t":"İsa'nın ölümden dirilmesi gerektiğini belirten Kutsal Yazı'yı henüz anlamamışlardı."},{"n":"10","h":"İsa, Mecdelli Meryem'e görünüyor","t":"Bundan sonra öğrenciler yine evlerine döndüler."},{"n":"11","t":"Meryem ise mezarın dışında durmuş ağlıyordu. Ağlarken eğilip mezarın içine baktı."},{"n":"12","t":"Beyazlara bürünmüş iki melek gördü; biri İsa'nın cesedinin yattığı yerin başucunda, öteki ayakucunda oturuyordu."},{"n":"13","t":"Meryem'e, \"Kadın, niçin ağlıyorsun?\" diye sordular.\nMeryem, \"Rabbimi almışlar\" dedi. \"O'nu nereye koyduklarını bilmiyorum.\""},{"n":"14","t":"Bunları söyledikten sonra arkasına döndü, İsa'nın orada, ayakta durduğunu gördü. Ama O'nun İsa olduğunu anlamadı."},{"n":"15","t":"İsa, \"Kadın, niçin ağlıyorsun?\" dedi. \"Kimi arıyorsun?\"\nMeryem O'nu bahçıvan sanarak, \"Efendim\" dedi, \"eğer O'nu sen götürdünse, nereye koyduğunu söyle de gidip O'nu alayım.\""},{"n":"16","t":"İsa ona, \"Meryem!\" dedi.\nO da döndü, İsa'ya İbranice, \"Rabbuni!\" dedi. Rabbuni, 'Öğretmenim' demektir."},{"n":"17","t":"İsa, \"Bana dokunma!\" dedi. \"Çünkü daha Baba'nın yanına çıkmadım. Kardeşlerime git ve onlara söyle, benim Babamın ve sizin Babanızın, benim Tanrımın ve sizin Tanrınızın yanına çıkıyorum.\""},{"n":"18","t":"Mecdelli Meryem öğrencilerin yanına gitti. Onlara, \"Rab'bi gördüm!\" dedi. Sonra Rab'bin kendisine söylediklerini onlara anlattı."},{"n":"19","h":"İsa öğrencilerine görünüyor","t":"Haftanın o ilk günü akşam olunca, öğrencilerin Yahudilerden korkusu nedeniyle bulundukları yerin kapıları kapalıyken İsa geldi, ortalarında durup onlara, \"Size esenlik olsun!\" dedi."},{"n":"20","t":"Bunu söyledikten sonra onlara ellerini ve böğrünü gösterdi. Öğrenciler Rab'bi görünce sevindiler."},{"n":"21","t":"İsa yine onlara, \"Size esenlik olsun!\" dedi. \"Baba beni gönderdiği gibi, ben de sizigönderiyorum.\""},{"n":"22","t":"Bunu söyledikten sonra onların üzerine üfleyerek, \"Kutsal Ruh'u alın!\" dedi."},{"n":"23","t":"\"Kimin günahlarını bağışlarsanız, bağışlanmış olur; kimin günahlarını bağışlamazsanız, bağışlanmamış kalır.\""},{"n":"24","h":"İsa Tomas'a görünüyor","t":"Onikilerden biri, İkiz diye anılan Tomas, İsa geldiğinde onlarla birlikte değildi."},{"n":"25","t":"Öbür öğrenciler ona, \"Biz Rab'bi gördük!\" dediler.\nTomas ise, \"O'nun ellerinde çivilerin izini görmedikçe, çivilerin izine parmağımla dokunmadıkça ve elimi böğrüne sokmadıkça inanmam\" dedi."},{"n":"26","t":"Sekiz gün sonra İsa'nın öğrencileri yine evdeydiler. Tomas da onlarla birlikteydi. Kapılar kapalıyken İsa gelip ortalarında durdu, \"Size esenlik olsun!\" dedi."},{"n":"27","t":"Sonra Tomas'a, \"Parmağını uzat\" dedi, \"ellerime bak, elini uzat, böğrüme koy. İmansız olma, imanlı ol!\""},{"n":"28","t":"Tomas O'na, \"Rabbim ve Tanrım!\" diye cevap verdi."},{"n":"29","t":"İsa ona, \"Beni gördüğün için mi iman ettin?\" dedi. \"Görmeden iman edenlere ne mutlu!\""},{"n":"30","t":"İsa, öğrencilerinin önünde, bu kitapta yazılı olmayan başka birçok mucizeler yaptı."},{"n":"31","t":"Ne var ki yazılanlar, İsa'nın, Tanrı'nın Oğlu Mesih olduğuna iman edesiniz ve iman ederek O'nun adıyla yaşama kavuşasınız diye yazılmıştır."}]},{"ch":21,"verses":[{"n":"1-2","h":"İsa göl kenarında","t":"Bundan sonra Taberiye gölünün kenarında İsa öğrencilerine yine göründü. Bu da şöyle oldu: Simun Petrus, İkiz diye anılan Tomas, Celile'nın Kana köyünden Natanyel, Zebedi'nin oğulları ve İsa'nın öğrencilerinden iki kişi daha birlikte bulunuyorlardı."},{"n":"3","t":"Simun Petrus ötekilere, \"Ben balık tutmaya gidiyorum\" dedi.\nOnlar, \"Biz de seninle geliyoruz\" dediler.\nDışarı çıkıp kayığa bindiler. Ama o gece bir şey tutamadılar."},{"n":"4","t":"Sabah olurken İsa kıyıda duruyordu. Ne var ki öğrenciler, O'nun İsa olduğunu anlamadılar."},{"n":"5","t":"İsa, \"Çocuklar, balığınız yok mu?\" diye sordu.\n\"Yok\" cevabını verdiler."},{"n":"6","t":"İsa, \"Ağı kayığın sağ yanına atın, tutarsınız\" dedi.\nBunun üzerine ağı attılar. O kadar çok balık tuttular ki, artık ağı çekemez olmuşlardı."},{"n":"7","t":"İsa'nın sevdiği öğrenci, Petrus'a, \"Bu Rab'dir!\" dedi.\nSimun Petrus O'nun Rab olduğunu işitince üzerinden çıkarmış olduğu üstlüğü giyip göle atladı."},{"n":"8","t":"Öbür öğrenciler balık dolu ağı çekerek kayıkla geldiler. Çünkü karadan ancak iki yüz arşın kadar uzaktaydılar."},{"n":"9","t":"Karaya çıkınca orada yanan bir kömür ateşi, ateşin üzerinde balık ve ekmek gördüler."},{"n":"10","t":"İsa onlara, \"Şimdi tuttuğunuz balıklardan getirin\" dedi."},{"n":"11","t":"Simun Petrus kayığa atladı ve tam yüz elli üç iri balıkla yüklü ağı karaya çekti. Bu kadar çok balık olduğu halde ağyırtılmamıştı."},{"n":"12","t":"İsa onlara, \"Gelin, yemek yiyin\" dedi.\nÖğrencilerden hiçbiri O'na, \"Sen kimsin?\" diye sormaya cesaret edemedi. Çünkü O'nun Rab olduğunu biliyorlardı."},{"n":"13","t":"İsa gidip ekmeği aldı, onlara verdi. Aynı şekilde balıkları da verdi."},{"n":"14","t":"İşte bu, İsa'nın ölümden dirildikten sonra öğrencilere üçüncü görünüşüydü."},{"n":"15","h":"İsa ile Petrus","t":"Yemekten sonra İsa, Simun Petrus'a, \"Yuhanna oğlu Simun, beni bunlardan daha çok seviyor musun?\" diye sordu.\nPetrus, \"Evet, Rab\" dedi, \"seni sevdiğimi bilirsin.\"\nİsa ona, \"Kuzularımı otlat\" dedi."},{"n":"16","t":"İkinci kez yine ona, \"Yuhanna oğlu Simun, beni seviyor musun?\" diye sordu.\nO da, \"Evet, Rab, seni sevdiğimi bilirsin\" dedi.\nİsa ona, \"Koyunlarımı güt\" dedi."},{"n":"17","t":"Üçüncü kez ona, \"Yuhanna oğlu Simun, beni seviyor musun?\" diye sordu.\nPetrus kendisine üçüncü kez, \"Beni seviyor musun?\" diye sormasına üzüldü. \"Rab, sen her şeyi bilirsin, seni sevdiğimi de bilirsin\" dedi.\nİsa ona, \"Koyunlarımı otlat\" dedi."},{"n":"18","t":"\"Sana doğrusunu söyleyeyim, gençliğinde kendi kuşağını kendin bağlar, istediğin yere giderdin. Ama yaşlanınca ellerini uzatacaksın, başkası seni bağlayacak ve istemediğin yere götürecek.\""},{"n":"19","t":"Bunu, Tanrı'yı ne tür bir ölümle yücelteceğini belirtmek için söyledi. Sonra ona, \"Ardımdan gel\" dedi."},{"n":"20","t":"Petrus arkasına döndü, İsa'nın sevdiği öğrencinin kendilerini izlediğini gördü. Bu öğrenci, akşam yemeğinde İsa'nın göğsüne yaslanan ve, \"Rab, seni ele verecek olan kimdir?\" diye soran öğrencidir."},{"n":"21","t":"Petrus onu görünce İsa'ya, \"Rab, ya bu ne olacak?\" diye sordu."},{"n":"22","t":"İsa ona, \"Ben gelinceye dek onun yaşamasını istiyorsam, bundan sana ne?\" dedi. \"Sen ardımdan gel!\""},{"n":"23","t":"Bu yüzden kardeşler arasında o öğrencinin ölmeyeceğine dair bir söylenti çıktı. Ama İsa Petrus'a, \"O ölmeyecek\" dememişti. Sadece, \"Ben gelinceye dek onun yaşamasını istiyorsam, bundan sana ne?\" demişti."},{"n":"24","t":"Bütün bunlara tanıklık eden ve bunları yazan öğrenci budur. Onun tanıklığının doğru olduğunu biliyoruz."},{"n":"25","t":"İsa'nın yaptığı daha başka çok şey vardır. Bunlar tek tek yazılsaydı, sanırım yazılan kitaplar dünyaya sığmazdı."}]}]}];
